var mcInteracoesDB = [
{"med1":["metformina"],"med2":["álcool","alcool","etanol","bebida alcoólica"],"nivel":"moderado","titulo":"Metformina + Álcool (Risco de Acidose Láctica)","mecanismo":"A metformina inibe a gliconeogênese hepática, aumentando a produção de lactato. O álcool potencializa esse efeito ao inibir ainda mais a neoglicogênese e elevar a produção de NADH — favorecendo o acúmulo de lactato no sangue.","efeito":"Acidose láctica — acúmulo perigoso de ácido lático com mortalidade de 30–50%. O risco é maior em jejum prolongado, desidratação, exercício intenso ou consumo agudo de grande volume de álcool. Insuficiência renal ou hepática aumentam ainda mais o risco.","conduta":"⚠️ Evitar álcool em quantidade excessiva ou em jejum durante uso de metformina. Consumo moderado e ocasional (1–2 doses) com alimentação adequada tem risco baixo. Orientar firmemente para não beber em jejum prolongado."},
{"med1":["aspirina","ácido acetilsalicílico","aas"],"med2":["álcool","alcool","etanol","bebida alcoólica"],"nivel":"moderado","titulo":"AAS / Aspirina + Álcool (Potencialização do Sangramento Gastrointestinal)","mecanismo":"Mecanismos aditivos: o álcool lesa diretamente a mucosa gástrica e inibe prostaglandinas gastroprotetoras; o AAS inibe COX-1, reduzindo prostaglandinas da mucosa e a agregação plaquetária. Os dois efeitos somam-se sinergicamente sobre a barreira gástrica.","efeito":"Risco significativamente aumentado de gastrite erosiva, úlcera péptica e sangramento gastrointestinal — mesmo com AAS em doses antiagregantes (100 mg). Risco de sangramento grave e hemorragia digestiva alta em pacientes com história de úlcera.","conduta":"⚠️ Evitar uso concomitante regular. Em pacientes que tomam AAS profilático e consomem álcool regularmente, avaliar proteção gástrica com IBP (pantoprazol, omeprazol). Abstinência alcoólica é o ideal em usuários crônicos de AAS."},
{"med1":["suco de grapefruit","toranja","grapefruit","sumo de toranja","suco de toranja"],"med2":["sinvastatina","lovastatina","atorvastatina"],"nivel":"alto","titulo":"Grapefruit / Toranja + Estatina (Rabdomiólise — Níveis até 260% Mais Altos)","mecanismo":"O grapefruit contém furanocumarinas (bergamotina, DHB) que inibem irreversivelmente o CYP3A4 intestinal. Sinvastatina, lovastatina e atorvastatina dependem de CYP3A4 para metabolismo de primeira passagem — a inibição eleva drasticamente sua biodisponibilidade oral.","efeito":"Elevação dos níveis plasmáticos da estatina em 200–260% — risco real de miopatia grave e rabdomiólise, com destruição muscular maciça, mioglobinúria e insuficiência renal aguda potencialmente fatal.","conduta":"❌ Evitar grapefruit e toranja em qualquer forma (suco, fruta inteira) durante uso de sinvastatina, lovastatina e atorvastatina. A inibição persiste por 24–72h — não adianta separar os horários. Rosuvastatina e pravastatina são alternativas sem interação relevante com grapefruit."},
{"med1":["suco de grapefruit","toranja","grapefruit","sumo de toranja","suco de toranja"],"med2":["midazolam","triazolam","alprazolam","diazepam"],"nivel":"moderado","titulo":"Grapefruit / Toranja + Benzodiazepínico (Sedação Excessiva por Inibição CYP3A4)","mecanismo":"Furanocumarinas do grapefruit inibem CYP3A4 intestinal, principal via de metabolismo de midazolam, triazolam e alprazolam — elevando significativamente seus níveis plasmáticos.","efeito":"Sedação excessiva e prolongada, confusão mental, comprometimento psicomotor e risco aumentado de quedas, especialmente em idosos. Midazolam e triazolam são os mais afetados.","conduta":"⚠️ Evitar grapefruit e seu suco durante uso de midazolam, triazolam e alprazolam. A inibição pode persistir por até 72h. Lorazepam e oxazepam (metabolismo por glicuronidação) são alternativas sem interação relevante."},
{"med1":["suco de grapefruit","toranja","grapefruit","sumo de toranja","suco de toranja"],"med2":["felodipino","nifedipino","anlodipino","nimodipino","verapamil","diltiazem","nisoldipino"],"nivel":"alto","titulo":"Grapefruit / Toranja + Bloqueador de Canal de Cálcio (Hipotensão Grave)","mecanismo":"Furanocumarinas do grapefruit inibem CYP3A4 intestinal. Felodipino, nifedipino e nisoldipino são extensamente metabolizados por CYP3A4 — a inibição pode triplicar ou mais os níveis do felodipino. Esta interação foi descoberta acidentalmente no estudo original com grapefruit.","efeito":"Hipotensão grave com queda brusca da pressão arterial, taquicardia reflexa, tonturas, cefaleia e risco de síncope e queda. Felodipino e nisoldipino são os mais afetados.","conduta":"❌ Evitar grapefruit e suco de toranja em pacientes usando felodipino e nifedipino. A inibição persiste por 24–72h após o consumo. Substituir grapefruit por outro cítrico (laranja, limão — sem interação). Anlodipino é menos afetado mas cautela ainda é recomendada."},
{"med1":["vitamina k","couve","espinafre","brócolis","repolho","couve-de-bruxelas","alface","salsinha","coentro"],"med2":["warfarina","varfarina"],"nivel":"moderado","titulo":"Vitamina K (Vegetais Verdes) + Warfarina (INR Imprevisível)","mecanismo":"A warfarina inibe a vitamina K-epóxido redutase, bloqueando a ativação de fatores de coagulação dependentes de vitamina K (II, VII, IX, X). Dieta rica em vitamina K (couve, espinafre, brócolis) compete diretamente com esse mecanismo, antagonizando o efeito anticoagulante.","efeito":"Redução do efeito anticoagulante — INR subterapêutico com risco de trombose (embolia pulmonar, AVC, TVP). Mudanças bruscas na dieta causam flutuações imprevisíveis do INR.","conduta":"⚠️ Manter o consumo de vegetais verdes CONSISTENTE — não é preciso eliminá-los, mas evitar mudanças abruptas nos hábitos alimentares. Monitorar INR após alterações dietéticas significativas. Orientar o paciente a comunicar mudanças de dieta ao médico."},
{"med1":["levofloxacino","ciprofloxacino","moxifloxacino","norfloxacino","ofloxacino"],"med2":["glibenclamida","glipizida","gliclazida","glimepirida","sulfonilureia","insulina","insulina nph","insulina regular","metformina"],"nivel":"alto","titulo":"Quinolona + Antidiabético Oral / Insulina (Disglicemia Grave e Imprevisível)","mecanismo":"Quinolonas, especialmente levofloxacino e ciprofloxacino, afetam diretamente as células β pancreáticas: inibem canais KATP (causando hiperinsulinemia e hipoglicemia) ou bloqueiam a secreção de insulina (causando hiperglicemia). O efeito é imprevisível e pode alternar no mesmo paciente.","efeito":"Hipoglicemia grave (risco de coma, convulsão e morte) ou hiperglicemia grave (cetoacidose diabética) de forma imprevisível. Risco maior com sulfonilureias (glibenclamida, glimepirida) e em idosos. Casos fatais relatados.","conduta":"⚠️ Monitorar glicemia com frequência aumentada (pelo menos 2–3× ao dia) durante todo o tratamento com quinolona. Orientar paciente sobre sintomas de hipo e hiperglicemia. Considerar antibiótico alternativo (amoxicilina-clavulanato, cefalosporina) em diabéticos com alto risco glicêmico."},
{"med1":["carbonato de cálcio","cálcio","citrato de cálcio","antiácido","hidróxido de alumínio","hidróxido de magnésio","omeprazol","lansoprazol","esomeprazol","pantoprazol","rabeprazol","ibp"],"med2":["levotiroxina"],"nivel":"moderado","titulo":"Carbonato de Cálcio / Antiácido / IBP + Levotiroxina (Hipotireoidismo por Subdose)","mecanismo":"Cálcio e antiácidos alcalinos formam quelatos insolúveis com a levotiroxina no lúmen intestinal, reduzindo sua biodisponibilidade em até 40%. IBPs elevam o pH gástrico — a levotiroxina requer pH ácido para dissolução e absorção adequadas.","efeito":"Hipotireoidismo clínico por subdosagem efetiva — TSH persistentemente elevado mesmo com dose aparentemente correta: fadiga, ganho de peso, bradicardia, depressão e dislipidemia.","conduta":"⚠️ Tomar levotiroxina em jejum (30–60 min antes do café da manhã). Separar do cálcio e antiácidos por no mínimo 4 horas. Monitorar TSH ao iniciar ou suspender esses medicamentos cronicamente."},
{"med1":["sulfato ferroso","fumarato ferroso","gluconato ferroso","ferro"],"med2":["levotiroxina"],"nivel":"moderado","titulo":"Ferro Oral + Levotiroxina (Quelação — Tomar com 4 Horas de Intervalo)","mecanismo":"O ferro ferroso forma quelatos insolúveis com a levotiroxina no lúmen intestinal, reduzindo sua absorção em 40–55%. Quanto menor o intervalo entre as tomadas, maior a interferência.","efeito":"Hipotireoidismo mal controlado — TSH elevado, sintomas persistentes (fadiga, ganho de peso, intolerância ao frio) mesmo com dose de levotiroxina que antes era eficaz. Frequentemente não reconhecido como causa.","conduta":"⚠️ Separar obrigatoriamente: tomar levotiroxina e ferro em horários diferentes, com intervalo mínimo de 4 horas entre eles. Ideal: levotiroxina em jejum pela manhã + ferro à tarde ou à noite. Monitorar TSH ao iniciar suplemento de ferro em paciente em uso de levotiroxina."},
{"med1":["sulfato ferroso","fumarato ferroso","gluconato ferroso","ferro"],"med2":["ciprofloxacino","levofloxacino","moxifloxacino","norfloxacino","doxiciclina","tetraciclina","minociclina"],"nivel":"alto","titulo":"Ferro Oral + Quinolona / Tetraciclina (Quelação — Absorção do Antibiótico Reduzida em até 90%)","mecanismo":"O ferro forma quelatos estáveis e insolúveis com quinolonas e tetraciclinas no lúmen intestinal. A biodisponibilidade do antibiótico pode cair em 50–90% dependendo do intervalo entre as tomadas, inviabilizando a concentração terapêutica.","efeito":"Níveis séricos subterapêuticos do antibiótico → falha no tratamento de infecções (UTI, pneumonia, infecções de pele) → progressão da infecção, resistência bacteriana e risco de sepse.","conduta":"❌ Não administrar simultaneamente. Separar por: quinolonas — 2h antes ou 6h depois do ferro; tetraciclinas — 2h antes ou 3h depois do ferro. Se separação não for viável, considerar antibiótico alternativo sem quelação (amoxicilina, cefalosporina)."},
{"med1":["melatonina"],"med2":["alprazolam","clonazepam","diazepam","lorazepam","bromazepam","midazolam","nitrazepam","zolpidem","zopiclona"],"nivel":"moderado","titulo":"Melatonina + Benzodiazepínico / Hipnótico (Potencialização Sedativa — Risco em Idosos)","mecanismo":"A melatonina possui efeito sedativo-hipnótico próprio mediado por receptores MT1/MT2. Somada a benzodiazepínicos ou hipnóticos Z-drugs (zolpidem, zopiclona), o efeito sedativo é aditivo.","efeito":"Sedação excessiva, sonolência diurna prolongada, confusão mental e risco aumentado de quedas — especialmente em idosos (risco de fratura de quadril). Comprometimento cognitivo e psicomotor.","conduta":"⚠️ Usar com cautela, principalmente em idosos. A melatonina é frequentemente prescrita para reduzir ou substituir benzodiazepínicos — verificar se o objetivo é substituição (correto) ou adição (risco). Orientar sobre risco de quedas noturnas e instruir uso de iluminação no percurso ao banheiro."},
{"med1":["ginkgo biloba","ginkgo","extrato de ginkgo"],"med2":["warfarina","varfarina","apixabana","rivaroxabana","dabigatrana","edoxabana","aspirina","ácido acetilsalicílico","aas","clopidogrel","ticagrelor"],"nivel":"moderado","titulo":"Ginkgo Biloba + Anticoagulante / Antiagregante (Risco Aumentado de Sangramento)","mecanismo":"O ginkgo biloba contém ginkgolídeos B que inibem o Fator de Ativação Plaquetária (PAF) e reduzem a agregação plaquetária. Combinado a anticoagulantes orais ou antiagregantes, o efeito antitrombótico é aditivo e pode elevar o INR de forma imprevisível.","efeito":"Risco aumentado de sangramento, incluindo sangramentos intracranianos espontâneos. Casos de hemorragia cerebral relatados com uso concomitante de ginkgo + warfarina ou AAS.","conduta":"⚠️ Evitar uso concomitante com anticoagulantes e antiagregantes. Informar médico e farmacêutico sobre uso de fitoterápicos. Monitorar INR se em uso de warfarina. Suspender ginkgo 7–10 dias antes de cirurgias ou procedimentos invasivos."},
{"med1":["erva de são joão","hipericão","hypericum","erva-de-são-joão","hypericum perforatum"],"med2":["fluoxetina","sertralina","escitalopram","paroxetina","citalopram","venlafaxina","duloxetina","fluvoxamina","warfarina","varfarina","etinilestradiol","anticoncepcional","contraceptivo","efavirenz","atazanavir","lopinavir","ciclosporina","digoxina"],"nivel":"alto","titulo":"Erva de São João (Hypericum) + ISRS / Outros (Síndrome Serotoninérgica + Indução Enzimática)","mecanismo":"Duplo mecanismo perigoso: (1) hiperforina inibe recaptação de serotonina/noradrenalina/dopamina — combinada com ISRS/IRSN causa síndrome serotoninérgica; (2) hiperforina é potente indutora de CYP3A4, CYP2C9 e P-glicoproteína — reduz drasticamente os níveis de warfarina, contraceptivos orais, antirretrovirais (efavirenz, atazanavir), ciclosporina e digoxina.","efeito":"Com ISRS/IRSN: síndrome serotoninérgica (agitação, tremor, mioclonias, hipertermia — potencialmente fatal). Com outros: falha terapêutica por redução dos níveis — gravidez não planejada, rejeição de transplante, sangramento por queda do INR, resistência ao HIV.","conduta":"❌ Contraindicado com ISRS/IRSN. Contraindicado em transplantados (ciclosporina), pacientes com HIV, em uso de warfarina ou contraceptivos orais. A indução enzimática persiste por 1–2 semanas após suspensão. Informar sempre médico sobre fitoterápicos em uso."},
{"med1":["tamoxifeno"],"med2":["fluoxetina","paroxetina"],"nivel":"alto","titulo":"Tamoxifeno + Fluoxetina / Paroxetina (Redução da Eficácia Anticâncer)","mecanismo":"Fluoxetina e paroxetina são potentes inibidores de CYP2D6, enzima responsável pela conversão do tamoxifeno em endoxifeno — seu metabólito ativo com 30–100× maior afinidade ao receptor de estrogênio. A inibição reduz os níveis de endoxifeno em até 64%.","efeito":"Redução substancial da eficácia do tamoxifeno no tratamento do câncer de mama hormônio-receptor positivo — aumento do risco de recidiva tumoral. O impacto clínico é equivalente a uma má adesão ao tratamento.","conduta":"❌ Evitar fluoxetina e paroxetina em pacientes em uso de tamoxifeno. Substituir por antidepressivos com menor inibição de CYP2D6: sertralina (inibição leve), venlafaxina, desvenlafaxina ou mirtazapina. Discutir obrigatoriamente com oncologista antes de qualquer troca."},
{"med1":["ciclosporina"],"med2":["claritromicina","eritromicina","fluconazol","itraconazol","cetoconazol","voriconazol","posaconazol"],"nivel":"alto","titulo":"Ciclosporina + Macrolídeo / Antifúngico Azólico (Nefrotoxicidade e Imunossupressão Excessiva)","mecanismo":"Macrolídeos (claritromicina, eritromicina) e azólicos (fluconazol, itraconazol, cetoconazol, voriconazol) inibem fortemente CYP3A4 e P-glicoproteína — principais vias de metabolismo da ciclosporina — elevando seus níveis séricos em 2 a 5 vezes.","efeito":"Nefrotoxicidade grave por acúmulo de ciclosporina, imunossupressão excessiva com risco de infecções oportunistas e, em transplantados, risco de toxicidade orgânica grave e rejeição paradoxal por toxicidade.","conduta":"❌ Evitar a combinação. Se inevitável: reduzir dose de ciclosporina, monitorar nível sérico (C0/C2) com muito maior frequência e avaliar função renal. Ao suspender o inibidor, reajustar a dose prontamente (risco de queda brusca dos níveis e rejeição aguda)."},
{"med1":["alopurinol"],"med2":["azatioprina","mercaptopurina"],"nivel":"alto","titulo":"Alopurinol + Azatioprina / Mercaptopurina (Toxicidade Grave na Medula Óssea)","mecanismo":"O alopurinol inibe a xantina oxidase, enzima essencial para o metabolismo de azatioprina e mercaptopurina. A inibição eleva os níveis ativos dos imunossupressores em até 400%, com acúmulo maciço de metabólitos tiopurínicos citotóxicos na medula óssea.","efeito":"Mielossupressão grave: leucopenia intensa, trombocitopenia e anemia aplástica — risco de infecções oportunistas fatais, sangramentos e morte. O quadro pode se manifestar semanas após o início da combinação.","conduta":"❌ Combinação altamente perigosa. Se for necessária: reduzir azatioprina ou mercaptopurina para 25–33% da dose habitual e monitorar hemograma semanalmente. Na prática clínica, preferir febuxostato como alternativa ao alopurinol em pacientes usando esses imunossupressores. Comunicar reumatologista ou hematologista imediatamente."},
{"med1":["tramadol"],"med2":["carbamazepina"],"nivel":"alto","titulo":"Tramadol + Carbamazepina (Redução da Analgesia + Risco Convulsivante)","mecanismo":"A carbamazepina é potente indutora de CYP3A4, principal via de metabolismo do tramadol, reduzindo seus níveis em até 50% e aumentando a formação de metabólitos. Paralelamente, o tramadol tem ação pró-convulsivante e a carbamazepina altera o limiar convulsivante de forma imprevisível.","efeito":"Efeito dual perigoso: (1) perda substancial da eficácia analgésica do tramadol, levando o paciente a escalar doses; (2) aumento significativo do risco de convulsões pela combinação dos efeitos pró-convulsivantes dos metabólitos do tramadol com a carbamazepina.","conduta":"❌ Evitar. Tramadol já é contraindicado em epilepsia — em pacientes usando carbamazepina, o risco é redobrado. Substituir por opioide sem interação enzimática significativa (morfina) ou discutir analgesia multimodal com médico."},
{"med1":["quetiapina"],"med2":["cetoconazol","itraconazol","voriconazol","posaconazol","fluconazol"],"nivel":"alto","titulo":"Quetiapina + Antifúngico Azólico (Níveis >300% — Arritmia e Sedação Grave)","mecanismo":"Antifúngicos azólicos (cetoconazol, itraconazol, voriconazol, posaconazol) são potentes inibidores de CYP3A4, principal via de metabolismo da quetiapina. Estudos demonstraram elevação de até 335% nos níveis plasmáticos de quetiapina com cetoconazol.","efeito":"Sedação profunda, hipotensão grave, prolongamento do intervalo QT com risco de Torsades de Pointes e arritmias ventriculares fatais. Possível síndrome neuroléptica maligna em casos extremos.","conduta":"❌ Contraindicado com cetoconazol e itraconazol. Se antifúngico azólico for inevitável: suspender temporariamente a quetiapina ou reduzir substancialmente a dose. Monitorar ECG (QTc) e nível de consciência. Preferir antifúngico alternativo sem inibição de CYP3A4 quando possível."},
{"med1":["rifampicina"],"med2":["efavirenz","lopinavir","atazanavir","darunavir","ritonavir","saquinavir","indinavir","nevirapina","antirretroviral"],"nivel":"alto","titulo":"Rifampicina + Antirretrovirais (Falha Terapêutica e Resistência HIV)","mecanismo":"A rifampicina é o mais potente indutor enzimático clínico conhecido (CYP3A4, CYP2B6, P-glicoproteína). Os inibidores de protease (lopinavir, atazanavir, darunavir) são altamente dependentes de CYP3A4 — a rifampicina reduz seus níveis em 75–90%. O efavirenz tem níveis reduzidos em 26–50%.","efeito":"Níveis subterapêuticos dos antirretrovirais → falha virológica → replicação viral persistente → desenvolvimento de resistência ao HIV, comprometendo opções terapêuticas futuras do paciente.","conduta":"❌ Rifampicina é praticamente incompatível com inibidores de protease. Alternativa: substituir rifampicina por rifabutina (indutor mais fraco) no tratamento da tuberculose em pacientes com HIV. Ajustar doses conforme PCDT TB/HIV do Ministério da Saúde. Discussão obrigatória com infectologista."},
{"med1":["propranolol","atenolol","metoprolol","bisoprolol","carvedilol","nebivolol","betabloqueador"],"med2":["verapamil","diltiazem"],"nivel":"alto","titulo":"Betabloqueador + Verapamil / Diltiazem (Bloqueio AV e Parada Cardíaca)","mecanismo":"Betabloqueadores e antagonistas do cálcio não-diidropiridínicos (verapamil e diltiazem) têm efeitos aditivos na redução da frequência e da condução cardíacas, agindo sobre o nó sinusal e nó AV por mecanismos complementares.","efeito":"Bradicardia grave, bloqueio atrioventricular de alto grau (II ou III), hipotensão severa e risco real de parada cardíaca. Risco máximo em pacientes com disfunção prévia do nó AV, insuficiência cardíaca ou doença de Chagas.","conduta":"❌ Combinação contraindicada especialmente por via IV. Por via oral, usar somente sob supervisão cardiológica com monitoramento de ECG e FC. Se bloqueador de canal de cálcio for necessário para hipertensão, preferir anlodipino (diidropiridínico — sem efeito cronotrópico negativo)."},
{"med1":["propranolol","atenolol","metoprolol","bisoprolol","carvedilol","nebivolol","betabloqueador"],"med2":["insulina","insulina nph","insulina regular","glibenclamida","glipizida","gliclazida","glimepirida","sulfonilureia"],"nivel":"alto","titulo":"Betabloqueador + Insulina / Sulfonilureia (Hipoglicemia Mascarada)","mecanismo":"Betabloqueadores (especialmente não-seletivos como propranolol) bloqueiam receptores β2-adrenérgicos, suprimindo taquicardia e tremor — os principais sinais de alerta da hipoglicemia. Também bloqueiam a glicogenólise adrenérgica, prolongando e aprofundando a crise.","efeito":"Hipoglicemia grave com sintomas mascarados — o paciente não percebe a crise hipoglicêmica. O suor frio pode ser o único sinal restante. Risco de coma hipoglicêmico sem aviso prévio. Sulfonilureias (glibenclamida, gliclazida, glimepirida) apresentam risco equivalente ao da insulina.","conduta":"⚠️ Monitorar glicemia com maior frequência. Orientar paciente a reconhecer a sudorese fria como sinal de alerta. Preferir betabloqueadores cardiosseletivos (atenolol, metoprolol, bisoprolol) — menor bloqueio β2 periférico. Evitar propranolol em diabéticos insulino-dependentes sempre que possível."},
{"med1":["enalapril","captopril","ramipril","lisinopril","perindopril","losartana","valsartana","irbesartana","olmesartana","telmisartana","ieca","bra"],"med2":["ibuprofeno","naproxeno","diclofenaco","nimesulida","cetoprofeno","meloxicam","indometacina","etoricoxibe","celecoxibe","aine"],"nivel":"alto","titulo":"IECA / BRA + AINE (Insuficiência Renal Aguda + Perda Anti-hipertensiva)","mecanismo":"AINEs inibem prostaglandinas que mantêm vasodilatação aferente renal; IECAs/BRAs reduzem a vasoconstrição eferente. A combinação compromete gravemente o fluxo glomerular por duplo mecanismo — a chamada \"tríade fatal\" (IECA + AINE + diurético) é a forma mais grave.","efeito":"Insuficiência renal aguda (nefrotoxicidade combinada), hipercalemia e redução significativa do efeito anti-hipertensivo. Risco elevado em idosos, desidratados ou com insuficiência renal prévia.","conduta":"❌ Evitar AINEs em pacientes usando IECA ou BRA, especialmente em uso crônico. Substituir por paracetamol ou dipirona para analgesia. Se AINE for inevitável: usar pelo menor tempo possível, monitorar creatinina, ureia e potássio, e manter hidratação adequada."},
{"med1":["furosemida","ácido etacrínico"],"med2":["gentamicina","amicacina","tobramicina","neomicina","estreptomicina","aminoglicosídeo"],"nivel":"alto","titulo":"Furosemida + Aminoglicosídeo (Ototoxicidade Grave e Irreversível)","mecanismo":"Efeito ototóxico sinérgico: a furosemida altera a composição iônica da endolinfa coclear, criando um ambiente que potencializa a captação e toxicidade dos aminoglicosídeos nas células ciliadas externas da cóclea.","efeito":"Perda auditiva neurossensorial grave — podendo ser permanente e irreversível (surdez total), além de vestibulopatia (tontura crônica, desequilíbrio). Risco adicional de nefrotoxicidade sinérgica com insuficiência renal aguda.","conduta":"❌ Evitar a combinação sempre que possível. Se ambos forem necessários (ex.: sepse com sobrecarga hídrica): usar doses mínimas de furosemida, monitorar audiometria, dosar nível sérico do aminoglicosídeo (pico e vale), monitorar creatinina. Preferir dosagem única diária (once-daily) do aminoglicosídeo — menor ototoxicidade."},
{"med1":["sinvastatina","lovastatina"],"med2":["claritromicina","eritromicina"],"nivel":"alto","titulo":"Sinvastatina / Lovastatina + Macrolídeo (Rabdomiólise Grave)","mecanismo":"Claritromicina e eritromicina são potentes inibidores de CYP3A4, a principal via de metabolismo de sinvastatina e lovastatina. A inibição eleva dramaticamente os níveis plasmáticos dessas estatinas.","efeito":"Miopatia grave com elevação de CPK e risco real de rabdomiólise — destruição muscular maciça com mioglobinúria, insuficiência renal aguda e hipercalemia potencialmente fatal.","conduta":"❌ Contraindicado. Suspender sinvastatina/lovastatina durante o tratamento com macrolídeo. Se antibioticoterapia com macrolídeo for necessária, preferir pravastatina ou rosuvastatina (menor dependência de CYP3A4). Reiniciar a estatina original após término do antibiótico."},
{"med1":["fenitoína"],"med2":["warfarina","varfarina"],"nivel":"alto","titulo":"Fenitoína + Warfarina (Interação Bidirecional Imprevisível)","mecanismo":"Interação bidirecional e bifásica: (1) inicialmente, fenitoína inibe CYP2C9 → potencialização da warfarina → risco de sangramento; (2) com uso prolongado, fenitoína induz CYP2C9/3A4 → acelera metabolismo da warfarina → redução do efeito anticoagulante. Warfarina pode também alterar níveis séricos de fenitoína de forma imprevisível.","efeito":"Risco duplo e sequencial: sangramento grave na fase inicial (INR supra-terapêutico) ou tromboembolismo na fase de indução (INR subterapêutico). Fenitoína pode atingir níveis tóxicos causando nistagmo, ataxia, confusão e convulsões.","conduta":"❌ Combinação de manejo muito difícil. Se inevitável: monitorar INR muito frequentemente nas primeiras semanas e após qualquer alteração de dose; monitorar nível sérico de fenitoína. Considerar anticoagulante alternativo (dabigatrana, rivaroxabana) se viável — menor interação com fenitoína."},
{"med1":["lítio","carbonato de lítio"],"med2":["fluoxetina","sertralina","escitalopram","paroxetina","citalopram","fluvoxamina","venlafaxina","duloxetina"],"nivel":"alto","titulo":"Lítio + ISRS / IRSN (Síndrome Serotoninérgica)","mecanismo":"O lítio potencializa a neurotransmissão serotoninérgica central por múltiplos mecanismos. Associado a ISRS/IRSN, que bloqueiam a recaptação de serotonina, o efeito é aditivo e pode produzir hiperserotonismo grave.","efeito":"Síndrome serotoninérgica: agitação, tremor, mioclonias, hiperreflexia, hipertermia, diarreia, taquicardia — podendo evoluir para rabdomiólise, convulsões e morte. ISRS também podem elevar o nível sérico de lítio, aumentando o risco de toxicidade litiêmica concomitante.","conduta":"⚠️ Usar com cautela sob supervisão psiquiátrica. Monitorar nível sérico de lítio (alvo 0,6–1,0 mEq/L). Orientar paciente sobre sinais precoces de síndrome serotoninérgica (tremor + agitação + febre). Suspender ambos e buscar emergência se quadro florido aparecer."},
{"med1":["fenelzina","tranilcipromina","isocarboxazida","selegilina","moclobemida","imao"],"med2":["álcool","etanol","bebida alcoólica","vinho","cerveja","cachaça","tiramina"],"nivel":"alto","titulo":"IMAO + Álcool (Crise Hipertensiva — Risco Fatal)","mecanismo":"IMAOs inibem a monoamina oxidase responsável pelo metabolismo da tiramina presente no álcool fermentado (vinho, cerveja, sidra). A tiramina acumulada provoca liberação maciça de catecolaminas. Além disso, o acetaldeído (metabólito do álcool) pode ter efeito vasoativo sinérgico.","efeito":"Crise hipertensiva grave com cefaleia occipital súbita e intensa, rigidez de nuca, visão turva, náusea, palpitações e risco de AVC hemorrágico ou infarto. O álcool pode também potencializar a sedação do IMAO de forma imprevisível.","conduta":"❌ Álcool absolutamente contraindicado durante o uso de IMAOs. Orientar sobre alimentos ricos em tiramina (queijos maturados, frios curados, vinho tinto, soja fermentada). O período de restrição continua por 14 dias após suspensão do IMAO (washout completo)."},
{"med1":["carbamazepina","fenitoína","fenobarbital","primidona","rifampicina","oxcarbazepina","topiramato","felbamato"],"med2":["etinilestradiol","levonorgestrel","desogestrel","gestodeno","noretisterona","anticoncepcional","anticoncepcional oral","contraceptivo"],"nivel":"alto","titulo":"Indutor Enzimático + Anticoncepcional Oral (Falha Contraceptiva)","mecanismo":"Indutores enzimáticos potentes (carbamazepina, fenitoína, fenobarbital, primidona, rifampicina) aceleram o metabolismo hepático dos hormônios contraceptivos via CYP3A4, reduzindo drasticamente os níveis séricos de etinilestradiol e progestogênios.","efeito":"Redução de até 50–70% nos níveis hormonais contraceptivos — falha contraceptiva com risco de gravidez não planejada mesmo com uso correto do anticoncepcional. O risco persiste por até 28 dias após suspensão do indutor.","conduta":"❌ Não confiar no anticoncepcional oral como único método durante o uso do indutor. Associar método de barreira (preservativo) durante todo o tratamento e por 28 dias após suspensão do indutor. Para pacientes em uso crônico de antiepilépticos, avaliar com médico o uso de DIU hormonal ou implante (menos afetados pela indução enzimática)."},
{"med1":["azitromicina","claritromicina","eritromicina"],"med2":["amiodarona","haloperidol","quetiapina","ziprasidona","metadona","sotalol","dronedarona","domperidona","ondansetrom"],"nivel":"alto","titulo":"Macrolídeo + Prolongador de QT (Arritmia Fatal)","mecanismo":"Macrolídeos inibem canais cardíacos hERG (IKr), prolongando o intervalo QT. Associados a outros prolongadores de QT (antiarrítmicos, antipsicóticos, metadona), o efeito é aditivo. Eritromicina tem o maior risco; azitromicina também prolonga QT apesar de ser considerada mais segura.","efeito":"Prolongamento grave do intervalo QT → Torsades de Pointes → fibrilação ventricular e morte súbita. Risco aumentado em hipocalemia, hipomagnesemia, doença cardíaca prévia, sexo feminino e idosos.","conduta":"❌ Evitar a combinação. Substituir o macrolídeo por antibiótico sem risco QT (amoxicilina, cefalosporina, doxiciclina) quando possível. Se inevitável: realizar ECG basal, corrigir eletrólitos (K⁺, Mg²⁺) e monitorar ECG durante tratamento. Suspender imediatamente se QTc > 500 ms."},
{"med1":["ciprofloxacino","levofloxacino","moxifloxacino","norfloxacino","ofloxacino"],"med2":["amiodarona","haloperidol","quetiapina","ziprasidona","metadona","sotalol","dronedarona","azitromicina"],"nivel":"alto","titulo":"Quinolona + Prolongador de QT (Arritmia Fatal)","mecanismo":"Quinolonas inibem canais cardíacos hERG (IKr), prolongando o intervalo QT. Associadas a outros prolongadores de QT (antiarrítmicos, antipsicóticos, metadona), o efeito é aditivo e pode desencadear Torsades de Pointes.","efeito":"Prolongamento grave do intervalo QT → Torsades de Pointes (taquicardia ventricular polimórfica) → fibrilação ventricular e morte súbita. Risco aumentado em hipocalemia, hipomagnesemia, doença cardíaca prévia e sexo feminino.","conduta":"❌ Evitar a combinação. Substituir a quinolona por antibiótico sem risco QT (amoxicilina, cefalosporina) quando possível. Se inevitável: realizar ECG basal, corrigir eletrólitos (K⁺, Mg²⁺) e monitorar ECG durante o tratamento. Suspender imediatamente se QTc > 500 ms."},
{"med1":["amitriptilina","nortriptilina","imipramina","clomipramina"],"med2":["biperideno","oxibutinina","escopolamina","hioscina","solifenacina","tolterodina","prometazina"],"nivel":"alto","titulo":"Antidepressivo Tricíclico + Anticolinérgico (Síndrome Anticolinérgica Grave)","efeito":"Tricíclicos já têm forte ação anticolinérgica intrínseca. Somados a biperideno, oxibutinina, escopolamina ou similares, causam síndrome anticolinérgica: boca seca intensa, retenção urinária, constipação grave, visão turva, taquicardia, confusão mental, delirium e hipertermia. Idosos são especialmente vulneráveis — risco aumentado de hospitalização e morte.","conduta":"❌ Evitar a combinação. Se anticolinérgico for necessário (ex.: biperideno para parkinsonismo induzido por medicamento), avaliar substituição do tricíclico por antidepressivo com menor perfil anticolinérgico (sertralina, escitalopram). Monitorar sinais de toxicidade anticolinérgica com atenção redobrada em idosos."},
{"med1":["haloperidol","quetiapina","olanzapina","risperidona","clozapina","aripiprazol","ziprasidona","clorpromazina"],"med2":["alprazolam","clonazepam","diazepam","lorazepam","bromazepam","midazolam","zolpidem","zopiclona"],"nivel":"alto","titulo":"Antipsicótico + Benzodiazepínico / Hipnótico (Depressão do SNC)","efeito":"Antipsicóticos potencializam a depressão do SNC causada por benzodiazepínicos: sedação profunda, hipotensão postural, comprometimento da função respiratória e, em casos graves, parada respiratória. Clozapina e olanzapina têm risco especialmente elevado — casos de morte foram relatados com a associação de clozapina e benzodiazepínico intravenoso.","conduta":"⚠️ Usar com extrema cautela. Se necessário, iniciar benzodiazepínico na menor dose e pelo menor tempo possível. Monitorar nível de consciência e função respiratória. Clozapina + benzodiazepínico: contraindicado na fase de ajuste de dose (risco de colapso cardiorrespiratório). Evitar administração simultânea por via IM ou IV."},
{"med1":["warfarina","varfarina","apixabana","rivaroxabana","dabigatrana","edoxabana"],"med2":["ibuprofeno","naproxeno","diclofenaco","aspirina","ácido acetilsalicílico","aas","nimesulida","cetoprofeno","meloxicam","etoricoxibe","celecoxibe","indometacina"],"nivel":"alto","titulo":"Anticoagulante Oral + AINE / AAS (Sangramento Grave)","efeito":"Duplo risco: (1) AINEs inibem a função plaquetária e lesam a mucosa gástrica; (2) ibuprofeno, naproxeno e outros AINEs podem elevar níveis de warfarina (inibição CYP2C9) ou deslocar da proteína plasmática. O risco de hemorragia grave — digestiva ou intracraniana — é 3 a 5 vezes maior com a associação.","conduta":"❌ Evitar sempre que possível. Para dor ou febre prefira paracetamol (até 2 g/dia) ou dipirona. Se AINE for imprescindível: avaliar com médico, monitorar INR (warfarina) e sinais de sangramento. AAS 100 mg profilático pode ser mantido em casos selecionados com avaliação cardiológica."},
{"med1":["fluoxetina","sertralina","escitalopram","paroxetina","citalopram","venlafaxina","duloxetina","fluvoxamina","nortriptilina","amitriptilina","clomipramina"],"med2":["sumatriptana","rizatriptana","zolmitriptana","almotriptana","eletriptana","naratriptana","triptano"],"nivel":"alto","titulo":"Antidepressivo Serotoninérgico + Triptano (Síndrome Serotoninérgica)","efeito":"Antidepressivos ISRSs/IRSNs/tricíclicos aumentam serotonina; triptanos são agonistas 5-HT diretos. A soma pode desencadear síndrome serotoninérgica: agitação, confusão, tremores, mioclonias, hipertermia, instabilidade autonômica e risco de morte.","conduta":"⚠️ Associação possível sob vigilância médica estrita em casos muito específicos (enxaqueca refratária com depressão). Iniciar triptano na dose mínima. Suspender imediatamente se surgirem agitação, tremores ou febre."},
{"med1":["fluoxetina","sertralina","escitalopram","paroxetina","citalopram","venlafaxina","duloxetina","fluvoxamina"],"med2":["tramadol","codeína","morfina","fentanila","oxicodona","buprenorfina","tapentadol","opioide"],"nivel":"alto","titulo":"ISRS / IRSN + Opioide (Síndrome Serotoninérgica + Depressão Respiratória)","efeito":"Duplo risco: (1) tramadol, codeína e tapentadol inibem recaptação de serotonina — somado ao ISRS, risco de síndrome serotoninérgica (agitação, tremores, febre, convulsões); (2) todos os opioides potencializam a depressão respiratória, especialmente com morfina, fentanila e buprenorfina.","conduta":"❌ Tramadol com ISRS: evitar — alto risco de síndrome serotoninérgica. Para analgesia em pacientes com ISRS, prefira paracetamol, dipirona ou AINEs (se sem contraindicação). Se opioide for imprescindível, monitorar sinais serotoninérgicos e função respiratória."},
{"med1":["sinvastatina","atorvastatina","rosuvastatina","lovastatina","pravastatina","pitavastatina"],"med2":["sinvastatina","atorvastatina","rosuvastatina","lovastatina","pravastatina","pitavastatina"],"nivel":"moderado","titulo":"Duas Estatinas (Duplicação Terapêutica — Miopatia)","efeito":"Associar duas estatinas não traz benefício adicional no colesterol e eleva significativamente o risco de miopatia (dor e fraqueza muscular) e rabdomiólise (destruição muscular grave com risco de insuficiência renal aguda). O risco é dose-dependente e cumulativo.","conduta":"❌ Não há indicação clínica para usar duas estatinas simultâneas. Se o LDL não está controlado, a conduta correta é intensificar a dose da estatina atual ou associar ezetimiba — nunca adicionar outra estatina. Comunicar ao médico prescriptor."},
{"med1":["fluoxetina","sertralina","escitalopram","paroxetina","citalopram","venlafaxina","duloxetina","fluvoxamina"],"med2":["fluoxetina","sertralina","escitalopram","paroxetina","citalopram","venlafaxina","duloxetina","fluvoxamina"],"nivel":"alto","titulo":"Dois Antidepressivos ISRS / IRSN (Duplicação Terapêutica)","efeito":"Dois antidepressivos da mesma família somam a ação na serotonina — risco de síndrome serotoninérgica: agitação intensa, tremores, febre alta, convulsões e risco de morte. Trocar de ISRS exige período de washout orientado pelo médico.","conduta":"❌ Evitar usar dois ISRS/IRSN simultaneamente. Nunca substituir um pelo outro sem orientação médica e período de washout adequado."},
{"med1":["fluoxetina","sertralina","escitalopram","paroxetina","citalopram","venlafaxina","duloxetina","fluvoxamina"],"med2":["alprazolam","clonazepam","diazepam","lorazepam","bromazepam","midazolam","zolpidem","zopiclona"],"nivel":"moderado","titulo":"ISRS / IRSN + Benzodiazepínico / Hipnótico","efeito":"Potencialização da sedação do sistema nervoso central. Risco de sonolência excessiva, comprometimento psicomotor e, em doses altas, depressão respiratória. Fluoxetina e fluvoxamina também inibem CYP3A4, elevando níveis de alprazolam, clonazepam e zolpidem.","conduta":"⚠️ Usar com cautela. Iniciar benzodiazepínico na menor dose possível. Evitar dirigir ou operar máquinas. Preferir benzodiazepínicos de meia-vida curta. Fluoxetina e fluvoxamina requerem redução de dose do benzodiazepínico."},
{"med1":["alprazolam","clonazepam","diazepam","lorazepam","bromazepam","midazolam"],"med2":["zolpidem","zopiclona"],"nivel":"alto","titulo":"Benzodiazepínico + Hipnótico Z-drug (Duplicação Terapêutica)","efeito":"Dois depressores do SNC da mesma classe funcional. A combinação soma os efeitos sedativos — risco de sedação profunda, depressão respiratória e parada respiratória.","conduta":"❌ Evitar. Raramente há indicação clínica para usar os dois simultaneamente. Informar ao médico se recebeu as duas prescrições."},
{"med1":["alprazolam","clonazepam","diazepam","bromazepam","zolpidem","zopiclona"],"med2":["codeína","tramadol","morfina","fentanila","tapentadol","buprenorfina"],"nivel":"alto","titulo":"Benzodiazepínico / Hipnótico + Opioide (Depressão Respiratória Fatal)","mecanismo":"Benzodiazepínicos potencializam a inibição GABAérgica do SNC; opioides deprimem o drive respiratório via receptores μ no tronco cerebral. A combinação produz depressão respiratória sinérgica, não apenas aditiva — o risco é maior do que a soma dos efeitos individuais.","efeito":"Depressão respiratória grave, sedação profunda, hipoxemia e morte. Esta combinação é responsável pela maioria das mortes por overdose de medicamentos prescritos. O risco é máximo nas primeiras 24–48h de uso combinado, mas persiste durante todo o tratamento.","conduta":"❌ Evitar a associação sempre que possível — é a combinação medicamentosa mais letal na prática clínica. Se inevitável: usar as menores doses efetivas de ambos, reduzir opioides em 30–50% ao iniciar BZD, monitorar frequência respiratória e saturação de O₂ continuamente. Ter naloxona disponível. Orientar paciente e família sobre sinais de depressão respiratória (sonolência extrema, respiração lenta ou superficial). Nunca prescrever essa combinação para pacientes que usam álcool ou outras drogas depressoras do SNC."},
{"med1":["alprazolam","clonazepam","diazepam","bromazepam","zolpidem","zopiclona"],"med2":["álcool","alcool","bebida"],"nivel":"alto","titulo":"Benzodiazepínico / Hipnótico + Álcool","efeito":"Potencialização da sedação do SNC. Risco de depressão respiratória e morte.","conduta":"❌ Proibido. Álcool é contraindicado com benzodiazepínicos e hipnóticos."},
{"med1":["sildenafila","tadalafila","vardenafila","avanafila"],"med2":["nitroglicerina","nitrato","isossorbida","mononitrato de isossorbida","dinitrato de isossorbida"],"nivel":"alto","titulo":"Inibidor de PDE-5 + Nitratos (Hipotensão Grave Fatal)","mecanismo":"Inibidores de PDE-5 potencializam o relaxamento vascular mediado pelo óxido nítrico (NO). Os nitratos liberam NO diretamente. A combinação causa vasodilatação maciça pela via GMPc com queda precipitada da resistência vascular periférica.","efeito":"Hipotensão grave e súbita — queda de pressão arterial de 50–80 mmHg sistólica possível. Pode causar síncope, infarto do miocárdio por hipoperfusão coronariana e morte. Sem antídoto de ação rápida.","conduta":"❌ Contraindicação absoluta. Nenhuma dose é segura. Vale para todos os nitratos (nitroglicerina sublingual, spray, adesivo; isossorbida oral). Tadalafila: risco persiste por 48h após a última dose. Sildenafila: 24h. Em emergência cardíaca, se o paciente usou inibidor de PDE-5 recentemente, NÃO administrar nitratos — usar morfina ou outros vasodilatadores alternativos."},
{"med1":["warfarina","varfarina"],"med2":["ibuprofeno","diclofenaco","nimesulida","cetoprofeno","meloxicam","etoricoxibe","celecoxibe","aine"],"nivel":"alto","titulo":"Warfarina + Anti-inflamatório (AINE)","efeito":"AINEs aumentam muito o risco de sangramento grave em pacientes anticoagulados.","conduta":"❌ Evitar. Usar paracetamol ou dipirona para dor. Informar sempre ao médico."},
{"med1":["warfarina","varfarina"],"med2":["fluconazol","itraconazol","cetoconazol","ketoconazol","claritromicina","metronidazol","ciprofloxacino"],"nivel":"alto","titulo":"Warfarina + Antifúngico / Antibiótico","efeito":"Potencializam muito o efeito anticoagulante — risco de sangramento grave.","conduta":"❌ Monitorar INR com muita frequência. Ajustar dose com médico."},
{"med1":["metotrexato"],"med2":["ibuprofeno","naproxeno","diclofenaco","nimesulida","cetoprofeno","meloxicam","indometacina","aine","aspirina","ácido acetilsalicílico","aas"],"nivel":"alto","titulo":"Metotrexato + AINE / AAS","efeito":"AINEs e aspirina reduzem a eliminação renal do metotrexato, causando acúmulo e toxicidade grave na medula óssea (pancitopenia, mucosite, até morte).","conduta":"❌ Evitar. Inclui AAS — mesmo em doses analgésicas. Informar sempre ao reumatologista ou oncologista."},
{"med1":["dissulfiram"],"med2":["álcool","alcool","metronidazol","bebida"],"nivel":"alto","titulo":"Dissulfiram + Álcool / Metronidazol","efeito":"Reação grave: rubor intenso, vômito, taquicardia, hipotensão. Pode ser fatal.","conduta":"❌ Absolutamente contraindicado."},
{"med1":["lítio","carbonato de lítio"],"med2":["ibuprofeno","diclofenaco","captopril","enalapril","losartana","aine"],"nivel":"alto","titulo":"Lítio + AINE / IECA","efeito":"Elevação do nível sérico de lítio — risco de toxicidade grave (tremores, confusão, convulsões).","conduta":"❌ Monitorar níveis de lítio rigorosamente. Evitar AINE sem orientação."},
{"med1":["amiodarona"],"med2":["warfarina","varfarina"],"nivel":"alto","titulo":"Amiodarona + Warfarina","efeito":"Amiodarona potencializa fortemente o efeito anticoagulante da warfarina — risco de hemorragia grave.","conduta":"❌ Reduzir dose de warfarina em 30-50% e monitorar INR semanalmente."},
{"med1":["amiodarona"],"med2":["digoxina"],"nivel":"alto","titulo":"Amiodarona + Digoxina","efeito":"Amiodarona eleva os níveis de digoxina podendo causar intoxicação digitálica — arritmias graves.","conduta":"❌ Reduzir dose de digoxina pela metade. Monitorar nível sérico e ECG."},
{"med1":["amiodarona"],"med2":["sinvastatina","atorvastatina"],"nivel":"alto","titulo":"Amiodarona + Estatina","efeito":"Amiodarona inibe metabolismo das estatinas — risco aumentado de rabdomiólise e insuficiência renal.","conduta":"❌ Limitar dose de sinvastatina a 20mg/dia. Preferir rosuvastatina com cautela."},
{"med1":["carbamazepina"],"med2":["contraceptivo","etinilestradiol","levonorgestrel","desogestrel"],"nivel":"alto","titulo":"Carbamazepina + Anticoncepcional","efeito":"Carbamazepina acelera o metabolismo dos hormônios anticoncepcionais, reduzindo drasticamente a eficácia contraceptiva.","conduta":"❌ Usar método contraceptivo adicional (preservativo). Discutir alternativas com médico."},
{"med1":["carbamazepina"],"med2":["claritromicina","eritromicina","fluconazol","itraconazol"],"nivel":"alto","titulo":"Carbamazepina + Macrolídeo / Antifúngico","efeito":"Antibióticos/antifúngicos inibem metabolismo da carbamazepina — risco de toxicidade (diplopia, ataxia, confusão).","conduta":"❌ Evitar ou monitorar nível sérico de carbamazepina rigorosamente."},
{"med1":["isotretinoína","acitretina"],"med2":["tetraciclina","doxiciclina","minociclina"],"nivel":"alto","titulo":"Retinoide + Tetraciclina","efeito":"Combinação causa pseudotumor cerebri (hipertensão intracraniana) — cefaleia intensa, alteração visual, risco de perda de visão.","conduta":"❌ Contraindicado absolutamente. Nunca combinar."},
{"med1":["rasagilina","selegilina"],"med2":["tramadol","petidina","meperidina"],"nivel":"alto","titulo":"Inibidor MAO-B + Tramadol","efeito":"Risco de síndrome serotoninérgica grave e síndrome hipertensiva aguda — potencialmente fatal.","conduta":"❌ Contraindicado. Aguardar 14 dias após suspender o inibidor de MAO."},
{"med1":["rasagilina"],"med2":["fluoxetina","sertralina","escitalopram","paroxetina","venlafaxina"],"nivel":"alto","titulo":"Inibidor MAO-B + Antidepressivo","efeito":"Risco de síndrome serotoninérgica grave — agitação, hipertermia, convulsões, risco de morte.","conduta":"❌ Contraindicado. Aguardar 14 dias de washout entre os medicamentos."},
{"med1":["rivaroxabana","apixabana"],"med2":["ibuprofeno","diclofenaco","aine","aspirina","ácido acetilsalicílico"],"nivel":"alto","titulo":"Anticoagulante Oral (NOAC) + AINE / AAS","efeito":"Combinação multiplica o risco de sangramento gastrointestinal grave.","conduta":"❌ Evitar. Usar paracetamol para dor quando necessário. Consultar médico."},
{"med1":["tacrolimo"],"med2":["claritromicina","eritromicina","fluconazol","itraconazol","cetoconazol"],"nivel":"alto","titulo":"Tacrolimo + Macrolídeo / Antifúngico","efeito":"Inibem metabolismo do tacrolimo — concentrações tóxicas podem causar insuficiência renal aguda e neurotoxicidade.","conduta":"❌ Monitorar nível sérico de tacrolimo e função renal rigorosamente."},
{"med1":["digoxina"],"med2":["amiodarona","verapamil","diltiazem"],"nivel":"alto","titulo":"Digoxina + Antiarrítmico","efeito":"Verapamil, diltiazem e amiodarona elevam os níveis de digoxina — risco de intoxicação digitálica (bradicardia, arritmias).","conduta":"❌ Reduzir dose de digoxina. Monitorar nível sérico e ECG."},
{"med1":["clopidogrel"],"med2":["omeprazol","esomeprazol"],"nivel":"alto","titulo":"Clopidogrel + Omeprazol / Esomeprazol","efeito":"Omeprazol e esomeprazol inibem a ativação do clopidogrel — risco cardiovascular aumentado (infarto, trombose de stent).","conduta":"❌ Substituir por pantoprazol ou rabeprazol se IBP for necessário."},
{"med1":["fenitoína"],"med2":["fluconazol","itraconazol","claritromicina","amiodarona"],"nivel":"alto","titulo":"Fenitoína + Inibidores de CYP","efeito":"Elevam os níveis de fenitoína — risco de toxicidade (nistagmo, ataxia, confusão mental).","conduta":"❌ Monitorar nível sérico de fenitoína. Ajustar dose com médico."},
{"med1":["fluoxetina","sertralina","escitalopram","paroxetina","citalopram","venlafaxina","duloxetina"],"med2":["tramadol","tapentadol"],"nivel":"moderado","titulo":"Antidepressivo ISRS/IRSN + Tramadol","efeito":"Risco de síndrome serotoninérgica — agitação, tremores, febre e confusão mental.","conduta":"⚠️ Usar com cautela. Atenção a sintomas neurológicos."},
{"med1":["captopril","enalapril","losartana","valsartana","lisinopril","candesartana","ramipril","perindopril","irbesartana","olmesartana","telmisartana"],"med2":["espironolactona","eplerenona","potássio","suplemento de potássio","cloreto de potássio"],"nivel":"alto","titulo":"IECA / BRA + Potássio / Espironolactona (Hipercalemia Grave)","efeito":"IECAs e BRAs retêm potássio ao bloquear a aldosterona. Associados a espironolactona (também poupadora de potássio) ou suplementos de potássio, causam hipercalemia grave — potássio >6,5 mEq/L provoca arritmias ventriculares fatais e parada cardíaca.","conduta":"❌ Associação IECA/BRA + espironolactona requer monitoramento regular de potássio e função renal. Evitar suplementos de potássio sem prescrição. Risco aumentado em idosos, diabéticos e pacientes com doença renal crônica. Avaliar potássio em 1–2 semanas após início ou ajuste de dose."},
{"med1":["metformina"],"med2":["álcool","alcool"],"nivel":"moderado","titulo":"Metformina + Álcool","efeito":"Aumento do risco de acidose lática — acúmulo de ácido no sangue.","conduta":"⚠️ Evitar consumo excessivo de álcool."},
{"med1":["ibuprofeno","diclofenaco","nimesulida","aine"],"med2":["captopril","enalapril","losartana","atenolol","metoprolol","bisoprolol"],"nivel":"moderado","titulo":"AINE + Anti-hipertensivo","efeito":"AINEs podem reduzir o efeito anti-hipertensivo e piorar a função renal.","conduta":"⚠️ Usar com cautela. Preferir paracetamol para dor em hipertensos."},
{"med1":["paracetamol"],"med2":["álcool","alcool"],"nivel":"moderado","titulo":"Paracetamol + Álcool","efeito":"Álcool aumenta risco de hepatotoxicidade com paracetamol, especialmente em doses altas ou uso crônico.","conduta":"⚠️ Evitar paracetamol em altas doses em quem bebe regularmente."},
{"med1":["metronidazol"],"med2":["álcool","alcool","bebida"],"nivel":"moderado","titulo":"Metronidazol + Álcool","efeito":"Reação tipo dissulfiram — rubor, náusea, taquicardia. Evitar álcool durante e 48h após o tratamento.","conduta":"⚠️ Proibido álcool durante o tratamento e por 48 horas após a última dose."},
{"med1":["fluoroquinolona","ciprofloxacino","levofloxacino","moxifloxacino"],"med2":["antiácido","cálcio","magnésio","ferro","zinco"],"nivel":"moderado","titulo":"Fluoroquinolona + Antiácido / Minerais","efeito":"Antiácidos com alumínio, magnésio, cálcio, ferro e zinco quelam as fluoroquinolonas, reduzindo drasticamente a absorção.","conduta":"⚠️ Tomar fluoroquinolona 2 horas antes ou 6 horas depois de antiácidos e minerais."},
{"med1":["ciprofloxacino","levofloxacino"],"med2":["teofilina","cafeína"],"nivel":"moderado","titulo":"Fluoroquinolona + Teofilina / Cafeína","efeito":"Fluoroquinolonas inibem metabolismo da teofilina — risco de toxicidade (náusea, taquicardia, convulsões).","conduta":"⚠️ Monitorar nível sérico de teofilina e reduzir dose se necessário."},
{"med1":["doxiciclina","tetraciclina"],"med2":["antiácido","cálcio","ferro","magnésio","leite"],"nivel":"moderado","titulo":"Tetraciclina / Doxiciclina + Antiácido / Leite","efeito":"Cálcio, magnésio e ferro quelam as tetraciclinas, reduzindo muito a absorção e eficácia antibiótica.","conduta":"⚠️ Tomar 2 horas antes ou 3 horas depois de antiácidos, leite e suplementos minerais."},
{"med1":["levotiroxina"],"med2":["cálcio","ferro","antiácido","colestiramina"],"nivel":"moderado","titulo":"Levotiroxina + Cálcio / Ferro / Antiácido","efeito":"Reduzem absorção da levotiroxina — hipotireoidismo pode não ser controlado adequadamente.","conduta":"⚠️ Tomar levotiroxina 30-60 minutos antes do café e 4 horas antes de suplementos minerais."},
{"med1":["glibenclamida","glicazida","glimepirida"],"med2":["fluconazol","ciprofloxacino","claritromicina"],"nivel":"moderado","titulo":"Sulfonilureia + Antibiótico / Antifúngico","efeito":"Potencialização do efeito hipoglicemiante — risco de hipoglicemia grave.","conduta":"⚠️ Monitorar glicemia com frequência durante o tratamento combinado."},
{"med1":["semaglutida","liraglutida","tirzepatida"],"med2":["insulina","sulfonilureia","glibenclamida"],"nivel":"moderado","titulo":"GLP-1 + Insulina / Sulfonilureia","efeito":"Combinação potencializa a redução da glicose — risco aumentado de hipoglicemia.","conduta":"⚠️ Reduzir dose de insulina ou sulfonilureia ao iniciar GLP-1. Monitorar glicemia."},
{"med1":["dapagliflozina","empagliflozina","canagliflozina"],"med2":["diurético","furosemida","hidroclorotiazida"],"nivel":"moderado","titulo":"SGLT-2 + Diurético","efeito":"Combinação pode causar desidratação e hipotensão, especialmente em idosos.","conduta":"⚠️ Monitorar pressão arterial e sinais de desidratação. Ajustar doses."},
{"med1":["colchicina"],"med2":["claritromicina","eritromicina","cetoconazol","itraconazol"],"nivel":"moderado","titulo":"Colchicina + Macrolídeo / Antifúngico","efeito":"Inibem metabolismo da colchicina — risco de toxicidade grave (miopatia, mielossupressão, insuficiência de múltiplos órgãos).","conduta":"⚠️ Reduzir dose de colchicina ou evitar a combinação. Risco elevado."},
{"med1":["pregabalina","gabapentina"],"med2":["opioides","morfina","codeína","tramadol","fentanila"],"nivel":"moderado","titulo":"Pregabalina / Gabapentina + Opioide","efeito":"Potencialização da depressão respiratória e sedação — risco aumentado de overdose.","conduta":"⚠️ Usar com cautela. Monitorar função respiratória. Evitar em pacientes de alto risco."},
{"med1":["pregabalina","gabapentina"],"med2":["álcool","alcool","benzodiazepínico","alprazolam","diazepam"],"nivel":"moderado","titulo":"Pregabalina / Gabapentina + Álcool / BZD","efeito":"Potencialização da sedação do SNC — tontura, confusão, risco de quedas.","conduta":"⚠️ Evitar álcool. Usar benzodiazepínico com muita cautela e em doses mínimas."},
{"med1":["rifampicina"],"med2":["warfarina","varfarina"],"nivel":"moderado","titulo":"Rifampicina + Warfarina","efeito":"Rifampicina reduz muito o efeito anticoagulante da warfarina — risco de trombose.","conduta":"⚠️ Aumentar dose de warfarina e monitorar INR frequentemente."},
{"med1":["isoniazida"],"med2":["fenitoína","carbamazepina"],"nivel":"moderado","titulo":"Isoniazida + Anticonvulsivante","efeito":"Isoniazida inibe metabolismo da fenitoína e carbamazepina — risco de toxicidade neurológica.","conduta":"⚠️ Monitorar nível sérico dos anticonvulsivantes. Ajustar doses."},
{"med1":["fluoxetina","paroxetina","sertralina","escitalopram"],"med2":["sumatriptana","rizatriptana","triptano"],"nivel":"moderado","titulo":"ISRS + Triptano","efeito":"Risco de síndrome serotoninérgica leve a moderada — cefaleia, agitação, tremores, sudorese.","conduta":"⚠️ Usar com cautela. Monitorar sintomas após a combinação. Orientar o paciente."},
{"med1":["haloperidol","quetiapina","risperidona","olanzapina"],"med2":["lítio","carbonato de lítio"],"nivel":"moderado","titulo":"Antipsicótico + Lítio","efeito":"Risco aumentado de neurotoxicidade — sintomas extrapiramidais, síndrome neuroléptica maligna em casos raros.","conduta":"⚠️ Monitorar nível sérico de lítio e sinais neurológicos regularmente."},
{"med1":["bupropiona"],"med2":["tramadol","antidepressivo","amitriptilina","venlafaxina"],"nivel":"moderado","titulo":"Bupropiona + Tramadol / Antidepressivo","efeito":"Risco aumentado de convulsões — especialmente com tramadol. Bupropiona já abaixa o limiar convulsivante.","conduta":"⚠️ Evitar tramadol com bupropiona. Monitorar se combinação de antidepressivos for necessária."},
{"med1":["verapamil","diltiazem"],"med2":["sinvastatina","atorvastatina"],"nivel":"moderado","titulo":"Verapamil / Diltiazem + Estatina","efeito":"Inibem metabolismo das estatinas — risco de miopatia e rabdomiólise, especialmente com sinvastatina.","conduta":"⚠️ Limitar sinvastatina a 10mg/dia. Preferir rosuvastatina ou pravastatina."},
{"med1":["mirtazapina"],"med2":["álcool","alcool","benzodiazepínico","diazepam","alprazolam"],"nivel":"moderado","titulo":"Mirtazapina + Álcool / Benzodiazepínico","efeito":"Potencialização da sedação — sonolência intensa, comprometimento psicomotor, risco de quedas.","conduta":"⚠️ Evitar álcool. Usar benzodiazepínico com cautela e preferir doses baixas."},
{"med1":["amitriptilina","nortriptilina","imipramina","clomipramina"],"med2":["tramadol"],"nivel":"alto","titulo":"Antidepressivo Tricíclico + Tramadol (Síndrome Serotoninérgica)","mecanismo":"Antidepressivos tricíclicos inibem recaptação de serotonina e noradrenalina; tramadol inibe recaptação de serotonina e tem ação opioide fraca. A combinação precipita síndrome serotoninérgica por efeito aditivo, e o tramadol baixa o limiar convulsivante já afetado pelos tricíclicos.","efeito":"Síndrome serotoninérgica — agitação, confusão, febre, rigidez muscular, mioclonias e instabilidade autonômica (taquicardia, hipertensão). Em casos graves: rabdomiólise, convulsões e morte. O risco convulsivo é particularmente elevado nessa combinação.","conduta":"❌ Evitar a combinação sempre que possível. Se imprescindível: tramadol em doses mínimas por curto período, com vigilância intensiva para síndrome serotoninérgica. Para analgesia em pacientes em uso de tricíclicos, preferir paracetamol, dipirona ou AINEs. Interromper imediatamente ao primeiro sinal (agitação, tremores, febre) e buscar atendimento de emergência."},
{"med1":["sulfametoxazol","sulfametoxazol + trimetoprima"],"med2":["warfarina","varfarina"],"nivel":"moderado","titulo":"Sulfametoxazol-Trimetoprima + Warfarina","efeito":"Potencializa muito o efeito anticoagulante — risco elevado de sangramento.","conduta":"⚠️ Monitorar INR frequentemente durante e após o antibiótico."},
{"med1":["sulfametoxazol","sulfametoxazol + trimetoprima"],"med2":["captopril","enalapril","losartana","espironolactona"],"nivel":"moderado","titulo":"Sulfametoxazol-Trimetoprima + IECA / Espironolactona","efeito":"Trimetoprima bloqueia excreção renal de potássio — risco de hipercalemia grave com IECA ou espironolactona.","conduta":"⚠️ Monitorar potássio sérico durante o tratamento combinado."},
{"med1":["alopurinol"],"med2":["amoxicilina","ampicilina"],"nivel":"moderado","titulo":"Alopurinol + Amoxicilina / Ampicilina","efeito":"Combinação aumenta muito o risco de erupção cutânea alérgica (rash maculopapular).","conduta":"⚠️ Informar médico e farmacêutico. Monitorar surgimento de lesões na pele."},
{"med1":["espironolactona"],"med2":["captopril","enalapril","lisinopril","losartana","valsartana"],"nivel":"moderado","titulo":"Espironolactona + IECA / BRA","efeito":"Ambos elevam o potássio — risco de hipercalemia grave com arritmias potencialmente fatais.","conduta":"⚠️ Monitorar potássio regularmente. Evitar suplementos de potássio."},
{"med1":["furosemida","hidroclorotiazida","clortalidona","indapamida","clorotiazida"],"med2":["lítio","carbonato de lítio"],"nivel":"alto","titulo":"Diurético + Lítio (Toxicidade por Lítio)","efeito":"Diuréticos — especialmente tiazídicos (hidroclorotiazida, clortalidona) — reduzem a excreção renal de lítio ao promover retenção compensatória de sódio no túbulo proximal. O nível sérico de lítio pode dobrar, causando toxicidade: tremores grosseiros, confusão, ataxia, convulsões e danos renais permanentes. Furosemida tem risco menor, mas significativo.","conduta":"❌ Iniciar ou ajustar diurético em paciente com lítio requer monitoramento do nível sérico de lítio em 5–7 dias. Considerar redução de dose do lítio. Orientar paciente a manter hidratação adequada e ingestão de sal estável — restrição de sódio agrava a retenção de lítio."},
{"med1":["metilfenidato","lisdexanfetamina"],"med2":["inibidor de mao","isocarboxazida"],"nivel":"moderado","titulo":"Estimulante TDAH + Inibidor de MAO","efeito":"Risco de crise hipertensiva grave e síndrome serotoninérgica.","conduta":"⚠️ Contraindicado. Aguardar 14 dias após suspender inibidor de MAO."},
{"med1":["metilfenidato","lisdexanfetamina"],"med2":["antidepressivo","amitriptilina","imipramina"],"nivel":"moderado","titulo":"Estimulante TDAH + Antidepressivo Tricíclico","efeito":"Estimulantes elevam nível sérico dos tricíclicos — risco de arritmias e toxicidade cardiovascular.","conduta":"⚠️ Monitorar ECG e pressão arterial. Usar doses mínimas necessárias."},
{"med1":["donepezila","rivastigmina"],"med2":["biperideno","escopolamina","oxibutinina","amitriptilina"],"nivel":"moderado","titulo":"Inibidor de Colinesterase + Anticolinérgico","efeito":"Mecanismos opostos — anticolinérgicos antagonizam completamente o efeito do inibidor de colinesterase.","conduta":"⚠️ Evitar a combinação. Revisar necessidade de anticolinérgico com médico."},
{"med1":["haloperidol","quetiapina","risperidona","olanzapina","clozapina"],"med2":["metoclopramida","domperidona"],"nivel":"moderado","titulo":"Antipsicótico + Metoclopramida / Domperidona","efeito":"Todos bloqueiam dopamina — risco aumentado de efeitos extrapiramidais e síndrome neuroléptica maligna.","conduta":"⚠️ Evitar a combinação. Usar ondansetrom como alternativa antiemética."},
{"med1":["ondansetrom"],"med2":["amiodarona","haloperidol","azitromicina","moxifloxacino"],"nivel":"moderado","titulo":"Ondansetrom + Prolongadores de QT","efeito":"Combinação de medicamentos que prolongam o intervalo QT — risco de arritmia ventricular grave (Torsades de Pointes).","conduta":"⚠️ Evitar combinação. Se necessário, monitoramento com ECG."},
{"med1":["vareniclina"],"med2":["álcool","alcool"],"nivel":"moderado","titulo":"Vareniclina + Álcool","efeito":"Vareniclina pode aumentar os efeitos intoxicantes do álcool e reduzir a tolerância.","conduta":"⚠️ Limitar consumo de álcool durante o tratamento de cessação do tabagismo."},
{"med1":["topiramato"],"med2":["contraceptivo","etinilestradiol"],"nivel":"moderado","titulo":"Topiramato + Anticoncepcional Hormonal","efeito":"Topiramato em doses altas reduz eficácia dos anticoncepcionais hormonais.","conduta":"⚠️ Usar método contraceptivo adicional ou considerar anticoncepcional de alta dose."},
{"med1":["isotretinoína"],"med2":["vitamina a","suplemento vitamina a"],"nivel":"moderado","titulo":"Isotretinoína + Vitamina A","efeito":"Ambos são retinoides — combinação causa hipervitaminose A com cefaleia, náusea, descamação grave.","conduta":"⚠️ Suspender suplementos de vitamina A durante o tratamento com isotretinoína."},
{"med1":["melatonina"],"med2":["fluvoxamina","cimetidina"],"nivel":"moderado","titulo":"Melatonina + Fluvoxamina / Cimetidina","efeito":"Inibem metabolismo da melatonina — concentrações podem ficar muito elevadas causando sedação excessiva.","conduta":"⚠️ Reduzir dose de melatonina. Monitorar sedação."},
{"med1":["ômega-3"],"med2":["warfarina","varfarina","rivaroxabana","clopidogrel"],"nivel":"moderado","titulo":"Ômega-3 + Anticoagulante / Antiagregante","efeito":"Em doses altas, ômega-3 tem efeito antiagregante plaquetário — pode potencializar sangramento.","conduta":"⚠️ Informar médico sobre uso de ômega-3. Monitorar sinais de sangramento."},
{"med1":["zinco"],"med2":["ciprofloxacino","levofloxacino","doxiciclina","tetraciclina"],"nivel":"moderado","titulo":"Zinco + Antibiótico","efeito":"Zinco quela e reduz absorção de fluoroquinolonas e tetraciclinas — eficácia antibiótica comprometida.","conduta":"⚠️ Tomar antibiótico 2 horas antes ou 6 horas depois do zinco."},
{"med1":["magnésio"],"med2":["ciprofloxacino","levofloxacino","doxiciclina","levotiroxina"],"nivel":"moderado","titulo":"Magnésio + Antibiótico / Levotiroxina","efeito":"Magnésio quela e reduz absorção de fluoroquinolonas, tetraciclinas e levotiroxina.","conduta":"⚠️ Separar a administração por no mínimo 2-4 horas."},
{"med1":["desmopressina"],"med2":["ibuprofeno","diclofenaco","aine"],"nivel":"moderado","titulo":"Desmopressina + AINE","efeito":"AINEs potencializam o efeito antidiurético da desmopressina — risco de hiponatremia (sódio baixo).","conduta":"⚠️ Monitorar sódio sérico. Evitar AINE ou usar com cautela."},
{"med1":["paracetamol"],"med2":["dipirona"],"nivel":"baixo","titulo":"Paracetamol + Dipirona","efeito":"Combinação geralmente segura em doses normais. Pode potencializar o efeito analgésico.","conduta":"✅ Pode ser usada sob orientação médica. Respeitar as doses máximas."},
{"med1":["ibuprofeno","diclofenaco"],"med2":["paracetamol"],"nivel":"baixo","titulo":"AINE + Paracetamol","efeito":"Combinação segura e frequentemente usada para potencializar analgesia. Mecanismos complementares.","conduta":"✅ Combinação válida. Respeitar as doses máximas de cada medicamento."},
{"med1":["omeprazol","pantoprazol","lansoprazol"],"med2":["ibuprofeno","diclofenaco","aine","aspirina"],"nivel":"baixo","titulo":"IBP + AINE (combinação protetora)","efeito":"O IBP protege a mucosa gástrica dos danos causados pelos AINEs. Combinação frequentemente recomendada.","conduta":"✅ Combinação adequada e protetora. Usar pelo menor tempo necessário."},
{"med1":["ácido fólico"],"med2":["metotrexato"],"nivel":"baixo","titulo":"Ácido Fólico + Metotrexato","efeito":"O ácido fólico reduz toxicidade do metotrexato (mucosite, náusea) sem reduzir sua eficácia terapêutica.","conduta":"✅ Combinação recomendada. Tomar ácido fólico 24h após a dose semanal de metotrexato."},
{"med1":["furosemida"],"med2":["espironolactona"],"nivel":"baixo","titulo":"Furosemida + Espironolactona","efeito":"Combinação diurética complementar — furosemida perde potássio e espironolactona poupa, equilibrando o efeito.","conduta":"✅ Combinação frequentemente intencional. Monitorar eletrólitos periodicamente."},
{"med1":["metformina"],"med2":["semaglutida","liraglutida","sitagliptina","linagliptina"],"nivel":"baixo","titulo":"Metformina + Antidiabético (complementar)","efeito":"Combinação de mecanismos complementares para controle glicêmico. Amplamente recomendada.","conduta":"✅ Combinação padrão no tratamento do DM2. Monitorar glicemia regularmente."},
{"med1":["atorvastatina","rosuvastatina","sinvastatina"],"med2":["ezetimiba"],"nivel":"baixo","titulo":"Estatina + Ezetimiba","efeito":"Combinação complementar para redução do colesterol — mecanismos diferentes e sinérgicos.","conduta":"✅ Combinação recomendada para dislipidemia resistente à estatina isolada."},
{"med1":["anlodipino","nifedipina"],"med2":["atorvastatina","sinvastatina"],"nivel":"baixo","titulo":"Anlodipino + Estatina","efeito":"Anlodipino pode aumentar levemente os níveis de sinvastatina — efeito clínico geralmente irrelevante.","conduta":"✅ Combinação geralmente segura. Limitar sinvastatina a 20mg com anlodipino."},
{"med1":["captopril","enalapril","losartana"],"med2":["diurético","hidroclorotiazida","furosemida"],"nivel":"baixo","titulo":"IECA / BRA + Diurético","efeito":"Combinação anti-hipertensiva clássica e muito utilizada. Efeitos complementares.","conduta":"✅ Combinação amplamente recomendada. Monitorar pressão e eletrólitos."},
{"med1":["aspirina","ácido acetilsalicílico"],"med2":["clopidogrel"],"nivel":"baixo","titulo":"AAS + Clopidogrel (dupla antiagregação)","efeito":"Dupla antiagregação plaquetária — aumento do risco de sangramento, mas indicada em situações específicas (stent coronariano, SCA).","conduta":"✅ Combinação indicada em contextos cardiovasculares específicos. Monitorar sangramentos."},
{"med1":["vitamina d","colecalciferol"],"med2":["cálcio"],"nivel":"baixo","titulo":"Vitamina D + Cálcio","efeito":"Combinação sinérgica — vitamina D aumenta a absorção intestinal de cálcio. Amplamente recomendada.","conduta":"✅ Combinação ideal para prevenção de osteoporose. Respeitar doses adequadas."},
{"med1":["clozapina"],"med2":["ciprofloxacino","levofloxacino","claritromicina"],"nivel":"alto","titulo":"Clozapina + Antibiótico Inibidor de CYP1A2","efeito":"Antibióticos elevam drasticamente os níveis de clozapina — risco de convulsões, agranulocitose e toxicidade grave.","conduta":"❌ Monitorar nível sérico de clozapina e hemograma rigorosamente."},
{"med1":["clozapina"],"med2":["carbamazepina","fenitoína"],"nivel":"alto","titulo":"Clozapina + Carbamazepina / Fenitoína","efeito":"Indutores enzimáticos reduzem muito os níveis de clozapina. Carbamazepina também potencializa agranulocitose.","conduta":"❌ Evitar carbamazepina com clozapina. Monitorar nível sérico."},
{"med1":["metotrexato"],"med2":["sulfametoxazol","trimetoprima","sulfametoxazol + trimetoprima"],"nivel":"alto","titulo":"Metotrexato + Sulfametoxazol-Trimetoprima","efeito":"Ambos inibem o folato — risco extremo de mielossupressão grave, pancitopenia e toxicidade fatal.","conduta":"❌ Contraindicado. Se inevitável, monitoramento hematológico intensivo."},
{"med1":["tacrolimo"],"med2":["ibuprofeno","diclofenaco","aine","nimesulida"],"nivel":"alto","titulo":"Imunossupressor + AINE","efeito":"AINEs potencializam nefrotoxicidade do tacrolimo — risco de insuficiência renal aguda.","conduta":"❌ Evitar AINEs. Usar paracetamol. Monitorar função renal."},
{"med1":["fentanila","morfina","codeína","tramadol"],"med2":["álcool","alcool"],"nivel":"alto","titulo":"Opioide + Álcool","efeito":"Potencialização da depressão do SNC e respiratória — risco muito alto de overdose fatal.","conduta":"❌ Proibido. Álcool é contraindicado com qualquer opioide."},
{"med1":["naltrexona"],"med2":["codeína","morfina","tramadol","fentanila"],"nivel":"alto","titulo":"Naltrexona + Opioide","efeito":"Naltrexona bloqueia completamente o efeito dos opioides e precipita abstinência grave em dependentes.","conduta":"❌ Nunca iniciar naltrexona sem estar limpo de opioides há pelo menos 7-10 dias."},
{"med1":["bupropiona"],"med2":["álcool","alcool"],"nivel":"moderado","titulo":"Bupropiona + Álcool","efeito":"Álcool reduz o limiar convulsivante já baixo da bupropiona — risco aumentado de convulsões.","conduta":"⚠️ Evitar ou minimizar muito o consumo de álcool durante o tratamento."},
{"med1":["quetiapina","olanzapina","risperidona"],"med2":["álcool","alcool"],"nivel":"moderado","titulo":"Antipsicótico + Álcool","efeito":"Potencialização da sedação, hipotensão ortostática e comprometimento cognitivo.","conduta":"⚠️ Evitar álcool. Risco aumentado de quedas e acidentes."},
{"med1":["metoclopramida"],"med2":["levodopa","carbidopa + levodopa"],"nivel":"moderado","titulo":"Metoclopramida + Levodopa","efeito":"Metoclopramida antagoniza o efeito da levodopa no SNC — piora dos sintomas parkinsonianos.","conduta":"⚠️ Contraindicado em parkinsonianos. Usar domperidona como alternativa antiemética."},
{"med1":["trazodona"],"med2":["fluoxetina","paroxetina","sertralina","escitalopram"],"nivel":"moderado","titulo":"Trazodona + ISRS","efeito":"Risco de síndrome serotoninérgica leve e potencialização da sedação — hipotensão ortostática aumentada.","conduta":"⚠️ Iniciar trazodona em dose baixa. Monitorar pressão ao levantar."},
{"med1":["dapagliflozina","empagliflozina","canagliflozina"],"med2":["insulina","insulina nph","insulina regular"],"nivel":"moderado","titulo":"SGLT-2 + Insulina","efeito":"Combinação eficaz mas com risco de cetoacidose diabética euglicêmica — glicose pode parecer normal.","conduta":"⚠️ Reduzir dose de insulina ao iniciar SGLT-2. Monitorar cetones."},
{"med1":["pioglitazona"],"med2":["insulina","insulina nph"],"nivel":"moderado","titulo":"Pioglitazona + Insulina","efeito":"Combinação potencializa retenção de líquidos — risco de edema e insuficiência cardíaca descompensada.","conduta":"⚠️ Contraindicado em insuficiência cardíaca. Monitorar retenção hídrica."},
{"med1":["colchicina"],"med2":["atorvastatina","sinvastatina","rosuvastatina"],"nivel":"moderado","titulo":"Colchicina + Estatina","efeito":"Combinação aumenta risco de miopatia — ambos podem causar dano muscular com risco aditivo.","conduta":"⚠️ Monitorar sintomas musculares. Usar dose mínima eficaz de colchicina."},
{"med1":["alopurinol"],"med2":["warfarina","varfarina"],"nivel":"moderado","titulo":"Alopurinol + Warfarina","efeito":"Alopurinol pode inibir metabolismo da warfarina — potencialização do efeito anticoagulante.","conduta":"⚠️ Monitorar INR após iniciar ou ajustar alopurinol."},
{"med1":["ciprofloxacino","levofloxacino"],"med2":["warfarina","varfarina"],"nivel":"moderado","titulo":"Fluoroquinolona + Warfarina","efeito":"Fluoroquinolonas potencializam o efeito anticoagulante da warfarina — risco de sangramento.","conduta":"⚠️ Monitorar INR durante e após o antibiótico."},
{"med1":["azitromicina"],"med2":["warfarina","varfarina"],"nivel":"moderado","titulo":"Azitromicina + Warfarina","efeito":"Azitromicina pode potencializar o efeito da warfarina.","conduta":"⚠️ Monitorar INR durante o tratamento com azitromicina."},
{"med1":["isotretinoína"],"med2":["álcool","alcool"],"nivel":"moderado","titulo":"Isotretinoína + Álcool","efeito":"Álcool potencializa hepatotoxicidade e eleva triglicerídeos — dois efeitos da isotretinoína.","conduta":"⚠️ Evitar álcool durante todo o tratamento. Monitorar perfil lipídico."},
{"med1":["tamsulosina","silodosina"],"med2":["sildenafila","tadalafila"],"nivel":"moderado","titulo":"Alfabloqueador + Inibidor PDE-5","efeito":"Combinação causa hipotensão ortostática significativa — risco de síncope nas primeiras doses.","conduta":"⚠️ Iniciar inibidor PDE-5 na menor dose. Não tomar junto com alfabloqueador."},
{"med1":["colestiramina","colestipol"],"med2":["levotiroxina","digoxina","warfarina","paracetamol"],"nivel":"moderado","titulo":"Colestiramina / Colestipol + Vários Medicamentos","efeito":"Resinas quelam praticamente todos os medicamentos no intestino — redução da absorção de quase qualquer fármaco.","conduta":"⚠️ Tomar TODOS os outros medicamentos 1h antes ou 4-6h depois das resinas."},
{"med1":["carbamazepina"],"med2":["varfarina","warfarina"],"nivel":"moderado","titulo":"Carbamazepina + Warfarina","efeito":"Carbamazepina induz metabolismo da warfarina — redução do efeito anticoagulante.","conduta":"⚠️ Monitorar INR frequentemente. Pode ser necessário aumentar dose de warfarina."},
{"med1":["fenitoína"],"med2":["contraceptivo","etinilestradiol","levonorgestrel"],"nivel":"moderado","titulo":"Fenitoína + Anticoncepcional","efeito":"Fenitoína induz metabolismo dos hormônios contraceptivos — redução significativa da eficácia.","conduta":"⚠️ Usar método contraceptivo adicional. Considerar anticoncepcionais alternativos."},
{"med1":["lamotrigina"],"med2":["contraceptivo","etinilestradiol","levonorgestrel"],"nivel":"moderado","titulo":"Lamotrigina + Anticoncepcional Hormonal","efeito":"Anticoncepcionais reduzem os níveis de lamotrigina em até 50% — perda de controle das crises epilépticas.","conduta":"⚠️ Ajustar dose de lamotrigina ao iniciar ou parar anticoncepcional."},
{"med1":["sumatriptana","rizatriptana"],"med2":["ergotamina"],"nivel":"moderado","titulo":"Triptano + Ergotamina","efeito":"Ambos causam vasoconstrição — combinação pode causar isquemia grave.","conduta":"⚠️ Não usar triptano dentro de 24h após ergotamina e vice-versa."},
{"med1":["denosumabe"],"med2":["cálcio","vitamina d"],"nivel":"moderado","titulo":"Denosumabe + Cálcio / Vitamina D (obrigatório)","efeito":"Denosumabe causa hipocalcemia — cálcio e vitamina D devem ser suplementados obrigatoriamente.","conduta":"⚠️ Suplementação de cálcio e vitamina D é OBRIGATÓRIA com denosumabe."},
{"med1":["ácido zoledrónico","alendronato"],"med2":["cálcio","vitamina d"],"nivel":"moderado","titulo":"Bisfosfonato + Cálcio / Vitamina D","efeito":"Bisfosfonatos requerem cálcio e vitamina D adequados — deficiência compromete a eficácia.","conduta":"⚠️ Suplementar cálcio e vitamina D antes e durante o tratamento."},
{"med1":["epoetina","eritropoetina","epoetina alfa","epoetina beta","alfaepoetina"],"med2":["ferro","sulfato ferroso","ferro sacarato","ferro iv","ferro oral"],"nivel":"moderado","titulo":"Eritropoetina + Ferro (necessário)","efeito":"A eritropoetina requer estoques de ferro adequados para funcionar — sem ferro suficiente, a resposta eritropoiética falha mesmo com dose adequada.","conduta":"⚠️ Garantir ferritina e saturação de transferrina adequadas antes e durante o tratamento. Suplementação de ferro oral ou IV é frequentemente necessária."},
{"med1":["epoetina","eritropoetina","epoetina alfa","epoetina beta","alfaepoetina"],"med2":["enalapril","losartana","captopril","lisinopril","amlodipino","anlodipino","atenolol","bisoprolol","metoprolol","carvedilol","hidroclorotiazida","furosemida","nifedipina","verapamil","diltiazem","espironolactona"],"nivel":"moderado","titulo":"Eritropoetina + Anti-hipertensivos","efeito":"A eritropoetina aumenta a produção de glóbulos vermelhos e eleva a viscosidade sanguínea, causando aumento da pressão arterial — pode reduzir a eficácia dos anti-hipertensivos ou descompensar hipertensão previamente controlada.","conduta":"⚠️ Monitorar pressão arterial regularmente durante o tratamento. Pode ser necessário ajuste ou intensificação da terapia anti-hipertensiva."},
{"med1":["epoetina","eritropoetina","epoetina alfa","epoetina beta","alfaepoetina"],"med2":["heparina","enoxaparina"],"nivel":"moderado","titulo":"Eritropoetina + Heparina","efeito":"A eritropoetina pode aumentar a agregação plaquetária e a trombogenicidade — a combinação com heparina é comum em pacientes em hemodiálise, mas exige atenção ao risco trombótico vascular e de oclusão do circuito de diálise.","conduta":"⚠️ Monitorar sinais de trombose vascular ou fistula arteriovenosa. Ajuste de dose de heparina pode ser necessário conforme resposta eritropoiética."},
{"med1":["epoetina","eritropoetina","epoetina alfa","epoetina beta","alfaepoetina"],"med2":["talidomida","lenalidomida","pomalidomida"],"nivel":"alto","titulo":"Eritropoetina + Talidomida / Imunomoduladores — RISCO DE TROMBOSE","efeito":"Combinação com alto potencial trombogênico: talidomida e seus análogos já aumentam significativamente o risco de trombose venosa profunda (TVP) e embolia pulmonar. A eritropoetina, ao aumentar a viscosidade sanguínea, potencializa esse risco de forma aditiva — risco de evento tromboembólico grave.","conduta":"🚨 ATENÇÃO: Combinação de alto risco trombótico. Profilaxia anticoagulante é geralmente obrigatória. Monitorar sinais e sintomas de TVP e embolia pulmonar. Rever relação risco-benefício da eritropoetina com a equipe médica."},
{"med1":["escopolamina","hioscina"],"med2":["amitriptilina","prometazina","biperideno","oxibutinina"],"nivel":"moderado","titulo":"Múltiplos Anticolinérgicos","efeito":"Efeitos anticolinérgicos cumulativos — boca seca intensa, retenção urinária, confusão mental, delirium em idosos.","conduta":"⚠️ Evitar múltiplos anticolinérgicos. Revisar polifarmácia com médico."},
{"med1":["rifampicina"],"med2":["fluconazol","itraconazol"],"nivel":"moderado","titulo":"Rifampicina + Antifúngico Azólico","efeito":"Rifampicina induz metabolismo dos azólicos — redução drástica da eficácia antifúngica.","conduta":"⚠️ Evitar combinação ou aumentar dose do antifúngico com monitoramento."},
{"med1":["metformina"],"med2":["vitamina b12","cianocobalamina"],"nivel":"baixo","titulo":"Metformina + Vitamina B12 (monitorar)","efeito":"Metformina reduz absorção de vitamina B12 com uso prolongado — risco de deficiência e neuropatia.","conduta":"✅ Monitorar vitamina B12 a cada 1-2 anos. Suplementar se níveis baixos."},
{"med1":["prednisona","dexametasona","hidrocortisona"],"med2":["cálcio","vitamina d"],"nivel":"baixo","titulo":"Corticoide + Cálcio / Vitamina D (protetora)","efeito":"Corticoides causam perda óssea — suplementação de cálcio e vitamina D é protetora no uso crônico.","conduta":"✅ Suplementação recomendada em uso crônico de corticoides."},
{"med1":["isoniazida"],"med2":["vitamina b6","piridoxina"],"nivel":"baixo","titulo":"Isoniazida + Vitamina B6 (protetora)","efeito":"Isoniazida causa deficiência de B6 — neuropatia periférica preventível com suplementação.","conduta":"✅ Suplementar vitamina B6 (10-50mg/dia) durante todo o tratamento com isoniazida."},
{"med1":["prednisona","dexametasona"],"med2":["omeprazol","pantoprazol"],"nivel":"baixo","titulo":"Corticoide + IBP (protetora)","efeito":"Corticoides em doses altas aumentam risco de úlcera — IBP é protetor gástrico recomendado.","conduta":"✅ IBP indicado no uso de corticoides sistêmicos por mais de 2 semanas."},
{"med1":["sinvastatina","atorvastatina","rosuvastatina"],"med2":["ubiquinona"],"nivel":"baixo","titulo":"Estatina + Coenzima Q10","efeito":"Estatinas reduzem síntese de CoQ10 — suplementação pode reduzir miopatia induzida por estatina.","conduta":"✅ CoQ10 (100-200mg/dia) é seguro e pode ajudar com dores musculares por estatina."},
{"med1":["sertralina","escitalopram","fluoxetina"],"med2":["ômega-3"],"nivel":"baixo","titulo":"ISRS + Ômega-3","efeito":"Ômega-3 pode ter efeito sinérgico antidepressivo — combinação frequentemente usada.","conduta":"✅ Combinação segura e potencialmente benéfica."},
{"med1":["warfarina","varfarina"],"med2":["aspirina","ácido acetilsalicílico","aas"],"nivel":"alto","titulo":"Warfarina + Aspirina","mecanismo":"A aspirina inibe a agregação plaquetária e pode causar lesão gástrica, potencializando o risco hemorrágico da warfarina por dois mecanismos distintos.","efeito":"Risco muito elevado de sangramento grave — gástrico, intestinal ou cerebral — pela soma do efeito anticoagulante com o antiagregante.","conduta":"❌ Evitar a combinação salvo indicação cardiológica específica (ex: stent). Usar a menor dose de AAS possível e monitorar INR."},
{"med1":["warfarina","varfarina"],"med2":["vitamina k","couve","espinafre","brócolis","repolho"],"nivel":"moderado","titulo":"Warfarina + Alimentos com Vitamina K","mecanismo":"A vitamina K é cofator dos fatores de coagulação que a warfarina bloqueia. Variações na ingestão alimentar alteram diretamente o INR.","efeito":"Consumo irregular de alimentos ricos em vitamina K (couve, espinafre, brócolis) provoca oscilações no INR — ora sub, ora suprateraupêutico.","conduta":"⚠️ Manter consumo constante (não eliminar) de vegetais folhosos. Informar médico sobre mudanças na dieta."},
{"med1":["warfarina","varfarina"],"med2":["álcool","alcool","bebida alcoólica"],"nivel":"moderado","titulo":"Warfarina + Álcool","mecanismo":"Uso agudo inibe o metabolismo da warfarina (aumenta INR); uso crônico induz enzimas hepáticas (reduz INR). Efeito paradoxal e imprevisível.","efeito":"Oscilação imprevisível do INR — tanto risco de sangramento quanto de trombose, além de risco de queda com trauma.","conduta":"⚠️ Evitar consumo de álcool. Monitorar INR com mais frequência em quem bebe."},
{"med1":["warfarina","varfarina"],"med2":["cranberry","suco de cranberry","arando"],"nivel":"moderado","titulo":"Warfarina + Cranberry","mecanismo":"O cranberry inibe CYP2C9 — a enzima responsável pelo metabolismo da warfarina — elevando seus níveis séricos.","efeito":"Aumento do efeito anticoagulante com risco de sangramento. Vários relatos de INR elevado após consumo de suco de cranberry.","conduta":"⚠️ Evitar suco de cranberry. Se necessário, monitorar INR com mais frequência."},
{"med1":["warfarina","varfarina"],"med2":["vitamina e","tocoferol"],"nivel":"moderado","titulo":"Warfarina + Vitamina E","mecanismo":"Vitamina E em doses altas (>400 UI/dia) interfere no metabolismo da vitamina K e inibe a agregação plaquetária, potencializando a anticoagulação.","efeito":"Aumento do INR e risco de sangramento com doses elevadas de vitamina E.","conduta":"⚠️ Evitar suplementação de vitamina E acima de 200 UI/dia durante uso de warfarina."},
{"med1":["warfarina","varfarina"],"med2":["erva de são joão","hipérico","hypericum"],"nivel":"alto","titulo":"Warfarina + Erva de São João","mecanismo":"A erva de São João é potente indutora de CYP2C9 e P-glicoproteína, acelerando o metabolismo e a eliminação da warfarina.","efeito":"Redução drástica do efeito anticoagulante — risco de trombose, AVC isquêmico e TEP.","conduta":"❌ Contraindicado. Suspender erva de São João e monitorar INR. Efeito persiste por semanas após suspensão."},
{"med1":["warfarina","varfarina"],"med2":["ginkgo biloba","ginkgo"],"nivel":"moderado","titulo":"Warfarina + Ginkgo Biloba","mecanismo":"O ginkgo biloba inibe o fator ativador plaquetário e tem ação antiagregante própria, potencializando o risco hemorrágico.","efeito":"Risco aumentado de sangramento, especialmente cerebral. Vários casos relatados na literatura.","conduta":"⚠️ Evitar uso de ginkgo biloba com anticoagulantes. Informar médico sobre uso de fitoterápicos."},
{"med1":["warfarina","varfarina"],"med2":["alho","suplemento de alho"],"nivel":"moderado","titulo":"Warfarina + Alho (Suplemento)","mecanismo":"O alho tem ação antiagregante plaquetária pela inibição da síntese do tromboxano A2, somando-se ao efeito anticoagulante.","efeito":"Potencialização do risco de sangramento. Doses culinárias são geralmente seguras; suplementos concentrados são o risco.","conduta":"⚠️ Evitar suplementos de alho. Consumo culinário moderado é geralmente tolerado com monitoramento."},
{"med1":["warfarina","varfarina"],"med2":["fenitoína","hidantoína"],"nivel":"moderado","titulo":"Warfarina + Fenitoína","mecanismo":"Interação bidirecional complexa: inicialmente a fenitoína inibe o metabolismo da warfarina (eleva INR), depois induz enzimas (reduz INR). A warfarina também pode elevar ou reduzir os níveis de fenitoína.","efeito":"Oscilações imprevisíveis no INR e nos níveis de fenitoína — risco tanto de sangramento quanto de trombose e toxicidade neurológica.","conduta":"⚠️ Monitorar INR e nível sérico de fenitoína frequentemente ao iniciar ou ajustar qualquer um dos medicamentos."},
{"med1":["warfarina","varfarina"],"med2":["colestiramina","colestipol"],"nivel":"moderado","titulo":"Warfarina + Colestiramina","mecanismo":"A colestiramina liga-se à warfarina no intestino (e também à vitamina K), reduzindo a absorção do anticoagulante e alterando o ciclo entero-hepático.","efeito":"Redução da eficácia anticoagulante — risco de trombose.","conduta":"⚠️ Tomar warfarina 1 hora antes ou 4–6 horas depois da colestiramina. Monitorar INR."},
{"med1":["warfarina","varfarina"],"med2":["doxiciclina"],"nivel":"moderado","titulo":"Warfarina + Doxiciclina","mecanismo":"A doxiciclina reduz a flora intestinal produtora de vitamina K e pode inibir levemente o metabolismo da warfarina, potencializando o efeito anticoagulante.","efeito":"Aumento do INR e risco de sangramento durante o tratamento antibiótico.","conduta":"⚠️ Monitorar INR durante o tratamento com doxiciclina. Ajustar dose se necessário."},
{"med1":["warfarina","varfarina"],"med2":["levofloxacino","levofloxacina"],"nivel":"moderado","titulo":"Warfarina + Levofloxacino","mecanismo":"O levofloxacino inibe levemente CYP1A2 e reduz a flora intestinal produtora de vitamina K, aumentando o efeito da warfarina.","efeito":"Elevação do INR com risco de sangramento durante o uso do antibiótico.","conduta":"⚠️ Monitorar INR durante e após o tratamento com levofloxacino."},
{"med1":["warfarina","varfarina"],"med2":["voriconazol"],"nivel":"alto","titulo":"Warfarina + Voriconazol","mecanismo":"O voriconazol inibe fortemente CYP2C9 e CYP3A4, bloqueando o metabolismo da warfarina e elevando muito seus níveis plasmáticos.","efeito":"Aumento muito expressivo do INR — risco de sangramento grave.","conduta":"❌ Reduzir dose de warfarina em 50% ao iniciar voriconazol. Monitorar INR com muita frequência."},
{"med1":["warfarina","varfarina"],"med2":["eritromicina"],"nivel":"moderado","titulo":"Warfarina + Eritromicina","mecanismo":"A eritromicina inibe CYP3A4 e reduz a flora intestinal produtora de vitamina K, potencializando o efeito anticoagulante.","efeito":"Elevação do INR com risco de sangramento.","conduta":"⚠️ Monitorar INR durante o tratamento. Preferir azitromicina se disponível."},
{"med1":["warfarina","varfarina"],"med2":["tramadol","codeína","codeina"],"nivel":"moderado","titulo":"Warfarina + Opioide (Tramadol / Codeína)","mecanismo":"O tramadol inibe CYP2C9 de forma dose-dependente, reduzindo o metabolismo da warfarina e elevando o INR. A codeína pode exercer efeito similar através de metabólitos ativos.","efeito":"Potencialização do efeito anticoagulante — risco de sangramento.","conduta":"⚠️ Monitorar INR ao iniciar ou suspender o opioide. Preferir paracetamol para analgesia quando possível."},
{"med1":["warfarina","varfarina"],"med2":["paracetamol","acetaminofeno"],"nivel":"moderado","titulo":"Warfarina + Paracetamol (uso crônico)","mecanismo":"O paracetamol inibe a síntese de fatores de coagulação dependentes de vitamina K por mecanismo ainda incerto, potencializando o efeito anticoagulante. O efeito é dose-dependente e se manifesta sobretudo com uso regular (≥1,5 g/dia por mais de 3 dias).","efeito":"Elevação significativa do INR com risco de sangramento, especialmente em doses elevadas e uso prolongado.","conduta":"⚠️ Paracetamol é a analgesia preferida sobre AINEs, mas não é isento de risco. Limitar a ≤2 g/dia e monitorar INR ao usar regularmente."},
{"med1":["warfarina","varfarina"],"med2":["omeprazol","pantoprazol","lansoprazol","esomeprazol","rabeprazol","ibp","inibidor de bomba de prótons"],"nivel":"moderado","titulo":"Warfarina + Inibidor de Bomba de Prótons (IBP)","mecanismo":"O omeprazol (e em menor grau o esomeprazol) inibe CYP2C19, via secundária de metabolismo da varfarina S, podendo elevar seus níveis plasmáticos. O pantoprazol apresenta menor interação.","efeito":"Elevação moderada do INR, com risco de sangramento. O efeito varia conforme o IBP utilizado.","conduta":"⚠️ Monitorar INR ao iniciar, trocar ou suspender IBP. Preferir pantoprazol ou rabeprazol quando possível."},
{"med1":["warfarina","varfarina"],"med2":["amoxicilina","ampicilina","amoxicilina + clavulanato","penicilina"],"nivel":"moderado","titulo":"Warfarina + Penicilina / Amoxicilina","mecanismo":"Antibióticos de amplo espectro alteram a flora intestinal redutora de vitamina K, diminuindo a produção endógena dessa vitamina e potencializando o efeito anticoagulante.","efeito":"Elevação do INR com risco de sangramento, geralmente moderado e transitório.","conduta":"⚠️ Monitorar INR durante e após o curso do antibiótico. Manter dieta habitual em vitamina K."},
{"med1":["warfarina","varfarina"],"med2":["levotiroxina","tiroxina","t4"],"nivel":"moderado","titulo":"Warfarina + Levotiroxina","mecanismo":"O excesso de hormônio tireoidiano aumenta o catabolismo de fatores de coagulação dependentes de vitamina K, potencializando o efeito da warfarina. Hipotireoidismo tem efeito inverso.","efeito":"Aumento do INR e risco de sangramento quando levotiroxina eleva o estado tireoidiano. Ajuste de dose mútuo frequentemente necessário.","conduta":"⚠️ Monitorar INR ao iniciar, ajustar ou suspender levotiroxina. Manter função tireoidiana estável."},
{"med1":["warfarina","varfarina"],"med2":["leflunomida"],"nivel":"moderado","titulo":"Warfarina + Leflunomida","mecanismo":"O metabólito ativo da leflunomida (teriflunomida) inibe CYP2C9, principal via de metabolismo da warfarina S.","efeito":"Aumento do INR e risco de sangramento, especialmente no início do tratamento com leflunomida.","conduta":"⚠️ Monitorar INR frequentemente ao iniciar ou suspender leflunomida."},
{"med1":["heparina","heparina não fracionada"],"med2":["ibuprofeno","diclofenaco","nimesulida","cetoprofeno","meloxicam","aine","ketorolaco"],"nivel":"alto","titulo":"Heparina + AINE","mecanismo":"AINEs inibem agregação plaquetária e danificam a mucosa gástrica, somando-se ao efeito anticoagulante da heparina por mecanismos complementares.","efeito":"Risco muito elevado de sangramento grave, especialmente gastrointestinal.","conduta":"❌ Evitar a combinação. Usar paracetamol para analgesia. Informar equipe de saúde."},
{"med1":["heparina","heparina não fracionada","enoxaparina","nadroparina","dalteparina"],"med2":["clopidogrel","ticagrelor","prasugrel"],"nivel":"moderado","titulo":"Heparina / HBPM + Antiagregante Plaquetário","mecanismo":"Ação anticoagulante da heparina somada à inibição plaquetária do antiagregante — mecanismos duplos de hemostasia bloqueados.","efeito":"Aumento significativo do risco de sangramento. Combinação às vezes necessária em SCA — requer monitoramento.","conduta":"⚠️ Combinação usada em síndrome coronariana aguda com supervisão cardiológica. Monitorar sinais de sangramento."},
{"med1":["enoxaparina","nadroparina","dalteparina"],"med2":["ibuprofeno","diclofenaco","nimesulida","aine","ketorolaco"],"nivel":"alto","titulo":"Heparina de Baixo Peso Molecular + AINE","mecanismo":"AINEs inibem plaquetas e agridem mucosa gástrica; HBPMs bloqueiam a cascata de coagulação — risco hemorrágico aditivo.","efeito":"Risco elevado de sangramento grave, especialmente em pós-operatório ou pacientes internados.","conduta":"❌ Evitar AINEs em pacientes anticoagulados com HBPM. Usar paracetamol."},
{"med1":["rivaroxabana"],"med2":["claritromicina","eritromicina"],"nivel":"alto","titulo":"Rivaroxabana + Macrolídeo","mecanismo":"Macrolídeos inibem CYP3A4 e P-glicoproteína — as duas vias de eliminação da rivaroxabana — causando acúmulo do anticoagulante.","efeito":"Aumento dos níveis de rivaroxabana com risco elevado de sangramento grave.","conduta":"❌ Evitar a combinação. Se necessário, monitorar sinais de sangramento e considerar alternativa antibiótica."},
{"med1":["rivaroxabana"],"med2":["itraconazol","cetoconazol","voriconazol","posaconazol"],"nivel":"alto","titulo":"Rivaroxabana + Antifúngico Azólico","mecanismo":"Azólicos inibem fortemente CYP3A4 e P-glicoproteína, bloqueando as duas principais vias de eliminação da rivaroxabana.","efeito":"Aumento expressivo dos níveis de rivaroxabana — risco de sangramento grave.","conduta":"❌ Contraindicado com itraconazol, cetoconazol e voriconazol. Usar fluconazol com cautela e monitoramento."},
{"med1":["rivaroxabana"],"med2":["carbamazepina","fenitoína","fenobarbital","rifampicina"],"nivel":"alto","titulo":"Rivaroxabana + Indutor Enzimático Potente","mecanismo":"Indutores de CYP3A4 e P-glicoproteína aceleram o metabolismo da rivaroxabana, reduzindo drasticamente seus níveis plasmáticos.","efeito":"Perda do efeito anticoagulante — risco de trombose, AVC e embolia.","conduta":"❌ Contraindicado. Substituir rivaroxabana por warfarina (monitorável) ou avaliar alternativas com cardiologista."},
{"med1":["rivaroxabana"],"med2":["verapamil","diltiazem"],"nivel":"moderado","titulo":"Rivaroxabana + Verapamil / Diltiazem","mecanismo":"Verapamil e diltiazem inibem P-glicoproteína e moderadamente CYP3A4, aumentando a exposição à rivaroxabana.","efeito":"Aumento dos níveis de rivaroxabana — risco moderado de sangramento aumentado.","conduta":"⚠️ Usar com cautela. Monitorar sinais de sangramento. Avaliar benefício-risco individualmente."},
{"med1":["apixabana"],"med2":["claritromicina","eritromicina"],"nivel":"alto","titulo":"Apixabana + Macrolídeo","mecanismo":"Macrolídeos inibem CYP3A4 e P-glicoproteína, as duas principais vias de eliminação da apixabana, causando seu acúmulo.","efeito":"Elevação dos níveis de apixabana com risco de sangramento grave.","conduta":"❌ Evitar a combinação. Considerar alternativa antibiótica ou reduzir dose de apixabana com orientação médica."},
{"med1":["apixabana"],"med2":["itraconazol","cetoconazol","voriconazol"],"nivel":"alto","titulo":"Apixabana + Antifúngico Azólico","mecanismo":"Inibição dupla de CYP3A4 e P-glicoproteína pelos azólicos leva ao acúmulo de apixabana no organismo.","efeito":"Risco elevado de sangramento grave por concentrações excessivas de apixabana.","conduta":"❌ Contraindicado com azólicos potentes. Reduzir dose ou substituir apixabana com orientação médica."},
{"med1":["apixabana"],"med2":["carbamazepina","fenitoína","fenobarbital","rifampicina"],"nivel":"alto","titulo":"Apixabana + Indutor Enzimático Potente","mecanismo":"Indutores potentes de CYP3A4 e P-glicoproteína aceleram o metabolismo da apixabana, reduzindo seus níveis em até 50%.","efeito":"Perda do efeito anticoagulante — risco de trombose e embolia.","conduta":"❌ Contraindicado. Substituir por warfarina monitorada ou ajustar sob supervisão de especialista."},
{"med1":["apixabana"],"med2":["verapamil","diltiazem"],"nivel":"moderado","titulo":"Apixabana + Verapamil / Diltiazem","mecanismo":"Inibição parcial de P-glicoproteína e CYP3A4 eleva moderadamente os níveis de apixabana.","efeito":"Aumento moderado do risco de sangramento.","conduta":"⚠️ Usar com cautela. Considerar redução de dose de apixabana. Monitorar sinais de sangramento."},
{"med1":["apixabana","rivaroxabana"],"med2":["amiodarona"],"nivel":"moderado","titulo":"NOAC + Amiodarona","mecanismo":"A amiodarona inibe P-glicoproteína e CYP3A4, aumentando moderadamente os níveis dos NOACs.","efeito":"Elevação dos níveis de apixabana ou rivaroxabana — risco aumentado de sangramento.","conduta":"⚠️ Monitorar sinais de sangramento. Avaliar redução de dose do NOAC com o médico."},
{"med1":["digoxina"],"med2":["quinidina"],"nivel":"alto","titulo":"Digoxina + Quinidina","mecanismo":"A quinidina inibe a P-glicoproteína e reduz a secreção tubular renal da digoxina, duplicando ou triplicando seus níveis séricos.","efeito":"Intoxicação digitálica grave — náusea, bradicardia, bloqueio AV, arritmias ventriculares potencialmente fatais.","conduta":"❌ Reduzir dose de digoxina em 50% ao iniciar quinidina. Monitorar nível sérico e ECG diariamente."},
{"med1":["digoxina"],"med2":["eritromicina","claritromicina"],"nivel":"alto","titulo":"Digoxina + Macrolídeo","mecanismo":"Macrolídeos eliminam a flora intestinal que degrada digoxina no intestino — aumentam a absorção. Também inibem P-glicoproteína renal, reduzindo eliminação.","efeito":"Elevação dos níveis de digoxina — risco de intoxicação (bradicardia, bloqueio AV, vômitos, visão amarelada).","conduta":"❌ Monitorar nível sérico de digoxina e ECG durante o uso de macrolídeo. Reduzir dose se necessário."},
{"med1":["digoxina"],"med2":["itraconazol","cetoconazol","fluconazol"],"nivel":"alto","titulo":"Digoxina + Antifúngico Azólico","mecanismo":"Azólicos inibem P-glicoproteína intestinal e renal, reduzindo a eliminação da digoxina e elevando seus níveis plasmáticos.","efeito":"Risco de intoxicação digitálica — bradicardia, bloqueio AV, arritmias.","conduta":"❌ Monitorar nível sérico de digoxina e ECG ao iniciar antifúngico. Reduzir dose de digoxina."},
{"med1":["digoxina"],"med2":["ciclosporina"],"nivel":"alto","titulo":"Digoxina + Ciclosporina","mecanismo":"A ciclosporina inibe fortemente a P-glicoproteína renal e intestinal, aumentando substancialmente os níveis de digoxina.","efeito":"Intoxicação digitálica grave com risco de arritmias fatais.","conduta":"❌ Reduzir dose de digoxina em 50%. Monitorar nível sérico frequentemente."},
{"med1":["digoxina"],"med2":["furosemida","hidroclorotiazida","diurético tiazídico"],"nivel":"alto","titulo":"Digoxina + Diurético (Hipocalemia)","mecanismo":"Diuréticos de alça e tiazídicos causam perda de potássio. A hipocalemia aumenta dramaticamente a toxicidade da digoxina ao potencializar sua ligação ao miocárdio.","efeito":"Mesmo em níveis \"normais\" de digoxina, a hipocalemia pode precipitar arritmias graves e bloqueio AV.","conduta":"❌ Monitorar potássio sérico regularmente. Manter potássio >4 mEq/L. Suplementar potássio conforme necessário."},
{"med1":["digoxina"],"med2":["colestiramina","colestipol"],"nivel":"moderado","titulo":"Digoxina + Colestiramina","mecanismo":"As resinas quelam a digoxina no intestino e interrompem seu ciclo entero-hepático, reduzindo sua absorção e eficácia.","efeito":"Redução dos níveis de digoxina — possível perda do controle do ritmo cardíaco.","conduta":"⚠️ Tomar digoxina 1 hora antes ou 4–6 horas depois da colestiramina."},
{"med1":["amiodarona"],"med2":["propranolol","atenolol","metoprolol","bisoprolol","carvedilol"],"nivel":"alto","titulo":"Amiodarona + Betabloqueador","mecanismo":"Ambos têm efeito cronotrópico e dromotrópico negativo — a combinação pode causar bradicardia e bloqueio AV sinérgico e excessivo.","efeito":"Bradicardia grave, bloqueio atrioventricular e possível parada cardíaca.","conduta":"❌ Usar apenas sob monitoramento cardiológico rigoroso com ECG. Reduzir dose de betabloqueador."},
{"med1":["amiodarona"],"med2":["verapamil","diltiazem"],"nivel":"alto","titulo":"Amiodarona + Verapamil / Diltiazem","mecanismo":"Triplo efeito negativo no nó sinusal e AV: cronotropismo, dromotropismo e inotropismo negativos, podendo levar ao colapso cardiovascular.","efeito":"Bradicardia extrema, bloqueio AV completo, insuficiência cardíaca e parada cardíaca.","conduta":"❌ Contraindicado na maioria dos casos. Se inevitável, apenas em UTI com monitoramento contínuo."},
{"med1":["amiodarona"],"med2":["ciprofloxacino","levofloxacino","moxifloxacino","norfloxacino"],"nivel":"alto","titulo":"Amiodarona + Quinolona (Prolongamento QT — Arritmia Fatal)","mecanismo":"Ambos prolongam o intervalo QT por mecanismos diferentes: amiodarona bloqueia canais de potássio (IKr); quinolonas inibem canais cardíacos hERG. O efeito é aditivo e imprevisível.","efeito":"Prolongamento grave do intervalo QT — risco elevado de Torsades de Pointes (taquicardia ventricular polimórfica) que pode degenerar em fibrilação ventricular e morte súbita.","conduta":"❌ Contraindicado. Substituir a quinolona por antibiótico sem risco QT (amoxicilina, azitromicina com cautela, cefalosporina). Se inevitável, monitorar ECG contínuo em ambiente hospitalar."},
{"med1":["amiodarona"],"med2":["haloperidol","quetiapina","ziprasidona"],"nivel":"moderado","titulo":"Amiodarona + Antipsicótico (QT)","mecanismo":"Prolongamento aditivo do intervalo QT por bloqueio de diferentes canais de potássio cardíacos.","efeito":"Risco de Torsades de Pointes e fibrilação ventricular.","conduta":"⚠️ Evitar a combinação. Se necessário, monitorar ECG e manter QTc <500ms."},
{"med1":["propranolol","atenolol","metoprolol","bisoprolol","carvedilol"],"med2":["adrenalina","epinefrina"],"nivel":"moderado","titulo":"Betabloqueador + Adrenalina / Epinefrina","mecanismo":"Betabloqueadores bloqueiam os receptores β2-adrenérgicos vasodilatadores, deixando a ação vasoconstritora α (adrenalina) sem oposição — crise hipertensiva paradoxal.","efeito":"Crise hipertensiva grave com bradicardia reflexa — especialmente se epinefrina for usada em anestesia local ou tratamento de anafilaxia.","conduta":"⚠️ Avisar dentista/anestesista sobre uso de betabloqueador. Em anafilaxia, a dose de adrenalina pode precisar ser maior."},
{"med1":["propranolol","atenolol","metoprolol","bisoprolol"],"med2":["clonidina"],"nivel":"moderado","titulo":"Betabloqueador + Clonidina","mecanismo":"Ao suspender a clonidina abruptamente, há liberação de noradrenalina. O betabloqueador bloqueia os receptores β vasodilatadores, potencializando vasoconstrição pela ativação α desimpedida — hipertensão rebote grave.","efeito":"Hipertensão rebote grave e potencialmente fatal se a clonidina for suspensa abruptamente.","conduta":"⚠️ Nunca suspender clonidina abruptamente. Se descontinuar, retirar o betabloqueador primeiro."},
{"med1":["propranolol","atenolol","metoprolol","bisoprolol","carvedilol"],"med2":["ibuprofeno","diclofenaco","nimesulida","aine"],"nivel":"moderado","titulo":"Betabloqueador + AINE","mecanismo":"AINEs inibem a síntese de prostaglandinas vasodilatadoras e retêm sódio, antagonizando o efeito anti-hipertensivo dos betabloqueadores.","efeito":"Redução do efeito anti-hipertensivo — pressão arterial pode aumentar. Risco aumentado em cardiopatas.","conduta":"⚠️ Preferir paracetamol para analgesia. Monitorar pressão arterial."},
{"med1":["propranolol","metoprolol"],"med2":["teofilina"],"nivel":"moderado","titulo":"Betabloqueador + Teofilina","mecanismo":"Betabloqueadores (especialmente não seletivos como propranolol) bloqueiam receptores β2 brônquicos, antagonizando o broncodilatador efeito da teofilina. Também reduzem clearance da teofilina.","efeito":"Broncoespasmo em pacientes com asma/DPOC e possível elevação dos níveis de teofilina com toxicidade.","conduta":"⚠️ Evitar betabloqueadores não seletivos em asmáticos. Monitorar teofilina e função pulmonar."},
{"med1":["propranolol","atenolol","metoprolol","bisoprolol","carvedilol"],"med2":["digoxina"],"nivel":"moderado","titulo":"Betabloqueador + Digoxina","mecanismo":"Ambos reduzem a condução pelo nó AV (efeito dromotrópico negativo) por mecanismos complementares — bloqueio adrenérgico e aumento do tônus vagal.","efeito":"Bradicardia excessiva e bloqueio atrioventricular, especialmente em idosos.","conduta":"⚠️ Monitorar frequência cardíaca e ECG. Usar doses mínimas necessárias."},
{"med1":["captopril","enalapril","lisinopril","ramipril","perindopril"],"med2":["aliskiren"],"nivel":"alto","titulo":"IECA + Aliskiren (Duplo Bloqueio)","mecanismo":"Ambos bloqueiam o sistema renina-angiotensina-aldosterona por vias diferentes — duplo bloqueio causa hipotensão grave, hipercalemia e lesão renal aguda.","efeito":"Hipotensão sintomática grave, hipercalemia e insuficiência renal aguda — especialmente em diabéticos.","conduta":"❌ Contraindicado. A combinação IECA + aliskiren foi proibida em diabéticos pelo risco de eventos cardiovasculares e renais."},
{"med1":["captopril","enalapril","lisinopril"],"med2":["losartana","valsartana","candesartana","olmesartana"],"nivel":"alto","titulo":"IECA + BRA (Duplo Bloqueio do SRAA)","mecanismo":"Dupla inibição do sistema renina-angiotensina-aldosterona por mecanismos complementares não oferece benefício adicional, mas multiplica os efeitos adversos.","efeito":"Hipotensão grave, hipercalemia e insuficiência renal aguda. Nenhum benefício cardiovascular adicional demonstrado.","conduta":"❌ Contraindicado. Estudos ONTARGET e VA NEPHRON-D demonstraram dano. Não combinar IECA com BRA."},
{"med1":["losartana","valsartana","candesartana","olmesartana"],"med2":["aliskiren"],"nivel":"alto","titulo":"BRA + Aliskiren","mecanismo":"Duplo bloqueio do SRAA — inibição da renina (aliskiren) somada ao bloqueio do receptor AT1 (BRA) causa hipotensão, hipercalemia e insuficiência renal.","efeito":"Hipotensão grave, hipercalemia e lesão renal aguda.","conduta":"❌ Contraindicado. Especialmente em diabéticos e pacientes com IRC."},
{"med1":["losartana","valsartana","candesartana"],"med2":["ibuprofeno","diclofenaco","nimesulida","aine"],"nivel":"moderado","titulo":"BRA + AINE","mecanismo":"AINEs inibem prostaglandinas vasodilatadoras renais e retêm sódio, antagonizando o efeito anti-hipertensivo dos BRAs e reduzindo o fluxo sanguíneo renal.","efeito":"Redução do efeito anti-hipertensivo e piora da função renal — especialmente perigoso em idosos e diabéticos.","conduta":"⚠️ Preferir paracetamol. Monitorar pressão arterial e função renal."},
{"med1":["anlodipino","nifedipina"],"med2":["tacrolimo"],"nivel":"moderado","titulo":"Bloqueador de Canal de Cálcio + Tacrolimo","mecanismo":"O anlodipino inibe CYP3A4, a principal via de metabolismo do tacrolimo, elevando seus níveis séricos e risco de toxicidade.","efeito":"Elevação dos níveis de tacrolimo com risco de nefrotoxicidade e neurotoxicidade.","conduta":"⚠️ Monitorar nível sérico de tacrolimo ao iniciar ou suspender bloqueador de canal de cálcio."},
{"med1":["nifedipina","felodipina"],"med2":["suco de toranja","toranja","grapefruit"],"nivel":"moderado","titulo":"Nifedipina / Felodipina + Toranja","mecanismo":"O suco de toranja inibe CYP3A4 intestinal — a principal via de metabolismo das diidropiridinas — elevando substancialmente sua biodisponibilidade.","efeito":"Aumento dos níveis de nifedipina/felodipina com hipotensão, taquicardia reflexa e rubor.","conduta":"⚠️ Evitar suco de toranja durante uso de nifedipina ou felodipina."},
{"med1":["ivabradina"],"med2":["claritromicina","eritromicina","itraconazol","cetoconazol","voriconazol"],"nivel":"alto","titulo":"Ivabradina + Inibidor Forte de CYP3A4","mecanismo":"Inibidores fortes de CYP3A4 bloqueiam o metabolismo da ivabradina, elevando seus níveis plasmáticos em 7–8 vezes.","efeito":"Bradicardia grave e arritmias — concentrações excessivas de ivabradina bloqueiam canais If cardíacos em excesso.","conduta":"❌ Contraindicado. Suspender ivabradina durante tratamento com macrolídeos ou antifúngicos azólicos."},
{"med1":["ivabradina"],"med2":["diltiazem","verapamil"],"nivel":"alto","titulo":"Ivabradina + Diltiazem / Verapamil","mecanismo":"Diltiazem e verapamil inibem CYP3A4 e também reduzem a frequência cardíaca, gerando efeito bradicardizante aditivo somado ao acúmulo da ivabradina.","efeito":"Bradicardia grave e bloqueio sinusal.","conduta":"❌ Contraindicado. Usar anlodipino (sem interação) se bloqueador de canal de cálcio for necessário."},
{"med1":["ivabradina"],"med2":["amiodarona"],"nivel":"moderado","titulo":"Ivabradina + Amiodarona","mecanismo":"Efeito bradicardizante aditivo — ambos reduzem a frequência sinusal, podendo causar bradicardia sintomática.","efeito":"Bradicardia excessiva e tontura, especialmente em idosos.","conduta":"⚠️ Monitorar frequência cardíaca. Ajustar dose de ivabradina."},
{"med1":["sotalol"],"med2":["ciprofloxacino","levofloxacino","moxifloxacino"],"nivel":"alto","titulo":"Sotalol + Fluoroquinolona","mecanismo":"O sotalol bloqueia canais de potássio (IKr) e as quinolonas também afetam a repolarização cardíaca — prolongamento aditivo do QT.","efeito":"Risco elevado de Torsades de Pointes e fibrilação ventricular.","conduta":"❌ Contraindicado. Substituir por antibiótico alternativo sem efeito no QT."},
{"med1":["sotalol"],"med2":["amiodarona"],"nivel":"alto","titulo":"Sotalol + Amiodarona","mecanismo":"Ambos prolongam intensamente o intervalo QT pelo bloqueio de canais de potássio cardíacos (IKr) — efeito aditivo e potencialmente fatal.","efeito":"Risco extremo de Torsades de Pointes e parada cardíaca.","conduta":"❌ Contraindicado. Nunca combinar dois antiarrítmicos que prolongam QT."},
{"med1":["sinvastatina"],"med2":["suco de toranja","toranja","grapefruit"],"nivel":"alto","titulo":"Sinvastatina + Toranja (Suco)","mecanismo":"O suco de toranja inibe CYP3A4 intestinal de forma irreversível, aumentando a biodisponibilidade da sinvastatina em até 16 vezes.","efeito":"Risco muito elevado de miopatia e rabdomiólise — destruição muscular com insuficiência renal aguda.","conduta":"❌ Evitar completamente suco de toranja com sinvastatina, atorvastatina ou lovastatina."},
{"med1":["atorvastatina"],"med2":["suco de toranja","toranja","grapefruit"],"nivel":"moderado","titulo":"Atorvastatina + Toranja","mecanismo":"A toranja inibe CYP3A4 intestinal, aumentando a biodisponibilidade da atorvastatina (efeito menor que na sinvastatina, pois atorvastatina tem mais rotas metabólicas).","efeito":"Aumento dos níveis de atorvastatina com risco aumentado de miopatia.","conduta":"⚠️ Evitar suco de toranja. Rosuvastatina e pravastatina são alternativas mais seguras."},
{"med1":["sinvastatina"],"med2":["ciclosporina"],"nivel":"alto","titulo":"Sinvastatina + Ciclosporina","mecanismo":"A ciclosporina inibe CYP3A4, OATP1B1/1B3 e P-glicoproteína, triplicando ou quadruplicando os níveis de sinvastatina.","efeito":"Risco muito alto de rabdomiólise e insuficiência renal aguda.","conduta":"❌ Contraindicado com sinvastatina. Usar rosuvastatina ≤10mg ou pravastatina com cautela em transplantados."},
{"med1":["rosuvastatina"],"med2":["ciclosporina"],"nivel":"alto","titulo":"Rosuvastatina + Ciclosporina","mecanismo":"A ciclosporina inibe o transportador OATP1B1, reduzindo a captação hepática de rosuvastatina e elevando seus níveis plasmáticos em ~10 vezes.","efeito":"Risco elevado de miopatia e rabdomiólise mesmo com a rosuvastatina.","conduta":"❌ Contraindicado com doses habituais. Se necessário, usar rosuvastatina 5mg/dia (dose máxima) sob supervisão."},
{"med1":["sinvastatina","atorvastatina"],"med2":["niacina","ácido nicotínico"],"nivel":"moderado","titulo":"Estatina + Niacina em Alta Dose","mecanismo":"A niacina em doses farmacológicas (>1g/dia) inibe a depuração de ácido lático muscular e potencializa a miopatia estatínica por mecanismo ainda incerto.","efeito":"Risco aumentado de miopatia e rabdomiólise — mais relevante com niacina >1g/dia.","conduta":"⚠️ Usar doses baixas de niacina. Monitorar CK e sintomas musculares. A FDA recomendou retirar a combinação de produtos fixos."},
{"med1":["fenofibrato","genfibrozila"],"med2":["sinvastatina","atorvastatina","rosuvastatina"],"nivel":"moderado","titulo":"Fibrato + Estatina","mecanismo":"Fibratos inibem a glucuronidação da estatina (principalmente genfibrozila) e ambos têm toxicidade muscular intrínseca — mecanismo aditivo.","efeito":"Risco aumentado de miopatia e rabdomiólise, especialmente com genfibrozila.","conduta":"⚠️ Preferir fenofibrato (menor interação) a genfibrozila. Evitar estatinas de alta dose. Monitorar CK."},
{"med1":["espironolactona"],"med2":["digoxina"],"nivel":"moderado","titulo":"Espironolactona + Digoxina","mecanismo":"A espironolactona e seu metabólito canrenoato podem interferir nos ensaios de dosagem da digoxina, gerando falsos resultados elevados, e também moderam a eliminação renal da digoxina.","efeito":"Aparente elevação dos níveis de digoxina nos testes (falso positivo) e possível leve aumento dos níveis reais — dificuldade no monitoramento.","conduta":"⚠️ Confirmar método de dosagem de digoxina (HPLC é mais específico). Monitorar ECG e sintomas clínicos de intoxicação."},
{"med1":["furosemida","ácido etacrínico"],"med2":["aminoglicosídeos","gentamicina","tobramicina","amicacina"],"nivel":"alto","titulo":"Diurético de Alça + Aminoglicosídeo","mecanismo":"Ambos são ototóxicos e nefrotóxicos por mecanismos diferentes (furosemida reduz fluxo perilinfático; aminoglicosídeos destroem células ciliadas) — toxicidade sinérgica.","efeito":"Surdez permanente (especialmente com ácido etacrínico) e insuficiência renal grave.","conduta":"❌ Evitar a combinação. Se necessário (ex: sepse com edema), monitorar audição e função renal intensivamente."},
{"med1":["dronedarona"],"med2":["sinvastatina","atorvastatina"],"nivel":"alto","titulo":"Dronedarona + Estatina","mecanismo":"A dronedarona inibe CYP3A4 e P-glicoproteína, elevando substancialmente os níveis de sinvastatina e em menor grau de atorvastatina.","efeito":"Risco elevado de miopatia e rabdomiólise.","conduta":"❌ Limitar sinvastatina a 10mg/dia com dronedarona. Preferir rosuvastatina ou pravastatina."},
{"med1":["dronedarona"],"med2":["digoxina"],"nivel":"alto","titulo":"Dronedarona + Digoxina","mecanismo":"A dronedarona inibe P-glicoproteína e CYP3A4, elevando os níveis de digoxina em aproximadamente 2,5 vezes.","efeito":"Intoxicação digitálica — bradicardia, bloqueio AV, arritmias.","conduta":"❌ Reduzir dose de digoxina em 50% ao iniciar dronedarona. Monitorar nível sérico e ECG."},
{"med1":["ranolazina"],"med2":["claritromicina","itraconazol","cetoconazol"],"nivel":"alto","titulo":"Ranolazina + Inibidor Forte de CYP3A4","mecanismo":"Inibidores de CYP3A4 bloqueiam o metabolismo da ranolazina, elevando seus níveis e aumentando o risco de prolongamento do QT e arritmias.","efeito":"Níveis tóxicos de ranolazina com risco de Torsades de Pointes.","conduta":"❌ Contraindicado. Suspender ranolazina ou substituir o inibidor de CYP3A4."},
{"med1":["sacubitril","sacubitril valsartana"],"med2":["captopril","enalapril","lisinopril","ramipril"],"nivel":"alto","titulo":"Sacubitril/Valsartana + IECA","mecanismo":"O sacubitril inibe a neprilisina, acumulando bradicinina. Combinado com IECA (que também eleva bradicinina), o risco de angioedema grave é muito alto.","efeito":"Angioedema grave — inchaço da laringe com risco de asfixia e morte.","conduta":"❌ Contraindicado absolutamente. Aguardar 36 horas após último IECA antes de iniciar sacubitril/valsartana."},
{"med1":["metoprolol"],"med2":["paroxetina","fluoxetina"],"nivel":"moderado","titulo":"Metoprolol + Paroxetina / Fluoxetina","mecanismo":"Paroxetina e fluoxetina inibem potentemente CYP2D6 — a principal enzima que metaboliza o metoprolol — elevando seus níveis em até 5 vezes.","efeito":"Bradicardia grave e bloqueio AV, hipotensão e broncoespasmo por acúmulo de metoprolol.","conduta":"⚠️ Reduzir dose de metoprolol. Monitorar frequência cardíaca. Considerar bisoprolol ou atenolol como alternativas."},
{"med1":["lítio","carbonato de lítio"],"med2":["teofilina","aminofilina"],"nivel":"moderado","titulo":"Lítio + Teofilina","mecanismo":"A teofilina aumenta a excreção renal de lítio ao competir pelo mesmo transportador tubular, reduzindo seus níveis séricos.","efeito":"Redução dos níveis de lítio — perda do controle do transtorno bipolar e risco de recaída.","conduta":"⚠️ Monitorar nível sérico de lítio ao iniciar ou suspender teofilina. Ajustar dose conforme necessário."},
{"med1":["lítio","carbonato de lítio"],"med2":["cafeína","café"],"nivel":"baixo","titulo":"Lítio + Cafeína","mecanismo":"A cafeína em grandes doses tem leve efeito natriurético e pode aumentar um pouco a excreção de lítio.","efeito":"Variação leve nos níveis de lítio com consumo muito elevado de cafeína. Clinicamente relevante apenas em grandes quantidades.","conduta":"✅ Manter consumo de café e chá estável. Evitar mudanças bruscas no consumo de cafeína."},
{"med1":["lítio","carbonato de lítio"],"med2":["celecoxibe","etoricoxibe","inibidor cox-2"],"nivel":"alto","titulo":"Lítio + Inibidor de COX-2","mecanismo":"Inibidores seletivos de COX-2 reduzem a síntese de prostaglandinas renais vasodilatadoras, diminuindo o fluxo renal e a excreção de lítio, elevando seus níveis séricos.","efeito":"Elevação dos níveis séricos de lítio com risco de toxicidade — tremores, confusão, convulsões.","conduta":"❌ Evitar inibidores de COX-2. Monitorar nível de lítio ao iniciar qualquer AINE, incluindo seletivos."},
{"med1":["lítio","carbonato de lítio"],"med2":["venlafaxina","duloxetina"],"nivel":"moderado","titulo":"Lítio + Antidepressivo IRSN","mecanismo":"A combinação de lítio com venlafaxina ou duloxetina aumenta a disponibilidade de serotonina por mecanismos sinérgicos — risco de síndrome serotoninérgica.","efeito":"Síndrome serotoninérgica leve a moderada — inquietação, tremores, sudorese, taquicardia.","conduta":"⚠️ Usar com cautela e iniciar antidepressivo em dose baixa. Monitorar sintomas neurológicos."},
{"med1":["fluoxetina","sertralina","escitalopram","paroxetina","citalopram","venlafaxina","duloxetina"],"med2":["ibuprofeno","diclofenaco","aspirina","ácido acetilsalicílico","aine"],"nivel":"moderado","titulo":"ISRS / IRSN + AINE / AAS","mecanismo":"ISRS e IRSN inibem a recaptação de serotonina plaquetária, reduzindo a ativação plaquetária. AINEs inibem a COX-1 plaquetária. A combinação bloqueia dois mecanismos de hemostasia.","efeito":"Aumento de 3–15 vezes no risco de sangramento gastrointestinal alto. Risco de hemorragia em qualquer local.","conduta":"⚠️ Evitar a combinação. Se necessário, usar IBP (omeprazol, pantoprazol) para proteção gástrica."},
{"med1":["fluoxetina","sertralina","escitalopram","paroxetina"],"med2":["warfarina","varfarina","rivaroxabana","apixabana"],"nivel":"moderado","titulo":"ISRS + Anticoagulante","mecanismo":"ISRS inibem captação plaquetária de serotonina (necessária para ativação plaquetária) e podem inibir CYP2C9 (fluoxetina, fluvoxamina), elevando níveis de warfarina.","efeito":"Risco aumentado de sangramento, especialmente gastrointestinal e intracraniano.","conduta":"⚠️ Monitorar INR (se warfarina). Usar IBP. Monitorar sinais de sangramento com NOACs."},
{"med1":["fluoxetina"],"med2":["aripiprazol"],"nivel":"moderado","titulo":"Fluoxetina + Aripiprazol","mecanismo":"A fluoxetina inibe CYP2D6, principal via de metabolismo do aripiprazol, elevando seus níveis em aproximadamente 2–3 vezes.","efeito":"Acúmulo de aripiprazol com potencial aumento de efeitos adversos — acatisia, tremores, tontura.","conduta":"⚠️ Reduzir dose de aripiprazol pela metade ao combinar com fluoxetina. Monitorar efeitos extrapiramidais."},
{"med1":["paroxetina"],"med2":["codeína","tramadol"],"nivel":"moderado","titulo":"Paroxetina + Codeína / Tramadol","mecanismo":"A paroxetina inibe CYP2D6, que converte a codeína em morfina (seu metabólito ativo). Com paroxetina, a codeína perde eficácia analgésica. No tramadol, inibe formação do metabólito ativo e aumenta risco serotoninérgico.","efeito":"Codeína sem efeito analgésico adequado. Tramadol: risco de síndrome serotoninérgica.","conduta":"⚠️ Evitar codeína com paroxetina (ineficaz). Evitar tramadol com paroxetina (risco serotoninérgico). Usar morfina ou oxicodona se opioide for necessário."},
{"med1":["fluoxetina","paroxetina"],"med2":["haloperidol"],"nivel":"moderado","titulo":"Fluoxetina / Paroxetina + Haloperidol","mecanismo":"Fluoxetina e paroxetina inibem CYP2D6, principal via de metabolismo do haloperidol, elevando seus níveis séricos.","efeito":"Acúmulo de haloperidol com risco de efeitos extrapiramidais, prolongamento do QT e síndrome neuroléptica maligna.","conduta":"⚠️ Reduzir dose de haloperidol. Monitorar ECG e sinais extrapiramidais."},
{"med1":["sertralina","duloxetina","venlafaxina"],"med2":["linezolida"],"nivel":"alto","titulo":"ISRS / IRSN + Linezolida","mecanismo":"A linezolida é um inibidor reversível de MAO. Combinada com ISRS ou IRSN, provoca acúmulo grave de serotonina.","efeito":"Síndrome serotoninérgica grave — hipertermia, agitação, convulsões, risco de morte.","conduta":"❌ Contraindicado. Aguardar 2 semanas após suspender ISRS (5 semanas para fluoxetina) antes de iniciar linezolida."},
{"med1":["escitalopram","citalopram"],"med2":["metadona"],"nivel":"alto","titulo":"Escitalopram / Citalopram + Metadona","mecanismo":"Escitalopram e citalopram prolongam o intervalo QT de forma dose-dependente. A metadona também prolonga o QT. O efeito é aditivo e perigoso.","efeito":"Prolongamento do QTc com risco elevado de Torsades de Pointes e morte súbita.","conduta":"❌ Contraindicado. Substituir por sertralina (menor efeito no QT) se antidepressivo for necessário."},
{"med1":["venlafaxina","duloxetina"],"med2":["inibidor de mao","isocarboxazida","fenelzina","tranilcipromina"],"nivel":"alto","titulo":"IRSN + Inibidor de MAO Irreversível","mecanismo":"IRSN elevam serotonina e noradrenalina; IMAO bloqueiam sua degradação. Combinação provoca acúmulo catastrófico de monoaminas.","efeito":"Síndrome serotoninérgica grave e potencialmente fatal — hipertermia, convulsões, colapso cardiovascular.","conduta":"❌ Contraindicado absolutamente. Aguardar 14 dias após suspender IMAO antes de iniciar IRSN (e vice-versa)."},
{"med1":["inibidor de mao","isocarboxazida","fenelzina","tranilcipromina"],"med2":["tiramina","queijo curado","vinho tinto","fígado","linguiça","salaminho","carne defumada","molho de soja","cerveja"],"nivel":"alto","titulo":"Inibidor de MAO + Tiramina (Alimentos)","mecanismo":"IMAO irreversíveis bloqueiam a MAO intestinal e hepática que degrada a tiramina dos alimentos. A tiramina absorvida causa liberação maciça de noradrenalina das terminações nervosas.","efeito":"Crise hipertensiva grave com dores de cabeça intensa, rubor, sudorese, AVC e morte — a \"crise do queijo\".","conduta":"❌ Dieta com restrição rigorosa de tiramina obrigatória. Evitar queijos curados, vinho, embutidos, fígado, molho de soja e fermentados durante e 14 dias após IMAO."},
{"med1":["inibidor de mao","isocarboxazida","fenelzina","tranilcipromina"],"med2":["efedrina","pseudoefedrina","fenilefrina"],"nivel":"alto","titulo":"Inibidor de MAO + Simpatomimético","mecanismo":"IMAO bloqueiam a degradação das catecolaminas. Simpatomiméticos (presentes em descongestionantes nasais) liberam grandes quantidades de noradrenalina que não é degradada.","efeito":"Crise hipertensiva grave, hipertermia, AVC e risco de morte.","conduta":"❌ Contraindicado absolutamente. Nenhum descongestionante oral com efedrina ou pseudoefedrina durante e 14 dias após IMAO."},
{"med1":["inibidor de mao","isocarboxazida","fenelzina","tranilcipromina"],"med2":["dextrometorfano"],"nivel":"alto","titulo":"Inibidor de MAO + Dextrometorfano","mecanismo":"O dextrometorfano é um agonista de receptores sigma e inibe levemente a recaptação de serotonina. Com IMAO, pode precipitar síndrome serotoninérgica grave.","efeito":"Síndrome serotoninérgica grave — agitação, mioclonia, hipertermia, convulsões.","conduta":"❌ Contraindicado. Evitar xaropes para tosse com dextrometorfano durante e 14 dias após IMAO."},
{"med1":["inibidor de mao","isocarboxazida","fenelzina","tranilcipromina"],"med2":["fluoxetina","sertralina","escitalopram","paroxetina","citalopram"],"nivel":"alto","titulo":"IMAO Irreversível + ISRS","mecanismo":"IMAO bloqueiam a degradação de serotonina; ISRS inibem sua recaptação — acúmulo catastrófico de serotonina na fenda sináptica.","efeito":"Síndrome serotoninérgica grave e frequentemente fatal — convulsões, coagulação intravascular, hipertermia maligna.","conduta":"❌ Contraindicado absolutamente. Aguardar 14 dias após suspender IMAO; 5 semanas após fluoxetina antes de iniciar IMAO."},
{"med1":["haloperidol"],"med2":["metadona"],"nivel":"alto","titulo":"Haloperidol + Metadona","mecanismo":"Ambos prolongam o intervalo QT por bloqueio de canais de potássio cardíacos IKr — efeito aditivo com dose-dependência.","efeito":"Prolongamento grave do QTc com risco de Torsades de Pointes e morte súbita.","conduta":"❌ Contraindicado. Monitorar ECG rigorosamente se combinação for inevitável. Manter QTc <500ms."},
{"med1":["clozapina"],"med2":["cafeína","café"],"nivel":"moderado","titulo":"Clozapina + Cafeína","mecanismo":"A cafeína inibe CYP1A2, principal enzima de metabolismo da clozapina, aumentando seus níveis séricos.","efeito":"Elevação dos níveis de clozapina com aumento de efeitos adversos — sedação, salivação excessiva, risco de convulsões.","conduta":"⚠️ Manter consumo de cafeína estável. Redução brusca de café pode diminuir níveis de clozapina drasticamente."},
{"med1":["clozapina","olanzapina"],"med2":["tabagismo","cigarro"],"nivel":"moderado","titulo":"Clozapina / Olanzapina + Tabagismo","mecanismo":"Hidrocarbonetos policíclicos da fumaça de cigarro induzem CYP1A2, acelerando o metabolismo de clozapina e olanzapina.","efeito":"Fumantes precisam de doses maiores de clozapina/olanzapina. Ao parar de fumar, os níveis sobem abruptamente — risco de toxicidade.","conduta":"⚠️ Ao parar de fumar, monitorar níveis de clozapina e reduzir dose preventivamente. Informar psiquiatra."},
{"med1":["quetiapina"],"med2":["carbamazepina"],"nivel":"moderado","titulo":"Quetiapina + Carbamazepina","mecanismo":"A carbamazepina é potente indutora de CYP3A4, a principal via de metabolismo da quetiapina, reduzindo seus níveis em até 87%.","efeito":"Perda quase completa do efeito antipsicótico — risco de recaída de psicose ou mania.","conduta":"⚠️ Aumentar substancialmente a dose de quetiapina. Monitorar eficácia clínica. Considerar outro estabilizador de humor."},
{"med1":["aripiprazol"],"med2":["carbamazepina"],"nivel":"moderado","titulo":"Aripiprazol + Carbamazepina","mecanismo":"A carbamazepina induz CYP3A4 e CYP2D6, acelerando o metabolismo do aripiprazol e reduzindo seus níveis em até 70%.","efeito":"Redução significativa do efeito antipsicótico — risco de recaída.","conduta":"⚠️ Dobrar a dose de aripiprazol com carbamazepina. Monitorar resposta clínica."},
{"med1":["risperidona","paliperidona"],"med2":["paroxetina","fluoxetina"],"nivel":"moderado","titulo":"Risperidona + Paroxetina / Fluoxetina","mecanismo":"Paroxetina e fluoxetina inibem CYP2D6, principal via de metabolismo da risperidona, elevando seus níveis e alterando a proporção risperidona/9-OH-risperidona.","efeito":"Acúmulo de risperidona com risco de efeitos extrapiramidais, prolactinemia e prolongamento do QT.","conduta":"⚠️ Reduzir dose de risperidona. Monitorar ECG e efeitos adversos."},
{"med1":["amitriptilina","nortriptilina","imipramina","clomipramina"],"med2":["propranolol","metoprolol"],"nivel":"moderado","titulo":"Antidepressivo Tricíclico + Betabloqueador","mecanismo":"Tricíclicos e betabloqueadores têm efeitos aditivos no sistema cardiovascular — prolongamento do PR, QRS e QT, além de hipotensão ortostática.","efeito":"Bradicardia, hipotensão ortostática e prolongamento do QT — risco de quedas em idosos.","conduta":"⚠️ Monitorar ECG, pressão arterial e frequência cardíaca. Usar com cautela em idosos."},
{"med1":["amitriptilina","nortriptilina","imipramina"],"med2":["biperideno","oxibutinina","escopolamina","prometazina"],"nivel":"moderado","titulo":"Tricíclico + Anticolinérgico","mecanismo":"Tricíclicos têm ação anticolinérgica intrínseca. Combinação com outros anticolinérgicos provoca efeitos cumulativos no sistema colinérgico periférico e central.","efeito":"Boca seca intensa, retenção urinária, constipação grave, glaucoma, confusão mental e delirium em idosos.","conduta":"⚠️ Evitar polifarmácia anticolinérgica. Revisar todos os medicamentos com escore anticolinérgico em idosos."},
{"med1":["bupropiona"],"med2":["carbamazepina"],"nivel":"moderado","titulo":"Bupropiona + Carbamazepina","mecanismo":"A carbamazepina induz CYP2B6, principal via de metabolismo da bupropiona, reduzindo seus níveis e aumentando a formação de metabólitos convulsivantes.","efeito":"Redução da eficácia antidepressiva e aumento do risco de convulsões.","conduta":"⚠️ Evitar a combinação. Se necessário, usar a menor dose eficaz de bupropiona e monitorar."},
{"med1":["alprazolam","triazolam","midazolam"],"med2":["claritromicina","eritromicina","itraconazol","cetoconazol","voriconazol"],"nivel":"alto","titulo":"Benzodiazepínico Metabolizado por CYP3A4 + Inibidor","mecanismo":"Inibidores de CYP3A4 bloqueiam o metabolismo de alprazolam, triazolam e midazolam — benzodiazepínicos de curta ação — elevando seus níveis em 2–10 vezes.","efeito":"Sedação profunda e prolongada, depressão respiratória, amnésia e risco de acidentes.","conduta":"❌ Contraindicado (triazolam com cetoconazol/itraconazol). Para outros: reduzir dose em 50–75%. Monitorar sedação."},
{"med1":["diazepam","clonazepam"],"med2":["cimetidina"],"nivel":"moderado","titulo":"Benzodiazepínico + Cimetidina","mecanismo":"A cimetidina inibe CYP2C19 e CYP3A4, reduzindo o metabolismo de diazepam e clonazepam e elevando seus níveis séricos.","efeito":"Sedação excessiva e prolongada, confusão mental e risco de quedas.","conduta":"⚠️ Preferir ranitidina, famotidina ou omeprazol como alternativa ao antiácido. Reduzir dose do BZD se necessário."},
{"med1":["zolpidem","zopiclona"],"med2":["fluoxetina","paroxetina"],"nivel":"moderado","titulo":"Hipnótico + ISRS","mecanismo":"ISRS podem inibir o metabolismo de zolpidem via CYP3A4 (fluoxetina) ou CYP2C19 e aumentar efeitos sedativos por interação farmacodinâmica.","efeito":"Aumento da sedação residual no dia seguinte, comprometimento cognitivo e motor.","conduta":"⚠️ Usar a menor dose eficaz de zolpidem. Monitorar sedação diurna e risco de quedas."},
{"med1":["pregabalina","gabapentina"],"med2":["pregabalina","gabapentina"],"nivel":"baixo","titulo":"Pregabalina + Gabapentina (Combinação)","mecanismo":"Ambas atuam no mesmo alvo (subunidade α2δ de canais de cálcio) — a combinação raramente oferece benefício adicional mas duplica os efeitos adversos.","efeito":"Tontura, sedação, confusão mental e risco de quedas sem ganho terapêutico.","conduta":"⚠️ Combinação geralmente sem benefício. Revisar com médico a necessidade de usar ambas."},
{"med1":["clozapina"],"med2":["valproato","ácido valproico","divalproato"],"nivel":"moderado","titulo":"Clozapina + Valproato","mecanismo":"O valproato pode inibir o metabolismo da clozapina e ambos têm potencial de causar sedação, ganho de peso e efeitos hematológicos.","efeito":"Elevação dos níveis de clozapina, sedação excessiva e aumento do risco de agranulocitose.","conduta":"⚠️ Monitorar hemograma, nível sérico de clozapina e sedação. Combinar com cautela e indicação específica."},
{"med1":["lítio","carbonato de lítio"],"med2":["succinilcolina","suxametônio"],"nivel":"moderado","titulo":"Lítio + Succinilcolina (Anestesia)","mecanismo":"O lítio reduz a síntese de acetilcolina e inibe a colinesterase plasmática, prolongando o bloqueio neuromuscular da succinilcolina.","efeito":"Paralisia prolongada pós-operatória — dificuldade de reverter o bloqueio neuromuscular.","conduta":"⚠️ Informar anestesiologista sobre uso de lítio. Pode ser necessário reduzir dose de succinilcolina."},
{"med1":["metilfenidato","lisdexanfetamina"],"med2":["clonidina"],"nivel":"moderado","titulo":"Estimulante (TDAH) + Clonidina","mecanismo":"A combinação de estimulante (que aumenta catecolaminas) com clonidina (que reduz tônus simpático) cria efeitos cardiovasculares opostos e imprevisíveis.","efeito":"Risco de arritmias, prolongamento do QT, hipotensão ou hipertensão. Alguns casos de morte súbita em crianças foram reportados.","conduta":"⚠️ Monitorar ECG, pressão e frequência cardíaca. Esta combinação exige acompanhamento cardiológico."},
{"med1":["modafinil"],"med2":["contraceptivo","etinilestradiol","levonorgestrel"],"nivel":"moderado","titulo":"Modafinil + Anticoncepcional Hormonal","mecanismo":"O modafinil induz CYP3A4, acelerando o metabolismo dos hormônios contraceptivos orais e reduzindo seus níveis plasmáticos.","efeito":"Redução da eficácia contraceptiva — risco de gravidez não planejada.","conduta":"⚠️ Usar método contraceptivo adicional (preservativo ou DIU) durante e por 1 mês após o modafinil."},
{"med1":["trazodona"],"med2":["carbamazepina"],"nivel":"moderado","titulo":"Trazodona + Carbamazepina","mecanismo":"A carbamazepina induz CYP3A4, acelerando o metabolismo da trazodona e reduzindo significativamente seus níveis séricos.","efeito":"Perda do efeito antidepressivo e ansiolítico da trazodona.","conduta":"⚠️ Aumentar dose de trazodona ou considerar antidepressivo com menor interação com indutores enzimáticos."},
{"med1":["fenobarbital"],"med2":["warfarina","varfarina"],"nivel":"moderado","titulo":"Fenobarbital + Warfarina","mecanismo":"O fenobarbital é potente indutor de CYP2C9 e CYP3A4, acelerando drasticamente o metabolismo da warfarina e reduzindo o INR.","efeito":"Redução do efeito anticoagulante — risco de trombose.","conduta":"⚠️ Monitorar INR frequentemente ao iniciar ou suspender fenobarbital. Ajustar dose de warfarina."},
{"med1":["fenobarbital"],"med2":["contraceptivo","etinilestradiol","levonorgestrel"],"nivel":"moderado","titulo":"Fenobarbital + Anticoncepcional Hormonal","mecanismo":"O fenobarbital induz CYP3A4 e CYP2C9, acelerando o metabolismo dos estrogênios e progestágenos contraceptivos.","efeito":"Redução importante da eficácia contraceptiva — risco de gravidez não planejada.","conduta":"⚠️ Usar método contraceptivo adicional. Considerar anticoncepcionais não hormonais (DIU de cobre)."},
{"med1":["oxcarbazepina"],"med2":["contraceptivo","etinilestradiol","levonorgestrel"],"nivel":"moderado","titulo":"Oxcarbazepina + Anticoncepcional","mecanismo":"A oxcarbazepina (e seu metabólito ativo monohydroxi) induz CYP3A4, reduzindo os níveis dos hormônios contraceptivos em até 50%.","efeito":"Redução da eficácia contraceptiva — risco de gravidez.","conduta":"⚠️ Usar método adicional de barreira. Anticoncepcionais com dose maior de etinilestradiol (≥50mcg) ou DIU hormonal."},
{"med1":["valproato","ácido valproico"],"med2":["ácido acetilsalicílico","aspirina"],"nivel":"moderado","titulo":"Valproato + Aspirina","mecanismo":"A aspirina desloca o valproato das proteínas plasmáticas e inibe sua β-oxidação mitocondrial, elevando os níveis do fármaco livre. Ambos têm efeito sobre plaquetas.","efeito":"Elevação dos níveis livres de valproato com toxicidade (tremores, sonolência), além de aumento do risco de sangramento.","conduta":"⚠️ Evitar aspirina em altas doses com valproato. Usar paracetamol para analgesia."},
{"med1":["valproato","ácido valproico"],"med2":["meropeném","ertapeném","imipeném"],"nivel":"alto","titulo":"Valproato + Carbapenêmico","mecanismo":"Carbapenêmicos (especialmente meropeném) reduzem rapidamente os níveis de valproato em até 70% por mecanismo ainda não completamente elucidado (inibição de absorção e aumento de glucuronidação).","efeito":"Perda do controle de crises epilépticas — convulsões graves, estado de mal epiléptico.","conduta":"❌ Evitar a combinação. Se antibiótico carbapenêmico for indispensável, substituir valproato por benzodiazepínico IV ou fenitoína durante o tratamento."},
{"med1":["baclofen"],"med2":["álcool","alcool"],"nivel":"moderado","titulo":"Baclofeno + Álcool","mecanismo":"O baclofeno é um agonista GABA-B com ação depressora central. O álcool também deprime o SNC — efeitos aditivos na depressão neurológica.","efeito":"Sedação excessiva, comprometimento psicomotor grave, risco de quedas e depressão respiratória.","conduta":"⚠️ Evitar álcool durante tratamento com baclofeno. Orientar paciente e cuidadores."},
{"med1":["ciclobenzaprina"],"med2":["inibidor de mao","isocarboxazida","fenelzina","tranilcipromina"],"nivel":"alto","titulo":"Ciclobenzaprina + Inibidor de MAO","mecanismo":"A ciclobenzaprina tem estrutura similar aos tricíclicos e inibe levemente a recaptação de monoaminas. Com IMAO, risco de síndrome serotoninérgica ou crise hipertensiva.","efeito":"Síndrome serotoninérgica grave ou crise hipertensiva.","conduta":"❌ Contraindicado. Aguardar 14 dias após suspender IMAO antes de usar ciclobenzaprina."},
{"med1":["ciclobenzaprina","carisoprodol"],"med2":["álcool","alcool","benzodiazepínico","diazepam","alprazolam"],"nivel":"moderado","titulo":"Relaxante Muscular + Álcool / Benzodiazepínico","mecanismo":"Relaxantes musculares de ação central deprimem o SNC. Combinados com álcool ou benzodiazepínicos, o efeito depressor é aditivo e perigoso.","efeito":"Sedação profunda, comprometimento cognitivo e motor grave, risco de quedas e acidentes.","conduta":"⚠️ Evitar álcool e minimizar uso de BZD com relaxantes musculares centrais."},
{"med1":["ciprofloxacino","levofloxacino","moxifloxacino"],"med2":["metadona"],"nivel":"alto","titulo":"Fluoroquinolona + Metadona","mecanismo":"Ambos prolongam o intervalo QT por mecanismos diferentes — fluoroquinolonas bloqueiam canais cardíacos hERG e a metadona bloqueia canais IKr. Efeito aditivo.","efeito":"Prolongamento grave do QTc com risco de Torsades de Pointes e morte súbita.","conduta":"❌ Contraindicado. Substituir por antibiótico sem efeito no QT (amoxicilina, doxiciclina) se possível."},
{"med1":["ciprofloxacino","levofloxacino","moxifloxacino"],"med2":["haloperidol","quetiapina","ziprasidona"],"nivel":"alto","titulo":"Fluoroquinolona + Antipsicótico (QT)","mecanismo":"Fluoroquinolonas e antipsicóticos como haloperidol, quetiapina e ziprasidona prolongam o QT por bloqueio de canais de potássio cardíacos — efeito aditivo perigoso.","efeito":"Risco aumentado de Torsades de Pointes e morte súbita por arritmia ventricular.","conduta":"❌ Evitar a combinação. Monitorar ECG se inevitável. Manter QTc <500ms."},
{"med1":["ciprofloxacino","levofloxacino"],"med2":["ibuprofeno","diclofenaco","nimesulida","aine"],"nivel":"moderado","titulo":"Fluoroquinolona + AINE","mecanismo":"Fluoroquinolonas inibem receptores GABA-A no SNC. AINEs inibem síntese de prostaglandinas neuroprotetoras. A combinação abaixa o limiar convulsivante.","efeito":"Risco aumentado de convulsões, especialmente em pacientes com histórico de epilepsia ou alterações neurológicas.","conduta":"⚠️ Preferir paracetamol para analgesia durante tratamento com fluoroquinolonas. Monitorar em epilépticos."},
{"med1":["ciprofloxacino"],"med2":["ciclosporina","tacrolimo"],"nivel":"moderado","titulo":"Ciprofloxacino + Imunossupressor Calcineurínico","mecanismo":"O ciprofloxacino inibe CYP1A2 e pode reduzir a excreção tubular renal da ciclosporina/tacrolimo, elevando seus níveis séricos e risco de nefrotoxicidade.","efeito":"Elevação dos níveis de ciclosporina ou tacrolimo com risco de nefrotoxicidade e neurotoxicidade.","conduta":"⚠️ Monitorar nível sérico do imunossupressor e função renal durante o uso de ciprofloxacino."},
{"med1":["ciprofloxacino"],"med2":["duloxetina"],"nivel":"moderado","titulo":"Ciprofloxacino + Duloxetina","mecanismo":"O ciprofloxacino inibe CYP1A2, principal via de metabolismo da duloxetina, podendo elevar seus níveis séricos.","efeito":"Aumento dos efeitos adversos da duloxetina — náusea, taquicardia, hipertensão, sudorese.","conduta":"⚠️ Monitorar efeitos adversos da duloxetina durante o tratamento com ciprofloxacino."},
{"med1":["claritromicina"],"med2":["ergotamina","tartarato de ergotamina"],"nivel":"alto","titulo":"Claritromicina + Ergotamina","mecanismo":"A claritromicina inibe fortemente CYP3A4, principal via de metabolismo da ergotamina, causando acúmulo rápido com vasoconstricção extrema.","efeito":"Ergotismo agudo — vasoconstricção intensa, isquemia de extremidades, dor intensa, gangrena.","conduta":"❌ Contraindicado absolutamente. Substituir por azitromicina ou outro antibiótico sem interação com CYP3A4."},
{"med1":["claritromicina","eritromicina"],"med2":["sildenafila","tadalafila","vardenafila"],"nivel":"moderado","titulo":"Macrolídeo + Inibidor de PDE-5","mecanismo":"Macrolídeos inibem CYP3A4, via principal de metabolismo dos inibidores de PDE-5, elevando seus níveis séricos significativamente.","efeito":"Hipotensão, rubor intenso, cefaleia e priapismo por acúmulo do inibidor de PDE-5.","conduta":"⚠️ Reduzir dose de sildenafila para 25mg ou tadalafila para 10mg durante tratamento com macrolídeo."},
{"med1":["azitromicina"],"med2":["metadona"],"nivel":"alto","titulo":"Azitromicina + Metadona","mecanismo":"A azitromicina prolonga o QT de forma moderada. Combinada com metadona (prolongamento significativo do QT), o efeito é aditivo.","efeito":"Risco de Torsades de Pointes e fibrilação ventricular em pacientes em manutenção com metadona.","conduta":"❌ Preferir amoxicilina ou doxiciclina. Se azitromicina for necessária, monitorar ECG."},
{"med1":["azitromicina"],"med2":["haloperidol","quetiapina","risperidona"],"nivel":"moderado","titulo":"Azitromicina + Antipsicótico","mecanismo":"A azitromicina tem efeito moderado de prolongamento do QT. Combinada com antipsicóticos que também prolongam o QT, o risco é aditivo.","efeito":"Prolongamento do QTc com risco aumentado de arritmias ventriculares.","conduta":"⚠️ Monitorar ECG. Preferir penicilinas ou cefalosporinas se disponíveis."},
{"med1":["eritromicina"],"med2":["carbamazepina"],"nivel":"alto","titulo":"Eritromicina + Carbamazepina","mecanismo":"A eritromicina inibe CYP3A4, principal enzima de metabolismo da carbamazepina, podendo triplicar seus níveis séricos.","efeito":"Toxicidade por carbamazepina — diplopia, ataxia, confusão mental, convulsões.","conduta":"❌ Contraindicado. Usar azitromicina ou amoxicilina como alternativa. Monitorar nível sérico se combinação for inevitável."},
{"med1":["rifampicina"],"med2":["verapamil","diltiazem","anlodipino","nifedipina"],"nivel":"moderado","titulo":"Rifampicina + Bloqueador de Canal de Cálcio","mecanismo":"A rifampicina é potente indutora de CYP3A4, principal via de metabolismo de todos os bloqueadores de canal de cálcio, reduzindo drasticamente seus níveis.","efeito":"Perda do efeito anti-hipertensivo e antianginoso — pressão arterial descontrolada.","conduta":"⚠️ Monitorar pressão arterial. Pode ser necessário aumentar consideravelmente a dose do BCC."},
{"med1":["rifampicina"],"med2":["tacrolimo","ciclosporina"],"nivel":"alto","titulo":"Rifampicina + Imunossupressor","mecanismo":"A rifampicina induz CYP3A4 e P-glicoproteína, reduzindo os níveis de ciclosporina e tacrolimo em 60–80%.","efeito":"Risco grave de rejeição aguda do órgão transplantado por nível subterapêutico do imunossupressor.","conduta":"❌ Evitar. Se indispensável (tuberculose em transplantado), triplicar a dose do imunossupressor e monitorar diariamente."},
{"med1":["rifampicina"],"med2":["fenitoína"],"nivel":"moderado","titulo":"Rifampicina + Fenitoína","mecanismo":"Interação bidirecional: rifampicina induz CYP2C9 (reduz fenitoína); fenitoína pode induzir rifampicina. Ambos induzem metabolismo um do outro.","efeito":"Redução dos níveis de fenitoína — risco de perda do controle das crises epilépticas.","conduta":"⚠️ Monitorar nível sérico de fenitoína ao iniciar ou suspender rifampicina."},
{"med1":["rifampicina"],"med2":["digoxina"],"nivel":"moderado","titulo":"Rifampicina + Digoxina","mecanismo":"A rifampicina induz P-glicoproteína intestinal e renal, aumentando a eliminação da digoxina e reduzindo seus níveis séricos.","efeito":"Redução dos níveis de digoxina — perda do controle do ritmo cardíaco.","conduta":"⚠️ Monitorar nível sérico de digoxina. Ajustar dose durante e após tratamento com rifampicina."},
{"med1":["isoniazida"],"med2":["álcool","alcool"],"nivel":"moderado","titulo":"Isoniazida + Álcool","mecanismo":"O álcool induz CYP2E1, acelerando a formação de metabólitos hepatotóxicos da isoniazida. Também aumenta o risco de hepatite alcoólica concomitante.","efeito":"Hepatotoxicidade grave — risco de insuficiência hepática aguda.","conduta":"⚠️ Evitar álcool durante todo o tratamento com isoniazida. Monitorar enzimas hepáticas mensalmente."},
{"med1":["vancomicina"],"med2":["aminoglicosídeos","gentamicina","tobramicina","amicacina"],"nivel":"alto","titulo":"Vancomicina + Aminoglicosídeo","mecanismo":"Ambos são nefrotóxicos por mecanismos diferentes (acúmulo tubular proximal). A combinação causa dano renal sinérgico e também potencializa a ototoxicidade.","efeito":"Insuficiência renal aguda e perda auditiva permanente — risco muito elevado.","conduta":"❌ Evitar a combinação quando possível. Se necessário (sepse grave), monitorar creatinina, nível sérico de vancomicina e audição diariamente."},
{"med1":["vancomicina"],"med2":["furosemida","ácido etacrínico"],"nivel":"moderado","titulo":"Vancomicina + Diurético de Alça","mecanismo":"Diuréticos de alça reduzem a perfusão renal e aumentam a concentração de vancomicina nos túbulos — potencializando a nefrotoxicidade.","efeito":"Risco aumentado de insuficiência renal aguda e ototoxicidade.","conduta":"⚠️ Monitorar função renal, nível sérico de vancomicina e audição. Manter hidratação adequada."},
{"med1":["metronidazol"],"med2":["fenitoína"],"nivel":"moderado","titulo":"Metronidazol + Fenitoína","mecanismo":"O metronidazol inibe CYP2C9, elevando os níveis de fenitoína. A fenitoína, por sua vez, pode acelerar o metabolismo do metronidazol (indução de CYP).","efeito":"Toxicidade por fenitoína — nistagmo, ataxia, confusão mental — e possível redução da eficácia do metronidazol.","conduta":"⚠️ Monitorar nível sérico de fenitoína durante e após uso de metronidazol."},
{"med1":["metronidazol"],"med2":["lítio","carbonato de lítio"],"nivel":"moderado","titulo":"Metronidazol + Lítio","mecanismo":"O metronidazol pode reduzir a excreção renal de lítio ao afetar a reabsorção tubular, elevando seus níveis séricos.","efeito":"Elevação dos níveis de lítio com risco de toxicidade — tremores, confusão, poliúria.","conduta":"⚠️ Monitorar nível sérico de lítio durante tratamento com metronidazol."},
{"med1":["tinidazol"],"med2":["álcool","alcool"],"nivel":"moderado","titulo":"Tinidazol + Álcool","mecanismo":"O tinidazol inibe acetaldeído desidrogenase (como o metronidazol), causando acúmulo de acetaldeído ao ingerir álcool — reação tipo dissulfiram.","efeito":"Rubor intenso, náusea, vômitos, taquicardia e hipotensão após ingestão de álcool.","conduta":"⚠️ Proibido álcool durante o tratamento e por 72 horas após a última dose de tinidazol."},
{"med1":["linezolida"],"med2":["fluoxetina","sertralina","paroxetina","escitalopram","venlafaxina","duloxetina"],"nivel":"alto","titulo":"Linezolida + Antidepressivo Serotonérgico","mecanismo":"A linezolida inibe a MAO de forma reversível não seletiva. Combinada com ISRS ou IRSN, ocorre acúmulo perigoso de serotonina no SNC.","efeito":"Síndrome serotoninérgica grave — febre, rigidez muscular, agitação, convulsões, risco de morte.","conduta":"❌ Contraindicado. Suspender ISRS/IRSN 2 semanas antes (5 semanas para fluoxetina) de iniciar linezolida."},
{"med1":["linezolida"],"med2":["tramadol","tapentadol"],"nivel":"alto","titulo":"Linezolida + Tramadol / Tapentadol","mecanismo":"A linezolida inibe MAO; tramadol e tapentadol têm propriedades de inibição da recaptação de serotonina — combinação precipita síndrome serotoninérgica.","efeito":"Síndrome serotoninérgica grave — potencialmente fatal.","conduta":"❌ Contraindicado. Usar morfina ou hidromorfona como opioide alternativo."},
{"med1":["linezolida"],"med2":["efedrina","pseudoefedrina","fenilefrina"],"nivel":"alto","titulo":"Linezolida + Simpatomimético","mecanismo":"A linezolida inibe MAO — a enzima que degrada noradrenalina. Simpatomiméticos liberam noradrenalina que não é degradada, causando crise adrenérgica.","efeito":"Crise hipertensiva grave, taquiarritmia e risco de AVC.","conduta":"❌ Contraindicado. Evitar todos os simpatomiméticos, incluindo descongestionantes nasais."},
{"med1":["doxiciclina"],"med2":["rifampicina"],"nivel":"moderado","titulo":"Doxiciclina + Rifampicina","mecanismo":"A rifampicina induz CYP3A4 e P-glicoproteína, acelerando o metabolismo e eliminação da doxiciclina.","efeito":"Redução dos níveis séricos de doxiciclina — perda de eficácia antibiótica (relevante no tratamento de brucelose).","conduta":"⚠️ Monitorar resposta clínica. Aumentar frequência de dose ou considerar outro antibiótico."},
{"med1":["voriconazol"],"med2":["fenitoína"],"nivel":"alto","titulo":"Voriconazol + Fenitoína","mecanismo":"Interação bidirecional: voriconazol inibe CYP2C9 (eleva fenitoína); fenitoína induz CYP2C19 e CYP3A4 (reduz voriconazol drasticamente).","efeito":"Toxicidade por fenitoína (nistagmo, ataxia) E falha terapêutica do voriconazol simultaneamente.","conduta":"❌ Evitar a combinação. Se inevitável, dobrar a dose de voriconazol e monitorar ambos os níveis séricos."},
{"med1":["voriconazol"],"med2":["rifampicina"],"nivel":"alto","titulo":"Voriconazol + Rifampicina","mecanismo":"A rifampicina induz CYP2C19, principal via de metabolismo do voriconazol, reduzindo seus níveis em até 96%.","efeito":"Falha terapêutica completa do antifúngico — infeção fúngica grave pode não ser tratada.","conduta":"❌ Contraindicado absolutamente. Substituir rifampicina por outro tuberculostático ou voriconazol por anfotericina B."},
{"med1":["voriconazol"],"med2":["carbamazepina","fenobarbital"],"nivel":"alto","titulo":"Voriconazol + Indutor Potente (Carbamazepina / Fenobarbital)","mecanismo":"Carbamazepina e fenobarbital induzem CYP2C19 e CYP3A4, reduzindo os níveis de voriconazol em mais de 90%.","efeito":"Falha no tratamento antifúngico com risco de disseminação da infecção fúngica grave.","conduta":"❌ Contraindicado. Substituir anticonvulsivante por levetiracetam ou voriconazol por equinocandina/anfotericina B."},
{"med1":["griseofulvina"],"med2":["warfarina","varfarina"],"nivel":"moderado","titulo":"Griseofulvina + Warfarina","mecanismo":"A griseofulvina induz enzimas microssomais hepáticas, acelerando o metabolismo da warfarina e reduzindo o INR.","efeito":"Redução do efeito anticoagulante — risco de trombose durante e após o tratamento antifúngico.","conduta":"⚠️ Monitorar INR ao iniciar e ao suspender griseofulvina. Pode ser necessário aumentar a dose de warfarina."},
{"med1":["griseofulvina"],"med2":["álcool","alcool"],"nivel":"moderado","titulo":"Griseofulvina + Álcool","mecanismo":"A griseofulvina pode intensificar os efeitos do álcool e causar reação tipo dissulfiram em alguns pacientes.","efeito":"Rubor, taquicardia e mal-estar após ingestão de álcool.","conduta":"⚠️ Evitar álcool durante o tratamento com griseofulvina."},
{"med1":["griseofulvina"],"med2":["contraceptivo","etinilestradiol","levonorgestrel"],"nivel":"moderado","titulo":"Griseofulvina + Anticoncepcional","mecanismo":"A griseofulvina induz CYP3A4 e enzimas hepáticas, acelerando o metabolismo dos hormônios contraceptivos.","efeito":"Redução da eficácia contraceptiva durante e até 1 mês após o tratamento.","conduta":"⚠️ Usar método contraceptivo adicional (preservativo) durante e por 1 mês após griseofulvina."},
{"med1":["terbinafina"],"med2":["warfarina","varfarina"],"nivel":"moderado","titulo":"Terbinafina + Warfarina","mecanismo":"A terbinafina pode inibir CYP2C9 de forma modesta, reduzindo o metabolismo da warfarina e elevando o INR.","efeito":"Aumento moderado do efeito anticoagulante — risco de sangramento.","conduta":"⚠️ Monitorar INR durante o tratamento com terbinafina."},
{"med1":["terbinafina"],"med2":["ciclosporina"],"nivel":"moderado","titulo":"Terbinafina + Ciclosporina","mecanismo":"A terbinafina aumenta o clearance da ciclosporina, reduzindo seus níveis séricos e risco de rejeição.","efeito":"Redução dos níveis de ciclosporina — risco de rejeição em transplantados.","conduta":"⚠️ Monitorar nível sérico de ciclosporina e ajustar dose durante o tratamento antifúngico."},
{"med1":["fluconazol"],"med2":["sirolimo","everolimo"],"nivel":"alto","titulo":"Fluconazol + Sirolimo / Everolimo","mecanismo":"O fluconazol inibe CYP3A4 e CYP2C9, principais vias de metabolismo de sirolimo e everolimo, podendo elevar seus níveis em 5–7 vezes.","efeito":"Toxicidade grave dos imunossupressores — nefrotoxicidade, neurotoxicidade, imunossupressão excessiva.","conduta":"❌ Reduzir dose de sirolimo/everolimo em ~90% ao iniciar fluconazol. Monitorar nível sérico diariamente."},
{"med1":["itraconazol","cetoconazol"],"med2":["midazolam","triazolam"],"nivel":"alto","titulo":"Antifúngico Azólico + Midazolam / Triazolam Oral","mecanismo":"Azólicos inibem fortemente CYP3A4 intestinal e hepático — benzodiazepínicos de curta ação que dependem exclusivamente desta via acumulam dramaticamente.","efeito":"Sedação prolongada e profunda, amnésia, depressão respiratória — especialmente perigoso com triazolam.","conduta":"❌ Contraindicado (triazolam oral + azólico). Midazolam oral contraindica; midazolam IV pode ser usado com cautela e monitoramento."},
{"med1":["cefalosporinas","cefalexina","ceftriaxona"],"med2":["warfarina","varfarina"],"nivel":"moderado","titulo":"Cefalosporina + Warfarina","mecanismo":"Cefalosporinas reduzem a flora intestinal produtora de vitamina K e algumas (cefalosporinas com cadeia N-MTT) inibem diretamente a epóxido redutase da vitamina K.","efeito":"Elevação do INR com risco de sangramento — mais relevante com cefalosporinas de 3ª/4ª geração.","conduta":"⚠️ Monitorar INR durante e após o tratamento com cefalosporinas, especialmente parenterais."},
{"med1":["amoxicilina","ampicilina","amoxicilina clavulanato"],"med2":["metotrexato"],"nivel":"moderado","titulo":"Penicilina + Metotrexato","mecanismo":"Penicilinas inibem transportadores tubulares renais orgânicos (OAT) que eliminam o metotrexato, reduzindo sua depuração e elevando seus níveis séricos.","efeito":"Acúmulo de metotrexato com risco de toxicidade na medula óssea (leucopenia, trombocitopenia) e mucosa.","conduta":"⚠️ Monitorar hemograma e funçao renal. Evitar a combinação em doses altas de metotrexato."},
{"med1":["claritromicina","eritromicina"],"med2":["rivaroxabana","apixabana"],"nivel":"alto","titulo":"Macrolídeo + NOAC (Rivaroxabana / Apixabana)","mecanismo":"Macrolídeos inibem CYP3A4 e P-glicoproteína simultaneamente, as duas principais vias de eliminação de rivaroxabana e apixabana.","efeito":"Elevação expressiva dos níveis dos NOACs com risco de sangramento grave.","conduta":"❌ Evitar a combinação. Considerar amoxicilina/azitromicina como alternativa. Se necessário, monitorar sinais de sangramento."},
{"med1":["estatinas","sinvastatina","atorvastatina","lovastatina"],"med2":["suco de toranja","toranja","grapefruit"],"nivel":"alto","titulo":"Estatina + Suco de Toranja","mecanismo":"A toranja contém furanocumarinas que inibem de forma irreversível o CYP3A4 intestinal — aumenta a biodisponibilidade oral de sinvastatina e atorvastatina em até 16 vezes.","efeito":"Risco muito elevado de miopatia e rabdomiólise — destruição muscular com mioglobinúria e insuficiência renal.","conduta":"❌ Evitar suco de toranja, toranja e pomelo com sinvastatina, atorvastatina e lovastatina. Rosuvastatina e pravastatina são alternativas seguras."},
{"med1":["carbamazepina"],"med2":["suco de toranja","toranja","grapefruit"],"nivel":"moderado","titulo":"Carbamazepina + Suco de Toranja","mecanismo":"A toranja inibe CYP3A4 intestinal, reduzindo o metabolismo de primeira passagem da carbamazepina e aumentando seus níveis séricos.","efeito":"Elevação dos níveis de carbamazepina com risco de toxicidade — diplopia, ataxia, confusão mental.","conduta":"⚠️ Evitar suco de toranja durante uso de carbamazepina."},
{"med1":["midazolam","triazolam"],"med2":["suco de toranja","toranja"],"nivel":"alto","titulo":"Midazolam / Triazolam + Suco de Toranja","mecanismo":"A toranja inibe CYP3A4 intestinal, aumentando em 2–5 vezes a biodisponibilidade oral de midazolam e triazolam.","efeito":"Sedação profunda e prolongada, amnésia e depressão respiratória.","conduta":"❌ Evitar suco de toranja com benzodiazepínicos metabolizados por CYP3A4. Usar lorazepam (não metabolizado por CYP3A4)."},
{"med1":["ciclosporina"],"med2":["suco de toranja","toranja"],"nivel":"alto","titulo":"Ciclosporina + Suco de Toranja","mecanismo":"Furanocumarinas da toranja inibem CYP3A4 e P-glicoproteína intestinais, aumentando substancialmente a absorção da ciclosporina.","efeito":"Elevação imprevisível dos níveis de ciclosporina com risco de nefrotoxicidade e rejeição por superdosagem.","conduta":"❌ Proibido absolutamente. Pacientes transplantados devem evitar toranja, pomelo e suco derivado."},
{"med1":["tacrolimo"],"med2":["suco de toranja","toranja"],"nivel":"alto","titulo":"Tacrolimo + Suco de Toranja","mecanismo":"A toranja inibe CYP3A4 e P-glicoproteína intestinais, aumentando a biodisponibilidade do tacrolimo de forma imprevisível.","efeito":"Níveis tóxicos de tacrolimo com risco de nefrotoxicidade, neurotoxicidade e infecções oportunistas.","conduta":"❌ Proibido. Pacientes em uso de tacrolimo devem evitar completamente toranja e derivados."},
{"med1":["sirolimo","everolimo"],"med2":["suco de toranja","toranja"],"nivel":"alto","titulo":"Sirolimo / Everolimo + Suco de Toranja","mecanismo":"A toranja inibe CYP3A4 intestinal e P-glicoproteína, aumentando dramaticamente a absorção de sirolimo e everolimo.","efeito":"Toxicidade grave — pneumonite, trombocitopenia, lesão renal aguda.","conduta":"❌ Proibido. Pacientes em manutenção com inibidores de mTOR devem evitar toranja permanentemente."},
{"med1":["levotiroxina"],"med2":["café","café expresso","café coado"],"nivel":"moderado","titulo":"Levotiroxina + Café","mecanismo":"O café reduz a absorção intestinal de levotiroxina ao aumentar a motilidade gastrointestinal e possivelmente por interferência com o pH luminal.","efeito":"Redução da absorção de levotiroxina em até 25–30% — hipotireoidismo mal controlado.","conduta":"⚠️ Tomar levotiroxina 30–60 minutos antes do primeiro café do dia, ou usar formulação em cápsula líquida (menos afetada)."},
{"med1":["levotiroxina"],"med2":["soja","leite de soja","tofu","isoflavona"],"nivel":"moderado","titulo":"Levotiroxina + Soja","mecanismo":"Isoflavonas de soja inibem a deiodinase intestinal e possivelmente ligam-se à levotiroxina no intestino, reduzindo sua absorção.","efeito":"Absorção reduzida de levotiroxina com hipotireoidismo não controlado.","conduta":"⚠️ Separar a levotiroxina por pelo menos 4 horas do consumo de soja. Monitorar TSH mais frequentemente em quem consome soja regularmente."},
{"med1":["levotiroxina"],"med2":["fibras","farelo de trigo","farelo de aveia","psyllium"],"nivel":"moderado","titulo":"Levotiroxina + Fibras Alimentares","mecanismo":"Fibras solúveis ligam-se à levotiroxina no lúmen intestinal, reduzindo sua absorção.","efeito":"Menor absorção de levotiroxina — necessidade de dose mais alta para atingir TSH alvo.","conduta":"⚠️ Tomar levotiroxina pelo menos 2 horas antes de suplementos de fibra ou refeições ricas em fibras."},
{"med1":["sulfato ferroso","ferro","gluconato ferroso"],"med2":["café","chá","chá preto","chá verde"],"nivel":"moderado","titulo":"Ferro + Café / Chá","mecanismo":"Taninos do café e chá formam complexos insolúveis com o ferro não-heme, bloqueando sua absorção intestinal.","efeito":"Redução da absorção de ferro em até 60–90% — anemia ferropriva de difícil correção.","conduta":"⚠️ Tomar ferro 1 hora antes ou 2 horas depois de café e chá. Tomar em jejum para máxima absorção."},
{"med1":["sulfato ferroso","ferro"],"med2":["vitamina c","ácido ascórbico","laranja","limão"],"nivel":"baixo","titulo":"Ferro + Vitamina C (Combinação Benéfica)","mecanismo":"A vitamina C reduz o ferro de Fe3+ para Fe2+ (forma mais absorvível) e forma quelatos solúveis que facilitam a captação intestinal.","efeito":"Aumento de até 3 vezes na absorção do ferro — combinação sinérgica e benéfica.","conduta":"✅ Tomar ferro com suco de laranja ou vitamina C para maximizar a absorção."},
{"med1":["levodopa","carbidopa","carbidopa + levodopa"],"med2":["proteína","carne","peixe","frango","laticínios"],"nivel":"moderado","titulo":"Levodopa + Proteína Dietética","mecanismo":"A levodopa e aminoácidos de origem proteica compartilham o mesmo transportador intestinal (LAT1) e da barreira hematoencefálica — competição direta.","efeito":"Redução da absorção e transporte cerebral de levodopa — piora dos sintomas parkinsonianos após refeições ricas em proteína.","conduta":"⚠️ Distribuir proteína ao longo do dia (não concentrar no almoço). Administrar levodopa 30 minutos antes das refeições."},
{"med1":["alendronato","risedronato","ibandronato"],"med2":["cálcio","leite","antiácido","café","suco de laranja"],"nivel":"moderado","titulo":"Bisfosfonato + Alimentos / Antiácido","mecanismo":"Cálcio, magnésio e outros cátions bivalentes quelam os bisfosfonatos no intestino, formando complexos insolúveis que não são absorvidos.","efeito":"Absorção de bisfosfonatos pode ser reduzida em >90% se tomados com alimentos ou antiácidos — perda da eficácia anti-osteoporótica.","conduta":"⚠️ Tomar bisfosfonato em jejum com 200ml de água, 30–60 min antes de qualquer alimento, bebida ou medicamento. Ficar em pé por 30 min."},
{"med1":["captopril","enalapril"],"med2":["sal de potássio","cloreto de potássio","sal light","sal diet"],"nivel":"moderado","titulo":"IECA + Sal de Potássio (Sal Light)","mecanismo":"IECAs retêm potássio ao reduzir aldosterona. Sais \"light\" substituem NaCl por KCl — ingestão aumentada de potássio somada à retenção pelo IECA causa hipercalemia.","efeito":"Hipercalemia grave com risco de arritmias cardíacas, especialmente em idosos e diabéticos.","conduta":"⚠️ Evitar sal light e substitutos de sódio por potássio. Verificar rótulos de alimentos diet/light."},
{"med1":["diuréticos tiazídicos","hidroclorotiazida","clortalidona"],"med2":["alcaçuz","extrato de alcaçuz","glycyrrhiza"],"nivel":"moderado","titulo":"Diurético Tiazídico + Alcaçuz","mecanismo":"O ácido glicirrízico do alcaçuz imita a aldosterona — retém sódio, eleva pressão e aumenta perda de potássio. Em combinação com tiazídicos, piora a hipocalemia.","efeito":"Hipocalemia grave, hipertensão resistente e edema — especialmente com consumo regular de alcaçuz em grandes quantidades.","conduta":"⚠️ Evitar alcaçuz em quantidades medicinais em pacientes usando diuréticos ou com hipertensão."},
{"med1":["fluoxetina","sertralina","escitalopram","paroxetina"],"med2":["álcool","alcool"],"nivel":"moderado","titulo":"ISRS + Álcool","mecanismo":"O álcool pode aumentar os efeitos sedativos dos ISRS e ambos afetam a neurotransmissão serotonérgica. Além disso, álcool é depressor do SNC e pode antagonizar o efeito antidepressivo.","efeito":"Sedação aumentada, comprometimento cognitivo, piora da depressão e risco de comportamento impulsivo.","conduta":"⚠️ Evitar álcool durante tratamento com antidepressivos."},
{"med1":["venlafaxina","duloxetina"],"med2":["álcool","alcool"],"nivel":"moderado","titulo":"IRSN + Álcool","mecanismo":"O álcool potencializa os efeitos depressores centrais dos IRSNs. A venlafaxina pode aumentar os efeitos psicomotores do álcool de forma desproporcional.","efeito":"Sedação aumentada, comprometimento psicomotor e risco de quedas e acidentes.","conduta":"⚠️ Evitar álcool completamente durante uso de venlafaxina ou duloxetina."},
{"med1":["amitriptilina","nortriptilina","imipramina"],"med2":["álcool","alcool"],"nivel":"moderado","titulo":"Antidepressivo Tricíclico + Álcool","mecanismo":"Tricíclicos têm ação anticolinérgica e depressora central. O álcool potencializa esses efeitos e pode elevar os níveis séricos dos tricíclicos.","efeito":"Sedação profunda, hipotensão ortostática grave, comprometimento psicomotor e risco de quedas.","conduta":"⚠️ Evitar álcool durante uso de tricíclicos. Risco de quedas especialmente perigoso em idosos."},
{"med1":["gabapentina","pregabalina"],"med2":["álcool","alcool"],"nivel":"moderado","titulo":"Gabapentina / Pregabalina + Álcool","mecanismo":"Ambas têm efeito depressor do SNC via inibição de canais de cálcio neuronais. O álcool potencializa essa depressão de forma sinérgica.","efeito":"Sedação excessiva, tontura, confusão, risco de quedas e depressão respiratória.","conduta":"⚠️ Evitar álcool durante uso de gabapentina ou pregabalina."},
{"med1":["metadona"],"med2":["suco de toranja","toranja"],"nivel":"moderado","titulo":"Metadona + Suco de Toranja","mecanismo":"A toranja inibe CYP3A4 intestinal e parcialmente CYP3A4 hepático — a metadona é parcialmente metabolizada por esta via.","efeito":"Elevação moderada dos níveis de metadona com maior risco de prolongamento do QT e overdose.","conduta":"⚠️ Evitar suco de toranja em pacientes em manutenção com metadona."},
{"med1":["warfarina","varfarina"],"med2":["cranberry","suco de cranberry"],"nivel":"moderado","titulo":"Warfarina + Suco de Cranberry","mecanismo":"Constituintes do cranberry (possivelmente quercetina e flavonoides) inibem CYP2C9, principal via de metabolismo da warfarina S.","efeito":"Aumento do INR e risco de sangramento — vários casos documentados na literatura, incluindo morte.","conduta":"⚠️ Evitar suco de cranberry. Monitorar INR se já em uso."},
{"med1":["erva de são joão","hipérico","hypericum"],"med2":["ciclosporina","tacrolimo"],"nivel":"alto","titulo":"Erva de São João + Imunossupressor","mecanismo":"A erva de São João induz fortemente CYP3A4 e P-glicoproteína, acelerando o metabolismo de ciclosporina e tacrolimo e reduzindo muito seus níveis séricos.","efeito":"Rejeição aguda do órgão transplantado — vários casos documentados na literatura.","conduta":"❌ Contraindicado absolutamente em transplantados. Interromper imediatamente e monitorar nível sérico do imunossupressor."},
{"med1":["erva de são joão","hipérico","hypericum"],"med2":["antiretroviral","indinavir","saquinavir","efavirenz"],"nivel":"alto","titulo":"Erva de São João + Antiretroviral","mecanismo":"A erva de São João induz CYP3A4 e P-glicoproteína, reduzindo drasticamente os níveis de muitos antiretrovirais.","efeito":"Falha virológica e seleção de vírus resistentes — perda do controle do HIV.","conduta":"❌ Contraindicado em pacientes com HIV. Informar sobre qualquer fitoterápico."},
{"med1":["erva de são joão","hipérico","hypericum"],"med2":["fluoxetina","sertralina","escitalopram","paroxetina"],"nivel":"moderado","titulo":"Erva de São João + ISRS","mecanismo":"A erva de São João aumenta a disponibilidade de serotonina por mecanismo próprio (inibição de recaptação). Somada ao ISRS, eleva o risco de síndrome serotoninérgica.","efeito":"Síndrome serotoninérgica leve a moderada — inquietação, sudorese, tremores, taquicardia.","conduta":"⚠️ Não combinar. A erva de São João não deve ser usada junto com nenhum antidepressivo convencional."},
{"med1":["erva de são joão","hipérico"],"med2":["contraceptivo","etinilestradiol"],"nivel":"alto","titulo":"Erva de São João + Anticoncepcional","mecanismo":"Indução de CYP3A4 e P-glicoproteína pela erva de São João acelera o metabolismo dos hormônios contraceptivos.","efeito":"Falha contraceptiva — gravidez não planejada. Vários casos documentados em todo o mundo.","conduta":"❌ Contraindicado com anticoncepcionais hormonais. Usar método de barreira adicional se erva de São João for usada."},
{"med1":["ginkgo biloba"],"med2":["warfarina","varfarina","aspirina","clopidogrel"],"nivel":"moderado","titulo":"Ginkgo Biloba + Anticoagulante / Antiagregante","mecanismo":"O ginkgo biloba inibe o fator ativador de plaquetas (PAF) e tem ação antiagregante própria, potencializando o efeito hemostático.","efeito":"Risco aumentado de sangramento, especialmente cerebral — vários casos de hemorragia intracraniana relatados.","conduta":"⚠️ Evitar ginkgo biloba com anticoagulantes e antiagregantes. Suspender 2 semanas antes de cirurgias."},
{"med1":["valeriana"],"med2":["alprazolam","diazepam","clonazepam","benzodiazepínico","zolpidem"],"nivel":"moderado","titulo":"Valeriana + Benzodiazepínico / Hipnótico","mecanismo":"A valeriana tem ação GABAérgica modesta que pode somar-se à ação dos benzodiazepínicos no receptor GABA-A.","efeito":"Potencialização da sedação com sonolência excessiva e comprometimento cognitivo.","conduta":"⚠️ Evitar a combinação. Informar médico e farmacêutico sobre uso de valeriana."},
{"med1":["vitamina d","colecalciferol"],"med2":["digoxina"],"nivel":"moderado","titulo":"Vitamina D + Digoxina","mecanismo":"A vitamina D em doses altas pode causar hipercalcemia. O cálcio elevado aumenta drasticamente a toxicidade da digoxina ao potencializar sua ligação ao miocárdio.","efeito":"Hipercalcemia induzida por vitamina D potencializa a toxicidade digitálica — arritmias e bloqueio AV.","conduta":"⚠️ Manter vitamina D em doses fisiológicas (1000–2000 UI/dia). Monitorar cálcio sérico em usuários de digoxina."},
{"med1":["melatonina"],"med2":["warfarina","varfarina"],"nivel":"baixo","titulo":"Melatonina + Anticoagulante","mecanismo":"A melatonina pode ter leve efeito antiagregante plaquetário e modesto efeito inibitório sobre CYP2C9.","efeito":"Possível leve aumento do INR em doses altas. O risco clínico é geralmente baixo com doses ≤5mg.","conduta":"✅ Geralmente seguro em doses baixas (≤5mg). Monitorar INR se doses elevadas forem usadas."},
{"med1":["coenzima q10","coq10","ubiquinona"],"med2":["warfarina","varfarina"],"nivel":"moderado","titulo":"Coenzima Q10 + Warfarina","mecanismo":"A CoQ10 tem estrutura similar à vitamina K e pode ter leve efeito agonista sobre os fatores de coagulação dependentes de vitamina K.","efeito":"Redução do efeito anticoagulante da warfarina — INR pode cair.","conduta":"⚠️ Monitorar INR ao iniciar ou suspender suplemento de CoQ10."},
{"med1":["gengibre","suplemento de gengibre"],"med2":["warfarina","varfarina","aspirina","clopidogrel"],"nivel":"moderado","titulo":"Gengibre (Suplemento) + Anticoagulante","mecanismo":"O gengibre em doses medicinais inibe o tromboxano A2 e tem ação antiagregante plaquetária.","efeito":"Potencialização do risco de sangramento em usuários de anticoagulantes e antiagregantes.","conduta":"⚠️ Consumo culinário moderado é geralmente seguro. Evitar suplementos de gengibre em altas doses com anticoagulantes."},
{"med1":["ciclosporina"],"med2":["ibuprofeno","diclofenaco","aine"],"nivel":"moderado","titulo":"Ciclosporina + AINE","mecanismo":"AINEs inibem prostaglandinas vasodilatadoras renais, reduzindo o fluxo sanguíneo renal já comprometido pela nefrotoxicidade da ciclosporina.","efeito":"Potencialização da nefrotoxicidade da ciclosporina — insuficiência renal aguda.","conduta":"⚠️ Evitar AINEs em pacientes em uso de ciclosporina. Usar paracetamol com cautela."},
{"med1":["ciclosporina"],"med2":["itraconazol","cetoconazol","fluconazol"],"nivel":"alto","titulo":"Ciclosporina + Antifúngico Azólico","mecanismo":"Azólicos inibem CYP3A4, principal via de metabolismo da ciclosporina, podendo triplicar seus níveis séricos.","efeito":"Toxicidade grave da ciclosporina — nefrotoxicidade, hepatotoxicidade e neurotoxicidade.","conduta":"❌ Reduzir dose de ciclosporina em 50–75% ao iniciar azólico. Monitorar nível sérico diariamente."},
{"med1":["colchicina"],"med2":["ciclosporina"],"nivel":"alto","titulo":"Colchicina + Ciclosporina","mecanismo":"A ciclosporina inibe P-glicoproteína e CYP3A4, bloqueando as principais vias de eliminação da colchicina — toxicidade grave pode ocorrer em dias.","efeito":"Toxicidade grave por colchicina — miopatia, neuropatia, mielossupressão, rabdomiólise e insuficiência de múltiplos órgãos.","conduta":"❌ Contraindicado em dose convencional de colchicina. Se necessário, usar dose única muito baixa (0,5mg) com monitoramento intensivo."},
{"med1":["metotrexato"],"med2":["leflunomida"],"nivel":"moderado","titulo":"Metotrexato + Leflunomida","mecanismo":"Ambos são hepatotóxicos por mecanismos diferentes. A combinação multiplica o risco de dano hepático e toxicidade na medula óssea.","efeito":"Hepatotoxicidade grave e mielossupressão — risco de cirrose e pancitopenia.","conduta":"⚠️ Combinação usada em artrite reumatoide refratária com monitoramento hepático rigoroso. Considerar biópsia hepática."},
{"med1":["azatioprina"],"med2":["febuxostat"],"nivel":"alto","titulo":"Azatioprina + Febuxostate","mecanismo":"O febuxostate, assim como o alopurinol, inibe a xantina oxidase — enzima que degrada a azatioprina. O acúmulo de metabólitos tóxicos causa mielossupressão grave.","efeito":"Risco de toxicidade grave na medula óssea — pancitopenia, agranulocitose.","conduta":"❌ Contraindicado. Substituir febuxostate por uricosúrico (probenecida) ou reduzir azatioprina a 25% com monitoramento intensivo."},
{"med1":["metotrexato"],"med2":["probenecida"],"nivel":"moderado","titulo":"Metotrexato + Probenecida","mecanismo":"A probenecida inibe os transportadores tubulares OAT que eliminam o metotrexato pelo rim, reduzindo sua depuração e elevando muito seus níveis séricos.","efeito":"Toxicidade por metotrexato — mielossupressão, mucosite, hepatotoxicidade.","conduta":"⚠️ Evitar a combinação com doses intermediárias ou altas de metotrexato. Monitorar hemograma e função renal."},
{"med1":["omeprazol","esomeprazol","lansoprazol","pantoprazol"],"med2":["atazanavir","rilpivirina","nelfinavir"],"nivel":"alto","titulo":"IBP + Antiretroviral pH-dependente","mecanismo":"Atazanavir e rilpivirina requerem pH gástrico ácido para absorção. IBPs elevam o pH gástrico, reduzindo drasticamente a absorção desses antiretrovirais.","efeito":"Falha virológica — níveis subterapêuticos do antiretroviral com risco de resistência ao HIV.","conduta":"❌ Contraindicado com atazanavir. Para rilpivirina, evitar IBPs e usar antiácidos 2h depois ou H2-bloqueadores."},
{"med1":["prednisona","dexametasona","prednisolona","hidrocortisona","betametasona","budesonida","triancinolona","deflazacorte"],"med2":["ibuprofeno","diclofenaco","naproxeno","nimesulida","cetoprofeno","meloxicam","aine"],"nivel":"alto","titulo":"Corticoide + AINE (Úlcera e Sangramento Gastrointestinal)","mecanismo":"Mecanismo duplo e sinérgico: corticoides inibem a síntese de prostaglandinas citoprotetoras da mucosa gástrica; AINEs inibem COX-1 e COX-2, reduzindo muco e bicarbonato gástrico. A combinação multiplica o dano mucoso.","efeito":"Risco de úlcera péptica e sangramento gastrointestinal grave 15 vezes maior que com cada fármaco isolado. Pode ocorrer sem dor prévia — primeira manifestação pode ser hematêmese ou melena.","conduta":"❌ Evitar sempre que possível. Se combinação for inevitável: prescri IBP obrigatoriamente (omeprazol, pantoprazol) durante todo o período. Preferir paracetamol ou dipirona para analgesia em pacientes em corticoterapia."},
{"med1":["prednisona","dexametasona","hidrocortisona"],"med2":["insulina","insulina nph","metformina","glibenclamida"],"nivel":"moderado","titulo":"Corticoide + Antidiabético","mecanismo":"Corticoides aumentam a gliconeogênese hepática e causam resistência insulínica periférica, elevando a glicemia — mecanismo oposto ao dos antidiabéticos.","efeito":"Descontrole glicêmico — hiperglicemia corticosteroidea, especialmente após cada dose oral de corticoide.","conduta":"⚠️ Monitorar glicemia com frequência. Pode ser necessário aumentar dose de insulina ou antidiabético durante corticoterapia."},
{"med1":["prednisona","dexametasona"],"med2":["warfarina","varfarina"],"nivel":"moderado","titulo":"Corticoide + Warfarina","mecanismo":"Efeito bidirecional: doses altas de corticoide podem ter efeito anticoagulante por inibição de fatores de coagulação; podem também alterar o metabolismo da warfarina.","efeito":"Variação imprevisível do INR — tanto risco de sangramento quanto de trombose.","conduta":"⚠️ Monitorar INR frequentemente ao iniciar, ajustar ou suspender corticoterapia."},
{"med1":["isotretinoína","acitretina"],"med2":["minociclina"],"nivel":"alto","titulo":"Retinoide + Minociclina","mecanismo":"Assim como outras tetraciclinas, a minociclina combinada com retinoides causa hipertensão intracraniana benigna (pseudotumor cerebri) por mecanismo sinérgico desconhecido.","efeito":"Hipertensão intracraniana — cefaleia intensa, náusea, visão turva (diplopia) e risco de perda permanente de visão.","conduta":"❌ Contraindicado absolutamente. A isotretinoína é incompatível com qualquer tetraciclina."},
{"med1":["acitretina"],"med2":["metotrexato"],"nivel":"alto","titulo":"Acitretina + Metotrexato","mecanismo":"Ambos são hepatotóxicos. A combinação multiplica o risco de hepatotoxicidade, fibrose e cirrose hepática.","efeito":"Hepatotoxicidade grave — risco de insuficiência hepática aguda.","conduta":"❌ Contraindicado. Nunca combinar dois hepatotóxicos sistêmicos com uso dermatológico."},
{"med1":["acitretina"],"med2":["álcool","alcool"],"nivel":"moderado","titulo":"Acitretina + Álcool","mecanismo":"O álcool converte a acitretina em etretinato, um metabólito com meia-vida de eliminação muito longa (até 3 anos) — tornando permanente o risco teratogênico.","efeito":"Formação de etretinato teratogênico de longa duração — risco de malformações fetais mesmo anos após o término do tratamento.","conduta":"❌ Proibido álcool durante e por 2 meses após acitretina (para mulheres), em razão do risco de formação de etretinato teratogênico de longa duração."},
{"med1":["fluticasona","budesonida"],"med2":["ritonavir","cobicistate","itraconazol"],"nivel":"moderado","titulo":"Corticoide Inalatório + Inibidor Forte de CYP3A4","mecanismo":"Inibidores de CYP3A4 (especialmente ritonavir) reduzem dramaticamente o metabolismo de corticoides inalatórios como fluticasona, causando efeito sistêmico.","efeito":"Síndrome de Cushing iatrogênica com uso de corticoide inalatório — ganho de peso, hiperglicemia, supressão adrenal.","conduta":"⚠️ Preferir beclometasona (menos afetada pelo ritonavir). Informar pneumologista e infectologista."},
{"med1":["tizanidina"],"med2":["ciprofloxacino","fluvoxamina"],"nivel":"alto","titulo":"Tizanidina + Inibidor de CYP1A2","mecanismo":"Ciprofloxacino e fluvoxamina inibem potentemente CYP1A2, única via de metabolismo da tizanidina, elevando seus níveis em até 10 vezes.","efeito":"Hipotensão grave, sedação profunda e bradicardia — risco de síncope e parada cardiorrespiratória.","conduta":"❌ Contraindicado absolutamente. Nenhuma tizanidina durante tratamento com ciprofloxacino ou fluvoxamina."},
{"med1":["tizanidina"],"med2":["álcool","alcool"],"nivel":"moderado","titulo":"Tizanidina + Álcool","mecanismo":"Ambos têm ação depressora do SNC — o álcool potencializa a hipotensão e a sedação da tizanidina.","efeito":"Hipotensão ortostática grave, sedação profunda e risco de quedas.","conduta":"⚠️ Proibido álcool com tizanidina. O risco de hipotensão grave é muito elevado."},
{"med1":["domperidona"],"med2":["metadona","sotalol","amiodarona","claritromicina","azitromicina"],"nivel":"moderado","titulo":"Domperidona + Prolongadores de QT","mecanismo":"A domperidona tem efeito moderado de prolongamento do QT. Combinada com outros medicamentos que prolongam o QT, o risco é aditivo.","efeito":"Prolongamento do QTc com risco de Torsades de Pointes — mais relevante em doses altas de domperidona.","conduta":"⚠️ Usar a menor dose por menor tempo possível. Evitar a combinação com outros prolongadores de QT."},
{"med1":["cloroquina","hidroxicloroquina"],"med2":["amiodarona","sotalol"],"nivel":"alto","titulo":"Cloroquina / Hidroxicloroquina + Antiarrítmico","mecanismo":"A cloroquina prolonga o intervalo QT por bloqueio de canais de potássio IKr. Combinada com amiodarona ou sotalol (mesmos mecanismos), o risco é aditivo e grave.","efeito":"Prolongamento grave do QT com risco de Torsades de Pointes e morte súbita.","conduta":"❌ Contraindicado. Monitorar ECG rigorosamente se a combinação for inevitável."},
{"med1":["ondansetrom"],"med2":["apomorfina"],"nivel":"alto","titulo":"Ondansetrom + Apomorfina","mecanismo":"O ondansetrom inibe receptores 5-HT3, os mesmos que a apomorfina usa para parte de seu mecanismo. A combinação causa hipotensão profunda e perda de consciência.","efeito":"Hipotensão grave e síncope — vários casos documentados e alertas das agências regulatórias.","conduta":"❌ Contraindicado absolutamente. Usar domperidona (não atravessa barreira hematoencefálica) como antiemético em pacientes com apomorfina."},
{"med1":["loperamida"],"med2":["quinidina","itraconazol"],"nivel":"moderado","titulo":"Loperamida + Inibidor de P-gp / CYP3A4","mecanismo":"A loperamida normalmente não atravessa a barreira hematoencefálica devido à P-glicoproteína. Inibidores de P-gp elevam seus níveis cerebrais.","efeito":"Efeitos opioides centrais da loperamida — sedação, depressão respiratória e euforia.","conduta":"⚠️ Evitar a combinação. A loperamida foi aprovada apenas para ação periférica — efeitos centrais são indesejados e potencialmente perigosos."},
{"med1":["donepezila","rivastigmina"],"med2":["suxametônio","succinilcolina"],"nivel":"moderado","titulo":"Inibidor de Colinesterase + Succinilcolina","mecanismo":"Inibidores de colinesterase bloqueiam a enzima que degrada a succinilcolina, prolongando muito seu bloqueio neuromuscular.","efeito":"Paralisia prolongada e apneia pós-operatória — dificuldade de reverter o bloqueio neuromuscular.","conduta":"⚠️ Informar anestesiologista sobre uso de inibidor de colinesterase. Pode ser necessário usar bloqueador neuromuscular não despolarizante."},
{"med1":["alendronato","risedronato"],"med2":["cálcio","vitamina d"],"nivel":"baixo","titulo":"Bisfosfonato + Cálcio / Vitamina D (Sequencial)","mecanismo":"Bisfosfonatos eficazes requerem estoques adequados de cálcio e vitamina D — caso contrário, podem causar hipocalcemia sintomática.","efeito":"Hipocalcemia se a suplementação não for feita. Suplementação adequada é protetora e sinérgica.","conduta":"✅ Suplementar cálcio e vitamina D 2 horas após o bisfosfonato (nunca junto). Suplementação é obrigatória."},
{"med1":["metformina"],"med2":["contraste iodado","gadolínio","contraste radiológico"],"nivel":"moderado","titulo":"Metformina + Contraste Iodado","mecanismo":"O contraste pode causar nefropatia aguda transitória. Com função renal reduzida, a metformina acumula e causa acidose lática grave.","efeito":"Acidose lática grave se o contraste causar redução da função renal.","conduta":"⚠️ Suspender metformina 48 horas antes do contraste IV e reiniciar apenas após confirmar função renal estável."},
{"med1":["fenofibrato","genfibrozila"],"med2":["ezetimiba"],"nivel":"baixo","titulo":"Fibrato + Ezetimiba","mecanismo":"Fibratos podem aumentar os níveis de ezetimiba ao competir pela glucuronidação. O efeito clínico é geralmente modesto.","efeito":"Leve aumento dos níveis de ezetimiba — clinicamente raramente significativo.","conduta":"✅ Combinação geralmente segura. Monitorar enzimas hepáticas e musculares periodicamente."},
{"med1":["pioglitazona"],"med2":["genfibrozila"],"nivel":"moderado","titulo":"Pioglitazona + Genfibrozila","mecanismo":"A genfibrozila inibe CYP2C8, principal via de metabolismo da pioglitazona, elevando seus níveis em aproximadamente 3 vezes.","efeito":"Risco aumentado de retenção de líquidos, edema, insuficiência cardíaca e hipoglicemia.","conduta":"⚠️ Reduzir dose de pioglitazona ou substituir genfibrozila por fenofibrato."},
{"med1":["saxagliptina"],"med2":["claritromicina","itraconazol","cetoconazol"],"nivel":"moderado","titulo":"Saxagliptina + Inibidor de CYP3A4","mecanismo":"Inibidores de CYP3A4 bloqueiam o metabolismo da saxagliptina, elevando seus níveis e do metabólito ativo.","efeito":"Aumento do risco de hipoglicemia e efeitos adversos da saxagliptina.","conduta":"⚠️ Limitar dose de saxagliptina a 2,5mg/dia durante uso de inibidor forte de CYP3A4."},
{"med1":["salbutamol","fenoterol","formoterol"],"med2":["propranolol","atenolol","metoprolol","betabloqueador"],"nivel":"moderado","titulo":"Beta-2 Agonista + Betabloqueador","mecanismo":"Betabloqueadores antagonizam os receptores β2-adrenérgicos dos broncodilatadores — os não seletivos (propranolol) são especialmente problemáticos.","efeito":"Broncoespasmo grave — o broncodilatador não consegue abrir as vias aéreas bloqueadas pelo betabloqueador.","conduta":"⚠️ Evitar betabloqueadores não seletivos em asmáticos. Usar betabloqueadores cardiosseletivos (bisoprolol, metoprolol) com cautela."},
{"med1":["teofilina"],"med2":["cimetidina"],"nivel":"moderado","titulo":"Teofilina + Cimetidina","mecanismo":"A cimetidina inibe CYP1A2 e CYP3A4, principais vias de metabolismo da teofilina, elevando seus níveis séricos.","efeito":"Toxicidade por teofilina — náusea, taquicardia, tremores, convulsões.","conduta":"⚠️ Substituir cimetidina por famotidina, ranitidina ou omeprazol. Monitorar nível sérico de teofilina."},
{"med1":["teofilina"],"med2":["ciprofloxacino"],"nivel":"moderado","titulo":"Teofilina + Ciprofloxacino","mecanismo":"O ciprofloxacino inibe CYP1A2 de forma dose-dependente, reduzindo o clearance da teofilina em até 30%.","efeito":"Elevação dos níveis de teofilina com risco de convulsões, arritmias e náusea grave.","conduta":"⚠️ Reduzir dose de teofilina em 30–50% ao iniciar ciprofloxacino. Monitorar nível sérico."},
{"med1":["levetiracetam"],"med2":["álcool","alcool"],"nivel":"moderado","titulo":"Levetiracetam + Álcool","mecanismo":"O álcool pode potencializar os efeitos sedativos e neurológicos do levetiracetam. Além disso, álcool abaixa o limiar convulsivante — contrapondo o efeito anticonvulsivante.","efeito":"Sedação aumentada e paradoxalmente maior risco de convulsões.","conduta":"⚠️ Evitar álcool durante uso de levetiracetam."},
{"med1":["valproato","ácido valproico"],"med2":["álcool","alcool"],"nivel":"moderado","titulo":"Valproato + Álcool","mecanismo":"O álcool potencializa a depressão do SNC pelo valproato e ambos são hepatotóxicos — o risco de dano hepático é aditivo.","efeito":"Sedação aumentada, tontura e risco de hepatotoxicidade.","conduta":"⚠️ Evitar álcool durante uso de valproato. Monitorar enzimas hepáticas."},
{"med1":["pramipexol","cabergolina","bromocriptina"],"med2":["metoclopramida","domperidona"],"nivel":"moderado","titulo":"Agonista Dopaminérgico + Antidopaminérgico","mecanismo":"Metoclopramida e domperidona bloqueiam receptores de dopamina, antagonizando diretamente o mecanismo terapêutico dos agonistas dopaminérgicos.","efeito":"Redução da eficácia do tratamento de Parkinson ou hiperprolactinemia.","conduta":"⚠️ Evitar a combinação. Usar ondansetrom como antiemético em parkinsonianos."},
{"med1":["levodopa","carbidopa + levodopa"],"med2":["metildopa"],"nivel":"moderado","titulo":"Levodopa + Metildopa","mecanismo":"A metildopa é inibidora da DOPA descarboxilase periférica — pode interferir na conversão periférica de levodopa. Ambas competem por transporte intestinal.","efeito":"Redução da eficácia da levodopa e potencial piora dos sintomas parkinsonianos.","conduta":"⚠️ Evitar metildopa em parkinsonianos. Usar anti-hipertensivos alternativos."},
{"med1":["memantina"],"med2":["dextrometorfano"],"nivel":"moderado","titulo":"Memantina + Dextrometorfano","mecanismo":"Ambos são antagonistas de receptores NMDA de glutamato. A combinação pode causar efeitos aditivos na inibição do sistema glutamatérgico.","efeito":"Risco de alucinações, confusão mental e outros efeitos psicomotores indesejados.","conduta":"⚠️ Evitar dextrometorfano em pacientes com Alzheimer tratados com memantina."},
{"med1":["memantina"],"med2":["amantadina"],"nivel":"moderado","titulo":"Memantina + Amantadina","mecanismo":"Ambas são antagonistas de receptores NMDA — a combinação pode resultar em psicose e efeitos anticolinérgicos excessivos pelo mecanismo aditivo.","efeito":"Alucinações, confusão mental, agitação e síndrome anticolinérgica.","conduta":"⚠️ Evitar a combinação. Informar neurologista ou geriatra."},
{"med1":["omeprazol","esomeprazol","lansoprazol","pantoprazol"],"med2":["magnésio"],"nivel":"baixo","titulo":"IBP Crônico + Magnésio (Deficiência)","mecanismo":"Uso prolongado de IBPs reduz a secreção gástrica ácida necessária para a absorção ativa de magnésio pelo TRPM6 intestinal.","efeito":"Hipomagnesemia grave com uso prolongado (>1 ano) — cãibras, arritmias, tetania.","conduta":"✅ Em uso crônico (>1 ano), monitorar magnésio sérico anualmente. Suplementar se necessário."},
{"med1":["omeprazol","esomeprazol"],"med2":["metotrexato"],"nivel":"moderado","titulo":"IBP + Metotrexato","mecanismo":"Omeprazol e esomeprazol inibem o transportador de efluxo ABCG2 renal do metotrexato, reduzindo sua eliminação e elevando seus níveis séricos.","efeito":"Toxicidade por metotrexato — mielossupressão, mucosite, hepatotoxicidade.","conduta":"⚠️ Evitar omeprazol/esomeprazol com metotrexato em doses intermediárias/altas. Usar pantoprazol."},
{"med1":["sulfametoxazol","sulfametoxazol + trimetoprima"],"med2":["metformina"],"nivel":"baixo","titulo":"Sulfametoxazol-Trimetoprima + Metformina","mecanismo":"A trimetoprima inibe a secreção tubular de creatinina (elevação falsa) e pode comprometer levemente a função renal — importante pois metformina exige função renal preservada.","efeito":"Elevação da creatinina sérica (parcialmente falsa) que pode levar à suspensão desnecessária da metformina.","conduta":"✅ Monitorar função renal real (cistatina C ou GFR calculado corretamente). Geralmente não há necessidade de suspender metformina."},
{"med1":["rivaroxabana","apixabana"],"med2":["voriconazol","posaconazol"],"nivel":"alto","titulo":"NOAC + Antifúngico Azólico Potente","mecanismo":"Voriconazol e posaconazol inibem fortemente CYP3A4 e P-glicoproteína, as duas vias de eliminação de rivaroxabana e apixabana — acúmulo do anticoagulante.","efeito":"Risco muito elevado de sangramento grave por concentrações excessivas do NOAC.","conduta":"❌ Contraindicado. Substituir NOAC por heparina de baixo peso molecular durante tratamento antifúngico azólico potente."},
{"med1":["ipratrópio","tiotrópio","tiotrópio"],"med2":["biperideno","oxibutinina","amitriptilina","prometazina"],"nivel":"moderado","titulo":"Anticolinérgico Inalatório + Anticolinérgico Sistêmico","mecanismo":"Anticolinérgicos inalatórios têm efeitos sistêmicos mínimos quando bem inalados, mas em combinação com anticolinérgicos orais os efeitos periféricos se somam.","efeito":"Boca seca intensa, retenção urinária, visão turva e constipação — toxicidade anticolinérgica cumulativa.","conduta":"⚠️ Revisar carga anticolinérgica total, especialmente em idosos. Evitar múltiplos anticolinérgicos."},
{"med1":["pseudoefedrina","efedrina"],"med2":["tricíclico","amitriptilina","nortriptilina","imipramina"],"nivel":"moderado","titulo":"Descongestionante Simpatomimético + Tricíclico","mecanismo":"Tricíclicos inibem o transportador de recaptação de noradrenalina. Simpatomiméticos que liberam noradrenalina têm resposta exagerada por não haver recaptação.","efeito":"Hipertensão aguda, taquicardia e risco de arritmias — especialmente com descongestionantes nasais e antigripais.","conduta":"⚠️ Evitar descongestionantes com tricíclicos. Usar spray nasal de corticoide como alternativa."},
{"med1":["tamoxifeno"],"med2":["warfarina","varfarina"],"nivel":"moderado","titulo":"Tamoxifeno + Warfarina","mecanismo":"O tamoxifeno inibe CYP2C9, principal enzima de metabolismo da warfarina S, elevando o INR de forma significativa.","efeito":"Elevação expressiva do INR com risco de sangramento grave.","conduta":"⚠️ Monitorar INR frequentemente ao iniciar tamoxifeno. Pode ser necessário reduzir dose de warfarina."},
{"med1":["medroxiprogesterona"],"med2":["rifampicina"],"nivel":"alto","titulo":"Medroxiprogesterona (Anticoncepcional Injetável) + Rifampicina","mecanismo":"A rifampicina induz CYP3A4, acelerando o metabolismo da medroxiprogesterona e reduzindo sua concentração a níveis subtherapêuticos.","efeito":"Falha contraceptiva — gravidez não planejada.","conduta":"❌ Usar método contraceptivo adicional. Considerar DIU de cobre como alternativa não hormonal."},
{"med1":["levonorgestrel","etonogestrel"],"med2":["carbamazepina","rifampicina","fenitoína","fenobarbital"],"nivel":"alto","titulo":"Progestágeno (Contracepção de Emergência) + Indutor Enzimático","mecanismo":"Indutores de CYP3A4 aceleram o metabolismo do levonorgestrel, reduzindo seus níveis abaixo do necessário para inibir a ovulação ou nidação.","efeito":"Falha da contracepção de emergência — risco de gravidez não planejada.","conduta":"❌ Em usuárias de indutores enzimáticos, usar 2 comprimidos de levonorgestrel 1,5mg (dose dobrada) ou preferir inserção de DIU de cobre como contracepção de emergência."},
{"med1":["ácido fólico"],"med2":["fenitoína","carbamazepina","fenobarbital"],"nivel":"moderado","titulo":"Ácido Fólico + Anticonvulsivante","mecanismo":"O ácido fólico em altas doses pode aumentar o metabolismo de alguns anticonvulsivantes (especialmente fenitoína), reduzindo seus níveis séricos.","efeito":"Possível redução dos níveis do anticonvulsivante com risco de perda do controle de crises.","conduta":"⚠️ Usar doses baixas de ácido fólico (400–800mcg/dia). Monitorar nível sérico do anticonvulsivante ao iniciar suplementação."},
{"med1":["fentanila"],"med2":["rifampicina"],"nivel":"moderado","titulo":"Fentanila + Rifampicina","mecanismo":"A rifampicina induz CYP3A4 e P-glicoproteína, acelerando o metabolismo da fentanila e reduzindo seus níveis plasmáticos.","efeito":"Redução da analgesia — dor não controlada mesmo em doses habituais de fentanila.","conduta":"⚠️ Aumentar a dose de fentanila ou usar morfina (menos afetada). Monitorar intensidade da dor."},
{"med1":["buprenorfina"],"med2":["alprazolam","diazepam","clonazepam","benzodiazepínico","zolpidem"],"nivel":"alto","titulo":"Buprenorfina + Benzodiazepínico / Hipnótico","mecanismo":"Combinação de agonista opioide parcial (buprenorfina) com depressor do SNC — embora a buprenorfina tenha \"teto\" de depressão respiratória, a combinação com BZD supera esse efeito protetor.","efeito":"Depressão respiratória grave e morte — FDA emitiu alerta de caixa preta (black box warning) para esta combinação.","conduta":"❌ Evitar a combinação. Se necessário, monitoramento hospitalar rigoroso. A maioria das mortes por overdose de buprenorfina ocorre com BZDs."},
{"med1":["naloxona"],"med2":["morfina","codeína","tramadol","fentanila","buprenorfina"],"nivel":"alto","titulo":"Naloxona + Opioide Agonista","mecanismo":"A naloxona é antagonista puro de receptores opioides — desloca o opioide agonista dos receptores e precipita abstinência aguda em dependentes.","efeito":"Síndrome de abstinência aguda grave — agitação, dor, convulsões, vômitos; em superdosagem, reverte efeitos letais do opioide.","conduta":"⚠️ Naloxona é usada intencionalmente para reverter overdose. Em pacientes não dependentes em emergência, é vital. Em dependentes, usar doses tituladas baixas."},
{"med1":["metformina"],"med2":["dapagliflozina","empagliflozina","canagliflozina"],"nivel":"baixo","titulo":"Metformina + SGLT-2 (Combinação Padrão)","mecanismo":"Mecanismos complementares: metformina reduz gliconeogênese hepática; SGLT-2 inibidores aumentam excreção de glicose na urina — sem sobreposição de mecanismo.","efeito":"Combinação muito eficaz para DM2 com benefícios cardiovasculares e renais adicionais. Risco baixo de hipoglicemia.","conduta":"✅ Combinação recomendada nas diretrizes de diabetes. Monitorar função renal e sinais de infecção urinária."},
{"med1":["insulina","insulina nph","insulina regular","insulina glargina","glibenclamida","glipizida","gliclazida","glimepirida"],"med2":["álcool","alcool","bebida"],"nivel":"alto","titulo":"Insulina / Sulfonilureia + Álcool (Hipoglicemia Grave)","mecanismo":"O álcool inibe a gliconeogênese hepática — em jejum ou com pouca ingestão, impede o fígado de repor glicose. Sulfonileureias (glibenclamida, glipizida) estimulam insulina independentemente da glicemia, agravando o risco.","efeito":"Hipoglicemia grave e silenciosa — sintomas como confusão e sonolência são mascarados pelos efeitos do álcool. Risco de hipoglicemia noturna, inconsciência e coma hipoglicêmico.","conduta":"❌ Nunca consumir álcool em jejum com insulina ou sulfonilureia. Ingerir carboidratos ao beber. Monitorar glicemia. Orientar familiares e cuidadores sobre o risco silencioso — em caso de inconsciência, acionar SAMU."},
{"med1":["vareniclina"],"med2":["bupropiona"],"nivel":"moderado","titulo":"Vareniclina + Bupropiona (Cessação Tabágica Combinada)","mecanismo":"Ambas agem no SNC para reduzir a dependência nicotínica por mecanismos diferentes — vareniclina via receptores nicotínicos; bupropiona via inibição da recaptação de dopamina/noradrenalina. Efeitos neurológicos aditivos.","efeito":"Risco aumentado de efeitos neuropsiquiátricos — humor deprimido, agitação, alteração de comportamento e ideação suicida.","conduta":"⚠️ Combinação possível mas com monitoramento estreito de sintomas neuropsiquiátricos. Informar paciente sobre sintomas de alerta."},
{"med1":["acarbose"],"med2":["enzimas digestivas","amilase","amilase pancreática"],"nivel":"moderado","titulo":"Acarbose + Enzimas Digestivas","mecanismo":"A acarbose inibe as alfa-glucosidases intestinais — o mesmo mecanismo que as enzimas digestivas de carboidratos ativam. As enzimas digestivas exógenas revertem o efeito da acarbose.","efeito":"Antagonismo direto — enzimas digestivas eliminam o efeito hipoglicemiante da acarbose.","conduta":"⚠️ Não usar enzimas digestivas com acarbose. A combinação anula o mecanismo terapêutico."},
{"med1":["sitagliptina","linagliptina","saxagliptina"],"med2":["insulina","sulfonilureia","glibenclamida","glimepirida"],"nivel":"moderado","titulo":"Inibidor de DPP-4 + Insulina / Sulfonilureia","mecanismo":"A combinação potencializa a liberação e ação da insulina por mecanismos diferentes. O risco de hipoglicemia é maior quando DPP-4 é combinado com secretagogos de insulina.","efeito":"Hipoglicemia moderada — especialmente com sulfonilureias de alta potência como glibenclamida.","conduta":"⚠️ Reduzir dose de sulfonilureia ou insulina ao adicionar inibidor de DPP-4. Monitorar glicemia."},
{"med1":["dapagliflozina","empagliflozina"],"med2":["rifampicina"],"nivel":"moderado","titulo":"SGLT-2 + Rifampicina","mecanismo":"A rifampicina induz UGT1A9, principal enzima de glucuronidação de dapagliflozina, reduzindo seus níveis séricos.","efeito":"Redução da eficácia do SGLT-2 inibidor — controle glicêmico inadequado.","conduta":"⚠️ Monitorar glicemia. Pode ser necessário trocar de antidiabético durante tratamento prolongado com rifampicina."},
{"med1":["montelucaste"],"med2":["genfibrozila","fluconazol"],"nivel":"moderado","titulo":"Montelucaste + Inibidor de CYP2C8","mecanismo":"O genfibrozila e fluconazol inibem CYP2C8, principal via de metabolismo do montelucaste, elevando seus níveis séricos significativamente.","efeito":"Acúmulo de montelucaste com possível aumento de efeitos adversos neuropsiquiátricos (pesadelos, ansiedade, alterações de comportamento).","conduta":"⚠️ Monitorar sintomas neuropsiquiátricos. Informar paciente sobre efeitos adversos que devem ser relatados."},
{"med1":["montelucaste"],"med2":["rifampicina"],"nivel":"moderado","titulo":"Montelucaste + Rifampicina","mecanismo":"A rifampicina induz CYP2C8 e CYP3A4, acelerando o metabolismo do montelucaste e reduzindo seus níveis em 40%.","efeito":"Redução da eficácia do montelucaste no tratamento da asma e rinite alérgica.","conduta":"⚠️ Monitorar controle dos sintomas respiratórios. Pode ser necessário aumentar a dose ou substituir."},
{"med1":["cetirizina","desloratadina","loratadina"],"med2":["álcool","alcool"],"nivel":"baixo","titulo":"Anti-Histamínico Não Sedativo + Álcool","mecanismo":"Cetirizina tem leve efeito sedativo residual que pode ser potencializado pelo álcool. Loratadina e desloratadina têm mínima interação.","efeito":"Leve potencialização da sedação com cetirizina. Loratadina e desloratadina têm impacto mínimo.","conduta":"✅ Loratadina e desloratadina são seguros com álcool em dose moderada. Cetirizina: evitar dirigir após uso com álcool."},
{"med1":["naltrexona"],"med2":["corticoide","prednisona","metilprednisolona"],"nivel":"moderado","titulo":"Naltrexona (Baixa Dose) + Corticoide","mecanismo":"A naltrexona em baixas doses (LDN) bloqueia receptores opioides nos glóbulos brancos, modulando citocinas. Corticoides suprimem a resposta imune pelo mesmo sistema — potencial antagonismo.","efeito":"Possível redução da eficácia do corticoide ou da naltrexona em baixa dose para condições imunológicas.","conduta":"⚠️ Monitorar resposta clínica. Combinação geralmente manejável com ajuste de doses."},
{"med1":["morfina","codeína"],"med2":["cimetidina"],"nivel":"moderado","titulo":"Opioide + Cimetidina","mecanismo":"A cimetidina inibe CYP3A4 e CYP2D6, reduzindo o metabolismo de morfina e codeína, podendo elevar seus níveis e reduzir a conversão de codeína ao metabólito ativo (morfina).","efeito":"Aumento dos efeitos adversos da morfina (sedação, náusea) e redução da analgesia da codeína.","conduta":"⚠️ Preferir ranitidina, famotidina ou omeprazol. Se cimetidina for necessária, reduzir dose do opioide."},
{"med1":["tramadol"],"med2":["carbamazepina"],"nivel":"moderado","titulo":"Tramadol + Carbamazepina","mecanismo":"A carbamazepina induz CYP3A4 e CYP2B6, acelerando o metabolismo do tramadol e reduzindo seus níveis — além disso, eleva limiar convulsivante de forma oposta.","efeito":"Redução da eficácia analgésica do tramadol e possível aumento do risco de convulsões.","conduta":"⚠️ Evitar a combinação. Usar opioide alternativo (morfina, oxicodona) se analgesia potente for necessária."},
{"med1":["tramadol"],"med2":["fenitoína"],"nivel":"moderado","titulo":"Tramadol + Fenitoína","mecanismo":"A fenitoína induz CYP2D6 e CYP3A4, acelerando o metabolismo do tramadol e reduzindo seus níveis analgésicos. Ambos abaixam o limiar convulsivante.","efeito":"Analgesia reduzida e risco aumentado de convulsões.","conduta":"⚠️ Evitar a combinação. Monitorar convulsões se uso for inevitável."},
{"med1":["paracetamol"],"med2":["carbamazepina","fenitoína","rifampicina"],"nivel":"moderado","titulo":"Paracetamol + Indutor Enzimático","mecanismo":"Indutores de CYP2E1 e CYP3A4 (carbamazepina, fenitoína, rifampicina) aumentam a formação do metabólito hepatotóxico NAPQI do paracetamol.","efeito":"Hepatotoxicidade em doses consideradas seguras — risco de insuficiência hepática aguda mesmo com paracetamol em dose normal.","conduta":"⚠️ Reduzir dose máxima de paracetamol para 2g/dia (ao invés de 4g) em usuários crônicos de indutores enzimáticos."},
{"med1":["ibuprofeno","naproxeno","ketoprofeno"],"med2":["lítio","carbonato de lítio"],"nivel":"alto","titulo":"AINE + Lítio","mecanismo":"AINEs inibem prostaglandinas vasodilatadoras renais, reduzindo o fluxo renal e a excreção de lítio — seus níveis séricos sobem de forma perigosa.","efeito":"Toxicidade por lítio — tremores de grande amplitude, confusão, ataxia, convulsões, danos renais permanentes.","conduta":"❌ Evitar. Usar paracetamol para dor em pacientes com lítio. Se AINE for inevitável, monitorar nível de lítio imediatamente."},
{"med1":["ketorolaco"],"med2":["warfarina","varfarina","heparina","enoxaparina"],"nivel":"alto","titulo":"Ketorolaco + Anticoagulante","mecanismo":"O ketorolaco inibe fortemente a COX-1 plaquetária, comprometendo a hemostasia, e irrita intensamente a mucosa gastrointestinal — risco hemorrágico muito elevado com anticoagulantes.","efeito":"Risco muito alto de hemorragia gastrointestinal grave — potencialmente fatal.","conduta":"❌ Contraindicado com qualquer anticoagulante. Usar paracetamol ou dipirona para analgesia."},
{"med1":["nimesulida"],"med2":["warfarina","varfarina","anticoagulante"],"nivel":"alto","titulo":"Nimesulida + Anticoagulante","mecanismo":"A nimesulida inibe COX-2 seletivamente mas tem efeitos antiagregantes plaquetários e pode afetar fatores de coagulação — risco hemorrágico somado ao anticoagulante.","efeito":"Risco elevado de sangramento gastrointestinal e em outros locais.","conduta":"❌ Evitar a combinação. Usar paracetamol ou dipirona para analgesia em pacientes anticoagulados."},
{"med1":["duloxetina"],"med2":["tioridazina","mesoridazina"],"nivel":"alto","titulo":"Duloxetina + Fenotiazina (Inibidor de CYP2D6)","mecanismo":"A duloxetina inibe CYP2D6, elevando os níveis de fenotiazinas que dependem desta via. A tioridazina também prolonga QT — o acúmulo é especialmente perigoso.","efeito":"Prolongamento grave do QT com risco de Torsades de Pointes.","conduta":"❌ Contraindicado. A duloxetina não deve ser usada com fenotiazinas que prolongam QT."},
{"med1":["clonazepam","diazepam"],"med2":["carbamazepina"],"nivel":"moderado","titulo":"Benzodiazepínico + Carbamazepina","mecanismo":"A carbamazepina induz CYP3A4, principal via de metabolismo de diazepam e clonazepam, reduzindo seus níveis séricos e eficácia anticonvulsivante.","efeito":"Redução da eficácia do benzodiazepínico — possível perda do controle de crises.","conduta":"⚠️ Monitorar eficácia do BZD. Pode ser necessário aumentar a dose de benzodiazepínico."},
{"med1":["carbamazepina"],"med2":["ácido valproico","valproato"],"nivel":"moderado","titulo":"Carbamazepina + Valproato","mecanismo":"A carbamazepina induz CYP2C9, acelerando o metabolismo do valproato e reduzindo seus níveis. O valproato, por sua vez, inibe a epóxido hidrolase, acumulando o metabólito tóxico 10,11-epóxido da carbamazepina.","efeito":"Níveis subterapêuticos de valproato (perda do controle de crises) E toxicidade por 10,11-epóxido da carbamazepina (diplopia, tontura).","conduta":"⚠️ Combinação frequente na epilepsia — monitorar níveis séricos de ambos regularmente."},
{"med1":["fenitoína"],"med2":["ácido valproico","valproato"],"nivel":"moderado","titulo":"Fenitoína + Valproato","mecanismo":"O valproato desloca a fenitoína das proteínas plasmáticas (eleva a fração livre e ativa) e inibe CYP2C9 (eleva os níveis totais). O resultado é complexo e imprevisível.","efeito":"Toxicidade por fenitoína mesmo com níveis totais normais (a fração livre está elevada) — nistagmo, ataxia, confusão.","conduta":"⚠️ Monitorar fenitoína livre (não total). Reduzir dose de fenitoína ao iniciar valproato."},
{"med1":["levetiracetam"],"med2":["carbamazepina"],"nivel":"moderado","titulo":"Levetiracetam + Carbamazepina","mecanismo":"A carbamazepina induz CYP3A4, podendo reduzir moderadamente os níveis de levetiracetam. Interação farmacocinética de impacto clínico geralmente modesto.","efeito":"Possível leve redução dos níveis de levetiracetam com necessidade de dose maior.","conduta":"⚠️ Monitorar frequência de crises. Ajustar dose de levetiracetam se necessário."},
{"med1":["fenitoína"],"med2":["ácido fólico"],"nivel":"moderado","titulo":"Fenitoína + Ácido Fólico (Alto Dose)","mecanismo":"O ácido fólico em altas doses (>5mg/dia) acelera o metabolismo da fenitoína, reduzindo seus níveis séricos. A fenitoína, por sua vez, causa deficiência de folato.","efeito":"Redução dos níveis de fenitoína e possível perda do controle das crises epilépticas com doses altas de folato.","conduta":"⚠️ Usar dose baixa de ácido fólico (400mcg/dia) para suplementação. Doses altas (>5mg) requerem monitoramento do nível de fenitoína."},
{"med1":["rivastigmina"],"med2":["betabloqueadores","propranolol","metoprolol"],"nivel":"moderado","titulo":"Rivastigmina + Betabloqueador","mecanismo":"A rivastigmina aumenta o tônus colinérgico cardíaco. Combinada com betabloqueadores (que já reduzem a frequência cardíaca), pode causar bradicardia sinérgica.","efeito":"Bradicardia excessiva e bloqueio atrioventricular — especialmente relevante em idosos com cardiopatia.","conduta":"⚠️ Monitorar ECG e frequência cardíaca ao iniciar rivastigmina em pacientes com betabloqueadores."},
{"med1":["donepezila","rivastigmina","galantamina"],"med2":["quinidina","amiodarona","sotalol"],"nivel":"moderado","titulo":"Inibidor de Colinesterase + Antiarrítmico","mecanismo":"Inibidores de colinesterase aumentam o tônus colinérgico cardíaco, potencializando o efeito cronotrópico negativo dos antiarrítmicos.","efeito":"Bradicardia sinusal grave e bloqueio AV.","conduta":"⚠️ Monitorar ECG e frequência cardíaca. Considerar pacemaker em pacientes de alto risco."},
{"med1":["amantadina"],"med2":["biperideno","oxibutinina","escopolamina"],"nivel":"moderado","titulo":"Amantadina + Anticolinérgico","mecanismo":"A amantadina tem ação anticolinérgica intrínseca. Combinada com anticolinérgicos, ocorre potencialização dos efeitos anticolinérgicos no SNC e periférico.","efeito":"Confusão mental, alucinações, retenção urinária e delirium — especialmente perigoso em idosos.","conduta":"⚠️ Evitar múltiplos anticolinérgicos, especialmente em idosos. Revisar necessidade de cada medicamento."},
{"med1":["rotigotina","pramipexol"],"med2":["metoclopramida"],"nivel":"moderado","titulo":"Agonista Dopaminérgico (Parkinson) + Metoclopramida","mecanismo":"A metoclopramida bloqueia receptores D2 de dopamina, antagonizando diretamente o mecanismo dos agonistas dopaminérgicos usados no Parkinson.","efeito":"Redução da eficácia do tratamento do Parkinson e piora dos sintomas motores.","conduta":"⚠️ Contraindicado em parkinsonianos. Usar ondansetrom ou domperidona como antiemético."},
{"med1":["levodopa","carbidopa + levodopa"],"med2":["haloperidol","clorpromazina","risperidona","olanzapina"],"nivel":"moderado","titulo":"Levodopa + Antipsicótico","mecanismo":"Antipsicóticos bloqueiam receptores de dopamina — mecanismo oposto ao da levodopa. A psicose por dopamina no Parkinson exige antipsicóticos que não bloqueiem D2 nigroestriatal.","efeito":"Piora dos sintomas parkinsonianos — rigidez, bradicinesia e tremor aumentados.","conduta":"⚠️ Usar apenas clozapina ou quetiapina em baixas doses para psicose parkinsoniana — estes têm menor afinidade pelos receptores D2 nigroestriatais."},
{"med1":["bromocriptina","cabergolina"],"med2":["eritromicina","claritromicina"],"nivel":"moderado","titulo":"Agonista Dopaminérgico Ergotamínico + Macrolídeo","mecanismo":"Macrolídeos inibem CYP3A4, principal via de metabolismo da bromocriptina e cabergolina, elevando seus níveis séricos.","efeito":"Acúmulo dos agonistas dopaminérgicos com risco de náusea, vômitos, hipotensão ortostática e alucinações.","conduta":"⚠️ Reduzir dose do agonista dopaminérgico ou usar azitromicina como alternativa antibiótica."},
{"med1":["oseltamivir"],"med2":["probenecida"],"nivel":"baixo","titulo":"Oseltamivir + Probenecida","mecanismo":"A probenecida inibe o transportador orgânico aniônico renal (OAT) que elimina o oseltamivir, dobrando seus níveis séricos.","efeito":"Aumento dos níveis de oseltamivir — pode ser benéfico em alguns contextos ou causar mais efeitos adversos gastrointestinais.","conduta":"✅ Interação geralmente não requer intervenção. Usada intencionalmente em algumas situações para economizar oseltamivir."},
{"med1":["isotretinoína"],"med2":["progesterona","levonorgestrel","etonogestrel"],"nivel":"moderado","titulo":"Isotretinoína + Anticoncepcional Apenas de Progestágeno","mecanismo":"A isotretinoína pode reduzir a eficácia dos anticoncepcionais apenas de progestágeno (pílula minidose, implante de etonogestrel), embora o mecanismo exato não esteja totalmente elucidado.","efeito":"Possível redução da eficácia contraceptiva — gravidez com risco de teratogenicidade extremamente grave.","conduta":"❌ Usar dois métodos contraceptivos eficazes durante isotretinoína, iniciando 1 mês antes e mantendo por 1 mês após. Anticoncepcionais com estrogênio são preferíveis."},
{"med1":["ciclosporina"],"med2":["metformina"],"nivel":"moderado","titulo":"Ciclosporina + Metformina","mecanismo":"A ciclosporina pode comprometer a função renal tubular, reduzindo a secreção tubular de metformina e elevando seu risco de acúmulo.","efeito":"Risco de acúmulo de metformina com acidose lática — especialmente se a função renal já estiver comprometida pela ciclosporina.","conduta":"⚠️ Monitorar função renal regularmente. Suspender metformina se creatinina elevar acima dos limites aceitos."},
{"med1":["sulfato ferroso","ferro"],"med2":["levotiroxina"],"nivel":"moderado","titulo":"Ferro + Levotiroxina","mecanismo":"O ferro forma quelatos insolúveis com a levotiroxina no lúmen intestinal, reduzindo sua absorção em até 50%.","efeito":"Hipotireoidismo mal controlado — TSH elevado mesmo com dose adequada de levotiroxina.","conduta":"⚠️ Tomar levotiroxina pelo menos 4 horas antes do suplemento de ferro."},
{"med1":["ferro","sulfato ferroso"],"med2":["quinolona","ciprofloxacino","levofloxacino"],"nivel":"moderado","titulo":"Ferro + Fluoroquinolona","mecanismo":"O ferro forma quelatos com as fluoroquinolonas no intestino, reduzindo drasticamente sua absorção oral.","efeito":"Redução da absorção do antibiótico em 30–80% — falha terapêutica da infecção bacteriana.","conduta":"⚠️ Tomar fluoroquinolona 2 horas antes ou 6 horas depois do ferro."},
{"med1":["cálcio","carbonato de cálcio","citrato de cálcio"],"med2":["quinolona","ciprofloxacino","levofloxacino","doxiciclina"],"nivel":"moderado","titulo":"Cálcio + Antibiótico","mecanismo":"O cálcio (cátion divalente) forma quelatos com fluoroquinolonas e tetraciclinas no intestino, impedindo sua absorção.","efeito":"Redução significativa da absorção do antibiótico — eficácia terapêutica comprometida.","conduta":"⚠️ Separar o antibiótico do cálcio por pelo menos 2 horas (quinolona) ou 3 horas (doxiciclina)."},
{"med1":["cálcio"],"med2":["tiazídico","hidroclorotiazida","clortalidona"],"nivel":"moderado","titulo":"Cálcio (Suplemento) + Diurético Tiazídico","mecanismo":"Tiazídicos reduzem a excreção renal de cálcio. Combinados com suplementação de cálcio e vitamina D, podem causar hipercalcemia — síndrome leite-álcali.","efeito":"Hipercalcemia com fraqueza muscular, confusão, constipação, nefrolitíase e insuficiência renal.","conduta":"⚠️ Monitorar cálcio sérico em usuários de tiazídicos que suplementam cálcio. Usar dose mínima necessária."},
{"med1":["magnésio"],"med2":["digoxina"],"nivel":"moderado","titulo":"Magnésio (Hipomagnesemia) + Digoxina","mecanismo":"A hipomagnesemia aumenta a excitabilidade do miocárdio e a sensibilidade à digoxina — assim como a hipocalemia. Baixo magnésio é frequente com diuréticos de alça.","efeito":"Toxicidade digitálica mesmo com níveis \"normais\" de digoxina — arritmias graves.","conduta":"⚠️ Manter magnésio sérico >0,8 mEq/L em usuários de digoxina. Suplementar magnésio em uso de diuréticos de alça."},
{"med1":["colecalciferol","vitamina d"],"med2":["tiazídico","hidroclorotiazida"],"nivel":"moderado","titulo":"Vitamina D + Tiazídico","mecanismo":"A vitamina D aumenta a absorção intestinal de cálcio; tiazídicos reduzem a excreção renal de cálcio. A combinação em doses altas pode levar à hipercalcemia.","efeito":"Hipercalcemia — fraqueza, confusão, nefrolitíase, calcificações vasculares.","conduta":"⚠️ Monitorar cálcio sérico com uso simultâneo de vitamina D e tiazídicos, especialmente em idosos."},
{"med1":["potássio","cloreto de potássio","gluconato de potássio"],"med2":["captopril","enalapril","losartana","espironolactona"],"nivel":"alto","titulo":"Suplemento de Potássio + IECA / BRA / Espironolactona","mecanismo":"Todos esses medicamentos retêm potássio por diferentes mecanismos. Suplementação adicional provoca acúmulo perigoso.","efeito":"Hipercalemia grave com risco de arritmias fatais — especialmente em idosos e diabéticos.","conduta":"❌ Evitar suplementos de potássio sem exame de potássio sérico confirmando deficiência real. Monitorar eletrolitos."},
{"med1":["ômega-3","ácido eicosapentaenoico","EPA"],"med2":["aspirina","clopidogrel"],"nivel":"baixo","titulo":"Ômega-3 + Antiagregante Plaquetário","mecanismo":"O ômega-3 em doses medicinais (>2g/dia) tem efeito antiagregante plaquetário leve — pode somar-se ao AAS ou clopidogrel.","efeito":"Risco levemente aumentado de sangramento com doses altas de ômega-3 em combinação com antiagregantes.","conduta":"✅ Em doses nutricionais (<2g/dia) geralmente seguro. Doses medicinais (4g/dia para triglicerídeos): monitorar sangramento."},
{"med1":["zinco"],"med2":["ferro","sulfato ferroso"],"nivel":"moderado","titulo":"Zinco + Ferro","mecanismo":"Zinco e ferro competem pelo mesmo transportador intestinal de metais divalentes (DMT-1) — absorção de um reduz a do outro.","efeito":"Redução mútua da absorção — comprometimento da correção de deficiência de ferro ou zinco.","conduta":"⚠️ Tomar zinco e ferro em horários separados (pelo menos 2 horas de intervalo)."},
{"med1":["zinco"],"med2":["levotiroxina"],"nivel":"moderado","titulo":"Zinco + Levotiroxina","mecanismo":"O zinco forma quelatos com a levotiroxina no intestino, reduzindo sua absorção oral.","efeito":"Absorção reduzida de levotiroxina — hipotireoidismo mal controlado.","conduta":"⚠️ Separar levotiroxina e zinco por pelo menos 4 horas."},
{"med1":["vitamina b12","cianocobalamina"],"med2":["omeprazol","esomeprazol","lansoprazol"],"nivel":"baixo","titulo":"Vitamina B12 + IBP (Deficiência Crônica)","mecanismo":"O ácido gástrico é necessário para separar a vitamina B12 das proteínas alimentares. IBPs reduzem a acidez, comprometendo a absorção da B12 proveniente de alimentos (não de suplementos).","efeito":"Deficiência de B12 com uso prolongado de IBP (>2 anos) — neuropatia periférica, anemia megaloblástica.","conduta":"✅ Monitorar B12 a cada 2 anos com uso prolongado de IBP. Suplementar se necessário (comprimidos sublinguais ou injetável funcionam bem)."},
{"med1":["furosemida"],"med2":["ibuprofeno","diclofenaco","aine"],"nivel":"moderado","titulo":"Furosemida + AINE","mecanismo":"AINEs inibem prostaglandinas vasodilatadoras renais, reduzindo o fluxo renal e a eficácia diurética da furosemida. Também antagonizam o efeito anti-hipertensivo.","efeito":"Redução do efeito diurético e anti-hipertensivo — edema retorna e pressão sobe. Risco de lesão renal.","conduta":"⚠️ Preferir paracetamol para analgesia em pacientes com insuficiência cardíaca ou renal usando furosemida."},
{"med1":["captopril","enalapril"],"med2":["dapagliflozina","empagliflozina","canagliflozina"],"nivel":"baixo","titulo":"IECA + SGLT-2 (Cardioproteção)","mecanismo":"Mecanismos complementares de nefroproteção e cardioproteção — IECA reduz pressão intraglomerular; SGLT-2 reduz reabsorção tubular de glicose e tem efeito osmótico protetor.","efeito":"Combinação benéfica com efeitos aditivos na proteção renal e cardiovascular em diabéticos.","conduta":"✅ Combinação recomendada em diabéticos com DCV ou IRC. Monitorar pressão e potássio."},
{"med1":["digoxina"],"med2":["eritromicina"],"nivel":"alto","titulo":"Digoxina + Eritromicina (Microbioma Intestinal)","mecanismo":"Até 10% dos pacientes têm flora intestinal que degrada a digoxina (Eggerthella lenta). A eritromicina elimina essa flora, aumentando subitamente a absorção da digoxina.","efeito":"Aumento repentino dos níveis de digoxina — intoxicação digitálica aguda.","conduta":"❌ Monitorar nível sérico de digoxina ao iniciar eritromicina. Substituir por azitromicina ou amoxicilina quando possível."},
{"med1":["warfarina","varfarina"],"med2":["atorvastatina","sinvastatina","rosuvastatina"],"nivel":"baixo","titulo":"Warfarina + Estatina","mecanismo":"Algumas estatinas (principalmente sinvastatina e atorvastatina) têm leve efeito inibitório sobre CYP2C9, podendo elevar modestamente o INR.","efeito":"Leve aumento do INR ao iniciar estatina — geralmente de pouca relevância clínica mas monitorável.","conduta":"✅ Monitorar INR nas primeiras semanas após iniciar ou ajustar dose de estatina."},
{"med1":["pantoprazol","rabeprazol"],"med2":["clopidogrel"],"nivel":"baixo","titulo":"Pantoprazol / Rabeprazol + Clopidogrel","mecanismo":"Ao contrário de omeprazol e esomeprazol, pantoprazol e rabeprazol têm menor efeito inibitório sobre CYP2C19 — a ativação do clopidogrel é menos comprometida.","efeito":"Menor risco cardiovascular do que com omeprazol. Combinação considerada relativamente segura.","conduta":"✅ Preferir pantoprazol ou rabeprazol (ao invés de omeprazol/esomeprazol) para proteção gástrica em usuários de clopidogrel."},
{"med1":["rivaroxabana","apixabana"],"med2":["dalteparina","enoxaparina","fondaparinux"],"nivel":"alto","titulo":"NOAC + Anticoagulante Parenteral","mecanismo":"Combinação de dois anticoagulantes com mecanismos diferentes — efeito anticoagulante aditivo sem benefício terapêutico adicional na maioria das situações.","efeito":"Risco muito elevado de sangramento grave.","conduta":"❌ Nunca combinar dois anticoagulantes sem indicação específica (ex: transição). A transição deve ser feita com cuidado preciso quanto ao momento."},
{"med1":["aminoglicosídeos","gentamicina","tobramicina","amicacina"],"med2":["ciclosporina","tacrolimo"],"nivel":"alto","titulo":"Aminoglicosídeo + Imunossupressor Calcineurínico","mecanismo":"Aminoglicosídeos e calcineurínicos são nefrotóxicos por mecanismos diferentes. A combinação provoca dano renal tubular sinérgico.","efeito":"Insuficiência renal aguda grave, especialmente em transplantados.","conduta":"❌ Evitar. Se inevitável (infecção grave em transplantado), monitorar função renal diariamente e usar menor dose eficaz por menor tempo."},
{"med1":["infliximabe","etanercepte","adalimumabe"],"med2":["anakinra"],"nivel":"alto","titulo":"Anti-TNF + Anakinra (Inibidor de IL-1)","mecanismo":"Combinação de dois imunossupressores biológicos com diferentes alvos — supressão imune cumulativa e risco de infecções oportunistas graves.","efeito":"Infecções graves e potencialmente fatais — tuberculose, fungos invasivos, sepse bacteriana.","conduta":"❌ Contraindicado. Nunca combinar dois imunossupressores biológicos."},
{"med1":["infliximabe","adalimumabe","etanercepte"],"med2":["vacina viva","vacina bcg","vacina febre amarela","vacina varicela"],"nivel":"alto","titulo":"Biológico Imunossupressor + Vacina de Vírus Vivo","mecanismo":"Imunossupressores biológicos reduzem a imunidade suficientemente para que organismos de vacinas vivas atenuadas causem doença.","efeito":"Doença por vacina — tuberculose disseminada após BCG, febre amarela vacinal, varicela disseminada.","conduta":"❌ Contraindicado. Vacinas vivas devem ser aplicadas pelo menos 4 semanas antes de iniciar biológico. Aguardar meses após suspender para revacinar."},
{"med1":["cloroquina","hidroxicloroquina"],"med2":["digoxina"],"nivel":"moderado","titulo":"Cloroquina / Hidroxicloroquina + Digoxina","mecanismo":"A cloroquina e hidroxicloroquina inibem P-glicoproteína renal, reduzindo a eliminação da digoxina e elevando seus níveis séricos.","efeito":"Intoxicação digitálica — bradicardia, arritmias.","conduta":"⚠️ Monitorar nível sérico de digoxina e ECG ao iniciar antipalúdico."},
{"med1":["cloroquina","hidroxicloroquina"],"med2":["ciclosporina"],"nivel":"moderado","titulo":"Cloroquina / Hidroxicloroquina + Ciclosporina","mecanismo":"A cloroquina pode inibir o metabolismo da ciclosporina e ambas têm efeito nefrotóxico potencial.","efeito":"Elevação dos níveis de ciclosporina com risco de nefrotoxicidade.","conduta":"⚠️ Monitorar nível sérico de ciclosporina e função renal ao usar antipalúdicos concomitantemente."},
{"med1":["colestipol","colestiramina"],"med2":["ácido valproico","valproato"],"nivel":"moderado","titulo":"Resina Quelante + Valproato","mecanismo":"As resinas quelam o valproato no intestino e interrompem seu ciclo entero-hepático, reduzindo seus níveis séricos.","efeito":"Redução dos níveis de valproato — risco de crises epilépticas.","conduta":"⚠️ Tomar valproato 1 hora antes ou 4–6 horas depois das resinas."},
{"med1":["colestiramina","colestipol"],"med2":["propranolol","metoprolol"],"nivel":"moderado","titulo":"Resina Quelante + Betabloqueador","mecanismo":"As resinas reduzem a absorção de betabloqueadores lipofílicos (propranolol, metoprolol) ao quelá-los no intestino.","efeito":"Redução dos níveis do betabloqueador — perda do controle da frequência cardíaca e da pressão.","conduta":"⚠️ Tomar betabloqueador 1 hora antes das resinas."},
{"med1":["hidroclorotiazida","clortalidona"],"med2":["ibuprofeno","diclofenaco","aine"],"nivel":"moderado","titulo":"Tiazídico + AINE","mecanismo":"AINEs inibem prostaglandinas vasodilatadoras renais, antagonizando o efeito natriurético e anti-hipertensivo dos tiazídicos. Retenção de sódio reduz o efeito diurético.","efeito":"Redução do efeito anti-hipertensivo e diurético — edema e hipertensão podem retornar.","conduta":"⚠️ Preferir paracetamol para analgesia em hipertensos tratados com diuréticos."},
{"med1":["dapagliflozina","empagliflozina"],"med2":["hidroclorotiazida","clortalidona"],"nivel":"moderado","titulo":"SGLT-2 + Tiazídico","mecanismo":"Ambos têm efeito natriurético e diurético — combinação pode causar depleção de volume e hipotensão, especialmente em idosos.","efeito":"Hipotensão, desidratação e hipocalemia — risco de quedas em idosos.","conduta":"⚠️ Monitorar pressão arterial, peso e eletrólitos. Reduzir dose de tiazídico ao iniciar SGLT-2."},
{"med1":["venlafaxina"],"med2":["clonidina"],"nivel":"moderado","titulo":"Venlafaxina + Clonidina","mecanismo":"A venlafaxina inibe a recaptação de noradrenalina, elevando os níveis no SNC. A clonidina age nos receptores α2-adrenérgicos centrais — a venlafaxina pode reduzir a eficácia da clonidina anti-hipertensiva.","efeito":"Redução da eficácia da clonidina e risco de hipertensão rebote ao suspender a clonidina.","conduta":"⚠️ Monitorar pressão arterial. Não suspender clonidina abruptamente."},
{"med1":["clomifeno"],"med2":["tamoxifeno"],"nivel":"moderado","titulo":"Clomifeno + Tamoxifeno","mecanismo":"Ambos são moduladores seletivos de receptores de estrogênio (SERM) — o tamoxifeno pode competir e reduzir a eficácia do clomifeno na indução da ovulação.","efeito":"Redução da eficácia da indução de ovulação pelo clomifeno.","conduta":"⚠️ Evitar uso simultâneo. Suspender tamoxifeno antes de iniciar ciclo de estimulação com clomifeno."},
{"med1":["finasterida","dutasterida"],"med2":["verapamil","diltiazem"],"nivel":"moderado","titulo":"Inibidor de 5-α Redutase + Inibidor de CYP3A4","mecanismo":"Verapamil e diltiazem inibem CYP3A4, via de metabolismo de dutasterida e finasterida, elevando moderadamente seus níveis.","efeito":"Aumento dos efeitos adversos dos inibidores de 5-αR — disfunção erétil, ginecomastia.","conduta":"⚠️ Geralmente bem tolerado. Monitorar efeitos adversos relacionados à supressão androgênica."},
{"med1":["tamsulosina","silodosina","doxazosina"],"med2":["verapamil","diltiazem"],"nivel":"moderado","titulo":"Alfabloqueador + Verapamil / Diltiazem","mecanismo":"Verapamil e diltiazem inibem CYP3A4, aumentando os níveis de tamsulosina e silodosina. Além disso, ambos os grupos têm efeito vasodilatador.","efeito":"Hipotensão ortostática grave — risco de síncope, especialmente nas primeiras doses.","conduta":"⚠️ Iniciar alfabloqueador em dose baixa. Orientar sobre hipotensão ao levantar."},
{"med1":["sildenafila","tadalafila"],"med2":["ritonavir","saquinavir","indinavir"],"nivel":"alto","titulo":"Inibidor de PDE-5 + Inibidor de Protease (HIV)","mecanismo":"Inibidores de protease inibem fortemente CYP3A4, elevando os níveis de sildenafila em até 11 vezes e de tadalafila em até 2 vezes.","efeito":"Hipotensão grave, priapismo, alteração visual e risco cardiovascular elevado.","conduta":"❌ Contraindicado com ritonavir. Com outros IPs: usar sildenafila 25mg e tadalafila 10mg com intervalo de 72h entre doses."},
{"med1":["sildenafila","tadalafila","vardenafila"],"med2":["cetoconazol","itraconazol","voriconazol"],"nivel":"moderado","titulo":"Inibidor de PDE-5 + Antifúngico Azólico","mecanismo":"Azólicos inibem CYP3A4, elevando consideravelmente os níveis dos inibidores de PDE-5.","efeito":"Hipotensão acentuada, priapismo e taquicardia reflexa.","conduta":"⚠️ Reduzir dose do inibidor de PDE-5 para metade. Não usar vardenafila com cetoconazol/itraconazol."},
{"med1":["minoxidil"],"med2":["nitroglicerina","nitratos","isossorbida"],"nivel":"moderado","titulo":"Minoxidil + Nitratos","mecanismo":"Ambos são vasodilatadores diretos — o efeito hipotensor é aditivo e pode ser excessivo.","efeito":"Hipotensão grave, taquicardia reflexa e retenção de líquidos.","conduta":"⚠️ Monitorar pressão arterial. O minoxidil oral exige diurético associado e betabloqueador para controlar taquicardia reflexa."},
{"med1":["desmopressina"],"med2":["carbamazepina","clorpropamida","oxitocina"],"nivel":"moderado","titulo":"Desmopressina + Potenciadores do Efeito Antidiurético","mecanismo":"Carbamazepina e clorpropamida potencializam o efeito antidiurético da desmopressina através de mecanismos que aumentam a sensibilidade renal ao ADH.","efeito":"Hiponatremia grave com risco de convulsões, coma e morte — especialmente em crianças e idosos.","conduta":"⚠️ Monitorar sódio sérico, especialmente na fase inicial. Usar dose mínima eficaz de desmopressina."},
{"med1":["ezetimiba"],"med2":["ciclosporina"],"nivel":"alto","titulo":"Ezetimiba + Ciclosporina","mecanismo":"A ciclosporina inibe OATP1B1 e MRP2, transportadores envolvidos na eliminação biliar da ezetimiba, elevando seus níveis em até 12 vezes.","efeito":"Acúmulo de ezetimiba com risco de hepatotoxicidade e disfunção renal.","conduta":"⚠️ Usar com cautela em transplantados. Monitorar função hepática e renal."},
{"med1":["ácido zoledrónico","pamidronato"],"med2":["aminoglicosídeos","gentamicina"],"nivel":"moderado","titulo":"Bisfosfonato IV + Aminoglicosídeo","mecanismo":"Ambos são nefrotóxicos. A combinação aumenta o risco de hipocalcemia prolongada (bisfosfonato) e insuficiência renal (aminoglicosídeo).","efeito":"Hipocalcemia grave e lesão renal aguda.","conduta":"⚠️ Monitorar cálcio sérico, magnésio e creatinina. Manter hidratação adequada."},
{"med1":["leflunomida"],"med2":["rifampicina"],"nivel":"moderado","titulo":"Leflunomida + Rifampicina","mecanismo":"A rifampicina induz CYP1A2 e CYP3A4, acelerando o metabolismo da leflunomida e elevando os níveis do metabólito ativo (teriflunomida) — paradoxalmente eleva o metabólito ativo.","efeito":"Possível aumento da eficácia E toxicidade da leflunomida (hepatotoxicidade, mielossupressão).","conduta":"⚠️ Monitorar hemograma e enzimas hepáticas com frequência. Combinação raramente necessária."},
{"med1":["adalimumabe","etanercepte","infliximabe"],"med2":["warfarina","varfarina"],"nivel":"moderado","titulo":"Biológico Anti-TNF + Warfarina","mecanismo":"A inflamação sistêmica altera o metabolismo hepático da warfarina. Ao controlar a inflamação com biológico, o metabolismo da warfarina normaliza — INR pode cair.","efeito":"Redução do INR ao controlar a inflamação com biológico — risco de subtratamento anticoagulante.","conduta":"⚠️ Monitorar INR mais frequentemente nas primeiras semanas após iniciar ou suspender biológico."},
{"med1":["probenecida"],"med2":["aspirina","ácido acetilsalicílico"],"nivel":"moderado","titulo":"Probenecida + Aspirina","mecanismo":"A aspirina compete com o ácido úrico no transportador tubular renal e antagoniza o efeito uricosúrico da probenecida, mesmo em baixas doses.","efeito":"Neutralização do efeito hipouricemiante da probenecida — gota não controlada.","conduta":"⚠️ Evitar aspirina em usuários de probenecida para gota. Usar paracetamol ou naproxeno para dor."},
{"med1":["furosemida"],"med2":["aminoglicosídeos"],"nivel":"alto","titulo":"Furosemida + Aminoglicosídeo","mecanismo":"A furosemida aumenta a concentração de aminoglicosídeos nos fluidos cocleares e reduz a velocidade de fluxo tubular renal — potencializando a ototoxicidade e nefrotoxicidade dos aminoglicosídeos.","efeito":"Surdez irreversível e insuficiência renal grave.","conduta":"❌ Evitar. Se necessário, monitorar função renal, eletrólitos e audição intensivamente. Usar menor dose por menor tempo."},
{"med1":["espironolactona"],"med2":["ibuprofeno","diclofenaco","aine"],"nivel":"moderado","titulo":"Espironolactona + AINE","mecanismo":"AINEs inibem prostaglandinas vasodilatadoras renais, reduzindo a perfusão renal e antagonizando o efeito diurético e natriurético da espironolactona.","efeito":"Redução do efeito diurético da espironolactona e risco de descompensação em pacientes com insuficiência cardíaca.","conduta":"⚠️ Preferir paracetamol para analgesia em pacientes em uso de espironolactona."},
{"med1":["ivabradina"],"med2":["suco de toranja","toranja"],"nivel":"moderado","titulo":"Ivabradina + Suco de Toranja","mecanismo":"A toranja inibe CYP3A4 intestinal, principal via de metabolismo da ivabradina, elevando seus níveis séricos.","efeito":"Bradicardia excessiva e possíveis distúrbios visuais (fenômenos luminosos).","conduta":"⚠️ Evitar suco de toranja durante uso de ivabradina."},
{"med1":["lapatinibe","erlotinibe","gefitinibe"],"med2":["omeprazol","esomeprazol","lansoprazol"],"nivel":"moderado","titulo":"Inibidor de Tirosina Quinase (EGFR) + IBP","mecanismo":"Lapatinibe e erlotinibe requerem pH ácido para dissolução e absorção. IBPs elevam o pH gástrico, reduzindo drasticamente a absorção oral.","efeito":"Redução significativa dos níveis do medicamento oncológico — falha no tratamento do câncer.","conduta":"❌ Evitar IBPs com lapatinibe. Para erlotinibe: tomar 2 horas antes ou 10 horas depois do IBP."},
{"med1":["imatinibe"],"med2":["rifampicina","carbamazepina","fenitoína"],"nivel":"alto","titulo":"Imatinibe + Indutor Enzimático Potente","mecanismo":"Indutores de CYP3A4 reduzem os níveis de imatinibe em até 70%, comprometendo o tratamento de leucemia mieloide crônica ou GIST.","efeito":"Falha terapêutica — perda do controle da doença oncológica.","conduta":"❌ Contraindicado. Substituir o indutor enzimático ou dobrar a dose de imatinibe com monitoramento oncológico."},
{"med1":["imatinibe"],"med2":["paracetamol"],"nivel":"moderado","titulo":"Imatinibe + Paracetamol","mecanismo":"O imatinibe inibe UGT1A6, enzima de glucuronidação do paracetamol, aumentando seus níveis e o risco de formação do metabólito hepatotóxico NAPQI.","efeito":"Risco aumentado de hepatotoxicidade pelo paracetamol — mesmo em doses consideradas seguras.","conduta":"⚠️ Limitar paracetamol a 2g/dia durante tratamento com imatinibe. Monitorar enzimas hepáticas."},
{"med1":["tacrolimo"],"med2":["nifedipina","anlodipino"],"nivel":"moderado","titulo":"Tacrolimo + Bloqueador de Canal de Cálcio","mecanismo":"Nifedipina e anlodipino inibem CYP3A4 (nifedipina mais que anlodipino), reduzindo o metabolismo do tacrolimo e elevando seus níveis séricos.","efeito":"Elevação dos níveis de tacrolimo com risco de nefrotoxicidade e neurotoxicidade.","conduta":"⚠️ Monitorar nível sérico de tacrolimo e função renal ao iniciar ou ajustar bloqueadores de canal de cálcio."},
{"med1":["sirolimo","everolimo"],"med2":["claritromicina","itraconazol"],"nivel":"alto","titulo":"Sirolimo / Everolimo + Inibidor de CYP3A4","mecanismo":"Inibidores fortes de CYP3A4 bloqueiam o metabolismo de sirolimo e everolimo, elevando seus níveis em 5–15 vezes.","efeito":"Toxicidade grave — pneumonite intersticial, trombocitopenia, mucosites e lesão renal aguda.","conduta":"❌ Contraindicado. Suspender o inibidor de CYP3A4 ou o imunossupressor durante o tratamento."},
{"med1":["ritonavir","cobicistate"],"med2":["sinvastatina","lovastatina"],"nivel":"alto","titulo":"Inibidor de Protease (HIV) + Sinvastatina / Lovastatina","mecanismo":"Ritonavir e cobicistate inibem fortemente CYP3A4, elevando os níveis de sinvastatina em até 30 vezes e lovastatina em até 10 vezes.","efeito":"Risco extremo de rabdomiólise — destruição muscular massiva com insuficiência renal e risco de vida.","conduta":"❌ Contraindicado absolutamente. Usar rosuvastatina (10mg máximo) ou pravastatina com inibidores de protease."},
{"med1":["ritonavir"],"med2":["alprazolam","triazolam","midazolam"],"nivel":"alto","titulo":"Ritonavir + Benzodiazepínico Oral","mecanismo":"O ritonavir inibe CYP3A4 de forma extremamente potente — benzodiazepínicos dependentes desta via acumulam em concentrações perigosas.","efeito":"Sedação prolongada e potencialmente fatal — depressão respiratória grave.","conduta":"❌ Contraindicado com triazolam e midazolam oral. Usar lorazepam ou oxazepam (metabolismo por glucuronidação)."},
{"med1":["efavirenz"],"med2":["metadona"],"nivel":"moderado","titulo":"Efavirenz + Metadona","mecanismo":"O efavirenz induz CYP3A4, acelerando o metabolismo da metadona e reduzindo seus níveis em 50–60%.","efeito":"Síndrome de abstinência por metadona — ansiedade, dores, insônia, compulsão por drogas.","conduta":"⚠️ Aumentar dose de metadona em 30–50% ao iniciar efavirenz. Monitorar sintomas de abstinência."},
{"med1":["tenofovir","tenofovir alafenamida"],"med2":["ibuprofeno","diclofenaco","aine"],"nivel":"moderado","titulo":"Tenofovir + AINE","mecanismo":"O tenofovir já tem potencial de nefrotoxicidade por acúmulo tubular renal. AINEs reduzem a perfusão renal, potencializando a lesão tubular proximal.","efeito":"Insuficiência renal aguda e síndrome de Fanconi tubular — perda de fosfato, glicose e aminoácidos.","conduta":"⚠️ Evitar AINEs com tenofovir. Usar paracetamol para analgesia. Monitorar função renal e fósforo sérico."},
{"med1":["hidroxiureia"],"med2":["didanosina","estavudina"],"nivel":"alto","titulo":"Hidroxiureia + Antiretroviral (ddI / d4T)","mecanismo":"A hidroxiureia inibe a ribonucleotídeo redutase, diminuindo o pool de desoxinucleotídeos — potencializa a toxicidade pancreática e neurológica da didanosina e estavudina.","efeito":"Pancreatite aguda grave, neuropatia periférica e lipodistrofia severa.","conduta":"❌ Contraindicado. Esta combinação foi responsável por óbitos e é completamente abandonada."},
{"med1":["metotrexato"],"med2":["trimetoprima"],"nivel":"alto","titulo":"Metotrexato + Trimetoprima","mecanismo":"A trimetoprima e o metotrexato são ambos antifolatos que inibem a dihidrofolato redutase — a combinação bloqueia completamente o metabolismo do folato.","efeito":"Mielossupressão grave com pancitopenia — potencialmente fatal, especialmente em idosos com função renal reduzida.","conduta":"❌ Contraindicado. Usar cefalexina ou amoxicilina para infecções urinárias em pacientes com metotrexato."},
{"med1":["varfarina","warfarina"],"med2":["amiodarona"],"nivel":"alto","titulo":"Warfarina + Amiodarona (risco prolongado)","mecanismo":"A amiodarona e seu metabólito desmetil-amiodarona inibem CYP2C9 de forma persistente — o efeito permanece por meses após suspender a amiodarona por sua meia-vida de 40–55 dias.","efeito":"Elevação progressiva do INR e risco crescente de hemorragia grave — o efeito persiste muito tempo após suspender amiodarona.","conduta":"❌ Reduzir dose de warfarina em 30–50% ao iniciar amiodarona. Monitorar INR semanalmente. O efeito persiste meses após suspender a amiodarona."},
{"med1":["fenitoína"],"med2":["valproato","ácido valproico"],"nivel":"moderado","titulo":"Fenitoína + Valproato (Interação Complexa)","mecanismo":"O valproato inibe CYP2C9 (eleva nível total de fenitoína) mas também desloca da albumina (eleva fração livre). Resultado: nível total pode estar normal mas fração ativa está elevada.","efeito":"Toxicidade por fenitoína com nível total \"normal\" — nistagmo, ataxia, confusão mental.","conduta":"⚠️ Monitorar fenitoína livre (não total). Sintomas de toxicidade com nível total normal devem ser investigados."},
{"med1":["diazepam"],"med2":["omeprazol"],"nivel":"baixo","titulo":"Diazepam + Omeprazol","mecanismo":"O omeprazol inibe CYP2C19, uma das vias de metabolismo do diazepam, podendo elevar levemente seus níveis séricos.","efeito":"Possível aumento leve da sedação do diazepam — efeito geralmente clinicamente irrelevante.","conduta":"✅ Geralmente sem relevância clínica. Monitorar sedação excessiva em idosos."},
{"med1":["omeprazol","lansoprazol"],"med2":["tacrolimo"],"nivel":"moderado","titulo":"IBP + Tacrolimo","mecanismo":"Omeprazol e lansoprazol são inibidores de CYP2C19 e CYP3A4 — vias de metabolismo do tacrolimo. Pantoprazol tem menor efeito.","efeito":"Elevação moderada dos níveis de tacrolimo com risco de toxicidade.","conduta":"⚠️ Preferir pantoprazol ou rabeprazol em pacientes com tacrolimo. Monitorar nível sérico."},
{"med1":["alopurinol"],"med2":["ciclosporina"],"nivel":"moderado","titulo":"Alopurinol + Ciclosporina","mecanismo":"O alopurinol pode elevar os níveis de ciclosporina por mecanismo não completamente elucidado — possivelmente inibição da xantina oxidase que metaboliza parcialmente a ciclosporina.","efeito":"Elevação dos níveis de ciclosporina com risco de nefrotoxicidade.","conduta":"⚠️ Monitorar nível sérico de ciclosporina e creatinina ao iniciar alopurinol."},
{"med1":["colchicina"],"med2":["verapamil","diltiazem"],"nivel":"moderado","titulo":"Colchicina + Verapamil / Diltiazem","mecanismo":"Verapamil e diltiazem inibem CYP3A4 e P-glicoproteína, as principais vias de eliminação da colchicina, elevando seus níveis.","efeito":"Toxicidade por colchicina — diarreia, miopatia, neuropatia e mielossupressão.","conduta":"⚠️ Reduzir dose de colchicina em 50% com verapamil ou diltiazem. Monitorar sintomas de toxicidade."},
{"med1":["alendronato","ibandronato"],"med2":["aspirina","ibuprofeno","aine"],"nivel":"moderado","titulo":"Bisfosfonato Oral + AINE","mecanismo":"Ambos irritam a mucosa esofágica e gástrica por mecanismos diferentes. A combinação multiplica o risco de esofagite, úlcera e perfuração gastrointestinal.","efeito":"Esofagite grave, úlcera esofágica e gástrica — potencialmente necessitando intervenção cirúrgica.","conduta":"⚠️ Usar IBP como proteção gástrica. Monitorar sintomas esofágicos (dor ao engolir, dor retroesternal)."},
{"med1":["metoclopramida"],"med2":["ciclosporina"],"nivel":"moderado","titulo":"Metoclopramida + Ciclosporina","mecanismo":"A metoclopramida acelera o esvaziamento gástrico, aumentando a velocidade de absorção da ciclosporina e elevando seu pico plasmático.","efeito":"Elevação dos níveis pico de ciclosporina com maior risco de nefrotoxicidade e neurotoxicidade.","conduta":"⚠️ Monitorar nível sérico de ciclosporina ao usar metoclopramida em transplantados."},
{"med1":["tiotropio"],"med2":["biperideno","oxibutinina","amitriptilina"],"nivel":"moderado","titulo":"Tiotropio (Inalatório) + Anticolinérgico Sistêmico","mecanismo":"O tiotropio tem efeito anticolinérgico sistêmico, embora mínimo. Combinado com anticolinérgicos orais, o efeito periférico pode se somar.","efeito":"Retenção urinária, boca seca intensa e constipação — mais relevante em homens idosos com hiperplasia prostática.","conduta":"⚠️ Monitorar sintomas urinários em idosos com hiperplasia prostática usando tiotropio + anticolinérgicos."},
{"med1":["budesonida","beclometasona"],"med2":["itraconazol","cetoconazol"],"nivel":"moderado","titulo":"Corticoide Inalatório + Antifúngico Azólico","mecanismo":"Azólicos inibem CYP3A4, principal via de metabolismo de budesonida e fluticasona, aumentando a exposição sistêmica ao corticoide inalatório.","efeito":"Síndrome de Cushing iatrogênica com supressão adrenal — especialmente com itraconazol e fluticasona.","conduta":"⚠️ Usar beclometasona (menos afetada) ao invés de budesonida/fluticasona. Monitorar cortisol basal em uso prolongado."},
{"med1":["omeprazol","pantoprazol"],"med2":["plavix","clopidogrel"],"nivel":"moderado","titulo":"Pantoprazol + Clopidogrel (menor interação)","mecanismo":"O pantoprazol tem menor inibição de CYP2C19 em comparação ao omeprazol/esomeprazol — a ativação do clopidogrel é menos comprometida.","efeito":"Menor impacto no efeito antiagregante do clopidogrel em comparação a omeprazol.","conduta":"✅ Pantoprazol é o IBP preferido em usuários de clopidogrel quando proteção gástrica é necessária."},
{"med1":["warfarina","varfarina"],"med2":["sucralfato"],"nivel":"moderado","titulo":"Warfarina + Sucralfato","mecanismo":"O sucralfato pode ligar-se à warfarina no trato gastrointestinal, reduzindo sua absorção. O mecanismo exato não está completamente esclarecido.","efeito":"Possível redução da absorção de warfarina — queda do INR e risco de subtratamento anticoagulante.","conduta":"⚠️ Tomar warfarina 2 horas antes do sucralfato. Monitorar INR."},
{"med1":["metronidazol"],"med2":["anticoagulante oral","warfarina","varfarina"],"nivel":"alto","titulo":"Metronidazol + Warfarina (Reforço)","mecanismo":"O metronidazol e seu metabólito hidroxi-metronidazol inibem CYP2C9 (principal) e CYP3A4 — bloqueando o metabolismo da warfarina S (forma mais potente).","efeito":"Elevação expressiva do INR — dobrar ou triplicar o INR não é incomum. Risco de hemorragia grave.","conduta":"❌ Reduzir dose de warfarina em 25–50% ao iniciar metronidazol. Monitorar INR em 2–3 dias."},
{"med1":["norfloxacino","ciprofloxacino"],"med2":["cafeína"],"nivel":"moderado","titulo":"Fluoroquinolona + Cafeína","mecanismo":"Ciprofloxacino e norfloxacino inibem CYP1A2, via de metabolismo da cafeína, elevando seus níveis no sangue.","efeito":"Efeitos estimulantes exacerbados da cafeína — insônia, taquicardia, ansiedade, tremores.","conduta":"⚠️ Reduzir consumo de café, chá e bebidas energéticas durante o tratamento com fluoroquinolonas."},
{"med1":["rifampicina"],"med2":["semaglutida","liraglutida"],"nivel":"moderado","titulo":"Rifampicina + GLP-1 (Injeção Subcutânea)","mecanismo":"O impacto da rifampicina em GLP-1 injetáveis subcutâneos é menor do que em medicamentos orais, mas a indução enzimática pode afetar vias metabólicas e transportadores relevantes.","efeito":"Possível redução modesta da eficácia do GLP-1 — controle glicêmico levemente afetado.","conduta":"⚠️ Monitorar glicemia mais frequentemente durante tratamento tuberculostático com rifampicina."},
{"med1":["sucralfato"],"med2":["quinolona","ciprofloxacino","levotiroxina","digoxina"],"nivel":"moderado","titulo":"Sucralfato + Vários Medicamentos","mecanismo":"O sucralfato é um complexo de alumínio que pode quelar múltiplos medicamentos no intestino — fluoroquinolonas, levotiroxina, digoxina e outros.","efeito":"Redução da absorção dos medicamentos concomitantes — perda de eficácia terapêutica.","conduta":"⚠️ Tomar todos os outros medicamentos 2 horas antes do sucralfato."},
{"med1":["piridostigmina","neostigmina"],"med2":["aminoglicosídeos","gentamicina"],"nivel":"moderado","titulo":"Inibidor de Colinesterase (Miastenia) + Aminoglicosídeo","mecanismo":"Aminoglicosídeos bloqueiam a junção neuromuscular e podem agravar a miastenia gravis. Os inibidores de colinesterase não conseguem compensar adequadamente esse bloqueio adicional.","efeito":"Crise miastênica grave — fraqueza muscular severa com risco de insuficiência respiratória.","conduta":"❌ Evitar aminoglicosídeos em pacientes com miastenia gravis. Usar alternativas como cefalosporinas ou fluoroquinolonas com cautela."},
{"med1":["warfarina","varfarina"],"med2":["clindamicina"],"nivel":"baixo","titulo":"Warfarina + Clindamicina","mecanismo":"A clindamicina altera a flora intestinal produtora de vitamina K e pode ter algum efeito inibitório sobre o metabolismo da warfarina.","efeito":"Leve aumento do INR durante o tratamento com clindamicina.","conduta":"⚠️ Monitorar INR ao usar clindamicina em pacientes anticoagulados."},
{"med1":["warfarina","varfarina"],"med2":["sinvastatina","atorvastatina","rosuvastatina"],"nivel":"baixo","titulo":"Warfarina + Estatina (Monitorar)","mecanismo":"Algumas estatinas têm leve inibição de CYP2C9 (sinvastatina, atorvastatina), podendo elevar modestamente os níveis de warfarina.","efeito":"Leve aumento do INR ao iniciar ou ajustar estatina — geralmente de pouca relevância clínica.","conduta":"✅ Monitorar INR nas primeiras 2–4 semanas após iniciar ou alterar dose de estatina."},
{"med1":["enalapril","captopril","lisinopril"],"med2":["sais de potássio","suplemento de potássio","cloreto de potássio"],"nivel":"alto","titulo":"IECA + Suplemento de Potássio","mecanismo":"Os IECAs retêm potássio por redução da aldosterona (via angiotensina II). Suplementar potássio nestas condições leva rapidamente à hipercalemia.","efeito":"Hipercalemia grave com risco de arritmias potencialmente fatais, parada cardíaca.","conduta":"❌ Evitar suplementos de potássio sem exame de potássio sérico confirmando hipocalemia real. Monitorar eletrolitos regularmente."},
{"med1":["espironolactona"],"med2":["trimetoprima","sulfametoxazol + trimetoprima"],"nivel":"alto","titulo":"Espironolactona + Trimetoprima","mecanismo":"A trimetoprima bloqueia secreção tubular renal de potássio (efeito semelhante à amilorida) e a espironolactona retém potássio. Efeito hipercalemiante aditivo.","efeito":"Hipercalemia grave com risco de arritmias fatais — especialmente perigosa em idosos e diabéticos.","conduta":"❌ Evitar a combinação em pacientes de alto risco. Monitorar potássio sérico dentro de 5 dias se a combinação for inevitável."},
{"med1":["digoxina"],"med2":["quinidina","procainamida"],"nivel":"alto","titulo":"Digoxina + Antiarrítmico Classe I","mecanismo":"Quinidina inibe fortemente P-glicoproteína e o transportador renal de cátions orgânicos, reduzindo a eliminação da digoxina e dobrando seus níveis séricos.","efeito":"Intoxicação digitálica grave — náuseas, bradicardia extrema, bloqueio AV, arritmias ventriculares.","conduta":"❌ Reduzir dose de digoxina em 50% ao iniciar quinidina. Monitorar ECG e nível sérico."},
{"med1":["heparina"],"med2":["nitroglicerina"],"nivel":"moderado","titulo":"Heparina + Nitroglicerina IV","mecanismo":"A nitroglicerina IV interfere na farmacodinâmica da heparina, reduzindo sua atividade anticoagulante — mecanismo não totalmente esclarecido (possível ligação ao glicerol).","efeito":"Redução do efeito anticoagulante da heparina durante infusão de nitroglicerina — risco de eventos trombóticos.","conduta":"⚠️ Monitorar TTPA com mais frequência durante infusão concomitante. Ajustar dose de heparina conforme necessário."},
{"med1":["amiodarona"],"med2":["lidocaína"],"nivel":"moderado","titulo":"Amiodarona + Lidocaína","mecanismo":"Ambos têm efeito estabilizador de membrana e reduzem a condução cardíaca — efeito aditivo no nó AV e no miocárdio.","efeito":"Risco de bradicardia sinusal grave, bloqueio AV e depressão miocárdica.","conduta":"⚠️ Monitorar ECG continuamente se a combinação for necessária em manejo de arritmias agudas."},
{"med1":["amiodarona"],"med2":["fentanila"],"nivel":"moderado","titulo":"Amiodarona + Fentanila","mecanismo":"A amiodarona pode potencializar os efeitos cardiovasculares depressores da fentanila — ambos têm ação sobre o sistema nervoso autônomo cardíaco.","efeito":"Bradicardia e hipotensão excessivas em ambiente anestésico.","conduta":"⚠️ Monitorar ECG e hemodinâmica. Avisar anestesiologista sobre uso de amiodarona."},
{"med1":["flecainida"],"med2":["amiodarona"],"nivel":"alto","titulo":"Flecainida + Amiodarona","mecanismo":"A amiodarona inibe CYP2D6, principal via de metabolismo da flecainida, elevando seus níveis séricos. Ambos têm efeito proarrítmico.","efeito":"Toxicidade por flecainida — arritmias graves incluindo Torsades de Pointes e arritmias ventriculares.","conduta":"❌ Reduzir dose de flecainida em 50% ao associar amiodarona. Monitorar ECG e nível sérico."},
{"med1":["atenolol","bisoprolol"],"med2":["nifedipina","anlodipino"],"nivel":"baixo","titulo":"Betabloqueador + Diidropiridina","mecanismo":"Betabloqueadores e diidropiridinas têm efeitos anti-hipertensivos complementares — o betabloqueador controla a taquicardia reflexa causada pela nifedipina.","efeito":"Combinação anti-hipertensiva eficaz e complementar. O risco é hipotensão excessiva em doses altas.","conduta":"✅ Combinação frequentemente usada em hipertensão refratária. Monitorar pressão arterial."},
{"med1":["losartana"],"med2":["rifampicina"],"nivel":"moderado","titulo":"Losartana + Rifampicina","mecanismo":"A rifampicina induz CYP2C9, principal via de conversão da losartana no metabólito ativo E-3174, reduzindo os níveis deste metabólito em ~40%.","efeito":"Redução do efeito anti-hipertensivo da losartana.","conduta":"⚠️ Monitorar pressão arterial. Considerar outro BRA menos dependente de CYP2C9 (valsartana, candesartana)."},
{"med1":["furosemida"],"med2":["lítio","carbonato de lítio"],"nivel":"alto","titulo":"Furosemida + Lítio (Depleção de Sódio)","mecanismo":"A furosemida causa depleção de sódio. Com menos sódio disponível no filtrado renal, o rim reabsorve mais lítio como \"substituto\" — os níveis séricos sobem perigosamente.","efeito":"Intoxicação por lítio — tremores, confusão, convulsões, danos renais permanentes.","conduta":"❌ Monitorar lítio sérico a cada 5–7 dias ao iniciar furosemida. Repor sódio adequadamente. Orientar hidratação."},
{"med1":["metformina"],"med2":["cimetidina"],"nivel":"moderado","titulo":"Metformina + Cimetidina","mecanismo":"A cimetidina inibe o transportador cátion orgânico renal (OCT2), que secreta ativamente a metformina — elevando seus níveis plasmáticos em ~50%.","efeito":"Acúmulo de metformina com risco de acidose lática, especialmente em pacientes com função renal limítrofe.","conduta":"⚠️ Preferir ranitidina, famotidina ou omeprazol. Se cimetidina for necessária, monitorar creatinina."},
{"med1":["metformina"],"med2":["álcool"],"nivel":"moderado","titulo":"Metformina + Álcool (Reforço)","mecanismo":"O álcool inibe a gliconeogênese hepática e eleva o lactato. Combinado com metformina (que também reduz captação hepática de lactato), ocorre acúmulo de ácido lático.","efeito":"Acidose lática grave — especialmente em uso excessivo de álcool ou em jejum prolongado com álcool.","conduta":"⚠️ Evitar consumo excessivo de álcool. Nunca ingerir álcool em jejum com metformina."},
{"med1":["glibenclamida","glimepirida","glicazida"],"med2":["aspirina","ácido acetilsalicílico"],"nivel":"moderado","titulo":"Sulfonilureia + Aspirina em Doses Altas","mecanismo":"A aspirina em doses anti-inflamatórias (>1,5g/dia) potencializa o efeito hipoglicemiante das sulfonilureias por deslocamento das proteínas plasmáticas e efeito hipoglicemiante próprio.","efeito":"Hipoglicemia grave com uso de aspirina em doses altas — mais relevante com glibenclamida.","conduta":"⚠️ Monitorar glicemia ao usar aspirina em doses analgésicas/anti-inflamatórias com sulfonilureias."},
{"med1":["insulina"],"med2":["corticoide","prednisona","dexametasona","hidrocortisona"],"nivel":"moderado","titulo":"Insulina + Corticoide (Hiperglicemia)","mecanismo":"Corticoides elevam a glicose por múltiplos mecanismos: aumentam gliconeogênese hepática, causam resistência insulínica periférica e estimulam o glucagon.","efeito":"Hiperglicemia corticosteroidea — o padrão típico é pico glicêmico no período da tarde e noite com glicose de jejum relativamente preservada.","conduta":"⚠️ Aumentar dose de insulina, especialmente de ação rápida/intermediária, ao iniciar corticoide. Monitorar glicemia 4x/dia."},
{"med1":["dapagliflozina","empagliflozina"],"med2":["insulina"],"nivel":"moderado","titulo":"SGLT-2 + Insulina (Cetoacidose Euglicêmica)","mecanismo":"SGLT-2 inibidores eliminam glicose pela urina, reduzindo o substrato para o metabolismo da insulina. Em jejum, cirurgia ou doença, o organismo usa ácidos graxos — produzindo cetonas sem hiperglicemia marcante.","efeito":"Cetoacidose diabética euglicêmica — cetonas elevadas com glicemia \"normal\" (150–200mg/dL) — subdiagnosticada e potencialmente fatal.","conduta":"⚠️ Suspender SGLT-2 antes de cirurgias, jejum prolongado ou doenças graves. Monitorar cetonas se sintomas surgirem sem hiperglicemia óbvia."},
{"med1":["semaglutida"],"med2":["anticoagulante oral","warfarina"],"nivel":"moderado","titulo":"Semaglutida + Anticoagulante Oral","mecanismo":"A semaglutida retarda o esvaziamento gástrico, podendo alterar a velocidade de absorção de vários medicamentos orais, incluindo a warfarina.","efeito":"Possível variação na absorção da warfarina — especialmente no início do tratamento quando o esvaziamento gástrico é mais retardado.","conduta":"⚠️ Monitorar INR com mais frequência nas primeiras semanas de semaglutida. Não há mudança de dose preventiva necessária."},
{"med1":["rivaroxabana"],"med2":["naproxeno"],"nivel":"alto","titulo":"Rivaroxabana + Naproxeno","mecanismo":"O naproxeno inibe a COX-1 plaquetária e irrita a mucosa gastrointestinal — somado ao efeito anticoagulante da rivaroxabana, o risco de sangramento GI é muito elevado.","efeito":"Risco muito alto de hemorragia gastrointestinal grave.","conduta":"❌ Evitar. Usar paracetamol para analgesia em pacientes com rivaroxabana."},
{"med1":["apixabana"],"med2":["naproxeno"],"nivel":"alto","titulo":"Apixabana + Naproxeno","mecanismo":"AINEs inibem a agregação plaquetária e danificam a mucosa gastrointestinal, multiplicando o risco hemorrágico da apixabana.","efeito":"Risco muito elevado de sangramento gastrointestinal grave.","conduta":"❌ Evitar AINEs com apixabana. Usar paracetamol para dor leve a moderada."},
{"med1":["clopidogrel"],"med2":["naproxeno","ibuprofeno"],"nivel":"moderado","titulo":"Clopidogrel + AINE","mecanismo":"Ibuprofeno pode competir com a aspirina (frequentemente coadministrada) pelo sítio de acetilação da COX-1 plaquetária, reduzindo o efeito antiagregante. AINEs também aumentam risco de sangramento GI.","efeito":"Possível redução da eficácia antiagregante e aumento do risco de sangramento gastrointestinal.","conduta":"⚠️ Preferir paracetamol para analgesia. Tomar ibuprofeno pelo menos 8 horas antes ou 30 minutos depois da aspirina se uso simultâneo for necessário."},
{"med1":["diltiazem"],"med2":["ivabradina"],"nivel":"alto","titulo":"Diltiazem + Ivabradina (Bradicardia)","mecanismo":"O diltiazem inibe CYP3A4 (eleva os níveis de ivabradina) e também reduz a frequência cardíaca (cronotropismo negativo) — efeito duplo e perigoso.","efeito":"Bradicardia sinusal grave com risco de síncope e parada cardíaca.","conduta":"❌ Contraindicado. O diltiazem eleva os níveis de ivabradina E potencializa seu efeito bradicardizante."},
{"med1":["captopril","enalapril"],"med2":["sucralfato"],"nivel":"baixo","titulo":"IECA + Sucralfato","mecanismo":"O sucralfato pode reduzir levemente a absorção de alguns IECAs (captopril) ao se ligar a eles no intestino.","efeito":"Leve redução da absorção do IECA — impacto clínico geralmente mínimo.","conduta":"✅ Tomar IECA 1–2 horas antes do sucralfato como precaução."},
{"med1":["cetirizina"],"med2":["loratadina"],"nivel":"baixo","titulo":"Cetirizina + Loratadina (Combinação Desnecessária)","mecanismo":"Ambas são anti-histamínicas H1 de segunda geração com mecanismo idêntico — a combinação não oferece benefício adicional mas duplica os efeitos adversos.","efeito":"Sedação aumentada sem melhora da eficácia anti-histamínica.","conduta":"⚠️ Sem benefício terapêutico em combinar dois anti-histamínicos. Usar apenas um, na dose adequada."},
{"med1":["azitromicina"],"med2":["suco de toranja"],"nivel":"baixo","titulo":"Azitromicina + Suco de Toranja","mecanismo":"Diferentemente dos macrolídeos eritromicina e claritromicina, a azitromicina não é metabolizada por CYP3A4 — a toranja tem pouco efeito sobre ela.","efeito":"Interação clinicamente irrelevante — azitromicina é segura com suco de toranja.","conduta":"✅ Azitromicina pode ser tomada com suco de toranja sem restrição."},
{"med1":["amoxicilina"],"med2":["álcool"],"nivel":"baixo","titulo":"Amoxicilina + Álcool","mecanismo":"A amoxicilina não inibe acetaldeído desidrogenase — não há reação tipo dissulfiram. O álcool pode reduzir levemente a eficácia imunológica e o sono.","efeito":"Sem interação medicamentosa direta. O álcool pode comprometer a recuperação e a hidratação durante infecções.","conduta":"✅ Sem contraindicação estrita. Evitar álcool em excesso durante qualquer infecção para não comprometer a recuperação."},
{"med1":["paracetamol"],"med2":["omeprazol"],"nivel":"baixo","titulo":"Paracetamol + Omeprazol","mecanismo":"Não há interação farmacocinética relevante. Cada um tem vias metabólicas independentes sem inibição mútua significativa.","efeito":"Sem interação clinicamente relevante. Combinação frequentemente usada.","conduta":"✅ Combinação segura. Omeprazol pode ser usado para proteger o estômago em uso frequente de analgésicos."},
{"med1":["loratadina","desloratadina"],"med2":["álcool"],"nivel":"baixo","titulo":"Loratadina / Desloratadina + Álcool","mecanismo":"Loratadina e desloratadina têm mínima ação no SNC (não sedativas). O álcool tem pouca adição aos seus efeitos.","efeito":"Sem sedação clinicamente relevante — comportamento diferente dos anti-histamínicos de primeira geração.","conduta":"✅ Loratadina e desloratadina são seguros com consumo moderado de álcool."},
{"med1":["omeprazol","pantoprazol"],"med2":["ferro","sulfato ferroso"],"nivel":"moderado","titulo":"IBP + Ferro","mecanismo":"O ferro não-heme (Fe3+) requer acidez gástrica para ser reduzido a Fe2+ (forma absorvível). IBPs elevam o pH gástrico, prejudicando esta conversão e reduzindo a absorção.","efeito":"Redução da absorção de ferro oral em até 50% — resposta terapêutica à reposição de ferro comprometida.","conduta":"⚠️ Tomar ferro em jejum e pelo menos 1 hora antes do IBP. Considerar suco de laranja para acidificar o estômago."},
{"med1":["rivaroxabana","apixabana"],"med2":["antiácido","cálcio","magnésio"],"nivel":"baixo","titulo":"NOAC + Antiácido","mecanismo":"Antiácidos podem levemente alterar o pH gástrico e a motilidade intestinal, mas os NOACs têm absorção pouco dependente de pH — a interação é geralmente mínima.","efeito":"Efeito clinicamente irrelevante na maioria dos casos.","conduta":"✅ NOACs podem ser tomados com antiácidos sem restrição específica. Evitar apenas antiácidos de magnésio em combinação com outros fatores de risco de sangramento."},
{"med1":["metformina"],"med2":["vitamina b12"],"nivel":"baixo","titulo":"Metformina + Vitamina B12 (Interação Benéfica)","mecanismo":"O uso prolongado de metformina reduz a absorção de vitamina B12 ao inibir o transportador de cálcio no íleo terminal (o cálcio é necessário para a absorção do complexo B12-fator intrínseco).","efeito":"Deficiência de B12 com uso prolongado — anemia macrocítica e neuropatia periférica que pode ser confundida com neuropatia diabética.","conduta":"✅ Monitorar B12 a cada 1–2 anos. Suplementar com 500–1000mcg/dia de B12 oral se deficiência detectada. Tomar B12 em horário diferente da metformina."},
{"med1":["atorvastatina"],"med2":["colchicina"],"nivel":"moderado","titulo":"Atorvastatina + Colchicina","mecanismo":"A colchicina inibe levemente P-glicoproteína e CYP3A4. Com atorvastatina, ambos têm toxicidade muscular intrínseca com risco aditivo de miopatia.","efeito":"Risco aumentado de miopatia — dor e fraqueza muscular, raramente evoluindo para rabdomiólise.","conduta":"⚠️ Usar a menor dose eficaz de colchicina. Monitorar sintomas musculares e CK se dor muscular surgir."},
{"med1":["levodopa"],"med2":["vitamina b6","piridoxina"],"nivel":"moderado","titulo":"Levodopa (Sem Inibidor de DOPA) + Vitamina B6","mecanismo":"A piridoxina é cofator da DOPA descarboxilase periférica — em altas doses, acelera a conversão de levodopa em dopamina perifericamente, antes de chegar ao cérebro.","efeito":"Redução da eficácia antiparkinsoniana da levodopa isolada — piora dos sintomas motores.","conduta":"⚠️ Relevante apenas para levodopa sem carbidopa. Com carbidopa (Sinemet), a vitamina B6 não tem impacto significativo."},
{"med1":["melatonina"],"med2":["benzodiazepínico","diazepam","zolpidem"],"nivel":"moderado","titulo":"Melatonina + Benzodiazepínico / Hipnótico","mecanismo":"A melatonina tem ação sedativa pelo receptor MT1/MT2. Combinada com BZDs ou zolpidem, pode potencializar a sedação residual no dia seguinte.","efeito":"Sedação matinal aumentada com comprometimento da atenção e coordenação motora.","conduta":"⚠️ A melatonina é geralmente usada como alternativa, não como complemento, aos BZDs. Monitorar sedação residual."},
{"med1":["pregabalina"],"med2":["thalidomida","lenalidomida"],"nivel":"moderado","titulo":"Pregabalina + Talidomida / Lenalidomida","mecanismo":"Ambas têm efeito sedativo e neurológico. A talidomida aumenta o risco de neuropatia periférica; a pregabalina, em algumas situações, também pode contribuir.","efeito":"Sedação excessiva e possível potencialização de neuropatia periférica.","conduta":"⚠️ Monitorar sintomas neurológicos e sedação. Usar doses mínimas eficazes de pregabalina."},
{"med1":["omeprazol"],"med2":["vitamina b12"],"nivel":"baixo","titulo":"Omeprazol (Crônico) + Vitamina B12","mecanismo":"A secreção ácida gástrica é necessária para liberar B12 das proteínas alimentares. IBPs crônicos comprometem esta etapa, reduzindo a absorção de B12 dos alimentos (não de suplementos).","efeito":"Deficiência de B12 com uso crônico (>2 anos) de IBPs em altas doses — risco de anemia e neuropatia.","conduta":"✅ Monitorar B12 anualmente com uso crônico de IBP. Suplementos sublinguais ou injetáveis de B12 funcionam independentemente do pH gástrico."},
{"med1":["hidroxicloroquina"],"med2":["ibuprofeno","diclofenaco"],"nivel":"baixo","titulo":"Hidroxicloroquina + AINE","mecanismo":"Interação farmacodinâmica modesta — a hidroxicloroquina tem algum efeito anti-inflamatório próprio que pode ser aditivo com os AINEs.","efeito":"Leve aumento do risco de irritação gastrointestinal. Não há interação farmacocinética relevante.","conduta":"✅ Combinação frequentemente utilizada em artrite reumatoide. Usar IBP para proteção gástrica em uso prolongado."},
{"med1":["ácido fólico"],"med2":["sulfametoxazol + trimetoprima","trimetoprima"],"nivel":"moderado","titulo":"Ácido Fólico + Sulfametoxazol-Trimetoprima","mecanismo":"A trimetoprima inibe dihidrofolato redutase, bloqueando o metabolismo do folato. O ácido fólico compete com este bloqueio — pode reduzir a eficácia antibacteriana em doses altas.","efeito":"Em doses suprafisiológicas de folato, possível redução da eficácia antibacteriana da trimetoprima.","conduta":"⚠️ Doses suplementares normais (400–800mcg) são seguras com SXT. Doses medicinais altas (5mg) podem reduzir eficácia — espaçar por 2 horas."},
{"med1":["sertralina","escitalopram","fluoxetina"],"med2":["sumatriptana","zolmitriptana","rizatriptana"],"nivel":"moderado","titulo":"ISRS + Triptano (Enxaqueca)","mecanismo":"Ambos aumentam a atividade serotoninérgica — ISRS por inibição da recaptação; triptanos por agonismo nos receptores 5-HT1B/1D. O risco de síndrome serotoninérgica é real mas geralmente leve.","efeito":"Síndrome serotoninérgica leve a moderada — fraqueza, hiperreflexia, descoordenação, sudorese.","conduta":"⚠️ FDA emitiu alerta mas a combinação é amplamente usada na prática. Usar dose mínima de triptano e monitorar sintomas neurológicos."},
{"med1":["pregabalina","gabapentina"],"med2":["morfina"],"nivel":"moderado","titulo":"Pregabalina / Gabapentina + Morfina","mecanismo":"Pregabalina e morfina têm sinergia analgésica por mecanismos complementares (canais de cálcio vs. receptores opioides). A depressão respiratória também é sinérgica.","efeito":"Potencialização da analgesia MAS também da depressão respiratória — risco de overdose.","conduta":"⚠️ Combinação usada em dor crônica grave — usar doses mínimas eficazes. A FDA emitiu alerta específico sobre esta combinação."},
{"med1":["antiácido","hidróxido de alumínio","hidróxido de magnésio"],"med2":["levotiroxina"],"nivel":"moderado","titulo":"Antiácido + Levotiroxina","mecanismo":"Hidróxido de alumínio e magnésio adsorvem a levotiroxina no intestino, formando complexos insolúveis que não são absorvidos.","efeito":"Redução da absorção de levotiroxina — hipotireoidismo mal controlado.","conduta":"⚠️ Tomar levotiroxina pelo menos 4 horas antes de qualquer antiácido."},
{"med1":["verapamil"],"med2":["carbamazepina"],"nivel":"moderado","titulo":"Verapamil + Carbamazepina","mecanismo":"O verapamil inibe CYP3A4, elevando os níveis de carbamazepina. A carbamazepina também pode induzir o metabolismo do verapamil, criando uma interação bidirecional complexa.","efeito":"Toxicidade por carbamazepina (diplopia, ataxia) E possível redução da eficácia do verapamil anti-hipertensivo.","conduta":"⚠️ Monitorar nível sérico de carbamazepina ao iniciar ou suspender verapamil."},
{"med1":["clopidogrel"],"med2":["pantoprazol"],"nivel":"baixo","titulo":"Clopidogrel + Pantoprazol (Preferido)","mecanismo":"O pantoprazol tem menor inibição de CYP2C19 comparado a omeprazol — a conversão do clopidogrel ao metabólito ativo é menos comprometida.","efeito":"Menor impacto na eficácia antiagregante do clopidogrel.","conduta":"✅ Pantoprazol é o IBP de escolha em pacientes com clopidogrel que necessitam de proteção gástrica."},
{"med1":["clobutinol","hytos plus","hytos"],"med2":["azitromicina","claritromicina","eritromicina","moxifloxacino","levofloxacino","ciprofloxacino","fluconazol","itraconazol","cetoconazol","voriconazol","haloperidol","quetiapina","risperidona","olanzapina","amiodarona","sotalol","quinidina","metadona","domperidona","ondansetrom","hidroxicloroquina","cloroquina"],"nivel":"alto","titulo":"🚫 Clobutinol (Hytos Plus) — PROIBIDO PELA ANVISA + Outro Medicamento","mecanismo":"O Clobutinol está PROIBIDO no Brasil por bloquear canais de potássio cardíacos (corrente hERG), prolongando o intervalo QT. Combinado com outros medicamentos que também prolongam o QT, o risco de arritmia fatal (Torsade de Pointes) é extremamente elevado.","efeito":"🚫 MEDICAMENTO PROIBIDO. O Clobutinol em si já é contraindicado. Associado a outros fármacos que prolongam QT, o risco de Torsade de Pointes e morte súbita é crítico.","conduta":"❌ NÃO USE. O Clobutinol está proibido pela ANVISA — descarte em farmácia habilitada. Se tomou recentemente e sentir palpitações ou batimento irregular, ligue SAMU (192)."},
{"med1":["clobutinol","hytos plus","hytos"],"med2":["paracetamol","ibuprofeno","dipirona","amoxicilina","dextrometorfano","levodropropizina"],"nivel":"alto","titulo":"🚫 Clobutinol (Hytos Plus) — PROIBIDO PELA ANVISA","mecanismo":"O Clobutinol teve seu registro cancelado pela ANVISA por causar arritmia cardíaca grave (prolongamento do intervalo QT e Torsade de Pointes). Qualquer uso é contraindicado — o problema não é a combinação, é o próprio medicamento.","efeito":"🚫 MEDICAMENTO PROIBIDO no Brasil por risco de arritmia cardíaca fatal.","conduta":"❌ NÃO USE. Descarte em farmácia. Para tosse seca, consulte seu farmacêutico sobre Dextrometorfano ou Levodropropizina — alternativas aprovadas e seguras."},
{"med1":["warfarina","varfarina"],"med2":["vitamina k","fitomenadiona","fitoquinona"],"nivel":"alto","titulo":"Warfarina / Varfarina + Vitamina K","efeito":"A vitamina K reduz o efeito anticoagulante da warfarina — risco de trombose, AVC e embolia pulmonar.","conduta":"❌ Evitar suplementação de vitamina K sem monitoramento do INR. Manter consumo alimentar de folhas verdes (couve, espinafre, brócolis) constante — variações bruscas afetam diretamente o INR."},
{"med1":["levotiroxina","puran t4","euthyrox"],"med2":["omeprazol","pantoprazol","esomeprazol","lansoprazol","rabeprazol","ibp"],"nivel":"moderado","titulo":"Levotiroxina + Omeprazol / IBP","efeito":"IBPs elevam o pH gástrico — a levotiroxina precisa de ambiente ácido para se dissolver. A absorção cai e o hipotireoidismo pode ficar mal controlado mesmo com dose correta.","conduta":"⚠️ Tomar levotiroxina em jejum, 30–60 minutos antes do IBP. Monitorar TSH após iniciar ou ajustar o omeprazol."},
{"med1":["tramadol","tramal"],"med2":["ondansetrom","ondansetrona","vonau","zofran"],"nivel":"moderado","titulo":"Tramadol + Ondansetrona","efeito":"A ondansetrona bloqueia receptores 5-HT3, que o tramadol usa como parte do seu mecanismo analgésico — pode reduzir até 30% da eficácia analgésica.","conduta":"⚠️ Preferir metoclopramida ou domperidona como antiemético em pacientes usando tramadol. Se necessário, ajustar dose do tramadol."},
{"med1":["sildenafila","tadalafila","vardenafila"],"med2":["anlodipino","nifedipina","enalapril","captopril","lisinopril","losartana","valsartana","candesartana","atenolol","metoprolol","bisoprolol","carvedilol","anti-hipertensivo"],"nivel":"moderado","titulo":"Sildenafila / Tadalafila + Anti-hipertensivo","efeito":"Inibidores da PDE-5 causam vasodilatação — combinados com anti-hipertensivos, podem provocar hipotensão sintomática grave, especialmente nas primeiras doses.","conduta":"⚠️ Iniciar inibidor de PDE-5 na menor dose disponível. Monitorar pressão arterial. Risco maior com alfabloqueadores (tamsulosina) e nas primeiras horas após a dose."},
{"med1":["valproato","ácido valproico","divalproato","depakene","depakote"],"med2":["lamotrigina","lamictal"],"nivel":"alto","titulo":"Valproato + Lamotrigina (Toxicidade Grave — Risco de Stevens-Johnson)","mecanismo":"O valproato inibe a glucuronidação da lamotrigina (UGT1A4), reduzindo sua eliminação em até 50% e dobrando sua meia-vida. Os níveis plasmáticos da lamotrigina atingem concentrações tóxicas mesmo em doses antes toleradas.","efeito":"Toxicidade grave pela lamotrigina — ataxia, diplopia, vertigem, náusea. Em casos graves: síndrome de Stevens-Johnson (reação cutânea bolhosa potencialmente fatal) e necrólise epidérmica tóxica.","conduta":"❌ Quando valproato é associado, a dose de lamotrigina deve ser reduzida para 50% da habitual e a titulação deve ser muito mais lenta. Monitorar rigorosamente sintomas cutâneos (eritema, bolhas). Qualquer lesão cutânea suspeita exige suspensão imediata da lamotrigina."},
{"med1":["valproato","ácido valproico","divalproato","depakene","depakote"],"med2":["carbamazepina","tegretol"],"nivel":"moderado","titulo":"Valproato + Carbamazepina (Indução Enzimática Mútua — Monitorar Níveis Séricos)","mecanismo":"A carbamazepina induz CYP2C9 e CYP3A4, reduzindo os níveis de valproato em 40–60%. O valproato inibe o metabolismo do metabólito ativo da carbamazepina (carbamazepina-10,11-epóxido), podendo elevar sua toxicidade mesmo com níveis totais normais. Interação bidirecional complexa.","efeito":"Redução dos níveis de valproato (perda do controle das crises epilépticas) e possível acúmulo do metabólito tóxico da carbamazepina (toxicidade neurológica: tontura, diplopia, ataxia). Controle epiléptico imprevisível.","conduta":"⚠️ Monitorar nível sérico de ambos os anticonvulsivantes regularmente, especialmente ao iniciar ou ajustar doses. Ajustes frequentes podem ser necessários. Monitorar sinais de toxicidade da carbamazepina mesmo com níveis totais aparentemente normais."},
{"med1":["carbamazepina","tegretol"],"med2":["lamotrigina","lamictal"],"nivel":"moderado","titulo":"Carbamazepina + Lamotrigina (Indução do Metabolismo — Dose de Lamotrigina Aumentada)","mecanismo":"A carbamazepina é potente indutora de UGT1A4 e CYP3A4, acelerando o metabolismo e a eliminação da lamotrigina. Os níveis plasmáticos da lamotrigina podem ser reduzidos em 40–50%, comprometendo o controle das crises.","efeito":"Níveis subterapêuticos de lamotrigina com perda do controle epiléptico. A dose de lamotrigina geralmente precisa ser maior (até 2×) quando usada com carbamazepina, em comparação ao uso isolado.","conduta":"⚠️ Doses de lamotrigina geralmente precisam ser ajustadas para cima ao associar carbamazepina. Monitorar nível sérico e resposta clínica ao ajustar qualquer um dos medicamentos. Ao suspender carbamazepina, reduzir lamotrigina gradualmente para evitar toxicidade."},
{"med1":["pseudoefedrina","fenilefrina","descongestionante"],"med2":["tranilcipromina","fenelzina","isocarboxazida","imao","inibidor de mao"],"nivel":"alto","titulo":"Descongestionante (Pseudoefedrina / Fenilefrina) + IMAO (Crise Hipertensiva Grave)","mecanismo":"Pseudoefedrina e fenilefrina são simpaticomiméticos que promovem liberação de noradrenalina e agonismo α-adrenérgico direto. Os IMAOs inibem a degradação das catecolaminas — a combinação causa acúmulo maciço de noradrenalina na fenda sináptica com vasoconstrição extrema.","efeito":"Crise hipertensiva grave (PA >180/120 mmHg) — cefaleia occipital explosiva, sudorese, palidez, rigidez nucal, risco de hemorragia intracraniana, AVC e parada cardíaca.","conduta":"❌ Contraindicado absolutamente. Descongestionantes (inclusive nasais com fenilefrina) são proibidos em pacientes usando IMAOs ou dentro de 14 dias após sua suspensão. Substituir por lavagem nasal salina ou corticoide tópico nasal para congestão."},
{"med1":["pseudoefedrina","fenilefrina","descongestionante"],"med2":["amitriptilina","imipramina","clomipramina","nortriptilina","antidepressivo tricíclico"],"nivel":"alto","titulo":"Descongestionante + Antidepressivo Tricíclico (Potencialização Cardiovascular)","mecanismo":"Os antidepressivos tricíclicos bloqueiam a recaptação de noradrenalina e a entrada pré-sináptica dos simpaticomiméticos, potencializando seus efeitos cardiovasculares. A pseudoefedrina e fenilefrina têm ação direta nos receptores α e β adrenérgicos, com efeito amplificado pelos tricíclicos.","efeito":"Hipertensão grave, taquiarritmias (taquicardia supraventricular, fibrilação ventricular), palpitações intensas e risco de síndrome coronariana aguda por vasospasmo coronariano.","conduta":"❌ Evitar descongestionantes sistêmicos em pacientes em uso de antidepressivos tricíclicos. Usar lavagem salina nasal ou corticoide nasal tópico para congestão. Caso imprescindível, supervisão médica com monitoramento cardíaco."},
{"med1":["prednisona","dexametasona","betametasona","hidrocortisona","prednisolona","corticoide","corticosteroide"],"med2":["metformina","insulina","insulina nph","insulina regular","glibenclamida","gliclazida","glimepirida","glipizida","sitagliptina","linagliptina","semaglutida","liraglutida","antidiabético"],"nivel":"moderado","titulo":"Corticoide + Antidiabético (Hiperglicemia Corticosteroide — Ajuste de Dose)","mecanismo":"Corticoides elevam a glicose por múltiplos mecanismos: aumentam a gliconeogênese hepática, causam resistência insulínica periférica, inibem a captação de glicose pelos tecidos e estimulam a secreção de glucagon. O padrão típico é hiperglicemia pós-prandial com glicemia de jejum relativamente preservada, especialmente com prednisona em dose matinal.","efeito":"Hiperglicemia corticosteroide — antagoniza o efeito de todos os antidiabéticos orais e da insulina. Pode descompensar diabetes previamente controlado, revelar diabetes não diagnosticado ou causar hiperglicemia mesmo em não-diabéticos com doses altas.","conduta":"⚠️ Monitorar glicemia 2–4× ao dia durante corticoterapia. Pode ser necessário aumentar dose de metformina, intensificar insulinização ou adicionar insulina em pacientes antes bem controlados com antidiabéticos orais. Ao suspender corticoide, reduzir antidiabéticos gradualmente para evitar hipoglicemia."},
{"med1":["haloperidol","clorpromazina","levomepromazina","tioridazina","pimozida","flufenazina","trifluoperazina","antipsicótico típico"],"med2":["biperideno","oxibutinina","escopolamina","hioscina","prometazina","difenidramina"],"nivel":"moderado","titulo":"Antipsicótico Típico + Anticolinérgico (Síndrome Anticolinérgica + Redução de Eficácia)","mecanismo":"Antipsicóticos típicos causam efeitos extrapiramidais (parkinsonismo) e anticolinérgicos são usados para tratá-los. Porém, o bloqueio colinérgico cumulativo potencializa a toxicidade anticolinérgica e pode paradoxalmente reduzir o efeito antipsicótico via neurônios colinérgicos estriatais. O uso prolongado de anticolinérgico com antipsicótico também aumenta o risco de discinesia tardia.","efeito":"Síndrome anticolinérgica cumulativa: boca seca intensa, constipação grave, retenção urinária, taquicardia, visão turva, confusão mental e delirium — idosos são especialmente vulneráveis. Paradoxalmente, pode reduzir a eficácia antipsicótica e aumentar o risco de discinesia tardia em uso prolongado.","conduta":"⚠️ Usar anticolinérgico (ex.: biperideno) apenas pelo tempo mínimo necessário para controlar efeitos extrapiramidais agudos — não de forma profilática. Preferir antipsicóticos com menor potencial extrapiramidal (quetiapina, risperidona em dose baixa) para evitar a necessidade do anticolinérgico. Em idosos: vigilância redobrada para síndrome anticolinérgica (confusão, retenção urinária). Tentar retirar gradualmente o anticolinérgico após 3 meses de estabilização."},
{"med1":["acenocumarol","sintrom"],"med2":["fluconazol","cetoconazol","itraconazol","voriconazol"],"nivel":"alto","titulo":"Acenocumarol + Antifúngico Azólico (Risco de Sangramento Grave)","mecanismo":"O acenocumarol é metabolizado principalmente pela CYP2C9. Os antifúngicos azólicos inibem esta enzima de forma potente, elevando significativamente os níveis de acenocumarol e seu efeito anticoagulante.","efeito":"Elevação expressiva do INR com risco grave de hemorragia — sangramento gastrointestinal, intracraniano ou em outros locais críticos.","conduta":"❌ Reduzir dose de acenocumarol ao iniciar azólico e monitorar INR em 2–3 dias. Preferir terbinafina tópica ou fluconazol em dose única para infecções superficiais."},
{"med1":["acenocumarol","sintrom"],"med2":["amiodarona"],"nivel":"alto","titulo":"Acenocumarol + Amiodarona (Risco Prolongado)","mecanismo":"A amiodarona e seu metabólito desmetil-amiodarona inibem CYP2C9 de forma persistente — o efeito permanece por meses após suspender a amiodarona por sua meia-vida de 40–55 dias. O acenocumarol é metabolizado principalmente pela CYP2C9.","efeito":"Elevação progressiva do INR e risco crescente de hemorragia grave — o efeito persiste muito tempo após suspender a amiodarona.","conduta":"❌ Reduzir dose de acenocumarol em 30–50% ao iniciar amiodarona. Monitorar INR semanalmente. O efeito persiste meses após suspender a amiodarona."},
{"med1":["acenocumarol","sintrom"],"med2":["metronidazol"],"nivel":"alto","titulo":"Acenocumarol + Metronidazol","mecanismo":"O metronidazol inibe CYP2C9 — principal via de metabolismo do acenocumarol — bloqueando sua inativação e elevando expressivamente o INR.","efeito":"Elevação expressiva do INR com risco de hemorragia grave.","conduta":"❌ Reduzir dose de acenocumarol em 25–50% ao iniciar metronidazol. Monitorar INR em 2–3 dias."},
{"med1":["acenocumarol","sintrom"],"med2":["vitamina k","fitomenadiona","fitoquinona"],"nivel":"alto","titulo":"Acenocumarol + Vitamina K","mecanismo":"A vitamina K é o cofator da síntese dos fatores de coagulação que o acenocumarol inibe. A ingestão de vitamina K restaura a coagulação e antagoniza o efeito anticoagulante.","efeito":"Redução do INR com risco de falha anticoagulante — trombose, AVC e embolia pulmonar.","conduta":"❌ Manter consumo de folhas verdes (couve, espinafre, brócolis) constante. Evitar suplementos de vitamina K sem monitoramento do INR."},
{"med1":["acenocumarol","sintrom"],"med2":["ibuprofeno","naproxeno","diclofenaco","aine","aspirina","ácido acetilsalicílico"],"nivel":"alto","titulo":"Acenocumarol + AINE / AAS","mecanismo":"AINEs inibem a COX-1 plaquetária (antiagregante) e danificam a mucosa gastrointestinal. O acenocumarol é anticoagulante. A combinação multiplica o risco hemorrágico por dois mecanismos simultâneos.","efeito":"Risco muito elevado de sangramento gastrointestinal grave — potencialmente fatal.","conduta":"❌ Evitar AINEs com acenocumarol. Usar paracetamol para analgesia. Nunca usar aspirina com acenocumarol sem indicação específica e monitoramento rigoroso do INR."},
{"med1":["dabigatrana","pradaxa"],"med2":["amiodarona"],"nivel":"moderado","titulo":"Dabigatrana + Amiodarona (Inibição de P-gp)","mecanismo":"A amiodarona inibe a P-glicoproteína intestinal e renal, reduzindo a eliminação ativa da dabigatrana e elevando seus níveis séricos em até 60%. A dabigatrana não é metabolizada pelo CYP — a P-gp é sua principal via de eliminação.","efeito":"Aumento do efeito anticoagulante da dabigatrana com risco aumentado de sangramento.","conduta":"⚠️ Considerar redução da dose de dabigatrana (de 150mg para 110mg 2×/dia) ao associar amiodarona, especialmente em idosos ou com função renal reduzida. Monitorar sinais de sangramento."},
{"med1":["dabigatrana","pradaxa"],"med2":["verapamil"],"nivel":"moderado","titulo":"Dabigatrana + Verapamil (Inibição de P-gp)","mecanismo":"O verapamil inibe a P-glicoproteína, transportador responsável pela eliminação ativa da dabigatrana — elevando seus níveis plasmáticos significativamente. O efeito é maior com formulações de liberação imediata de verapamil.","efeito":"Aumento do efeito anticoagulante com risco de sangramento, especialmente em pacientes com função renal reduzida.","conduta":"⚠️ Administrar verapamil pelo menos 2 horas antes da dabigatrana para minimizar o pico plasmático. Considerar dose de 110mg 2×/dia em idosos ou com IRC leve a moderada."},
{"med1":["dabigatrana","pradaxa"],"med2":["rifampicina","carbamazepina","fenitoína","fenobarbital","erva de são joão"],"nivel":"alto","titulo":"Dabigatrana + Indutor de P-gp (Redução Grave do Efeito Anticoagulante)","mecanismo":"Rifampicina e outros indutores potentes de P-gp aumentam drasticamente a eliminação da dabigatrana, reduzindo seus níveis plasmáticos em até 66% — comprometendo gravemente o efeito anticoagulante.","efeito":"Falha anticoagulante — risco de trombose, AVC isquêmico e embolia pulmonar.","conduta":"❌ Contraindicado com rifampicina. Evitar indutores de P-gp com dabigatrana — o efeito anticoagulante torna-se inadequado e imprevisível."},
{"med1":["dabigatrana","pradaxa"],"med2":["cetoconazol","itraconazol"],"nivel":"alto","titulo":"Dabigatrana + Azólico Potente (Inibição Intensa de P-gp)","mecanismo":"Cetoconazol e itraconazol inibem fortemente a P-gp — principal transportador de eliminação da dabigatrana. Os níveis séricos podem aumentar significativamente, com risco de supranível anticoagulante.","efeito":"Risco elevado de sangramento por acúmulo de dabigatrana.","conduta":"❌ Cetoconazol sistêmico é contraindicado com dabigatrana. Usar fluconazol com precaução e monitoramento rigoroso de sinais de sangramento."},
{"med1":["edoxabana","lixiana","savaysa"],"med2":["ciclosporina","quinidina","cetoconazol"],"nivel":"alto","titulo":"Edoxabana + Inibidor Potente de P-gp","mecanismo":"A edoxabana é substrato da P-glicoproteína. Inibidores potentes de P-gp (ciclosporina, quinidina, cetoconazol) reduzem sua eliminação, elevando significativamente os níveis séricos e o risco hemorrágico.","efeito":"Risco elevado de sangramento por supranível de edoxabana.","conduta":"⚠️ Reduzir a dose de edoxabana para 30mg/dia quando associada a inibidores potentes de P-gp. Monitorar sinais de sangramento ativamente."},
{"med1":["edoxabana","lixiana","savaysa"],"med2":["rifampicina","carbamazepina","fenitoína"],"nivel":"alto","titulo":"Edoxabana + Indutor de P-gp (Redução do Efeito Anticoagulante)","mecanismo":"Rifampicina e outros indutores de P-gp aumentam a eliminação da edoxabana, reduzindo sua eficácia anticoagulante de forma significativa.","efeito":"Falha anticoagulante — risco de trombose, AVC e embolia pulmonar.","conduta":"❌ Evitar indutores potentes de P-gp com edoxabana. O efeito anticoagulante torna-se inadequado e imprevisível."},
{"med1":["cilostazol","cebralat","pletal"],"med2":["claritromicina","eritromicina","itraconazol","cetoconazol","fluconazol","voriconazol"],"nivel":"alto","titulo":"Cilostazol + Inibidor de CYP3A4 / CYP2C19","mecanismo":"O cilostazol é metabolizado principalmente por CYP3A4 e CYP2C19. Inibidores dessas enzimas elevam substancialmente os níveis do cilostazol e de seu metabólito ativo, amplificando o risco de efeitos adversos cardiovasculares e hemorrágicos.","efeito":"Taquicardia, cefaleia intensa, hipotensão e risco aumentado de sangramento — os metabólitos acumulam em concentrações tóxicas.","conduta":"❌ Contraindicado com inibidores fortes de CYP3A4 (cetoconazol, itraconazol, claritromicina). Com inibidores moderados: reduzir dose de cilostazol para 50mg 2×/dia e monitorar tolerância."},
{"med1":["cilostazol","cebralat","pletal"],"med2":["omeprazol","esomeprazol","lansoprazol"],"nivel":"moderado","titulo":"Cilostazol + IBP (Inibidor de CYP2C19)","mecanismo":"Omeprazol e esomeprazol são inibidores potentes de CYP2C19, reduzindo o metabolismo do cilostazol e elevando seus níveis séricos e de seu metabólito ativo.","efeito":"Aumento dos efeitos adversos do cilostazol — taquicardia, palpitações, cefaleia.","conduta":"⚠️ Reduzir dose de cilostazol para 50mg 2×/dia ao usar omeprazol ou esomeprazol. Preferir pantoprazol ou rabeprazol como IBP."},
{"med1":["cilostazol","cebralat","pletal"],"med2":["warfarina","varfarina","acenocumarol","sintrom","apixabana","rivaroxabana","dabigatrana","edoxabana","heparina","enoxaparina"],"nivel":"alto","titulo":"Cilostazol + Anticoagulante","mecanismo":"O cilostazol é um antiagregante plaquetário potente (inibidor de PDE III). Combinado com anticoagulantes, o risco hemorrágico é aditivo — bloqueio simultâneo da hemostasia primária (plaquetária) e secundária (coagulação).","efeito":"Risco elevado de sangramento grave — gastrointestinal, intracraniano ou pós-cirúrgico.","conduta":"⚠️ Usar com extrema cautela. A combinação pode ser necessária em contextos específicos (ex.: doença arterial periférica + fibrilação atrial). Monitorar sinais de sangramento ativamente."},
{"med1":["dipiridamol","persantin"],"med2":["cafeína","café","chá preto","bebida energética"],"nivel":"moderado","titulo":"Dipiridamol + Cafeína (Antagonismo — Teste de Estresse Inválido)","mecanismo":"O dipiridamol inibe a adenosina desaminase, elevando os níveis de adenosina e causando vasodilatação coronariana. A cafeína é antagonista competitivo dos receptores de adenosina — reverte este efeito vasodilatador.","efeito":"Redução ou anulação do efeito vasodilatador do dipiridamol — teste de estresse farmacológico inválido; pode mascarar isquemia coronariana.","conduta":"⚠️ Suspender cafeína (café, chá, refrigerante, chocolate) por 24–48 horas antes de exame com dipiridamol IV. Na terapia oral crônica, a interação é clinicamente menos relevante."},
{"med1":["dipiridamol","persantin"],"med2":["adenosina"],"nivel":"alto","titulo":"Dipiridamol + Adenosina (Potenciação Grave da Bradicardia)","mecanismo":"O dipiridamol bloqueia a recaptação e o metabolismo da adenosina, elevando muito seus níveis plasmáticos. A combinação potencializa o efeito cronotrópico negativo da adenosina de forma sinérgica.","efeito":"Bradicardia grave, bloqueio AV e hipotensão — risco de síncope e parada cardíaca.","conduta":"❌ Contraindicado. Se adenosina for necessária em pacientes com dipiridamol (ex.: cardioversão em emergência), usar dose muito reduzida com monitoramento cardíaco intensivo."},
{"med1":["prasugrel","efient"],"med2":["warfarina","varfarina","acenocumarol","sintrom","apixabana","rivaroxabana","dabigatrana","edoxabana"],"nivel":"alto","titulo":"Prasugrel + Anticoagulante Oral","mecanismo":"O prasugrel é um inibidor irreversível de P2Y12 (antiagregante muito potente). Combinado com anticoagulante oral, o risco hemorrágico é substancialmente aumentado — duplo bloqueio da hemostasia plaquetária e da coagulação.","efeito":"Risco muito elevado de sangramento grave — gastrointestinal, intracraniano e retroperitoneal.","conduta":"⚠️ Terapia tripla (dupla antiagregação + anticoagulante) só deve ser mantida pelo menor tempo necessário. Preferir prasugrel + anticoagulante sem aspirina quando possível. Monitorar sinais de sangramento ativamente."},
{"med1":["prasugrel","efient"],"med2":["ibuprofeno","naproxeno","diclofenaco","aine"],"nivel":"moderado","titulo":"Prasugrel + AINE","mecanismo":"O prasugrel inibe irreversivelmente as plaquetas via P2Y12. AINEs adicionam inibição reversível da COX-1 plaquetária e irritação da mucosa gastrointestinal — aumentando o risco de sangramento.","efeito":"Risco aumentado de sangramento gastrointestinal e em outros sítios.","conduta":"⚠️ Evitar AINEs com prasugrel. Usar paracetamol para analgesia."},
{"med1":["ticagrelor","brilique","brilinta"],"med2":["cetoconazol","itraconazol","claritromicina","ritonavir","atazanavir"],"nivel":"alto","titulo":"Ticagrelor + Inibidor Potente de CYP3A4","mecanismo":"O ticagrelor é metabolizado pela CYP3A4. Inibidores potentes desta enzima elevam os níveis de ticagrelor em até 7 vezes, amplificando seu efeito antiagregante e o risco de sangramento e efeitos adversos.","efeito":"Supranível de ticagrelor com risco grave de sangramento, dispneia e bradicardia.","conduta":"❌ Contraindicado com inibidores fortes de CYP3A4. Suspender o inibidor antes ou usar antiagregante alternativo (clopidogrel) se o inibidor for essencial."},
{"med1":["ticagrelor","brilique","brilinta"],"med2":["rifampicina","carbamazepina","fenitoína","fenobarbital","dexametasona"],"nivel":"alto","titulo":"Ticagrelor + Indutor Forte de CYP3A4","mecanismo":"Indutores potentes de CYP3A4 aceleram o metabolismo do ticagrelor, reduzindo seus níveis plasmáticos em até 75% — comprometendo gravemente o efeito antiagregante plaquetário.","efeito":"Perda de eficácia antiagregante — risco de trombose do stent e eventos cardiovasculares graves (IAM, AVC).","conduta":"❌ Contraindicado com indutores fortes de CYP3A4. Usar clopidogrel como alternativa se indutor enzimático for necessário."},
{"med1":["ticagrelor","brilique","brilinta"],"med2":["aspirina","ácido acetilsalicílico"],"nivel":"moderado","titulo":"Ticagrelor + Aspirina em Dose Alta (Redução de Eficácia)","mecanismo":"O ticagrelor requer aspirina em baixa dose (75–100mg) para otimizar seu efeito antiagregante. Doses altas de aspirina (>100mg/dia) reduzem a eficácia do ticagrelor — mecanismo possivelmente relacionado à redução da tromboxano sintase plaquetária.","efeito":"Redução da eficácia antiagregante do ticagrelor — possível aumento do risco cardiovascular.","conduta":"⚠️ Usar aspirina somente em dose baixa (75–100mg/dia) com ticagrelor. Doses >100mg/dia são contraindicadas em manutenção — usar apenas aspirina em baixa dose como terapia dupla."},
{"med1":["fondaparinux","arixtra"],"med2":["ibuprofeno","naproxeno","diclofenaco","aine","aspirina","ácido acetilsalicílico"],"nivel":"alto","titulo":"Fondaparinux + AINE / Aspirina","mecanismo":"O fondaparinux inibe o fator Xa, bloqueando a via extrínseca da coagulação. AINEs e aspirina inibem a COX-1 plaquetária e danificam a mucosa gastrointestinal — a combinação provoca bloqueio duplo da hemostasia.","efeito":"Risco muito elevado de sangramento gastrointestinal e em outros sítios — potencialmente fatal.","conduta":"❌ Evitar AINEs com fondaparinux. Usar paracetamol para analgesia."},
{"med1":["fondaparinux","arixtra"],"med2":["clopidogrel","prasugrel","ticagrelor","brilique","brilinta","efient"],"nivel":"alto","titulo":"Fondaparinux + Antiagregante Plaquetário","mecanismo":"A combinação de anticoagulante parenteral (fondaparinux) com antiagregante plaquetário provoca bloqueio simultâneo da coagulação e da função plaquetária — dupla inibição da hemostasia.","efeito":"Risco muito elevado de sangramento grave, especialmente gastrointestinal e em locais de acesso vascular.","conduta":"⚠️ A terapia combinada pode ser necessária em síndromes coronarianas agudas — usar pelo menor tempo possível e com monitoramento rigoroso de sinais de sangramento."},
{"med1":["moclobemida","aurorix"],"med2":["fluoxetina","sertralina","escitalopram","paroxetina","citalopram","fluvoxamina","isrs"],"nivel":"alto","titulo":"Moclobemida + ISRS (Síndrome Serotoninérgica)","mecanismo":"A moclobemida (RIMA) inibe reversivelmente a MAO-A, reduzindo a degradação de serotonina. Combinada com ISRS, que bloqueia a recaptação de serotonina, o efeito serotoninérgico é aditivo e pode precipitar síndrome serotoninérgica.","efeito":"Síndrome serotoninérgica — agitação, confusão, tremor, mioclonias, sudorese, taquicardia, hipertermia — podendo evoluir para convulsões e colapso cardiovascular em casos graves.","conduta":"❌ Contraindicado. Respeitar período de washout: 14 dias após suspender moclobemida antes de iniciar ISRS; 14 dias após suspender ISRS antes de iniciar moclobemida (exceto fluoxetina — 5 semanas de washout)."},
{"med1":["moclobemida","aurorix"],"med2":["sumatriptana","naratriptana","rizatriptana","zolmitriptana","eletriptana","almotriptana","frovatriptana","triptano"],"nivel":"alto","titulo":"Moclobemida + Triptano (Síndrome Serotoninérgica)","mecanismo":"A moclobemida inibe a degradação de serotonina via MAO-A. Os triptanos são agonistas de receptores 5-HT1 — a combinação eleva os efeitos serotoninérgicos de forma sinérgica.","efeito":"Síndrome serotoninérgica — hipertensão, taquicardia, agitação, tremor, hipertermia — potencialmente fatal.","conduta":"❌ Contraindicado. Evitar triptanos durante e até 24 horas após o uso de moclobemida. Em enxaqueca refratária com necessidade de triptano, discutir suspensão da moclobemida com washout adequado."},
{"med1":["moclobemida","aurorix"],"med2":["tramadol","tramal"],"nivel":"moderado","titulo":"Moclobemida + Tramadol (Síndrome Serotoninérgica)","mecanismo":"O tramadol inibe a recaptação de serotonina e noradrenalina além de sua ação opioide fraca. Combinado com moclobemida (inibidor de MAO-A), os níveis de serotonina aumentam de forma significativa.","efeito":"Síndrome serotoninérgica moderada a grave — agitação, tremor, diaforese, taquicardia, hipertermia.","conduta":"⚠️ Evitar. Substituir tramadol por opioide sem ação serotoninérgica (morfina, codeína) em pacientes usando moclobemida. Se uso conjunto for inevitável, monitorar sinais de síndrome serotoninérgica ativamente."},
{"med1":["moclobemida","aurorix"],"med2":["tiramina","queijo maturado","vinho tinto","frios","embutidos"],"nivel":"moderado","titulo":"Moclobemida + Tiramina (Crise Hipertensiva — Menos Intensa que IMAOs Irreversíveis)","mecanismo":"A moclobemida (RIMA) inibe de forma reversível e seletiva a MAO-A — ao contrário dos IMAOs irreversíveis, a tiramina pode competir pelo sítio ativo da MAO. Em doses normais o risco é menor, mas ingestão excessiva de tiramina pode superar a capacidade enzimática residual.","efeito":"Elevação da pressão arterial geralmente moderada após ingestão de grandes quantidades de alimentos ricos em tiramina. O risco é menor do que com IMAOs irreversíveis, mas real com excesso alimentar.","conduta":"⚠️ Restrição moderada de tiramina — evitar grandes quantidades de queijos muito maturados, embutidos curados e vinho tinto. Não é necessária restrição absoluta como com IMAOs irreversíveis, mas excesso deve ser evitado."},
{"med1":["flufenazina","flufenan"],"med2":["álcool","alcool","etanol","bebida alcoólica"],"nivel":"moderado","titulo":"Flufenazina + Álcool (Depressão do SNC e Hipotensão Postural)","mecanismo":"A flufenazina (antipsicótico típico) deprime o SNC e tem efeito α-bloqueador que causa hipotensão postural. O álcool potencializa ambos os efeitos por mecanismos aditivos sobre o SNC e sobre o controle vascular.","efeito":"Sedação excessiva, hipotensão postural grave com risco de síncope e quedas. Em idosos: risco elevado de fratura. Comprometimento cognitivo e psicomotor.","conduta":"⚠️ Proibir álcool durante o uso de flufenazina. Orientar sobre risco de tontura ao levantar (hipotensão ortostática) — especialmente perigoso quando associado ao álcool."},
{"med1":["flufenazina","flufenan","trifluoperazina"],"med2":["amiodarona","sotalol","quinidina","dronedarona","antiarrítmico"],"nivel":"alto","titulo":"Flufenazina / Trifluoperazina + Anti-arrítmico (Prolongamento do QT — Torsades de Pointes)","mecanismo":"Flufenazina e trifluoperazina são fenotiazinas que bloqueiam canais de potássio cardíacos (IKr), prolongando o intervalo QT. Combinadas com anti-arrítmicos que também prolongam o QT (amiodarona, sotalol, quinidina), o efeito é aditivo.","efeito":"Prolongamento aditivo do QTc com risco de Torsades de Pointes — arritmia ventricular polimórfica que pode degenerar em fibrilação ventricular e morte súbita.","conduta":"❌ Evitar a combinação. Se necessário, monitorar ECG (QTc) antes e durante o tratamento. Suspender se QTc > 500ms. Corrigir hipocalemia e hipomagnesemia que potencializam o risco."},
{"med1":["flufenazina","flufenan"],"med2":["carbonato de lítio","lítio"],"nivel":"moderado","titulo":"Flufenazina + Lítio (Toxicidade Neurotóxica)","mecanismo":"A combinação de antipsicótico típico com lítio pode aumentar a sensibilidade do SNC à toxicidade do lítio. Há relatos de síndrome neurotóxica — especialmente com lítio em nível sérico no limite superior ou em idosos.","efeito":"Toxicidade neurológica: tremor intenso, confusão, disartria, ataxia e, em casos graves, encefalopatia. O risco é maior com lítio > 1,0 mEq/L.","conduta":"⚠️ Monitorar lítio sérico com maior frequência. Manter lítio no limite inferior da faixa terapêutica (0,6–0,8 mEq/L). Vigilância rigorosa de sinais de toxicidade neurológica (tremor, dificuldade de fala, desorientação)."},
{"med1":["modafinil","stavigile","modiodal"],"med2":["warfarina","varfarina","acenocumarol","sintrom"],"nivel":"moderado","titulo":"Modafinil + Anticoagulante Cumarínico (Queda do INR por Indução de CYP2C9)","mecanismo":"O modafinil é indutor moderado de CYP2C9, principal via de metabolismo de warfarina e acenocumarol. A indução enzimática aumenta o clearance do anticoagulante, reduzindo seus níveis plasmáticos e o INR.","efeito":"Queda do INR com risco de subterapia anticoagulante — trombose, AVC e embolia pulmonar em pacientes com fibrilação atrial ou prótese valvar.","conduta":"⚠️ Monitorar INR em 5–7 dias após iniciar ou suspender modafinil. Ajustar dose de anticoagulante conforme necessário. Não suspender modafinil abruptamente em pacientes anticoagulados."},
{"med1":["modafinil","stavigile","modiodal"],"med2":["ciclosporina","sandimmun"],"nivel":"moderado","titulo":"Modafinil + Ciclosporina (Redução dos Níveis por Indução de CYP3A4)","mecanismo":"O modafinil induz CYP3A4, principal via de metabolismo da ciclosporina, acelerando sua depuração e reduzindo os níveis séricos.","efeito":"Queda dos níveis de ciclosporina abaixo do terapêutico — risco real de rejeição aguda em transplantados.","conduta":"❌ Evitar em transplantados em uso de ciclosporina. Se uso conjunto for indispensável, monitorar níveis de ciclosporina (C0/C2) semanalmente e ajustar dose. Ao suspender modafinil, reduzir ciclosporina gradualmente para evitar toxicidade por acúmulo."},
{"med1":["pimozida","orap"],"med2":["cetoconazol","itraconazol","voriconazol","posaconazol","claritromicina","eritromicina"],"nivel":"alto","titulo":"Pimozida + Inibidor de CYP3A4 (QT Prolongado — Risco Fatal)","mecanismo":"A pimozida é metabolizada primariamente pela CYP3A4. Inibidores desta enzima (azólicos e macrolídeos) elevam drasticamente seus níveis plasmáticos — e a pimozida já prolonga o QT de forma dose-dependente.","efeito":"Prolongamento grave do intervalo QTc com risco de Torsades de Pointes e fibrilação ventricular — potencialmente fatal. Casos de morte súbita cardíaca relatados com esta combinação.","conduta":"❌ Contraindicado absolutamente com inibidores potentes de CYP3A4. A FDA emitiu alerta específico para esta combinação. Se antifúngico for necessário, preferir terbinafina ou anfotericina B (sem inibição de CYP3A4)."},
{"med1":["pimozida","orap"],"med2":["fluoxetina","paroxetina","fluvoxamina"],"nivel":"alto","titulo":"Pimozida + ISRS Inibidor de CYP2D6 (QT Prolongado)","mecanismo":"A pimozida é parcialmente metabolizada pela CYP2D6. Fluoxetina, paroxetina e fluvoxamina inibem esta e outras vias metabólicas da pimozida — a fluvoxamina também inibe CYP1A2, elevando ainda mais os níveis. O acúmulo de pimozida prolonga o QTc de forma grave.","efeito":"Prolongamento grave do QTc com risco de Torsades de Pointes e morte súbita.","conduta":"❌ Contraindicado com fluoxetina, paroxetina e fluvoxamina. Se ISRS for necessário, usar sertralina ou escitalopram em doses baixas com monitoramento do ECG (QTc)."},
{"med1":["pimozida","orap","tioridazina","mesoridazina"],"med2":["amiodarona","sotalol","quinidina","dronedarona","metadona","haloperidol"],"nivel":"alto","titulo":"Pimozida / Tioridazina / Mesoridazina + QT Prolongadores (Risco de Morte Súbita)","mecanismo":"Pimozida, tioridazina e mesoridazina são os antipsicóticos com maior risco de prolongamento de QT — bloqueio de canais hERG/IKr cardíacos. Combinados com outros QT prolongadores (antiarrítmicos classe IA/III, metadona, outros antipsicóticos), o efeito é aditivo e pode ser fatal.","efeito":"Prolongamento grave do QTc com alto risco de Torsades de Pointes, fibrilação ventricular e morte súbita — mesmo em pacientes sem cardiopatia prévia conhecida.","conduta":"❌ Evitar qualquer combinação de pimozida, tioridazina ou mesoridazina com outros QT prolongadores. Monitorar ECG obrigatoriamente. Corrigir hipocalemia e hipomagnesemia. Considerar substituição por antipsicótico com menor risco de QT (aripiprazol)."},
{"med1":["selegilina","jumex","eldepryl"],"med2":["fluoxetina","sertralina","escitalopram","paroxetina","citalopram","fluvoxamina"],"nivel":"alto","titulo":"Selegilina + ISRS (Síndrome Serotoninérgica)","mecanismo":"Em doses baixas (5–10mg/dia), a selegilina inibe seletivamente MAO-B. Porém, mesmo nessas doses, a combinação com ISRSs que elevam a serotonina sináptica pode precipitar síndrome serotoninérgica — o risco aumenta com doses > 10mg/dia, quando a seletividade se perde.","efeito":"Síndrome serotoninérgica — agitação, hipertermia, rigidez muscular, mioclonias, taquicardia, sudorese, convulsões — potencialmente fatal.","conduta":"❌ Contraindicado. Respeitar washout de 14 dias após suspender selegilina antes de iniciar ISRS; 14 dias (ou 5 semanas para fluoxetina) após suspender ISRS antes de iniciar selegilina."},
{"med1":["selegilina","jumex","eldepryl"],"med2":["sumatriptana","naratriptana","rizatriptana","zolmitriptana","eletriptana","triptano"],"nivel":"alto","titulo":"Selegilina + Triptano (Síndrome Serotoninérgica)","mecanismo":"A selegilina inibe MAO-B (e parcialmente MAO-A em doses altas), reduzindo a degradação de serotonina. Os triptanos são agonistas serotonérgicos diretos (5-HT1). A combinação eleva o tônus serotonérgico central de forma perigosa.","efeito":"Síndrome serotoninérgica — cefaleia grave, hipertensão, hipertermia, agitação, tremor.","conduta":"❌ Contraindicado. Usar analgésicos não-serotonérgicos para crises de enxaqueca em pacientes com selegilina (AINEs, paracetamol — nunca triptanos)."},
{"med1":["selegilina","jumex"],"med2":["tiramina","queijo maturado","vinho tinto","frios","embutidos"],"nivel":"moderado","titulo":"Selegilina em Dose Alta + Tiramina (Crise Hipertensiva)","mecanismo":"Em doses baixas (5–10mg/dia oral), a selegilina tem seletividade MAO-B e o risco com tiramina é mínimo. Em doses > 10mg/dia ou na forma transdérmica em dose alta, a seletividade se perde e MAO-A também é inibida — com o mesmo risco dos IMAOs irreversíveis.","efeito":"Crise hipertensiva com doses altas — cefaleia súbita e intensa, rigidez de nuca, risco de AVC hemorrágico.","conduta":"⚠️ Em dose baixa oral (5–10mg/dia): sem restrição rigorosa de tiramina. Com doses > 10mg/dia ou sistema transdérmico de alta dose: seguir restrição de tiramina equivalente a IMAO irreversível (evitar queijos maturados, embutidos curados e vinho tinto em quantidade)."},
{"med1":["tioridazina","mesoridazina"],"med2":["álcool","alcool","etanol","bebida alcoólica"],"nivel":"moderado","titulo":"Tioridazina / Mesoridazina + Álcool (Depressão do SNC e Risco Cardiovascular)","mecanismo":"Tioridazina e mesoridazina são fenotiazinas com efeito sedativo, anticolinérgico e α-bloqueador. O álcool potencializa todos esses efeitos por mecanismos aditivos sobre o SNC e sobre o controle cardiovascular — e ambas já têm alto risco de prolongamento do QT de forma independente.","efeito":"Sedação profunda, hipotensão ortostática grave, taquicardia e agravamento do risco de prolongamento do QT. Em idosos: risco elevado de queda e fratura. Risco de comprometimento cardiovascular grave.","conduta":"⚠️ Álcool absolutamente contraindicado durante o uso de tioridazina e mesoridazina. Reforçar orientação ao paciente sobre risco de síncope, quedas e alterações do ritmo cardíaco."},
{"med1":["tolterodina","detrusitol"],"med2":["cetoconazol","itraconazol","voriconazol","claritromicina","ritonavir"],"nivel":"moderado","titulo":"Tolterodina + Inibidor de CYP3A4 (Toxicidade Anticolinérgica por Acúmulo)","mecanismo":"A tolterodina é metabolizada pela CYP3A4 e CYP2D6. Inibidores potentes de CYP3A4 (cetoconazol, claritromicina, ritonavir) elevam os níveis de tolterodina em até 4–5 vezes — aumentando o risco de toxicidade anticolinérgica.","efeito":"Síndrome anticolinérgica por supradosagem relativa — boca seca intensa, retenção urinária, constipação, visão turva, taquicardia, confusão mental (especialmente em idosos).","conduta":"⚠️ Limitar dose de tolterodina a 1mg 2×/dia ao usar inibidores potentes de CYP3A4. Avaliar alternativa com beta-3 agonista (mirabegron) — sem bloqueio anticolinérgico e sem interação relevante de CYP3A4."},
{"med1":["tolterodina","detrusitol"],"med2":["biperideno","escopolamina","oxibutinina","hioscina","prometazina","difenidramina","amitriptilina","imipramina"],"nivel":"moderado","titulo":"Tolterodina + Outros Anticolinérgicos (Síndrome Anticolinérgica Cumulativa)","mecanismo":"A tolterodina é um anticolinérgico urinário. Associada a outros fármacos com ação anticolinérgica (antidepressivos tricíclicos, anti-histamínicos clássicos, antipsicóticos), o bloqueio muscarínico total é aditivo.","efeito":"Síndrome anticolinérgica cumulativa — boca seca intensa, retenção urinária, constipação grave, visão turva, taquicardia, confusão e delirium — especialmente grave em idosos (critérios de Beers).","conduta":"⚠️ Revisar polifarmácia em idosos — a carga anticolinérgica total é mais importante que cada fármaco individualmente. Considerar mirabegron como alternativa sem efeito anticolinérgico adicional."},
{"med1":["dextrometorfano","dextromethorphan"],"med2":["fluoxetina","paroxetina","sertralina","escitalopram","citalopram","fluvoxamina"],"nivel":"moderado","titulo":"Dextrometorfano + ISRS (Síndrome Serotoninérgica e Elevação de Níveis)","mecanismo":"O dextrometorfano (DXM) inibe fracamente a recaptação de serotonina e é substrato de CYP2D6. ISRSs inibidores potentes de CYP2D6 (fluoxetina, paroxetina) elevam os níveis de DXM e seu efeito serotoninérgico.","efeito":"Síndrome serotoninérgica moderada a grave — agitação, tremor, mioclonias, sudorese, hipertermia — especialmente com fluoxetina e paroxetina (inibidores potentes de CYP2D6).","conduta":"⚠️ Evitar xaropes com dextrometorfano em pacientes usando fluoxetina ou paroxetina. Preferir mucolíticos sem DXM (ambroxol, carbocisteína) para tosse."},
{"med1":["dextrometorfano","dextromethorphan"],"med2":["álcool","alcool","etanol","bebida alcoólica"],"nivel":"moderado","titulo":"Dextrometorfano + Álcool (Potencialização da Depressão do SNC)","mecanismo":"O dextrometorfano é antagonista NMDA com efeitos dissociativos em doses elevadas. O álcool deprime o SNC por múltiplos mecanismos. A combinação potencializa mutuamente os efeitos depressores centrais.","efeito":"Sedação excessiva, comprometimento cognitivo e psicomotor, tontura e risco de efeitos dissociativos intensificados. Em doses altas de DXM com álcool: risco de psicose dissociativa aguda.","conduta":"⚠️ Evitar álcool durante uso de antitussígenos com dextrometorfano. Orientar sobre comprometimento da capacidade de conduzir veículos."},
{"med1":["tizanidina","sirdalud"],"med2":["morfina","codeína","tramadol","oxicodona","fentanila","clonazepam","diazepam","alprazolam","bromazepam","lorazepam","zolpidem"],"nivel":"moderado","titulo":"Tizanidina + Opioide / Benzodiazepínico (Sedação e Hipotensão Cumulativa)","mecanismo":"A tizanidina deprime o SNC via agonismo α2-adrenérgico central. Combinada com opioides ou benzodiazepínicos, o efeito depressor central e hipotensor é aditivo — aumentando o risco de sedação excessiva, depressão respiratória e quedas.","efeito":"Sedação profunda, hipotensão grave, tontura intensa e risco de queda — especialmente em idosos. Em doses elevadas: risco de depressão respiratória.","conduta":"⚠️ Usar com extrema cautela. Iniciar com dose mínima de tizanidina (2mg). Proibir álcool. Se possível, evitar associação com opioides e benzodiazepínicos — especialmente em idosos."},
{"med1":["tizanidina","sirdalud"],"med2":["amlodipino","anlodipino","hidroclorotiazida","enalapril","captopril","losartana","valsartana","atenolol","propranolol"],"nivel":"moderado","titulo":"Tizanidina + Anti-hipertensivo (Hipotensão Aditiva)","mecanismo":"A tizanidina tem ação hipotensora central via agonismo α2-adrenérgico — mecanismo similar à clonidina. Combinada com anti-hipertensivos, o efeito hipotensor é aditivo.","efeito":"Hipotensão ortostática significativa — tontura, lipotimia e risco de queda ao levantar. O risco é maior com a primeira dose ou após aumento de dose.","conduta":"⚠️ Monitorar pressão arterial, especialmente na posição em pé, ao iniciar tizanidina em pacientes hipertensos. Iniciar com 2mg e ajustar gradualmente. Orientar mudança de posição lentamente ao levantar."},
{"med1":["felodipino","plendil","renedil"],"med2":["rifampicina","rifampin"],"nivel":"alto","titulo":"Felodipino + Rifampicina (Indução de CYP3A4 — Perda do Efeito Anti-hipertensivo)","mecanismo":"A rifampicina é um indutor potente de CYP3A4, a principal enzima responsável pelo metabolismo do felodipino. A co-administração reduz a AUC do felodipino em até 90%, tornando-o praticamente ineficaz.","efeito":"Perda quase total do efeito anti-hipertensivo e antianginoso. O paciente pode apresentar hipertensão grave durante a vigência do tratamento com rifampicina.","conduta":"🚫 Combinação contraindicada na prática clínica. Substituir o felodipino por anti-hipertensivo não metabolizado pela CYP3A4 (ex: hidroclorotiazida, lisinopril, atenolol). Após suspensão da rifampicina, reintroduzir o BCC com cuidado."},
{"med1":["felodipino","plendil","renedil"],"med2":["cetoconazol","itraconazol","voriconazol","posaconazol","claritromicina","ritonavir","saquinavir"],"nivel":"moderado","titulo":"Felodipino + Inibidor de CYP3A4 (Aumento dos Níveis — Hipotensão)","mecanismo":"Inibidores potentes de CYP3A4 (antifúngicos azólicos, macrolídeos, inibidores de protease) reduzem o metabolismo hepático de primeira passagem do felodipino, elevando seus níveis plasmáticos significativamente.","efeito":"Hipotensão arterial, taquicardia reflexa, cefaleia, rubor facial e edema periférico intensificados. Em idosos: risco de síncope.","conduta":"⚠️ Monitorar pressão arterial com atenção ao iniciar ou suspender o inibidor de CYP3A4. Considerar redução de dose do felodipino. Preferir antifúngicos tópicos quando possível."},
{"med1":["felodipino","plendil","renedil"],"med2":["atenolol","metoprolol","propranolol","bisoprolol","carvedilol"],"nivel":"moderado","titulo":"Felodipino + Beta-bloqueador (Hipotensão e Bradicardia Aditivas)","mecanismo":"O felodipino causa vasodilatação periférica e pode induzir taquicardia reflexa. Os beta-bloqueadores atenuam essa resposta reflexa e somam efeito hipotensor. A combinação é frequentemente usada na HAS, mas requer atenção à dose.","efeito":"Hipotensão arterial, bradicardia e redução do débito cardíaco — especialmente ao iniciar ou aumentar a dose de qualquer um dos fármacos. Risco maior em idosos e em pacientes com disfunção sistólica.","conduta":"⚠️ Associação possível e frequentemente usada, mas iniciar com doses baixas e monitorar PA e frequência cardíaca. Evitar em bradicardia sintomática ou bloqueio AV de 2º-3º grau."},
{"med1":["nifedipino","nifedipina","adalat"],"med2":["rifampicina","rifampin"],"nivel":"alto","titulo":"Nifedipino + Rifampicina (Indução de CYP3A4 — Perda do Efeito)","mecanismo":"A rifampicina induz fortemente a CYP3A4, que é responsável pelo metabolismo de primeira passagem do nifedipino. A AUC do nifedipino cai em 70–90% com a co-administração.","efeito":"Controle pressórico inadequado, retorno da angina e risco de eventos cardiovasculares por perda do efeito terapêutico.","conduta":"🚫 Evitar combinação. Substituir por anti-hipertensivo sem metabolismo significativo pela CYP3A4 (atenolol, lisinopril, hidroclorotiazida) durante o tratamento com rifampicina."},
{"med1":["nifedipino","nifedipina","adalat"],"med2":["fenitoína","carbamazepina","fenobarbital","oxcarbazepina"],"nivel":"moderado","titulo":"Nifedipino + Anticonvulsivante Indutor (Redução dos Níveis de Nifedipino)","mecanismo":"Fenitoína, carbamazepina e fenobarbital são indutores moderados a potentes da CYP3A4. Reduzem a biodisponibilidade oral do nifedipino, comprometendo o controle pressórico.","efeito":"Perda ou redução significativa do efeito anti-hipertensivo. Pode necessitar de doses mais elevadas de nifedipino ou troca do anti-hipertensivo.","conduta":"⚠️ Monitorar PA com maior frequência ao usar anticonvulsivantes indutores. Ajustar dose do nifedipino conforme resposta clínica ou substituir por anti-hipertensivo não-substrato de CYP3A4."},
{"med1":["nifedipino","nifedipina","adalat"],"med2":["digoxina","lanoxin"],"nivel":"moderado","titulo":"Nifedipino + Digoxina (Aumento dos Níveis de Digoxina)","mecanismo":"O nifedipino pode reduzir a depuração renal da digoxina por inibição da P-glicoproteína e por alterações no fluxo renal, elevando os níveis séricos da digoxina em 15–45%.","efeito":"Risco de toxicidade digitálica — náuseas, vômitos, visão com halo amarelado/verde, bradicardia e arritmias (bloqueio AV, extrassístoles ventriculares).","conduta":"⚠️ Monitorar nível sérico de digoxina ao iniciar ou suspender nifedipino. Medir digoxinemia e ECG quando houver suspeita de toxicidade. Pode ser necessário reduzir a dose de digoxina."},
{"med1":["nimodipino","nimotop"],"med2":["rifampicina","rifampin"],"nivel":"alto","titulo":"Nimodipino + Rifampicina (Indução Potente de CYP3A4 — Perda do Efeito Neuroprotetor)","mecanismo":"A rifampicina induz fortemente a CYP3A4, reduzindo a biodisponibilidade do nimodipino em mais de 85%. O nimodipino é usado após hemorragia subaracnóidea para prevenir vasoespasmo cerebral — perder seu efeito representa risco neurológico grave.","efeito":"Perda do efeito neuroprotetor após hemorragia subaracnóidea, com risco aumentado de vasoespasmo e isquemia cerebral.","conduta":"🚫 Contraindicado. Não usar rifampicina concomitantemente ao nimodipino pós-HSA. Substituir rifampicina por antibiótico alternativo (azitromicina, fluoroquinolona) se possível."},
{"med1":["nimodipino","nimotop"],"med2":["cetoconazol","itraconazol","voriconazol","claritromicina","ritonavir"],"nivel":"alto","titulo":"Nimodipino + Inibidor Potente de CYP3A4 (Toxicidade por Acúmulo)","mecanismo":"O nimodipino é metabolizado quase exclusivamente pela CYP3A4. Inibidores potentes (antifúngicos azólicos, claritromicina, ritonavir) elevam sua AUC em 4–9 vezes, com risco de toxicidade grave.","efeito":"Hipotensão grave, cefaleia intensa, rubor e risco de colapso cardiovascular. Em contexto pós-HSA, a hipotensão pode piorar a perfusão cerebral e agravar o quadro neurológico.","conduta":"🚫 Evitar combinação. Se necessário, reduzir dose do nimodipino drasticamente e monitorar PA de forma contínua em ambiente hospitalar."},
{"med1":["nimodipino","nimotop"],"med2":["valproato","divalproato","ácido valproico","depakote","depakene"],"nivel":"moderado","titulo":"Nimodipino + Valproato (Aumento dos Níveis de Nimodipino)","mecanismo":"O valproato inibe enzimas hepáticas, podendo reduzir o metabolismo do nimodipino e elevar seus níveis plasmáticos. Embora o mecanismo exato seja incompletamente compreendido, a interação é clinicamente relevante.","efeito":"Hipotensão arterial e bradicardia mais pronunciadas. Cefaleia e rubor intensificados.","conduta":"⚠️ Monitorar PA ao associar valproato e nimodipino. Ajustar dose do nimodipino se necessário. Atenção especial em pacientes com epilepsia que recebem nimodipino por vasoespasmo pós-HSA."},
{"med1":["nisoldipino","syscor","baymycard"],"med2":["rifampicina","rifampin"],"nivel":"alto","titulo":"Nisoldipino + Rifampicina (Indução Máxima de CYP3A4 — Perda Total do Efeito)","mecanismo":"A rifampicina induz a CYP3A4 de forma tão intensa que a biodisponibilidade oral do nisoldipino cai praticamente a zero. Esta é uma das interações fármaco-fármaco mais drásticas descritas para BCCs.","efeito":"Perda total do efeito anti-hipertensivo, com risco de hipertensão grave e eventos cardiovasculares. Níveis plasmáticos tornam-se indetectáveis.","conduta":"🚫 Contraindicado. Substituir o nisoldipino por anti-hipertensivo não dependente de CYP3A4 (tiazídico, IECA, beta-bloqueador) durante e após o uso de rifampicina."},
{"med1":["nisoldipino","syscor","baymycard"],"med2":["fenitoína","carbamazepina","fenobarbital"],"nivel":"alto","titulo":"Nisoldipino + Anticonvulsivante Indutor (Perda do Efeito Anti-hipertensivo)","mecanismo":"Fenitoína e carbamazepina são indutores potentes de CYP3A4. Estudos mostram redução da AUC do nisoldipino em mais de 80% com a co-administração de fenitoína — tornando o tratamento ineficaz.","efeito":"Controle pressórico insuficiente com PA elevada mesmo em doses habituais de nisoldipino.","conduta":"🚫 Evitar combinação. Substituir o nisoldipino por anti-hipertensivo sem interação relevante de CYP3A4 em pacientes em uso crônico de anticonvulsivantes indutores."},
{"med1":["nisoldipino","syscor","baymycard"],"med2":["cetoconazol","itraconazol","claritromicina","ritonavir"],"nivel":"moderado","titulo":"Nisoldipino + Inibidor de CYP3A4 (Aumento dos Níveis — Hipotensão)","mecanismo":"Inibidores potentes de CYP3A4 reduzem o metabolismo hepático de primeira passagem do nisoldipino, elevando sua AUC em 4–6 vezes — com consequente hipotensão e taquicardia reflexa.","efeito":"Hipotensão arterial, taquicardia, cefaleia, rubor e edema intensificados. Risco de síncope em pacientes idosos ou com disfunção autonômica.","conduta":"⚠️ Reduzir dose do nisoldipino ao iniciar inibidor de CYP3A4. Monitorar PA de perto. Suspenso o inibidor, a dose original pode ser necessária."},
{"med1":["indapamida","natrilix"],"med2":["digoxina","lanoxin"],"nivel":"moderado","titulo":"Indapamida + Digoxina (Hipocalemia → Toxicidade Digitálica)","mecanismo":"A indapamida, como os tiazídicos, pode causar hipocalemia. A hipocalemia aumenta a sensibilidade do miocárdio à digoxina por competição com o potássio pelos sítios de ligação da Na⁺/K⁺-ATPase — potencializando sua toxicidade mesmo com níveis séricos de digoxina dentro da faixa terapêutica.","efeito":"Risco de toxicidade digitálica mesmo com digoxinemia normal — náuseas, bradicardia, bloqueio AV, extrassístoles e taquiarritmias ventriculares.","conduta":"⚠️ Monitorar potássio sérico regularmente. Repor potássio se K⁺ < 3,5 mEq/L. Considerar associação com diurético poupador de potássio (espironolactona, amilorida). Monitorar ECG e digoxinemia."},
{"med1":["indapamida","natrilix"],"med2":["ibuprofeno","naproxeno","diclofenaco","celecoxibe","etoricoxibe","nimesulida","cetoprofeno"],"nivel":"moderado","titulo":"Indapamida + AINE (Redução do Efeito Diurético e Anti-hipertensivo)","mecanismo":"Os AINEs inibem a síntese de prostaglandinas vasodilatadoras renais, que são necessárias para o efeito diurético e natriurético dos tiazídicos. Além disso, os AINEs causam retenção de sódio e água, antagonizando o efeito anti-hipertensivo.","efeito":"Redução do efeito diurético e anti-hipertensivo da indapamida. Pode haver aumento da PA e retenção de líquidos, especialmente com uso crônico de AINEs.","conduta":"⚠️ Preferir paracetamol como analgésico/antipirético em pacientes usando indapamida para HAS. Se AINE for necessário, usar pelo menor tempo possível e monitorar PA e função renal."},
{"med1":["indapamida","natrilix"],"med2":["enalapril","captopril","lisinopril","losartana","valsartana","candesartana","telmisartana"],"nivel":"moderado","titulo":"Indapamida + IECA / BRA (Hipotensão de Primeira Dose)","mecanismo":"A indapamida causa depleção de sódio e ativação do sistema renina-angiotensina. A introdução de IECA ou BRA nesse contexto bloqueia abruptamente a angiotensina II — podendo causar queda brusca da PA na primeira dose (fenômeno de primeira dose).","efeito":"Hipotensão aguda, tontura, síncope — especialmente nas primeiras horas após a primeira dose do IECA/BRA em paciente usando indapamida.","conduta":"⚠️ Iniciar IECA/BRA com dose mínima. Orientar o paciente a tomar a primeira dose à noite, deitado. Monitorar PA nas primeiras 2 horas após a 1ª dose. A combinação é eficaz e amplamente utilizada após o ajuste."},
{"med1":["dronedarona","multaq"],"med2":["warfarina","varfarina","acenocumarol","sintrom"],"nivel":"moderado","titulo":"Dronedarona + Anticoagulante Cumarínico (Aumento do INR por Inibição de CYP2C9)","mecanismo":"A dronedarona inibe moderadamente a CYP2C9, principal enzima responsável pelo metabolismo do S-warfarina (enantiômero mais ativo). A co-administração eleva o INR em média 1,2–1,7 vezes acima do valor prévio.","efeito":"Risco aumentado de sangramento — equimoses, epistaxe, hematúria, sangramento gastrointestinal e, nos casos graves, hemorragia intracraniana.","conduta":"⚠️ Monitorar INR com maior frequência ao iniciar ou suspender a dronedarona. Ajustar a dose do cumarínico conforme INR. Considerar troca para anticoagulante de ação direta (apixabana, rivaroxabana) como alternativa mais previsível."},
{"med1":["dronedarona","multaq"],"med2":["dabigatrana","pradaxa"],"nivel":"moderado","titulo":"Dronedarona + Dabigatrana (Inibição de P-gp — Aumento dos Níveis de Dabigatrana)","mecanismo":"A dronedarona é inibidora da glicoproteína P (P-gp). A dabigatrana (etexilato) é substrato da P-gp para absorção intestinal. A co-administração reduz a secreção intestinal de dabigatrana, elevando seus níveis plasmáticos em 70–100%.","efeito":"Aumento significativo da exposição à dabigatrana — com risco de sangramento maior, incluindo hemorragia gastrointestinal e intracraniana.","conduta":"⚠️ A associação é contraindicada na maioria das diretrizes quando a função renal está reduzida (ClCr < 50 mL/min). Com função renal normal, usar dabigatrana 110mg 2×/dia e monitorar função renal. Considerar apixabana ou rivaroxabana como alternativa mais segura."},
{"med1":["dronedarona","multaq"],"med2":["rifampicina","rifampin"],"nivel":"alto","titulo":"Dronedarona + Rifampicina (Indução de CYP3A4 — Perda da Eficácia Antiarrítmica)","mecanismo":"A rifampicina é indutora potente de CYP3A4, principal via de metabolismo da dronedarona. A co-administração reduz a exposição à dronedarona em mais de 80%, tornando-a ineficaz para controle do ritmo cardíaco.","efeito":"Perda do controle do ritmo na FA — recorrência de fibrilação atrial e risco de eventos tromboembólicos.","conduta":"🚫 Combinação contraindicada. Substituir a rifampicina por antibiótico alternativo (azitromicina, fluoroquinolona com cuidado para QT) ou substituir a dronedarona por outro antiarrítmico não dependente de CYP3A4."},
{"med1":["dronedarona","multaq"],"med2":["verapamil","diltiazem"],"nivel":"alto","titulo":"Dronedarona + Verapamil / Diltiazem (Bradicardia Grave e Bloqueio AV)","mecanismo":"A dronedarona prolonga o intervalo PR por ação sobre canais de cálcio e canais Ih. O verapamil e o diltiazem são bloqueadores dos canais de cálcio com efeito cronotrópico e dromotrópico negativo pronunciado. A combinação potencializa o risco de bloqueio atrioventricular.","efeito":"Bradicardia grave (FC < 50 bpm), bloqueio AV de 1º, 2º ou 3º grau, tonturas e síncope. Em idosos: risco de colapso hemodinâmico.","conduta":"🚫 Se a combinação for inevitável: realizar ECG antes de iniciar e em 1–2 semanas. Iniciar verapamil ou diltiazem em dose mínima e monitorar FC e intervalo PR rigorosamente. Em geral, evitar a combinação."},
{"med1":["sotalol","sotacor"],"med2":["hidroclorotiazida","furosemida","bumetanida","ácido etacrínico","indapamida","clortalidona"],"nivel":"alto","titulo":"Sotalol + Diurético Hipocalemiante (Hipocalemia → Torsades de Pointes)","mecanismo":"O sotalol prolonga o intervalo QT por bloqueio de canais de potássio IKr. A hipocalemia induzida por diuréticos tiazídicos e de alça potencializa o bloqueio dos canais de potássio, aumentando ainda mais o QTc e o risco de taquicardia ventricular polimórfica.","efeito":"QT prolongado e risco de Torsades de Pointes — taquicardia ventricular polimórfica potencialmente fatal. O risco é maior com doses elevadas de sotalol e hipocalemia grave (K⁺ < 3,0 mEq/L).","conduta":"🚫 Monitorar potássio sérico rigorosamente ao combinar sotalol com diuréticos. Manter K⁺ ≥ 4,0 mEq/L durante uso de sotalol. Considerar adição de diurético poupador de potássio (espironolactona, amilorida) ou suplementação oral de KCl. Realizar ECG periódico."},
{"med1":["sotalol","sotacor"],"med2":["verapamil","diltiazem"],"nivel":"alto","titulo":"Sotalol + Verapamil / Diltiazem (Bradicardia Grave e Bloqueio AV — Risco de Colapso)","mecanismo":"O sotalol é beta-bloqueador não seletivo com propriedades antiarrítmicas classe III (prolongamento do QT). O verapamil e o diltiazem são bloqueadores dos canais de cálcio com ação cronotrópica e dromotrópica negativa. A combinação é sinérgica para depressão da condução e do automatismo cardíacos.","efeito":"Bradicardia grave, bloqueio AV de alto grau (podendo chegar ao bloqueio completo), hipotensão severa e risco de parada cardíaca. Casos fatais foram relatados.","conduta":"🚫 Combinação geralmente contraindicada. Se absolutamente necessária, realizar apenas em ambiente hospitalar com monitorização contínua do ECG. Em pacientes ambulatoriais, substituir um dos fármacos."},
{"med1":["sotalol","sotacor"],"med2":["insulina","insulina nph","insulina regular","insulina glargina","glibenclamida","gliclazida","glimepirida"],"nivel":"moderado","titulo":"Sotalol + Antidiabético (Mascaramento da Taquicardia Hipoglicêmica)","mecanismo":"Como beta-bloqueador não seletivo, o sotalol bloqueia os receptores β2-adrenérgicos responsáveis por tremor e taquicardia — sinais de alerta de hipoglicemia. Além disso, pode prolongar e intensificar episódios hipoglicêmicos ao reduzir a glicogenólise mediada por catecolaminas.","efeito":"Mascaramento dos sinais adrenérgicos de hipoglicemia (tremor, palpitações) — o paciente pode não perceber a hipoglicemia a tempo. A sudorese persiste como sinal de alerta, mas pode ser insuficiente. Risco de hipoglicemia grave desapercebida.","conduta":"⚠️ Orientar paciente diabético em uso de sotalol a monitorar glicemia com maior frequência — especialmente antes de atividade física e durante ajuste de dose de insulina/hipoglicemiante. Reforçar que o tremor e as palpitações podem estar ausentes na hipoglicemia."},
{"med1":["clortalidona","higrotona","hygroton"],"med2":["digoxina","lanoxin"],"nivel":"moderado","titulo":"Clortalidona + Digoxina (Hipocalemia → Toxicidade Digitálica)","mecanismo":"A clortalidona causa perda renal de potássio e magnésio. A hipocalemia aumenta a afinidade da digoxina pela Na⁺/K⁺-ATPase miocárdica — potencializando sua toxicidade mesmo com digoxinemia dentro da faixa terapêutica. O efeito é intensificado pela hipomagnesemia associada.","efeito":"Toxicidade digitálica clinicamente significativa mesmo com níveis séricos de digoxina normais — bradicardia sinusal, bloqueio AV, extrassístoles ventriculares, náuseas e visão com halo amarelado/verde.","conduta":"⚠️ Monitorar potássio e magnésio séricos regularmente. Manter K⁺ ≥ 4,0 mEq/L e Mg²⁺ ≥ 0,8 mEq/L em pacientes digitalizados. Considerar adição de poupador de potássio (espironolactona) ou suplementação. Realizar ECG e digoxinemia se houver suspeita de toxicidade."},
{"med1":["clortalidona","higrotona","hygroton"],"med2":["enalapril","captopril","lisinopril","ramipril","losartana","valsartana","candesartana","telmisartana"],"nivel":"moderado","titulo":"Clortalidona + IECA / BRA (Hipotensão de Primeira Dose)","mecanismo":"A clortalidona tem ação prolongada (meia-vida de 45–60h) e causa depleção volumétrica e sódica sustentada, ativando o sistema renina-angiotensina. A introdução de IECA ou BRA nesse contexto bloqueia abruptamente o eixo renina-angiotensina, podendo causar queda intensa da PA.","efeito":"Hipotensão aguda e ortostática — tontura, síncope e, nos casos graves, insuficiência renal aguda pré-renal. O risco é maior em idosos, pacientes com depleção volumétrica ou que recebem doses altas de clortalidona.","conduta":"⚠️ Iniciar IECA/BRA com a menor dose disponível. Orientar a tomar a primeira dose à noite, deitado. Monitorar PA e creatinina/ureia nas primeiras semanas. A associação é amplamente usada e eficaz após o ajuste de doses."},
{"med1":["atazanavir","reyataz"],"med2":["sinvastatina","lovastatina","atorvastatina"],"nivel":"alto","titulo":"Atazanavir + Estatina (Rabdomiólise por Inibição de CYP3A4)","mecanismo":"O atazanavir é forte inibidor de CYP3A4. Sinvastatina e lovastatina são metabolizadas quase exclusivamente pela CYP3A4 — a co-administração eleva seus níveis em 5–10 vezes, com risco de miopatia e rabdomiólise. A atorvastatina é afetada em menor grau, mas ainda significativamente.","efeito":"Miopatia grave — dor muscular intensa, fraqueza e elevação de CK. Nos casos graves: rabdomiólise com insuficiência renal aguda e urina cor de chá.","conduta":"🚫 Sinvastatina e lovastatina são contraindicadas com atazanavir. Usar rosuvastatina (dose máxima 10mg/dia) ou pravastatina como alternativas mais seguras. Atorvastatina: dose máxima 20mg/dia com monitoração."},
{"med1":["atazanavir","reyataz"],"med2":["midazolam","triazolam","halcion"],"nivel":"alto","titulo":"Atazanavir + Midazolam / Triazolam (Sedação Excessiva — Contraindicado)","mecanismo":"O atazanavir inibe fortemente a CYP3A4, que é responsável pelo metabolismo do midazolam e do triazolam oral. A co-administração eleva os níveis de benzodiazepínicos em múltiplas vezes, com risco de sedação prolongada e depressão respiratória grave.","efeito":"Sedação profunda e prolongada, amnésia e depressão respiratória potencialmente fatal. O efeito pode durar horas além do esperado.","conduta":"🚫 Midazolam oral e triazolam são contraindicados com atazanavir. Se sedação for necessária, pode-se usar midazolam IV com dose única em ambiente monitorado. Considerar lorazepam ou oxazepam (metabolismo independente de CYP3A4) como alternativas."},
{"med1":["atazanavir","reyataz"],"med2":["antiácido","hidróxido de alumínio","hidróxido de magnésio","carbonato de cálcio","bicarbonato"],"nivel":"moderado","titulo":"Atazanavir + Antiácido (Redução da Absorção por Elevação de pH)","mecanismo":"O atazanavir necessita de pH gástrico ácido para se dissolver e ser absorvido. Antiácidos elevam temporariamente o pH gástrico, reduzindo a solubilidade do atazanavir e sua biodisponibilidade em 20–30%. O efeito é menor que o dos IBPs, mas ainda relevante.","efeito":"Redução da absorção do atazanavir — níveis plasmáticos mais baixos com risco de falha virológica a médio prazo.","conduta":"⚠️ Separar a tomada de antiácidos do atazanavir por pelo menos 2 horas (tomar o atazanavir 2h antes ou 1h depois do antiácido). IBPs são contraindicados sem ritonavir/cobicistat — com booster, permitir apenas omeprazol ≤20mg/dia."},
{"med1":["darunavir","prezista"],"med2":["sinvastatina","lovastatina"],"nivel":"alto","titulo":"Darunavir/Ritonavir + Sinvastatina / Lovastatina (Rabdomiólise)","mecanismo":"O darunavir é administrado com ritonavir ou cobicistat — ambos são inibidores potentes de CYP3A4. Sinvastatina e lovastatina são substratos exclusivos de CYP3A4, e seus níveis podem aumentar em até 10 vezes, causando toxicidade muscular grave.","efeito":"Miopatia, dor muscular intensa, fraqueza e, nos casos graves, rabdomiólise com insuficiência renal aguda.","conduta":"🚫 Sinvastatina e lovastatina são contraindicadas com darunavir/ritonavir. Preferir rosuvastatina (máx. 10mg/dia) ou pravastatina. Evitar atorvastatina em doses elevadas."},
{"med1":["darunavir","prezista"],"med2":["midazolam","triazolam","halcion"],"nivel":"alto","titulo":"Darunavir/Ritonavir + Midazolam / Triazolam (Sedação Grave — Contraindicado)","mecanismo":"Darunavir boosted com ritonavir/cobicistat inibe intensamente a CYP3A4. Midazolam oral e triazolam são metabolizados quase exclusivamente por essa via — a combinação pode elevar seus níveis em 10–20 vezes, com risco de sedação prolongada e depressão respiratória.","efeito":"Sedação grave e prolongada, depressão respiratória com risco de óbito. O paciente pode permanecer sedado por horas além do previsto.","conduta":"🚫 Contraindicado. Usar lorazepam ou oxazepam (glicuronoconjugação, sem CYP3A4) como alternativas. Midazolam IV dose única em ambiente monitorado pode ser usado com extrema cautela."},
{"med1":["darunavir","prezista"],"med2":["etinilestradiol","levonorgestrel","desogestrel","drospirenona","anticoncepcional oral","anticontraceptivo"],"nivel":"moderado","titulo":"Darunavir/Ritonavir + Contraceptivo Hormonal Oral (Redução da Eficácia)","mecanismo":"O ritonavir (booster do darunavir) induz a CYP3A4 para alguns substratos enquanto inibe para outros. Com contraceptivos contendo etinilestradiol, há redução de até 40% nos níveis hormonais, comprometendo a proteção contraceptiva.","efeito":"Risco de falha contraceptiva e gravidez não planejada, especialmente em mulheres em uso de anticontraceptivos de baixa dose.","conduta":"⚠️ Utilizar método contraceptivo adicional não hormonal (preservativo, DIU de cobre) durante o uso de darunavir/ritonavir. Discutir com a paciente a troca para DIU hormonal ou implante, menos dependentes de absorção oral."},
{"med1":["indinavir","crixivan"],"med2":["sinvastatina","lovastatina"],"nivel":"alto","titulo":"Indinavir + Sinvastatina / Lovastatina (Rabdomiólise por Inibição de CYP3A4)","mecanismo":"O indinavir inibe a CYP3A4, elevando os níveis de sinvastatina e lovastatina em múltiplas vezes. Ao contrário de outros IPs, o indinavir não requer booster, mas sua própria ação inibitória sobre CYP3A4 é suficiente para causar interação clinicamente significativa.","efeito":"Miopatia, dor e fraqueza muscular, elevação de CK e, nos casos graves, rabdomiólise com insuficiência renal.","conduta":"🚫 Sinvastatina e lovastatina contraindicadas com indinavir. Usar rosuvastatina (máx. 10mg/dia) ou pravastatina como alternativas."},
{"med1":["indinavir","crixivan"],"med2":["midazolam","triazolam","halcion"],"nivel":"alto","titulo":"Indinavir + Midazolam / Triazolam (Sedação Excessiva — Contraindicado)","mecanismo":"O indinavir inibe a CYP3A4 e eleva os níveis de midazolam oral e triazolam em múltiplas vezes, com risco de sedação grave e depressão respiratória.","efeito":"Sedação prolongada e profunda, amnésia e risco de depressão respiratória.","conduta":"🚫 Contraindicado. Substituir por lorazepam ou oxazepam quando sedação ansiolítica for necessária."},
{"med1":["nelfinavir","viracept"],"med2":["rifampicina","rifampin"],"nivel":"alto","titulo":"Nelfinavir + Rifampicina (Indução Máxima de CYP3A4 — Falha Antirretroviral)","mecanismo":"A rifampicina é o indutor mais potente de CYP3A4. O nelfinavir é substrato de CYP3A4 e CYP2C19, e tem seus níveis reduzidos em 82% com a co-administração de rifampicina, tornando os níveis antirretrovirais subterapêuticos.","efeito":"Falha virológica — supressão inadequada do HIV com risco de progressão da doença, desenvolvimento de infecções oportunistas e seleção de mutações de resistência.","conduta":"🚫 Contraindicado. A rifampicina é incompatível com todos os IPs. Para tuberculose em paciente usando nelfinavir, substituir rifampicina por rifabutina (indutora mais fraca) e ajustar dose do nelfinavir conforme protocolo."},
{"med1":["nelfinavir","viracept"],"med2":["sinvastatina","lovastatina"],"nivel":"alto","titulo":"Nelfinavir + Sinvastatina / Lovastatina (Rabdomiólise)","mecanismo":"O nelfinavir inibe moderadamente a CYP3A4 — elevando os níveis de sinvastatina e lovastatina de forma clinicamente relevante, com risco de toxicidade muscular.","efeito":"Miopatia e risco de rabdomiólise com insuficiência renal aguda.","conduta":"🚫 Sinvastatina e lovastatina contraindicadas. Preferir rosuvastatina (máx. 10mg) ou pravastatina."},
{"med1":["nelfinavir","viracept"],"med2":["midazolam","triazolam","halcion"],"nivel":"alto","titulo":"Nelfinavir + Midazolam / Triazolam (Contraindicado)","mecanismo":"O nelfinavir inibe a CYP3A4, elevando os níveis de midazolam oral e triazolam com risco de sedação grave e depressão respiratória.","efeito":"Sedação excessiva e prolongada, risco de depressão respiratória.","conduta":"🚫 Contraindicado. Usar lorazepam ou oxazepam como alternativas."},
{"med1":["saquinavir","invirase"],"med2":["amiodarona","dronedarona","sotalol","moxifloxacino","haloperidol","quetiapina","metadona"],"nivel":"alto","titulo":"Saquinavir + Prolongadores de QT (Torsades de Pointes — Contraindicado)","mecanismo":"O saquinavir prolonga o intervalo QT e QTc de forma dose-dependente. Sua combinação com outros fármacos prolongadores de QT (antiarrítmicos, antipsicóticos, metadona) é sinérgica e aumenta dramaticamente o risco de taquicardia ventricular polimórfica.","efeito":"Torsades de Pointes — taquicardia ventricular polimórfica potencialmente fatal, podendo evoluir para fibrilação ventricular e morte súbita.","conduta":"🚫 Contraindicado com outros prolongadores de QT. Realizar ECG antes e após início do saquinavir. Corrigir hipocalemia e hipomagnesemia antes do tratamento. Se não houver alternativa ao IP, considerar atazanavir ou darunavir (menor risco de QT)."},
{"med1":["saquinavir","invirase"],"med2":["sinvastatina","lovastatina"],"nivel":"alto","titulo":"Saquinavir/Ritonavir + Sinvastatina / Lovastatina (Rabdomiólise)","mecanismo":"Saquinavir é sempre administrado com ritonavir, que é o inibidor de CYP3A4 mais potente disponível. A combinação eleva os níveis de sinvastatina e lovastatina em mais de 10 vezes.","efeito":"Miopatia grave e rabdomiólise com risco de insuficiência renal aguda.","conduta":"🚫 Sinvastatina e lovastatina contraindicadas. Usar rosuvastatina (máx. 10mg) ou pravastatina."},
{"med1":["nevirapina","viramune"],"med2":["etinilestradiol","levonorgestrel","desogestrel","drospirenona","anticoncepcional oral","gestodeno","noretisterona"],"nivel":"alto","titulo":"Nevirapina + Contraceptivo Hormonal Oral (Falha Contraceptiva por Indução de CYP3A4)","mecanismo":"A nevirapina é autoindutor potente de CYP3A4 e CYP2B6. Os estrogênios e progestágenos dos contraceptivos orais são substratos de CYP3A4, e seus níveis caem em 20–50% com a co-administração de nevirapina, comprometendo a eficácia contraceptiva.","efeito":"Falha contraceptiva com risco de gravidez não planejada — risco adicional e crítico em mulheres soropositivas em uso de ARV.","conduta":"🚫 Contraceptivos orais são insuficientes com nevirapina. Usar método contraceptivo de alta eficácia não dependente de metabolismo hepático: DIU de cobre, DIU hormonal (levonorgestrel intrauterino tem menor impacto), implante subdérmico ou injeção de medroxiprogesterona. Sempre associar preservativo."},
{"med1":["nevirapina","viramune"],"med2":["metadona","methadone"],"nivel":"alto","titulo":"Nevirapina + Metadona (Síndrome de Abstinência por Indução Enzimática)","mecanismo":"A nevirapina induz CYP3A4 e CYP2B6, principais enzimas do metabolismo da metadona. A co-administração reduz os níveis plasmáticos de metadona em 50–60%, precipitando síndrome de abstinência aguda em pacientes em terapia de manutenção para dependência de opioides.","efeito":"Síndrome de abstinência de opioides — ansiedade, sudorese, tremores, taquicardia, diarreia, náuseas, dor muscular e intensa fissura — podendo levar à recaída do uso de drogas ilícitas.","conduta":"⚠️ Monitorar sintomas de abstinência ao iniciar nevirapina em usuários de metadona. Aumentar a dose de metadona de 5–10mg por dia conforme necessário. Comunicar a equipe de tratamento de dependência química. Considerar uso de efavirenz (mesma questão, mas melhor documentada) ou dolutegravir (sem interação com metadona)."},
{"med1":["nevirapina","viramune"],"med2":["ketoconazol","cetoconazol"],"nivel":"moderado","titulo":"Nevirapina + Cetoconazol (Interação Bidirecional — Redução Mútua dos Níveis)","mecanismo":"A nevirapina induz CYP3A4, reduzindo os níveis de cetoconazol. Ao mesmo tempo, o cetoconazol inibe CYP3A4 e pode elevar transitoriamente os níveis de nevirapina. A interação é bidirecional e resulta em eficácia reduzida de ambos.","efeito":"Falha antifúngica por níveis inadequados de cetoconazol. Possível variação imprevisível dos níveis de nevirapina.","conduta":"⚠️ Evitar a combinação. Para tratamento de candidíase sistêmica em paciente em uso de nevirapina, preferir fluconazol (menor impacto, embora também iniba CYP3A4 em menor grau) e monitorar resposta clínica."},
{"med1":["rilpivirina","edurant"],"med2":["antiácido","hidróxido de alumínio","hidróxido de magnésio","carbonato de cálcio"],"nivel":"moderado","titulo":"Rilpivirina + Antiácido (Redução da Absorção — Separar 4 Horas)","mecanismo":"A rilpivirina necessita de pH gástrico ácido para dissolução e absorção adequadas. Antiácidos elevam o pH gástrico temporariamente, reduzindo a biodisponibilidade da rilpivirina em até 30–50%.","efeito":"Níveis plasmáticos de rilpivirina abaixo do terapêutico com risco de falha virológica e seleção de mutações de resistência (especialmente mutação K101E, E138A, V179L, Y181C, Y188L).","conduta":"⚠️ Separar a tomada do antiácido e da rilpivirina por pelo menos 4 horas (tomar rilpivirina 4h depois do antiácido, ou 2h antes). Bloqueadores H2: separar por 12h (antes) ou 4h (depois). IBPs: contraindicados."},
{"med1":["rilpivirina","edurant"],"med2":["carbamazepina","fenitoína","fenobarbital","oxcarbazepina"],"nivel":"alto","titulo":"Rilpivirina + Anticonvulsivante Indutor (Falha Virológica por Indução de CYP3A4)","mecanismo":"Carbamazepina, fenitoína e fenobarbital são indutores potentes de CYP3A4, principal via de metabolismo da rilpivirina. A co-administração reduz os níveis da rilpivirina em 46–80%, tornando-a ineficaz.","efeito":"Falha virológica — supressão inadequada do HIV com risco de progressão da doença e desenvolvimento de resistência ao ITRNN.","conduta":"🚫 Contraindicado. Para pacientes HIV+ em uso de anticonvulsivantes indutores, preferir regime baseado em inibidor de integrase (dolutegravir, bictegravir) que não dependem de CYP3A4 para metabolismo."},
{"med1":["rilpivirina","edurant"],"med2":["metadona","methadone"],"nivel":"moderado","titulo":"Rilpivirina + Metadona (Prolongamento de QTc Aditivo)","mecanismo":"A rilpivirina prolonga discretamente o intervalo QTc. A metadona é um dos fármacos com maior potencial de prolongamento de QT entre todos os medicamentos. A associação pode ser aditiva para o risco de Torsades de Pointes, especialmente em doses elevadas de metadona.","efeito":"Prolongamento do QTc com risco de Torsades de Pointes — especialmente quando a dose de metadona for elevada (>100mg/dia) ou houver hipocalemia associada.","conduta":"⚠️ Realizar ECG basal e repetir após 4 semanas de uso concomitante. Monitorar eletrólitos (K⁺ e Mg²⁺). Se QTc > 500ms, reconsiderar o regime antirretroviral."},
{"med1":["ketoconazol","cetoconazol","nizoral"],"med2":["ciclosporina","sandimmun","neoral"],"nivel":"alto","titulo":"Cetoconazol + Ciclosporina (Toxicidade da Ciclosporina por Inibição de CYP3A4)","mecanismo":"O cetoconazol é um dos inibidores mais potentes de CYP3A4 e P-gp. A ciclosporina é metabolizada quase exclusivamente pela CYP3A4. A co-administração eleva os níveis de ciclosporina em 4–5 vezes, com risco de toxicidade grave em órgão-alvo.","efeito":"Nefrotoxicidade aguda (elevação de creatinina, oligúria), neurotoxicidade (tremor, convulsão), hepatotoxicidade e hipertensão grave. Em transplantados: risco de perda do enxerto.","conduta":"🚫 Evitar a combinação. Se inevitável (ex.: tratamento de candidíase em transplantado), reduzir dose de ciclosporina em 50–75% e monitorar nível sérico diariamente. Restaurar dose original ao suspender cetoconazol — risco de rejeição por queda abrupta dos níveis."},
{"med1":["ketoconazol","cetoconazol","nizoral"],"med2":["sinvastatina","lovastatina","atorvastatina"],"nivel":"alto","titulo":"Cetoconazol + Estatina (Rabdomiólise por Inibição de CYP3A4)","mecanismo":"O cetoconazol sistêmico inibe fortemente a CYP3A4 e eleva os níveis de sinvastatina, lovastatina e atorvastatina em múltiplas vezes, com risco de toxicidade muscular grave.","efeito":"Miopatia, dor e fraqueza muscular, elevação de CK e risco de rabdomiólise com insuficiência renal aguda.","conduta":"🚫 Sinvastatina e lovastatina contraindicadas com cetoconazol sistêmico. Suspender estatina temporariamente ou usar rosuvastatina/pravastatina (menor dependência de CYP3A4). Retomar a estatina após completar o tratamento antifúngico."},
{"med1":["ketoconazol","cetoconazol","nizoral"],"med2":["budesonida","fluticasona","beclometasona","triancinolona","dexametasona"],"nivel":"alto","titulo":"Cetoconazol + Corticosteroide Inalatório / Tópico (Síndrome de Cushing Iatrogênica)","mecanismo":"O cetoconazol inibe fortemente a CYP3A4, que é responsável pelo metabolismo de corticosteroides inalatórios (budesonida, fluticasona) e tópicos. A inibição aumenta drasticamente a exposição sistêmica ao corticosteroide, mesmo em doses inalatórias ou tópicas, podendo causar supressão do eixo HPA.","efeito":"Síndrome de Cushing iatrogênica — ganho de peso, hiperglicemia, hipertensão, osteoporose, imunossupressão, face em lua cheia. Risco de insuficiência adrenal ao suspender o corticosteroide.","conduta":"⚠️ Evitar a associação, especialmente com budesonida e fluticasona (alta dependência de CYP3A4). Se inevitável, monitorar sinais de hipercortisolismo. Considerar redução gradual da dose do corticosteroide durante o uso de cetoconazol sistêmico."},
{"med1":["ketoconazol","cetoconazol","nizoral"],"med2":["midazolam","triazolam","halcion","alprazolam"],"nivel":"alto","titulo":"Cetoconazol + Midazolam / Triazolam (Sedação Excessiva — Contraindicado)","mecanismo":"O cetoconazol é o inibidor de CYP3A4 mais potente entre os antifúngicos. Midazolam oral e triazolam têm praticamente todo o seu metabolismo via CYP3A4, e seus níveis podem elevar-se em 10–15 vezes com a co-administração.","efeito":"Sedação profunda e prolongada, amnésia anterograde e depressão respiratória com risco de apneia e óbito.","conduta":"🚫 Midazolam oral e triazolam contraindicados com cetoconazol sistêmico. Midazolam IV pode ser usado com dose única reduzida em ambiente monitorado. Alprazolam: reduzir dose em 50–75%. Preferir lorazepam ou oxazepam."},
{"med1":["posaconazol","noxafil"],"med2":["sinvastatina","lovastatina","atorvastatina"],"nivel":"alto","titulo":"Posaconazol + Estatina (Rabdomiólise por Inibição de CYP3A4)","mecanismo":"O posaconazol é inibidor potente de CYP3A4. Sinvastatina e lovastatina são metabolizadas quase exclusivamente por CYP3A4 — seus níveis podem elevar-se em 5–10 vezes com co-administração de posaconazol.","efeito":"Miopatia, dor muscular severa e risco de rabdomiólise com insuficiência renal aguda.","conduta":"🚫 Sinvastatina e lovastatina contraindicadas durante o uso de posaconazol. Suspender estatina temporariamente (prophylaxis antifúngica dura semanas a meses) ou usar rosuvastatina/pravastatina em baixas doses com monitoração."},
{"med1":["posaconazol","noxafil"],"med2":["midazolam","triazolam","halcion"],"nivel":"alto","titulo":"Posaconazol + Midazolam / Triazolam (Sedação Grave — Contraindicado)","mecanismo":"O posaconazol inibe fortemente a CYP3A4, elevando os níveis de midazolam oral e triazolam em múltiplas vezes, com risco de sedação prolongada e depressão respiratória.","efeito":"Sedação excessiva e prolongada, depressão respiratória e risco de apneia.","conduta":"🚫 Midazolam oral e triazolam contraindicados com posaconazol. Usar lorazepam ou oxazepam como alternativas."},
{"med1":["posaconazol","noxafil"],"med2":["metadona","methadone"],"nivel":"alto","titulo":"Posaconazol + Metadona (QT Prolongado e Aumento dos Níveis de Metadona)","mecanismo":"O posaconazol inibe CYP3A4 e possivelmente CYP2D6, aumentando os níveis de metadona. Adicionalmente, ambos prolongam o intervalo QT — o efeito combinado é aditivo para o risco de Torsades de Pointes.","efeito":"Elevação dos níveis de metadona com risco de toxicidade opioide (sedação, depressão respiratória) e prolongamento adicional do QTc com risco de Torsades de Pointes.","conduta":"⚠️ Monitorar ECG (intervalo QTc) e sinais de toxicidade opioide ao iniciar posaconazol em paciente em metadona. Considerar redução da dose de metadona. Manter eletrólitos normais (K⁺ ≥ 4,0, Mg²⁺ ≥ 0,8)."},
{"med1":["tamoxifeno","nolvadex","tamoxan"],"med2":["etinilestradiol","anticoncepcional oral","anticontraceptivo","estrogênio"],"nivel":"alto","titulo":"Tamoxifeno + Estrogênio / Anticoncepcional Oral (Antagonismo e Tromboembolismo)","mecanismo":"O tamoxifeno antagoniza o receptor de estrogênio no tecido mamário. A adição de estrogênio exógeno (anticoncepcional oral, TRH) pode antagonizar o efeito antitumoral do tamoxifeno no tecido mamário e, ao mesmo tempo, potencializar o risco trombótico — já elevado pelo tamoxifeno via ação pró-estrogênica no fígado.","efeito":"Risco aumentado de tromboembolismo venoso (TVP, TEP) e potencial redução da eficácia do tratamento do câncer de mama. O risco tromboembólico com a combinação é maior que com cada fármaco isoladamente.","conduta":"🚫 Contraceptivos hormonais com estrogênio são contraindicados com tamoxifeno. Usar métodos não hormonais (preservativo, DIU de cobre) ou progestágeno isolado (desogestrel, DIU de levonorgestrel) com avaliação oncológica prévia."},
{"med1":["tamoxifeno","nolvadex","tamoxan"],"med2":["rifampicina","rifampin"],"nivel":"alto","titulo":"Tamoxifeno + Rifampicina (Redução do Metabólito Ativo por Indução de CYP3A4)","mecanismo":"O tamoxifeno é metabolizado pela CYP3A4 a N-desmetiltamoxifeno e, posteriormente, pela CYP2D6 ao endoxifeno (principal metabólito ativo). A rifampicina induz CYP3A4, desviando o metabolismo e reduzindo os níveis de endoxifeno, comprometendo a eficácia anticâncer.","efeito":"Redução significativa dos níveis de endoxifeno — metabólito 30–100 vezes mais ativo que o tamoxifeno — com potencial redução da eficácia do tratamento do câncer de mama.","conduta":"⚠️ Evitar rifampicina em pacientes em uso de tamoxifeno. Se tuberculose for diagnosticada, substituir rifampicina por rifabutina (indutor mais fraco) com monitoração clínica rigorosa da resposta ao tamoxifeno."},
{"med1":["oxicodona","oxycontin"],"med2":["diazepam","alprazolam","clonazepam","bromazepam","lorazepam","midazolam","zolpidem","zopiclona"],"nivel":"alto","titulo":"Oxicodona + Benzodiazepínico / Hipnótico (Depressão Respiratória Fatal)","mecanismo":"A oxicodona deprime o SNC e o drive respiratório via agonismo μ-opioide. Benzodiazepínicos e hipnóticos potencializam esse efeito por mecanismos GABAérgicos independentes. A combinação é sinérgica para depressão respiratória — responsável pela maioria das mortes por overdose de opioides nos EUA e em crescimento no Brasil.","efeito":"Depressão respiratória grave, apneia, sedação profunda e óbito — mesmo em doses individuais dentro do range terapêutico de cada fármaco. Risco especialmente elevado em pacientes sem tolerância prévia a opioides.","conduta":"🚫 Evitar a combinação sempre que possível. Se absolutamente necessária (ex.: dor oncológica grave + ansiedade), iniciar com as menores doses, monitorar SpO₂ e ter naloxona disponível. Orientar familiares sobre uso de naloxona intranasal em emergência."},
{"med1":["oxicodona","oxycontin"],"med2":["álcool","alcool","etanol","bebida alcoólica"],"nivel":"alto","titulo":"Oxicodona + Álcool (Overdose Fatal — Contraindicado)","mecanismo":"O álcool potencializa a depressão do SNC da oxicodona por mecanismos aditivos e sinérgicos. Adicionalmente, o álcool pode alterar a cinética de liberação de formulações de liberação prolongada (LP), aumentando os picos plasmáticos — fenômeno chamado \"dose dumping\" — com risco de overdose aguda.","efeito":"Depressão respiratória grave, sedação profunda, hipotensão e óbito. O \"dose dumping\" com formulas LP pode elevar os níveis de oxicodona em até 2-3x rapidamente.","conduta":"🚫 Álcool é absolutamente contraindicado com oxicodona. Orientar firmemente o paciente e familiares. Alertar que inclui cerveja, vinho e destilados — qualquer quantidade aumenta o risco."},
{"med1":["oxicodona","oxycontin"],"med2":["cetoconazol","ketoconazol","itraconazol","voriconazol","posaconazol","claritromicina","ritonavir"],"nivel":"moderado","titulo":"Oxicodona + Inibidor de CYP3A4 (Aumento dos Níveis — Risco de Toxicidade Opioide)","mecanismo":"A oxicodona é metabolizada principalmente pela CYP3A4 (N-desmetilação). Inibidores potentes desta via elevam os níveis de oxicodona em 50–170%, com risco de toxicidade opioide mesmo sem mudança de dose.","efeito":"Sedação excessiva, náuseas, constipação intensa, miose e, em casos graves, depressão respiratória. Pode mascarar progressão de doença oncológica por sedação excessiva.","conduta":"⚠️ Reduzir a dose de oxicodona ao iniciar inibidores potentes de CYP3A4. Monitorar sinais de toxicidade opioide. Ao suspender o inibidor, reverter gradualmente para a dose original para evitar abstinência abrupta."},
{"med1":["metildopa","aldomet"],"med2":["amitriptilina","imipramina","nortriptilina","clomipramina"],"nivel":"moderado","titulo":"Metildopa + Antidepressivo Tricíclico (Perda do Efeito Anti-hipertensivo)","mecanismo":"Os antidepressivos tricíclicos bloqueiam a recaptação de noradrenalina nos terminais adrenérgicos e, ao mesmo tempo, bloqueiam receptores α-adrenérgicos, antagonizando o mecanismo central de ação da metildopa (que depende de ativação de receptores α₂ para reduzir o tônus simpático).","efeito":"Redução ou perda do efeito anti-hipertensivo da metildopa — com possível elevação da pressão arterial. Risco especialmente importante em gestantes em uso de metildopa para hipertensão gestacional.","conduta":"⚠️ Evitar antidepressivos tricíclicos em pacientes em uso de metildopa. Se necessário tratar depressão, preferir ISRSs (sertralina é mais estudada na gestação) ou mirtazapina, avaliando o contexto clínico."},
{"med1":["metildopa","aldomet"],"med2":["haloperidol","haldol"],"nivel":"moderado","titulo":"Metildopa + Haloperidol (Toxicidade no SNC)","mecanismo":"A associação de metildopa (agonista α₂ central com efeito sedativo) e haloperidol (antagonista dopaminérgico com efeitos extrapiramidais) pode resultar em toxicidade aditiva no SNC. Casos de demência reversível, confusão mental e sintomas extrapiramidais foram relatados com a combinação.","efeito":"Confusão mental, sedação excessiva, irritabilidade, rigidez e sintomas extrapiramidais — podendo simular demência ou quadro psicótico agudo.","conduta":"⚠️ Monitorar sinais de toxicidade no SNC ao combinar metildopa e haloperidol. Se confusão mental ou rigidez aparecerem, suspender um dos fármacos e reavaliar. A combinação deve ser usada com cautela, especialmente em idosos."},
{"med1":["metildopa","aldomet"],"med2":["sulfato ferroso","ferro","fumarato ferroso","gluconato ferroso"],"nivel":"moderado","titulo":"Metildopa + Suplemento de Ferro (Quelação — Redução da Absorção)","mecanismo":"O ferro forma quelatos insolúveis com a metildopa no trato gastrointestinal, reduzindo sua absorção oral em 70–80%. O efeito ocorre independentemente da forma do ferro (sulfato, fumarato, gluconato).","efeito":"Redução significativa dos níveis plasmáticos de metildopa com perda do controle da pressão arterial — risco especialmente grave em gestantes com hipertensão tratada com metildopa e anemia ferropriva concomitante (situação clínica comum).","conduta":"⚠️ Separar a administração de metildopa e ferro por pelo menos 2 horas. Monitorar PA com maior atenção ao iniciar ou ajustar suplementação de ferro em pacientes em uso de metildopa."},
{"med1":["sirolimo","rapamune","rapamicina","everolimo","afinitor","certican"],"med2":["rifampicina","rifampin"],"nivel":"alto","titulo":"Sirolimo / Everolimo + Rifampicina (Indução Máxima de CYP3A4 — Perda do Efeito Imunossupressor)","mecanismo":"A rifampicina é o indutor mais potente de CYP3A4 e P-gp. Sirolimo e everolimo são substratos exclusivos dessa via — a co-administração reduz a AUC do sirolimo em mais de 80%, tornando os níveis imunossupressores completamente subterapêuticos.","efeito":"Perda do efeito imunossupressor com risco de rejeição aguda do enxerto transplantado. Em oncologia: perda da eficácia antitumoral.","conduta":"🚫 Contraindicado. A rifampicina é incompatível com sirolimo e everolimo. Para tuberculose em transplantado em uso dessas drogas, substituir rifampicina por rifabutina e aumentar drasticamente a dose do imunossupressor com monitoração sérica intensiva."},
{"med1":["sirolimo","rapamune","rapamicina","everolimo","afinitor","certican"],"med2":["ciclosporina","sandimmun","neoral"],"nivel":"moderado","titulo":"Sirolimo / Everolimo + Ciclosporina (Nefrotoxicidade Potencializada)","mecanismo":"A ciclosporina inibe a CYP3A4 e P-gp, elevando os níveis de sirolimo/everolimo. Adicionalmente, a combinação tem efeito nefrotóxico aditivo — a ciclosporina causa vasoconstrição da arteríola aferente e o sirolimo prejudica a recuperação após injúria renal.","efeito":"Nefrotoxicidade cumulativa — elevação de creatinina, proteinúria e risco de perda acelerada da função renal do enxerto com uso prolongado.","conduta":"⚠️ Quando usados juntos (protocolos de transplante), monitorar função renal e nível sérico de sirolimo/everolimo com frequência. Em muitos protocolos atuais, a ciclosporina é retirada após período inicial precisamente para reduzir nefrotoxicidade cumulativa."},
{"med1":["sirolimo","rapamune","rapamicina","everolimo","afinitor","certican"],"med2":["cetoconazol","ketoconazol","itraconazol","voriconazol","posaconazol","claritromicina","ritonavir"],"nivel":"alto","titulo":"Sirolimo / Everolimo + Inibidor Potente de CYP3A4 (Toxicidade por Acúmulo)","mecanismo":"Sirolimo e everolimo têm índice terapêutico estreito e são metabolizados exclusivamente pela CYP3A4. Inibidores potentes (antifúngicos azólicos, claritromicina, inibidores de protease) elevam a AUC em 4–11 vezes, causando toxicidade em múltiplos sistemas.","efeito":"Imunossupressão excessiva com risco aumentado de infecções oportunistas, pneumonite intersticial, estomatite grave, trombocitopenia, hiperlipidemia e nefrotoxicidade.","conduta":"⚠️ Reduzir dose de sirolimo/everolimo em 70–80% ao iniciar inibidor potente de CYP3A4. Monitorar nível sérico diariamente nas primeiras semanas. Ao suspender o inibidor, restaurar dose original gradualmente para evitar rejeição."},
{"med1":["flecainida","tambocor"],"med2":["fluoxetina","paroxetina"],"nivel":"moderado","titulo":"Flecainida + Fluoxetina / Paroxetina (Toxicidade por Inibição de CYP2D6)","mecanismo":"A flecainida é metabolizada principalmente pela CYP2D6. Fluoxetina e paroxetina são inibidores potentes dessa enzima — a co-administração pode elevar os níveis de flecainida em 50–300%, dependendo do fenótipo do paciente (metabolizadores lentos são mais vulneráveis).","efeito":"Toxicidade por flecainida: alargamento excessivo do QRS (>25% do basal), prolongamento do PR, bradicardia, efeito pró-arrítmico paradoxal e taquicardia ventricular. Pode precipitar flutter atrial com condução AV acelerada (risco de FA com resposta ventricular rápida).","conduta":"⚠️ Reduzir dose de flecainida ao iniciar fluoxetina ou paroxetina. Monitorar ECG (QRS, PR e frequência cardíaca). Preferir sertralina ou escitalopram como antidepressivo — menor inibição de CYP2D6."},
{"med1":["flecainida","tambocor"],"med2":["verapamil","diltiazem"],"nivel":"alto","titulo":"Flecainida + Verapamil / Diltiazem (Depressão Miocárdica Grave)","mecanismo":"A flecainida reduz a velocidade de condução intraventricular (bloqueio de canal de sódio) e tem efeito inotrópico negativo. Verapamil e diltiazem adicionam bloqueio de canal de cálcio com efeitos cronotrópico, dromotrópico e inotrópico negativos pronunciados. O efeito combinado é aditivo sobre a contratilidade e condução cardíaca.","efeito":"Depressão miocárdica grave — risco de bradicardia severa, bloqueio AV de alto grau, hipotensão significativa e insuficiência cardíaca aguda. Maior risco em pacientes com função sistólica já reduzida.","conduta":"🚫 Evitar a combinação em pacientes com disfunção sistólica. Se necessário para controle de frequência na FA, monitorar ECG e função cardíaca rigorosamente. Iniciar com doses mínimas e aumentar gradualmente."},
{"med1":["flecainida","tambocor"],"med2":["digoxina","lanoxin"],"nivel":"moderado","titulo":"Flecainida + Digoxina (Aumento dos Níveis de Digoxina)","mecanismo":"A flecainida pode elevar os níveis séricos de digoxina em 15–25% por redução da distribuição e depuração da digoxina, possivelmente via inibição de P-gp. Adicionalmente, ambos prolongam o intervalo PR — a combinação tem efeito aditivo na condução AV.","efeito":"Risco de toxicidade digitálica (náuseas, bradicardia, bloqueio AV) e alargamento do intervalo PR com potencial de bloqueio de condução AV.","conduta":"⚠️ Monitorar nível sérico de digoxina ao iniciar ou ajustar flecainida. Realizar ECG com atenção ao intervalo PR. Manter digoxinemia na metade inferior do range terapêutico (0,5–0,9 ng/mL)."},
{"med1":["quinidina","quinidex"],"med2":["warfarina","varfarina","acenocumarol","sintrom"],"nivel":"alto","titulo":"Quinidina + Anticoagulante Cumarínico (Aumento do INR por Múltiplos Mecanismos)","mecanismo":"A quinidina eleva o efeito anticoagulante da warfarina por dois mecanismos: (1) inibição de CYP2C9, reduzindo o metabolismo do S-warfarina (enantiômero mais ativo); (2) redução da síntese dos fatores de coagulação dependentes de vitamina K por mecanismo direto. O efeito combinado é superior ao de outros inibidores de CYP2C9 isolados.","efeito":"Elevação significativa do INR com risco de sangramento maior — equimoses espontâneas, epistaxe, hematúria, sangramento gastrointestinal e hemorragia intracraniana.","conduta":"⚠️ Monitorar INR com frequência dobrada ao iniciar ou suspender quinidina. Reduzir dose de warfarina preventivamente. Alertar o paciente sobre sinais de sangramento."},
{"med1":["quinidina","quinidex"],"med2":["metoprolol","propranolol","carvedilol","bisoprolol"],"nivel":"moderado","titulo":"Quinidina + Beta-bloqueador (Inibição de CYP2D6 — Bradicardia e Hipotensão)","mecanismo":"A quinidina é inibidor potente de CYP2D6, enzima responsável pelo metabolismo de metoprolol, propranolol e carvedilol. A co-administração eleva os níveis desses beta-bloqueadores em 2–5 vezes, potencializando seus efeitos cronotrópico e inotrópico negativos.","efeito":"Bradicardia sintomática, hipotensão e possível insuficiência cardíaca — especialmente em pacientes já com função sistólica reduzida. Risco de bloqueio AV.","conduta":"⚠️ Reduzir dose do beta-bloqueador ao iniciar quinidina. Monitorar FC e PA. Preferir atenolol (excretado por via renal, sem metabolismo por CYP2D6) se beta-bloqueador for necessário."},
{"med1":["procainamida","pronestyl"],"med2":["amiodarona","cordarone","ancoron"],"nivel":"alto","titulo":"Procainamida + Amiodarona (QT Prolongado Aditivo e Aumento dos Níveis de Procainamida)","mecanismo":"A amiodarona prolonga o intervalo QT e inibe CYP2D6 e P-gp, reduzindo a depuração da procainamida e do seu metabólito ativo NAPA. O acúmulo combinado de procainamida e NAPA agrava o prolongamento do QT de forma aditiva ao efeito da amiodarona.","efeito":"Prolongamento marcado do QTc com risco elevado de Torsades de Pointes e fibrilação ventricular. Toxicidade da procainamida: hipotensão, alargamento do QRS e lupus induzido.","conduta":"🚫 Evitar a combinação. Se necessário em arritmias refratárias (uso hospitalar), monitorar ECG contínuo, níveis séricos de procainamida e NAPA, e eletrólitos. Ter desfibrilador disponível."},
{"med1":["procainamida","pronestyl"],"med2":["cimetidina","tagamet"],"nivel":"moderado","titulo":"Procainamida + Cimetidina (Redução da Depuração Renal — Aumento dos Níveis)","mecanismo":"A cimetidina inibe a secreção tubular renal de cátions orgânicos, reduzindo a eliminação renal da procainamida e do NAPA. Os níveis de procainamida podem elevar-se em 30–50% com cimetidina, com risco de toxicidade.","efeito":"Acúmulo de procainamida e NAPA — prolongamento do QTc, alargamento do QRS, hipotensão e risco de Torsades de Pointes.","conduta":"⚠️ Monitorar níveis séricos de procainamida e NAPA ao usar cimetidina concomitantemente. Considerar substituir cimetidina por famotidina ou ranitidina (menor interação com secreção tubular de cátions) ou por um IBP."},
{"med1":["procainamida","pronestyl"],"med2":["quinidina","quinidex"],"nivel":"alto","titulo":"Procainamida + Quinidina (Prolongamento Aditivo do QT — Torsades de Pointes)","mecanismo":"Procainamida e quinidina são ambos antiarrítmicos classe IA com mecanismo de prolongamento do intervalo QT. A associação é aditiva para esse efeito — tornando o risco de Torsades de Pointes cumulativo e significativamente aumentado.","efeito":"QTc muito prolongado com risco de Torsades de Pointes, síncope e morte súbita. Ambos também têm efeito pró-arrítmico individual — o risco combinado é substancialmente maior.","conduta":"🚫 Contraindicado. Antiarrítmicos da mesma classe (IA) não devem ser combinados. Se refratariedade arrítmica, considerar amiodarona em monoterapia sob monitoração hospitalar."},
{"med1":["almotriptana","axert","almogran"],"med2":["ergotamina","di-hidroergotamina","ergot","cafergot"],"nivel":"alto","titulo":"Almotriptana + Ergotamina / Di-hidroergotamina (Vasoespasmo Coronariano e Cerebral)","mecanismo":"Almotriptana e derivados do ergot causam vasoconstrição via receptores 5-HT1B/1D e α-adrenérgicos, respectivamente. A combinação é sinérgica para vasoconstrição — com risco de espasmo de artérias coronarianas, cerebrais e periféricas.","efeito":"Vasoespasmo grave — dor torácica isquêmica, isquemia de extremidades e risco de AVC isquêmico. Casos de infarto agudo do miocárdio foram relatados com a combinação de triptanos e ergotamínicos.","conduta":"🚫 Contraindicado. Separar almotriptana de ergotamina/di-hidroergotamina por pelo menos 24 horas. Se a crise não ceder com o triptano, procurar serviço de urgência — não associar ergotamínico."},
{"med1":["almotriptana","axert","almogran"],"med2":["cetoconazol","ketoconazol","itraconazol","eritromicina"],"nivel":"moderado","titulo":"Almotriptana + Inibidor de CYP3A4 (Aumento dos Níveis)","mecanismo":"A almotriptana é parcialmente metabolizada pela CYP3A4 e MAO-A. Inibidores de CYP3A4 (cetoconazol, itraconazol) elevam a AUC da almotriptana em 60–80%, embora o intervalo terapêutico seja amplo e o risco seja menor que com eletriptana.","efeito":"Elevação dos níveis de almotriptana com possível aumento dos efeitos vasoconstritores (pressão torácica, parestesias) e do risco cardiovascular.","conduta":"⚠️ Reduzir a dose de almotriptana para 6,25mg (metade do comprimido padrão) ao usar inibidores potentes de CYP3A4. Não exceder 12,5mg em 24h nessa combinação."},
{"med1":["eletriptana","relpax"],"med2":["cetoconazol","ketoconazol","itraconazol","voriconazol","claritromicina","ritonavir","nelfinavir"],"nivel":"alto","titulo":"Eletriptana + Inibidor Potente de CYP3A4 (Aumento Drástico dos Níveis — Contraindicado)","mecanismo":"A eletriptana é metabolizada quase exclusivamente pela CYP3A4. Inibidores potentes (antifúngicos azólicos, claritromicina, inibidores de protease) elevam sua AUC em 3–6 vezes — muito mais que para outros triptanos — por sua alta dependência dessa via.","efeito":"Risco aumentado de vasoconstrição coronariana e cerebral, pressão torácica, parestesias e eventos isquêmicos com os níveis elevados de eletriptana.","conduta":"🚫 Contraindicado dentro de 72h do uso de inibidores potentes de CYP3A4. Usar almotriptana ou naratriptana (menor dependência de CYP3A4) como alternativa em pacientes em uso de antifúngicos azólicos ou inibidores de protease."},
{"med1":["eletriptana","relpax"],"med2":["ergotamina","di-hidroergotamina","ergot","cafergot"],"nivel":"alto","titulo":"Eletriptana + Ergotamina (Vasoespasmo — Contraindicado)","mecanismo":"Combinação sinérgica de vasoconstritores — eletriptana (agonista 5-HT1B/1D) e ergotamina (agonista α-adrenérgico e serotoninérgico) causam vasoconstrição aditiva de artérias coronarianas e cerebrais.","efeito":"Vasoespasmo grave com risco de isquemia miocárdica e cerebral. Casos de infarto do miocárdio foram relatados.","conduta":"🚫 Contraindicado. Separar por pelo menos 24 horas. Não usar ergotamina como resgate após falha do triptano."},
{"med1":["zolmitriptana","zomig"],"med2":["cimetidina","tagamet"],"nivel":"moderado","titulo":"Zolmitriptana + Cimetidina (Inibição de CYP1A2 — Duplicação dos Níveis)","mecanismo":"A zolmitriptana é metabolizada primariamente pela CYP1A2 ao metabólito ativo N-desmetilzolmitriptana. A cimetidina inibe a CYP1A2 e reduz a depuração tubular renal de cátions, elevando a AUC da zolmitriptana em 50–100%. É uma das interações mais específicas dos triptanos com anti-H2.","efeito":"Duplicação dos níveis de zolmitriptana e seu metabólito ativo — com aumento dos efeitos vasoconstritores, parestesias e risco cardiovascular.","conduta":"⚠️ Reduzir a dose de zolmitriptana para 2,5mg (dose máxima de 5mg/24h) ao usar cimetidina. Preferir famotidina ou omeprazol como alternativas para controle ácido — sem interação com CYP1A2."},
{"med1":["zolmitriptana","zomig"],"med2":["ergotamina","di-hidroergotamina","ergot","cafergot"],"nivel":"alto","titulo":"Zolmitriptana + Ergotamina (Vasoespasmo — Contraindicado)","mecanismo":"Combinação sinérgica de vasoconstritores. Zolmitriptana (agonista 5-HT1B/1D) e ergotamina/di-hidroergotamina causam vasoconstrição aditiva de artérias coronarianas, cerebrais e periféricas.","efeito":"Vasoespasmo grave com risco de isquemia coronariana e cerebral. Elevação da pressão arterial. Casos de infarto periférico foram relatados.","conduta":"🚫 Contraindicado. Separar por pelo menos 24 horas. Não combinar como estratégia de resgate na crise migranosa."},
{"med1":["letrozol","femara"],"med2":["tamoxifeno","tamoxifen","nolvadex"],"nivel":"grave","titulo":"Letrozol + Tamoxifeno (Antagonismo Farmacológico — Contraindicado)","mecanismo":"O letrozol inibe a aromatase, reduzindo os níveis de estrogênio circulante. O tamoxifeno é um modulador seletivo do receptor de estrogênio (SERM) cujo metabólito ativo (endoxifeno) compete com o estrogênio pelos receptores. Em uso simultâneo, o tamoxifeno upregula a aromatase e reduz os níveis de endoxifeno — antagonizando diretamente a ação do letrozol.","efeito":"Perda de eficácia antiestrogênica. Estudos clínicos (ATAC, BIG 1-98) demonstraram que a combinação simultânea não é superior à monoterapia e pode ser inferior ao letrozol isolado em câncer de mama hormônio-positivo.","conduta":"🚫 Contraindicado uso concomitante. Usar letrozol ou tamoxifeno isoladamente. A transição sequencial (ex: 2–3 anos de tamoxifeno → letrozol) é estratégia validada e diferente do uso simultâneo."},
{"med1":["letrozol","femara"],"med2":["warfarina","varfarina","coumadin"],"nivel":"moderado","titulo":"Letrozol + Warfarina (Potencialização do Efeito Anticoagulante)","mecanismo":"O letrozol inibe moderadamente CYP2A6 e pode inibir CYP2C9, enzima responsável pelo metabolismo da S-warfarina (isômero mais ativo). A inibição resulta em aumento da exposição à warfarina e potencialização do efeito anticoagulante.","efeito":"Aumento do RNI com risco aumentado de sangramento. Casos de hemorragia foram relatados em pós-comercialização.","conduta":"⚠️ Monitorar RNI mais frequentemente após início, ajuste de dose ou suspensão do letrozol. Ajustar dose de warfarina conforme necessário."},
{"med1":["agomelatina","valdoxan"],"med2":["fluvoxamina","luvox"],"nivel":"grave","titulo":"Agomelatina + Fluvoxamina (Inibição CYP1A2 — Contraindicado)","mecanismo":"A agomelatina é metabolizada quase exclusivamente pela CYP1A2 (>90%). A fluvoxamina é inibidora potente e seletiva da CYP1A2. A coadministração aumenta a exposição à agomelatina em até 60 vezes (AUC ×60), saturando completamente a via de eliminação.","efeito":"Toxicidade hepática grave. Hepatotoxicidade idiossincrática dose-dependente da agomelatina — risco elevado em níveis plasmáticos supraterapêuticos. Casos de hepatite fulminante descritos.","conduta":"🚫 Contraindicado. A combinação é explicitamente proibida na bula da agomelatina. Não coadministrar. Considerar alternativa antidepressiva sem interação CYP1A2."},
{"med1":["agomelatina","valdoxan"],"med2":["ciprofloxacino","cipro","ciprofloxacin"],"nivel":"grave","titulo":"Agomelatina + Ciprofloxacino (Inibição CYP1A2 — Contraindicado)","mecanismo":"O ciprofloxacino é inibidor moderado-forte da CYP1A2. Como a agomelatina é eliminada quase que exclusivamente por essa via, a inibição eleva de forma substancial a exposição sistêmica ao antidepressivo.","efeito":"Aumento significativo dos níveis plasmáticos de agomelatina com risco de hepatotoxicidade e efeitos adversos dose-dependentes (tontura, náusea, elevação de transaminases).","conduta":"🚫 Contraindicado conforme bula. Evitar a combinação. Se antibioticoterapia for necessária, substituir por outro antibiótico que não iniba CYP1A2 (ex: amoxicilina, azitromicina)."},
{"med1":["agomelatina","valdoxan"],"med2":["tabaco","cigarro","fumo","nicotina"],"nivel":"moderado","titulo":"Agomelatina + Tabaco (Indução CYP1A2 — Redução de Eficácia)","mecanismo":"Hidrocarbonetos policíclicos aromáticos da fumaça do cigarro são indutores potentes da CYP1A2. Fumantes podem ter exposição à agomelatina reduzida em 50–80% comparado a não-fumantes.","efeito":"Redução significativa da eficácia antidepressiva. Pacientes fumantes podem não atingir concentrações plasmáticas terapêuticas com doses padrão.","conduta":"⚠️ Informar o paciente fumante sobre a redução de eficácia. Avaliar resposta clínica cuidadosamente. A cessação do tabagismo durante o tratamento pode elevar abruptamente os níveis de agomelatina — remonitorar após cessação."},
{"med1":["atomoxetina","atomoxetine","strattera","cloridrato de atomoxetina"],"med2":["inibidor mao","imao","fenelzina","tranilcipromina","selegilina","moclobemida","isocarboxazida"],"nivel":"grave","titulo":"Atomoxetina + IMAOs (Crise Hipertensiva / Risco Fatal — Contraindicado)","mecanismo":"A atomoxetina inibe o transportador de norepinefrina (NET), elevando norepinefrina na fenda sináptica. Os IMAOs bloqueiam a degradação de catecolaminas. A combinação resulta em acúmulo maciço de norepinefrina e dopamina — causando crise adrenérgica grave.","efeito":"Crise hipertensiva grave, hipertermia, colapso cardiovascular. Potencialmente fatal. Situação de emergência médica.","conduta":"🚫 Contraindicado. Intervalo mínimo de 14 dias após suspensão do IMAO antes de iniciar atomoxetina (e vice-versa). Monitorar pressão arterial e pulso ao iniciar terapia."},
{"med1":["atomoxetina","atomoxetine","strattera","cloridrato de atomoxetina"],"med2":["fluoxetina","paroxetina","prozac","paxil"],"nivel":"moderado","titulo":"Atomoxetina + Fluoxetina/Paroxetina (Inibição CYP2D6 — Toxicidade)","mecanismo":"A atomoxetina é extensamente metabolizada pela CYP2D6. Fluoxetina e paroxetina são inibidores potentes desta isoenzima. A inibição aumenta a AUC da atomoxetina em 6–10 vezes em metabolizadores extensos — convertendo-os funcionalmente em metabolizadores lentos.","efeito":"Taquicardia, elevação pressórica, insônia, boca seca, diminuição do apetite e irritabilidade intensificados. Risco de síndrome serotoninérgica leve. Prolongamento de QTc relatado em doses elevadas.","conduta":"⚠️ Se combinação necessária, iniciar atomoxetina com dose mínima (0,5 mg/kg/dia) e titular lentamente. Monitorar ECG, PA e frequência cardíaca. Considerar alternativa ao ISRS que não iniba CYP2D6 (sertralina, escitalopram afetam menos)."},
{"med1":["canabidiol","cbd","cannabidiol","canabidiol / tetrahidrocanabinol","thc"],"med2":["warfarina","varfarina","coumadin"],"nivel":"grave","titulo":"Canabidiol (CBD) + Warfarina (Inibição CYP2C9 — Aumento Crítico do RNI)","mecanismo":"O CBD inibe potentemente CYP2C9 e CYP2C19. A S-warfarina, isômero farmacologicamente ativo, é substrato de CYP2C9. A inibição reduz o clearance da warfarina, elevando significativamente seus níveis plasmáticos e o efeito anticoagulante.","efeito":"Elevação pronunciada do RNI com risco grave de hemorragia. Casos de sangramento grave (incluindo intracraniano) relatados em uso concomitante. O efeito pode ser agudo e imprevisível.","conduta":"🚫 Evitar combinação. Se uso de CBD for imprescindível, monitorar RNI em 2–3 dias após início e a cada mudança de dose. Redução empírica da dose de warfarina pode ser necessária. Orientar paciente para sinais de sangramento (hematomas, fezes escuras, sangramento urinário)."},
{"med1":["canabidiol","cbd","cannabidiol","canabidiol / tetrahidrocanabinol"],"med2":["clobazam","frisium","onfi"],"nivel":"moderado","titulo":"Canabidiol (CBD) + Clobazam (Inibição CYP2C19 — Acúmulo do Metabólito Ativo)","mecanismo":"O CBD inibe CYP2C19, responsável pela conversão de clobazam em N-desmetilclobazam (metabólito ativo e também sedativo). A inibição não elimina o metabólito mas pode alterar o perfil de exposição global ao clobazam e seus produtos. Estudos clínicos (Dravet, LGS) demonstraram interação significativa.","efeito":"Sedação excessiva, ataxia, irritabilidade paradoxal e — com menos frequência — depressão respiratória. O efeito foi documentado em estudos do Epidiolex® em combinação com clobazam.","conduta":"⚠️ Reduzir dose de clobazam em 25–50% ao iniciar CBD. Monitorar sedação e nível de alerta. Esta combinação é frequentemente usada clinicamente em epilepsias refratárias — ajuste cuidadoso de dose é o padrão."},
{"med1":["canabidiol","cbd","cannabidiol","canabidiol / tetrahidrocanabinol"],"med2":["tacrolimo","prograf","ciclosporina","sandimmun","sirolimo","rapamune","everolimo"],"nivel":"moderado","titulo":"Canabidiol (CBD) + Imunossupressores (CYP3A4/CYP2C9 — Aumento de Toxicidade)","mecanismo":"O CBD inibe CYP3A4 e CYP2C9. Tacrolimo, ciclosporina, sirolimo e everolimo são substratos de CYP3A4 com janela terapêutica estreita. A inibição reduz o metabolismo destes fármacos, elevando seus níveis plasmáticos.","efeito":"Nefrotoxicidade, neurotoxicidade e imunossupressão excessiva. Em transplantados, elevação do nível de tacrolimo pode precipitar rejeição paradoxal (por toxicidade que exige dose redução) ou infecção oportunista grave.","conduta":"⚠️ Monitorar níveis séricos dos imunossupressores com mais frequência ao iniciar, ajustar ou suspender CBD. Ajustar doses conforme necessário. Comunicar ao especialista responsável pelo transplante."},
{"med1":["lurasidona","cloridrato de lurasidona","latuda"],"med2":["cetoconazol","ketoconazol","itraconazol","voriconazol","posaconazol","ritonavir","claritromicina"],"nivel":"grave","titulo":"Lurasidona + Inibidores Fortes CYP3A4 (Contraindicado)","mecanismo":"A lurasidona é metabolizada quase exclusivamente pela CYP3A4. Inibidores potentes desta isoenzima (azólicos, ritonavir, claritromicina) elevam a AUC da lurasidona em 9–13 vezes — atingindo concentrações associadas a toxicidade grave.","efeito":"Sedação profunda, hipotensão ortostática grave, prolongamento de QTc com risco de arritmias ventriculares (torsades de pointes). Síndrome neuroléptica maligna em doses tóxicas.","conduta":"🚫 Contraindicado conforme bula. Substituir o inibidor CYP3A4 por alternativa que não iniba a via (ex: fluconazol dose única tópica, azitromicina no lugar de claritromicina). Se indispensável, suspender temporariamente a lurasidona."},
{"med1":["lurasidona","cloridrato de lurasidona","latuda"],"med2":["rifampicina","rifampin","carbamazepina","fenitoína","fenobarbital"],"nivel":"grave","titulo":"Lurasidona + Indutores Fortes CYP3A4 (Contraindicado)","mecanismo":"A indução de CYP3A4 por rifampicina, carbamazepina ou fenitoína reduz a AUC da lurasidona em até 85% — eliminando virtualmente a exposição terapêutica.","efeito":"Falha terapêutica. Recaída psicótica ou de episódio maníaco/depressivo bipolar. Risco de hospitalização.","conduta":"🚫 Contraindicado conforme bula. Substituir o indutor por alternativa sem efeito indutor relevante (ex: levetiracetam, lamotrigina no lugar de carbamazepina; levofloxacino no lugar de rifampicina, quando possível clinicamente)."},
{"med1":["lurasidona","cloridrato de lurasidona","latuda"],"med2":["grapefruit","toranja","suco de toranja"],"nivel":"moderado","titulo":"Lurasidona + Grapefruit (Inibição Intestinal CYP3A4)","mecanismo":"Furanocumarinas do grapefruit inibem irreversivelmente CYP3A4 intestinal, aumentando a biodisponibilidade oral da lurasidona de forma imprevisível.","efeito":"Aumento variável (20–100%) da exposição à lurasidona — sedação, hipotensão, prolongamento de QTc.","conduta":"⚠️ Evitar grapefruit e seu suco durante uso de lurasidona. Orientar claramente o paciente sobre esta restrição alimentar."},
{"med1":["sibutramina","sibutramine","meridia"],"med2":["inibidor mao","imao","fenelzina","tranilcipromina","selegilina","moclobemida","isocarboxazida"],"nivel":"grave","titulo":"Sibutramina + IMAOs (Síndrome Serotoninérgica Grave — Contraindicado)","mecanismo":"A sibutramina inibe a recaptação de serotonina, norepinefrina e dopamina. Os IMAOs bloqueiam a degradação destas monoaminas. A combinação resulta em acúmulo maciço de serotonina — precipitando síndrome serotoninérgica grave.","efeito":"Síndrome serotoninérgica: hipertermia, rigidez, mioclonias, agitação, confusão, instabilidade autonômica (taquicardia, hipertensão, diaforese). Pode ser fatal.","conduta":"🚫 Contraindicado. Intervalo mínimo de 14 dias entre suspensão do IMAO e início da sibutramina (e vice-versa). Em caso de síndrome serotoninérgica: suspender todos os agentes serotoninérgicos, suporte clínico e considerar ciproeptadina."},
{"med1":["sibutramina","sibutramine","meridia"],"med2":["fluoxetina","paroxetina","sertralina","citalopram","escitalopram","venlafaxina","duloxetina","triptano","sumatriptana","zolmitriptana","eletriptana"],"nivel":"grave","titulo":"Sibutramina + ISRSs/SNRIs/Triptanos (Síndrome Serotoninérgica)","mecanismo":"Efeito serotoninérgico aditivo. A sibutramina inibe recaptação de serotonina; ISRSs e SNRIs idem; triptanos são agonistas serotoninérgicos. A sobreposição de mecanismos eleva sinapticamente a serotonina a níveis tóxicos.","efeito":"Síndrome serotoninérgica: agitação, tremores, mioclonias, hipertermia, taquicardia, diarreia. Casos graves com rabdomiólise e insuficiência renal.","conduta":"🚫 Contraindicado. A sibutramina não deve ser associada a nenhum agente serotoninérgico. Monitorar pacientes que iniciam sibutramina para sinais precoces de toxicidade serotoninérgica."},
{"med1":["buspirona","buspirone","cloridrato de buspirona","buspar"],"med2":["inibidor mao","imao","fenelzina","tranilcipromina","selegilina","moclobemida","isocarboxazida"],"nivel":"grave","titulo":"Buspirona + IMAOs (Hipertensão Grave — Contraindicado)","mecanismo":"A buspirona tem efeito agonista parcial em receptores dopaminérgicos D2 e serotoninérgicos 5-HT1A, além de inibir fraca e indiretamente a recaptação de monoaminas. Os IMAOs amplificam este efeito ao bloquear a degradação de dopamina, serotonina e norepinefrina.","efeito":"Hipertensão grave, agitação, síndrome serotoninérgica. Casos de crise hipertensiva com risco de AVC hemorrágico descritos.","conduta":"🚫 Contraindicado. Intervalo mínimo de 14 dias entre suspensão do IMAO e início da buspirona. Em substituição de IMAO por buspirona, o washout é obrigatório."},
{"med1":["buspirona","buspirone","cloridrato de buspirona","buspar"],"med2":["fluconazol","itraconazol","cetoconazol","ketoconazol","eritromicina","diltiazem","verapamil"],"nivel":"moderado","titulo":"Buspirona + Inibidores CYP3A4 (Aumento da Exposição)","mecanismo":"A buspirona é extensamente metabolizada por CYP3A4 (first-pass hepático e intestinal pronunciado). Inibidores desta isoenzima reduzem seu clearance, elevando a AUC em 4–13 vezes dependendo do inibidor.","efeito":"Sedação excessiva, tontura, náuseas. Com diltiazem/verapamil: bradicardia e hipotensão adicionais. Risco aumentado de disfunção psicomotora.","conduta":"⚠️ Reduzir dose de buspirona ao iniciar inibidores CYP3A4. Com fluconazol e itraconazol: considerar dose mínima efetiva (5 mg 2×/dia). Monitorar sedação e pressão arterial. O grapefruit também inibe CYP3A4 intestinal — orientar evitar."},
{"med1":["clobazam","frisium","onfi"],"med2":["omeprazol","esomeprazol","lansoprazol","pantoprazol","fluconazol","fluvoxamina"],"nivel":"moderado","titulo":"Clobazam + Inibidores CYP2C19 (Acúmulo de N-Desmetilclobazam)","mecanismo":"O clobazam é convertido a N-desmetilclobazam (N-CLB) pelo CYP3A4, e o N-CLB é eliminado por CYP2C19. Inibidores de CYP2C19 (omeprazol, esomeprazol, fluconazol, fluvoxamina) reduzem o clearance do N-CLB, que é também farmacologicamente ativo e contribui para sedação e toxicidade.","efeito":"Sedação excessiva, ataxia, confusão mental, depressão respiratória em casos graves. O acúmulo de N-CLB pode ser mais pronunciado que o do próprio clobazam.","conduta":"⚠️ Monitorar sedação e função neurológica. Se possível, substituir omeprazol por pantoprazol (menor inibição de CYP2C19). Com fluconazol: preferir alternativa antifúngica. Ajustar dose de clobazam se efeitos adversos persistirem."},
{"med1":["etossuximida","ethosuximide","zarontin"],"med2":["ácido valproico","valproato","divalproato","depakote","valproate"],"nivel":"moderado","titulo":"Etossuximida + Ácido Valproico (Inibição Metabólica — Toxicidade)","mecanismo":"O ácido valproico inibe o metabolismo hepático da etossuximida (via CYP3A4 e possivelmente glucuronidação), elevando seus níveis plasmáticos. A interação é bidirecional: em alguns pacientes, a etossuximida também altera os níveis de valproato.","efeito":"Elevação dos níveis de etossuximida com risco de toxicidade: náuseas, vômitos, sedação, ataxia, psicose tóxica. Raramente perda de controle de crises por paradoxo dose-toxicidade.","conduta":"⚠️ Monitorar níveis séricos de ambos os fármacos após início ou ajuste. Titular etossuximida cuidadosamente. A combinação é clinicamente usada em epilepsias de ausência refratárias — o benefício pode superar o risco com monitoramento adequado."},
{"med1":["etossuximida","ethosuximide","zarontin"],"med2":["rifampicina","rifampin","carbamazepina","fenitoína","fenobarbital"],"nivel":"moderado","titulo":"Etossuximida + Indutores Enzimáticos (Redução de Nível — Falha Terapêutica)","mecanismo":"Rifampicina, carbamazepina, fenitoína e fenobarbital são potentes indutores de CYP3A4. A etossuximida é substrato desta isoenzima. A indução acelera seu metabolismo, reduzindo a concentração plasmática em 30–50%.","efeito":"Perda de controle das crises de ausência — potencialmente levando a estado de mal de ausência (petit mal status). Risco de deterioração neurológica aguda.","conduta":"⚠️ Monitorar nível sérico de etossuximida após introdução de indutor. Aumentar dose conforme necessário. Se possível, substituir antiepiléptico indutor por não-indutor (ex: levetiracetam). Ajuste inverso ao suspender o indutor."},
{"med1":["perampanel","fycompa"],"med2":["levonorgestrel","desogestrel","etonogestrel","anticoncepcional oral","contraceptivo oral","etinilestradiol"],"nivel":"moderado","titulo":"Perampanel + Contraceptivos Orais (Indução CYP3A4 — Falha Contraceptiva)","mecanismo":"Em doses ≥12 mg/dia, o perampanel induz CYP3A4 de forma clinicamente significativa, acelerando o metabolismo de progestinas (levonorgestrel, desogestrel, etonogestrel) — reduzindo sua biodisponibilidade e eficácia contraceptiva.","efeito":"Falha contraceptiva com risco de gestação não planejada. Em doses menores (≤8 mg/dia), o efeito indutor é mínimo e menos preocupante.","conduta":"⚠️ Em doses de perampanel ≥12 mg/dia: usar método contraceptivo não hormonal ou com estrogênio (COC com etinilestradiol ≥30 mcg), ou barreira adicional. Informar a paciente sobre o risco. Planejar contracepção antes de escalar a dose."},
{"med1":["perampanel","fycompa"],"med2":["rifampicina","rifampin","carbamazepina","oxcarbazepina","fenitoína","fenobarbital"],"nivel":"moderado","titulo":"Perampanel + Indutores CYP3A4 (Redução de Nível — Ajuste de Dose)","mecanismo":"Indutores fortes de CYP3A4 (rifampicina, carbamazepina, fenitoína, fenobarbital) reduzem a meia-vida do perampanel de ~105 horas para ~25 horas e diminuem sua AUC em até 50–67%.","efeito":"Redução da eficácia antiepiléptica. Risco de recorrência de crises em pacientes previamente controlados.","conduta":"⚠️ Em pacientes usando indutores, o perampanel geralmente requer doses maiores (dobrar a dose usual, até máximo de 12 mg/dia). Monitorar resposta clínica. Ao suspender o indutor, reduzir dose de perampanel para evitar toxicidade."},
{"med1":["lacosamida","vimpat"],"med2":["betabloqueador","atenolol","bisoprolol","metoprolol","carvedilol","propranolol","verapamil","diltiazem","digoxina","amiodarona","dronedarona","sotalol"],"nivel":"moderado","titulo":"Lacosamida + Fármacos que Prolongam Intervalo PR (Bradicardia / BAV)","mecanismo":"A lacosamida bloqueia canais de sódio voltagem-dependentes com inativação lenta, afetando a condução do nó AV. A combinação com outros fármacos que prolongam o intervalo PR (betabloqueadores, antagonistas de cálcio não-diidropiridínicos, digoxina, antiarrítmicos) produz efeito aditivo.","efeito":"Bradicardia sinusal, bloqueio atrioventricular de 1.º ou 2.º grau, prolongamento de PR. Risco de síncope e parada cardíaca em pacientes com cardiopatia subjacente.","conduta":"⚠️ Realizar ECG antes e após início da lacosamida em pacientes em uso de tais medicamentos. Titular lacosamida lentamente. Em pacientes com BAV pré-existente ou doença do nó sinusal, a lacosamida é de uso cauteloso — avaliar implante de marca-passo se necessário antes de iniciar."},
{"med1":["zonisamida","zonegran"],"med2":["topiramato","topamax"],"nivel":"moderado","titulo":"Zonisamida + Topiramato (Inibição Dupla da Anidrase Carbônica — Nefrolitíase)","mecanismo":"Ambos inibem a anidrase carbônica renal. O efeito combinado alcaliniza a urina e reduz a excreção urinária de citrato, criando condições que favorecem a precipitação de cristais de fosfato de cálcio e a formação de cálculos renais.","efeito":"Risco 2–3 vezes maior de nefrolitíase. Oligoidrose (redução da sudorese) com risco de hipertermia — especialmente em crianças. Acidose metabólica hiperclorêmica aditiva.","conduta":"⚠️ Manter hidratação adequada (≥2 litros/dia). Monitorar pH urinário e eletrólitos periodicamente. Considerar citrato de potássio como profilaxia de cálculos. Alertar sobre risco de hipertermia em climas quentes. Evitar a combinação em pacientes com histórico de litíase renal."},
{"med1":["zonisamida","zonegran"],"med2":["rifampicina","rifampin","carbamazepina","fenitoína","fenobarbital"],"nivel":"moderado","titulo":"Zonisamida + Indutores CYP3A4 (Redução de Meia-Vida — Ajuste de Dose)","mecanismo":"Indutores de CYP3A4 reduzem a meia-vida da zonisamida de ~63 horas para ~27 horas (carbamazepina) ou ~38 horas (fenitoína), diminuindo significativamente a exposição ao fármaco.","efeito":"Redução dos níveis plasmáticos de zonisamida e perda de controle epiléptico. Risco de recorrência de crises.","conduta":"⚠️ Doses de zonisamida tipicamente são 33–50% maiores quando em coadministração com indutores. Monitorar resposta clínica e nível sérico quando disponível. Ajustar dose em ambas as direções ao iniciar ou suspender o indutor."},
{"med1":["roflumilaste","daxas","daliresp"],"med2":["rifampicina","rifampin"],"nivel":"grave","titulo":"Roflumilaste + Rifampicina (Indução CYP — Contraindicado)","mecanismo":"A rifampicina é indutora potente de CYP3A4 e CYP1A2 — as principais enzimas de metabolização do roflumilaste. A indução reduz a AUC total do roflumilaste e seu metabólito ativo (roflumilaste N-óxido) em ~80%, eliminando efetivamente a atividade farmacológica.","efeito":"Perda completa da eficácia em DPOC. Risco de exacerbação grave. A alternativa para tuberculose concomitante exige consulta com especialistas.","conduta":"🚫 Contraindicado conforme bula. Roflumilaste não deve ser usado durante tratamento antituberculoso com rifampicina. Avaliar caso a caso com pneumologista e infectologista."},
{"med1":["roflumilaste","daxas","daliresp"],"med2":["teofilina","aminofilina"],"nivel":"moderado","titulo":"Roflumilaste + Teofilina (Sinergia PDE — Aumento de Efeitos Adversos)","mecanismo":"Roflumilaste inibe seletivamente PDE4; a teofilina inibe PDE de forma não-seletiva (incluindo PDE4). A inibição cumulativa de PDE4 resulta em efeito farmacológico aditivo, sem proporcionar benefício adicional sobre a broncodilatação, mas amplificando efeitos adversos.","efeito":"Náuseas, vômitos, diarreia, insônia e perda de peso intensificados. Risco de arritmias e convulsões com teofilina em níveis elevados.","conduta":"⚠️ Evitar uso combinado quando possível. Se necessário, manter teofilina em doses mínimas e monitorar níveis séricos. Preferir broncodilatadores de ação longa (LABA, LAMA) como alternativa à teofilina."},
{"med1":["roflumilaste","daxas","daliresp"],"med2":["fluconazol","cetoconazol","ketoconazol","enoxacino","cimetidina"],"nivel":"moderado","titulo":"Roflumilaste + Inibidores CYP3A4/CYP1A2 (Aumento de Exposição)","mecanismo":"Roflumilaste é substrato de CYP3A4 e CYP1A2. Inibidores destas isoenzimas (fluconazol, cetoconazol, enoxacino, cimetidina) aumentam a AUC total do roflumilaste em 50–90%.","efeito":"Amplificação de efeitos adversos dose-dependentes: náuseas, diarreia, cefaleia, insônia, perda de peso. Risco de descontinuação por intolerância.","conduta":"⚠️ Usar com cautela. Monitorar tolerabilidade. Com inibidores potentes (cetoconazol, fluconazol), considerar alternativa terapêutica. Informar paciente sobre possível piora de efeitos adversos gastrointestinais."},
{"med1":["baricitinibe","olumiant","tofacitinibe","xeljanz","citrato de tofacitinibe"],"med2":["vacina viva","vacina de vírus vivo","vacina febre amarela","vacina varicela","vacina rotavírus","vacina sarampo","bcg"],"nivel":"grave","titulo":"Inibidores JAK (Baricitinibe/Tofacitinibe) + Vacinas Vivas (Contraindicado)","mecanismo":"Inibidores da via JAK-STAT suprimem a sinalização de interleucinas e interferons essenciais para a resposta imune. A imunossupressão resultante impede a geração de resposta protetora adequada a vacinas vivas e, criticamente, pode permitir que o vírus vacinal cause doença disseminada.","efeito":"Infecção disseminada pelo vírus vacinal (varicela disseminada, sarampo vacinal, etc.). Risco de tuberculose reativada com BCG. Óbito descrito com febre amarela em imunossuprimidos.","conduta":"🚫 Contraindicado. Todas as vacinas vivas devem ser administradas ≥4 semanas antes do início do inibidor JAK. Vacinas inativadas (influenza, pneumocócica, herpes zoster recombinante Shingrix®) são seguras e recomendadas. Atualizar calendário vacinal antes de iniciar tratamento."},
{"med1":["baricitinibe","olumiant","tofacitinibe","xeljanz","citrato de tofacitinibe"],"med2":["adalimumabe","infliximabe","etanercepte","abatacepte","tocilizumabe","rituximabe","anti-tnf","biologico"],"nivel":"grave","titulo":"Inibidores JAK + Biológicos Imunossupressores (Imunossupressão Excessiva)","mecanismo":"A combinação de dois ou mais imunossupressores de mecanismos diferentes (JAK + anti-TNF, JAK + abatacepte, etc.) resulta em supressão sinérgica das defesas imunológicas, sem benefício aditivo demonstrado em indicações aprovadas.","efeito":"Infecções graves e oportunistas: pneumonia por Pneumocystis jirovecii, tuberculose, infecções fúngicas invasivas, sepse. Risco aumentado de neoplasias hematológicas.","conduta":"🚫 Contraindicado. Inibidores JAK não devem ser associados a biológicos imunossupressores. Monoterapia ou combinação com DMARDs convencionais (metotrexato, hidroxicloroquina) é o padrão seguro."},
{"med1":["anfotericina b","anfotericina","amphotericin","fungizone","abelcet","ambisome"],"med2":["aminoglicosídeo","amicacina","gentamicina","tobramicina","estreptomicina","vancomicina"],"nivel":"grave","titulo":"Anfotericina B + Aminoglicosídeos/Vancomicina (Nefrotoxicidade Sinérgica)","mecanismo":"A anfotericina B liga-se ao ergosterol da membrana fúngica mas também à membrana do epitélio tubular renal — causando aumento de permeabilidade, perda de potássio e magnésio e redução da TFG. Aminoglicosídeos causam lesão tubular proximal por acumulação lisossômica. Os mecanismos somam-se de forma sinérgica, não apenas aditiva.","efeito":"Lesão renal aguda grave, frequentemente requerendo diálise. Hipocalemia e hipomagnesemia profundas que predispõem a arritmias. Em pacientes de UTI, a combinação pode ser fatal.","conduta":"⚠️ Evitar combinação quando possível. Se necessário: hidratação IV vigorosa (500 mL SF 0,9% antes de cada dose de anfotericina), monitorar creatinina, eletrólitos e débito urinário diariamente. Preferir formulações lipídicas (AmBisome®) — menor nefrotoxicidade. Espaçar doses de aminoglicosídeo (dose única diária)."},
{"med1":["anfotericina b","anfotericina","amphotericin","fungizone","abelcet","ambisome"],"med2":["ciclosporina","sandimmun","ciclosporin"],"nivel":"grave","titulo":"Anfotericina B + Ciclosporina (Nefrotoxicidade Grave)","mecanismo":"Mecanismos nefrotóxicos independentes e aditivos: anfotericina B causa vasoconstricção aferente renal e lesão tubular direta; a ciclosporina causa vasoconstricção aferente via tromboxano A2 e endotelina, além de fibrose intersticial crônica.","efeito":"IRA grave, frequentemente irreversível em transplantados. Risco elevado de perda do enxerto renal.","conduta":"⚠️ Usar apenas quando não houver alternativa. Preferir formulação lipídica de anfotericina. Monitorar função renal diariamente. Reduzir dose de ciclosporina e manter seus níveis no menor intervalo terapêutico possível durante o curso de anfotericina."},
{"med1":["anfotericina b","anfotericina","amphotericin","fungizone","abelcet","ambisome"],"med2":["digoxina","digitoxina"],"nivel":"moderado","titulo":"Anfotericina B + Digoxina (Hipocalemia → Toxicidade Digitálica)","mecanismo":"A anfotericina B causa perda renal e tubular de potássio e magnésio. A hipocalemia resultante sensibiliza o miocárdio aos efeitos tóxicos da digoxina — o mesmo nível sérico de digoxina torna-se tóxico em contexto de hipocalemia.","efeito":"Arritmias digitálicas (extrassístoles ventriculares, bigeminismo, bloqueios, taquicardia ventricular) mesmo com níveis séricos de digoxina \"terapêuticos\".","conduta":"⚠️ Monitorar potássio sérico e ECG diariamente durante coadministração. Repor potássio e magnésio agressivamente. Considerar suspensão temporária da digoxina ou redução de dose. Verificar nível sérico de digoxina antes de qualquer ajuste."},
{"med1":["ganciclovir","cytovene","cymevene"],"med2":["zidovudina","azt","retrovir"],"nivel":"grave","titulo":"Ganciclovir + Zidovudina (Mielossupressão Grave — Geralmente Contraindicado)","mecanismo":"Ambos os fármacos suprimem a medula óssea por mecanismos independentes: ganciclovir por toxicidade direta ao progenitor hematopoiético; zidovudina por inibição da DNA polimerase mitocondrial, causando disfunção dos precursores mieloides. Os efeitos são sinérgicos.","efeito":"Neutropenia grave (CAN <500/mm³) com risco elevado de infecções bacterianas e fúngicas oportunistas. Anemia e trombocitopenia. A necessidade de G-CSF é frequente.","conduta":"⚠️ Evitar combinação sempre que possível. Se indispensável (CMV sistêmico em paciente com AIDS): monitorar hemograma 2×/semana. Considerar G-CSF profilático. Substituir zidovudina por tenofovir ou abacavir quando clinicamente viável."},
{"med1":["ganciclovir","cytovene","cymevene"],"med2":["mofetila de micofenolato","micofenolato","cellcept","myfortic"],"nivel":"moderado","titulo":"Ganciclovir + Micofenolato de Mofetila (Mielossupressão e Competição Tubular)","mecanismo":"Ambos competem pela secreção tubular renal via transportadores OAT1/OAT3, resultando em aumento mútuo dos níveis plasmáticos. Adicionalmente, a combinação amplifica a supressão medular de forma aditiva.","efeito":"Leucopenia significativa. Risco aumentado de infecção oportunista em transplantados. Elevação dos níveis de ambos os fármacos por competição tubular.","conduta":"⚠️ Monitorar hemograma semanalmente durante uso conjunto. Considerar redução de dose de micofenolato (guiada por nível de MPAG, se disponível). Em episódios de neutropenia grave, G-CSF pode ser necessário."},
{"med1":["pirazinamida","pyrazinamide"],"med2":["alopurinol","probenecida","benzbromaron"],"nivel":"moderado","titulo":"Pirazinamida + Agentes Uricosúricos/Antigotosos (Antagonismo — Ineficácia)","mecanismo":"A pirazinamida e seu metabólito ácido pirazinoico inibem a excreção tubular renal de ácido úrico (transportador URAT1), causando hiperuricemia significativa (em até 40–50% dos pacientes em esquemas com pirazinamida). O alopurinol e agentes uricosúricos não conseguem reverter adequadamente essa hiperuricemia induzida por fármaco.","efeito":"Hiperuricemia persistente com risco de crises gotosas agudas durante o esquema antituberculoso. O alopurinol tem eficácia drasticamente reduzida neste contexto.","conduta":"⚠️ Informar o paciente sobre risco de gota durante tratamento da TB. Hidratação adequada. Anti-inflamatórios (colchicina, AINE) para crise aguda são mais eficazes que alopurinol neste contexto. Avaliar suspensão da pirazinamida após 2 meses (fase de ataque) quando possível — a hiperuricemia costuma reverter após este período."},
{"med1":["ribavirina","copegus","rebetol"],"med2":["didanosina","ddi","videx"],"nivel":"grave","titulo":"Ribavirina + Didanosina (Toxicidade Mitocondrial Grave — Contraindicado)","mecanismo":"A ribavirina inibe a inosina monofosfato desidrogenase (IMPDH), aumentando intracelularmente a concentração do trifosfato de didanosina (ddATP). Este acúmulo inibe a DNA polimerase mitocondrial (Pol-γ), causando disfunção mitocondrial grave.","efeito":"Acidose láctica, pancreatite aguda, neuropatia periférica e hepatotoxicidade grave. Casos fatais descritos. Descontinuado em ensaios clínicos por toxicidade inaceitável.","conduta":"🚫 Contraindicado. Substituir didanosina por tenofovir ou abacavir em pacientes que necessitam de ribavirina para tratamento de hepatite C ou outras indicações."},
{"med1":["ribavirina","copegus","rebetol"],"med2":["azatioprina","imuran"],"nivel":"grave","titulo":"Ribavirina + Azatioprina (Mielossupressão e Hepatotoxicidade)","mecanismo":"A ribavirina inibe IMPDH, via compartilhada com o metabolismo da azatioprina (6-mercaptopurina → 6-tioguanina). A interação resulta em acúmulo de metabólitos citotóxicos da azatioprina (6-metiltioguanina nucleotídeos), causando toxicidade hepática nodular regenerativa e supressão medular.","efeito":"Mielossupressão grave (leucopenia, anemia, trombocitopenia), hepatotoxicidade e hipertensão portal não-cirrótica (doença hepática nodular regenerativa). Risco de descontinuação de ambos os fármacos.","conduta":"⚠️ Evitar combinação. Se imprescindível: monitorar hemograma e provas hepáticas mensalmente, reduzir dose de azatioprina e considerar substituição por micofenolato. Comunicar ao hepatologista e ao especialista responsável pelo imunossupressor."},
{"med1":["valaciclovir","valtrex","valcivir"],"med2":["aminoglicosídeo","amicacina","gentamicina","tobramicina","cisplatina","metotrexato","ciclosporina","tacrolimo","anfotericina b"],"nivel":"moderado","titulo":"Valaciclovir + Nefrotóxicos (Toxicidade Renal Aditiva)","mecanismo":"O valaciclovir é convertido a aciclovir, eliminado por filtração glomerular e secreção tubular. Em contexto de lesão renal prévia ou simultânea por nefrotóxicos, o clearance do aciclovir é reduzido, elevando seus níveis plasmáticos. Aciclovir em altas concentrações precipita em túbulo coletor causando nefrotoxicidade cristalina adicional.","efeito":"IRA por nefrotoxicidade aditiva e/ou cristalúria de aciclovir. Neurotoxicidade por aciclovir (encefalopatia, alucinações, tremores) se níveis elevarem muito — mais risco com a forma IV do que oral.","conduta":"⚠️ Monitorar função renal, garantir hidratação adequada (≥1,5 L/dia). Em insuficiência renal prévia, ajustar dose de valaciclovir pela TFG. Monitorar sinais de neurotoxicidade."},
{"med1":["valaciclovir","valtrex"],"med2":["cimetidina","tagamet"],"nivel":"leve","titulo":"Valaciclovir + Cimetidina (Inibição da Secreção Tubular)","mecanismo":"A cimetidina inibe a secreção tubular renal catiônica e também a excreção do aciclovir por competição transportadora, reduzindo seu clearance renal em ~25%.","efeito":"Elevação modesta dos níveis de aciclovir. Na maioria dos pacientes com função renal normal, a interação tem relevância clínica limitada. Em insuficiência renal, pode amplificar toxicidade.","conduta":"✅ Geralmente sem necessidade de ajuste em pacientes com função renal normal. Preferir ranitidina, famotidina ou IBP como alternativas ao cimetidina em pacientes com comprometimento renal."},
{"med1":["sulfassalazina","salazopyrin","azulfidine"],"med2":["ácido fólico","folato","metilfolato"],"nivel":"moderado","titulo":"Sulfassalazina + Ácido Fólico (Inibição da Absorção — Deficiência)","mecanismo":"A sulfassalazina inibe o transportador de folato reduzido (RFC/SLC19A1) no intestino delgado e inibe também a di-hidrofolato redutase, reduzindo a disponibilidade de folato ativo. Pode causar deficiência funcional de folato mesmo com níveis séricos na faixa normal.","efeito":"Macrocitose, anemia megaloblástica, hiperhomocisteinemia. Em mulheres em idade fértil: risco aumentado de defeitos do tubo neural em gestação. Piora de mucosite em pacientes em esquemas combinados.","conduta":"⚠️ Suplementar ácido fólico 1–5 mg/dia em todos os pacientes em uso prolongado de sulfassalazina. Dose maior (5 mg) em mulheres que planejam gravidez. Monitorar hemograma anualmente."},
{"med1":["sulfassalazina","salazopyrin"],"med2":["azatioprina","imuran","mercaptopurina","purinethol"],"nivel":"moderado","titulo":"Sulfassalazina + Azatioprina (Mielossupressão Aditiva)","mecanismo":"Ambos suprimem a medula óssea. Adicionalmente, a sulfassalazina inibe TPMT (tiopurina metiltransferase), a enzima que inativa a 6-mercaptopurina derivada da azatioprina. A inibição aumenta a exposição a metabólitos citotóxicos (6-TGN), potencializando a toxicidade hematológica.","efeito":"Leucopenia grave, risco elevado de infecções oportunistas e sepse. Hepatotoxicidade. A toxicidade é mais pronunciada em metabolizadores lentos de TPMT.","conduta":"⚠️ Monitorar hemograma mensalmente. Considerar genotipagem ou fenotipagem de TPMT antes de combinar. Reduzir dose de azatioprina se leucócitos caírem abaixo de 3.500/mm³. Avaliar sempre a necessidade da combinação versus monoterapia."},
{"med1":["metimazol","tapazole","propiltiouracil","ptu","propylthiouracil"],"med2":["warfarina","varfarina","coumadin","acenocumarol","sintrom"],"nivel":"moderado","titulo":"Antitireoidianos (Metimazol/PTU) + Anticoagulantes Cumarínicos (Variação de RNI)","mecanismo":"No hipertireoidismo, o metabolismo dos fatores de coagulação dependentes de vitamina K é acelerado (catabolismo aumentado) e a resposta à warfarina está aumentada. À medida que o tratamento antitireoidiano restaura o eutireoidismo, o metabolismo normaliza — os fatores de coagulação retornam aos níveis normais e a sensibilidade à warfarina diminui, exigindo doses maiores. Adicionalmente, o PTU pode ter efeito direto sobre a síntese de vitamina K.","efeito":"Elevação do RNI (risco de sangramento) na fase inicial do tratamento antitireoidiano; queda do RNI (risco trombótico) ao alcançar eutireoidismo sem ajuste da warfarina.","conduta":"⚠️ Monitorar RNI a cada 2–4 semanas durante a fase de ajuste da tireóide. Antecipar necessidade de redução da warfarina ao atingir eutireoidismo. Educar o paciente sobre sinais de sangramento e sobre a importância de não alterar doses sem orientação médica."},
{"med1":["metimazol","tapazole","propiltiouracil","ptu"],"med2":["clozapina","carbamazepina","metamizol","dipirona","fenilbutazona"],"nivel":"grave","titulo":"Antitireoidianos + Outros Mielossupressores (Agranulocitose Aditiva)","mecanismo":"Metimazol e PTU causam agranulocitose idiossincrática em 0,2–0,5% dos pacientes — provavelmente por mecanismo imune. Outros fármacos com risco de agranulocitose (clozapina, carbamazepina, dipirona em uso prolongado) somam este risco de forma aditiva ou sinérgica.","efeito":"Agranulocitose grave (neutrófilos <500/mm³) com risco muito elevado de infecções bacterianas fatais — sepse, pneumonia, infecções de partes moles necrotizantes.","conduta":"🚫 Evitar combinação quando possível. Se imprescindível: monitorar hemograma semanalmente nas primeiras 12 semanas. Orientar paciente a procurar atendimento de emergência imediatamente em caso de febre, calafrios ou odinofagia. Suspender antitireoidiano e/ou o outro mielossupressor na presença de neutropenia."}
,
{"med1":["mirabegrona","myrbetriq","betmiga"],"med2":["metoprolol","propranolol","carvedilol","nebivolol","timolol"],"nivel":"moderado","titulo":"Mirabegrona + Betabloqueadores (Inibição CYP2D6 — Aumento da Exposição)","mecanismo":"A mirabegrona é inibidora moderada da CYP2D6. Metoprolol, propranolol, carvedilol e nebivolol são substratos de CYP2D6. A inibição reduz o clearance desses betabloqueadores, podendo elevar sua AUC em 90–180% — efeito equivalente à conversão a metabolizador lento.","efeito":"Bradicardia, hipotensão, broncoespasmo (com betabloqueadores não-seletivos), fadiga excessiva e tontura. Com metoprolol: risco de BAV e hipotensão sintomática aumentados.","conduta":"⚠️ Monitorar frequência cardíaca e pressão arterial ao iniciar mirabegrona em usuários de betabloqueadores. Com metoprolol: considerar dose mais baixa ou substituição por atenolol ou bisoprolol (menor dependência de CYP2D6). Titular com cautela."},
{"med1":["mirabegrona","myrbetriq","betmiga"],"med2":["flecainida","propafenona","encainida"],"nivel":"moderado","titulo":"Mirabegrona + Antiarrítmicos Classe 1C (Inibição CYP2D6 — Toxicidade)","mecanismo":"Flecainida e propafenona são substratos de CYP2D6 com janela terapêutica estreita. A inibição desta isoenzima pela mirabegrona pode elevar substancialmente seus níveis plasmáticos.","efeito":"Toxicidade antiarrítmica: prolongamento de QRS/QTc, arritmias proarrítmicas (taquicardia ventricular, fibrilação ventricular), tontura, visão turva e sabor metálico (flecainida).","conduta":"⚠️ Evitar combinação quando possível. Se necessária, monitorar ECG periodicamente. Com flecainida: medir nível sérico antes e após início da mirabegrona e ajustar dose conforme necessário."},
{"med1":["mirabegrona","myrbetriq","betmiga"],"med2":["desipramina","nortriptilina","amitriptilina","clomipramina","imipramina","cloridrato de nortriptilina","cloridrato de clomipramina","cloridrato de imipramina"],"nivel":"moderado","titulo":"Mirabegrona + Antidepressivos Tricíclicos (Inibição CYP2D6 — Toxicidade TCA)","mecanismo":"TCAs são extensamente metabolizados por CYP2D6. A inibição desta via pela mirabegrona eleva seus níveis plasmáticos, potencializando tanto os efeitos terapêuticos quanto os adversos e tóxicos.","efeito":"Toxicidade anticolinérgica excessiva (retenção urinária, constipação, boca seca, visão turva, confusão em idosos), sedação excessiva, prolongamento de QTc e risco de arritmias.","conduta":"⚠️ Monitorar sintomas anticolinérgicos e ECG. Em idosos, o risco de delirium é elevado — preferir antidepressivo não-TCA se possível. Reduzir dose do TCA em 25–50% se sintomas de toxicidade surgirem."},
{"med1":["dupilumabe","dupixent"],"med2":["vacina viva","vacina de vírus vivo","vacina febre amarela","vacina varicela","vacina sarampo","bcg","vacina rotavírus"],"nivel":"moderado","titulo":"Dupilumabe + Vacinas Vivas (Imunossupressão — Usar com Cautela)","mecanismo":"O dupilumabe bloqueia a sinalização de IL-4 e IL-13, suprimindo a resposta imune Th2. Embora seu mecanismo seja mais seletivo que corticosteroides sistêmicos ou outros biológicos, a administração de vacinas vivas em contexto de imunossupressão requer avaliação cuidadosa.","efeito":"Risco potencial de resposta imune inadequada à vacinação ou, teoricamente, disseminação do vírus vacinal — embora evidências sejam mais limitadas que com imunossupressores amplos.","conduta":"⚠️ Administrar vacinas vivas necessárias preferencialmente ≥4 semanas antes de iniciar dupilumabe. Vacinas inativadas (influenza, pneumocócica) são seguras e recomendadas durante o tratamento. Consultar infectologista em casos de necessidade urgente de vacinas vivas durante tratamento."},
{"med1":["dupilumabe","dupixent"],"med2":["ciclosporina","metotrexato","azatioprina","imunossupressor"],"nivel":"moderado","titulo":"Dupilumabe + Imunossupressores Sistêmicos (Imunossupressão Aditiva)","mecanismo":"A combinação de dupilumabe com imunossupressores sistêmicos (ciclosporina, metotrexato, azatioprina) — usados off-label em dermatite atópica grave — não tem dados robustos de segurança e pode resultar em imunossupressão mais ampla do que o desejado.","efeito":"Risco aumentado de infecções, incluindo oportunistas. Reativação de hepatite B, tuberculose e infecções por herpes.","conduta":"⚠️ Evitar combinação sem supervisão especializada. Rastrear tuberculose e hepatite B antes de iniciar. Monitorar sinais de infecção. O dupilumabe foi desenvolvido para substituir (não combinar com) imunossupressores sistêmicos em dermatite atópica."},
{"med1":["estradiol","estradiol hemi-hidratado","estrogênio","estrogeno","valerato de estradiol"],"med2":["carbamazepina","fenitoína","fenobarbital","rifampicina","topiramato","oxcarbazepina","primidona"],"nivel":"moderado","titulo":"Estradiol + Indutores Enzimáticos (CYP3A4 — Redução de Eficácia Hormonal)","mecanismo":"O estradiol é metabolizado principalmente pela CYP3A4. Indutores desta isoenzima (antiepilépticos como carbamazepina, fenitoína, fenobarbital; rifampicina; topiramato em doses maiores) aceleram seu metabolismo, reduzindo significativamente os níveis plasmáticos.","efeito":"Perda de eficácia da terapia hormonal (sintomas de menopausa, irregularidade menstrual, falha contraceptiva em ACO). Sangramento de escape em doses terapêuticas convencionais.","conduta":"⚠️ Considerar dose maior de estradiol ou transição para via transdérmica (menor first-pass). Para contracepção: usar método de barreira adicional ou anticoncepcional não estrogênico (DIU de cobre, progestágeno de depósito). Preferir antiepiléptico sem efeito indutor (lamotrigina, levetiracetam, gabapentina) quando possível."},
{"med1":["estradiol","estradiol hemi-hidratado","estrogênio","valerato de estradiol","etinil estradiol","etinilestradiol"],"med2":["tabaco","cigarro","fumo"],"nivel":"moderado","titulo":"Estradiol / Estrogênio + Tabaco (Risco Tromboembólico e Cardiovascular)","mecanismo":"O tabaco induz CYP1A2, acelerando o metabolismo do etinilestradiol e aumentando a produção de metabólitos hidroxilados com maior potencial trombogênico. Adicionalmente, nicotina e monóxido de carbono causam disfunção endotelial e ativação plaquetária — criando sinergismo trombótico com o estrogênio.","efeito":"Risco 2–4 vezes maior de trombose venosa profunda, embolia pulmonar e AVC isquêmico. O risco aumenta com a idade (especialmente >35 anos) e com o número de cigarros/dia.","conduta":"🚫 Estrogênios combinados (ACO, anel vaginal, adesivo) contraindicados em mulheres fumantes >35 anos. Abaixo de 35 anos: orientar fortemente sobre o risco, considerar progestágeno isolado ou DIU. A cessação do tabagismo elimina grande parte do risco residual."},
{"med1":["estradiol","estradiol hemi-hidratado","estrogênio","valerato de estradiol","etinil estradiol","etinilestradiol"],"med2":["warfarina","varfarina","acenocumarol","rivaroxabana","apixabana","heparina","anticoagulante"],"nivel":"moderado","titulo":"Estradiol / Estrogênio + Anticoagulantes (Risco Trombótico Aditivo)","mecanismo":"Os estrogênios aumentam a síntese hepática de fatores pró-coagulantes (fatores II, VII, IX, X, fibrinogênio) e reduzem os anticoagulantes naturais (proteína S, antitrombina). Esta atividade pró-trombótica pode contrariar parcialmente o efeito anticoagulante e aumentar a instabilidade do RNI com warfarina.","efeito":"Maior risco de tromboembolismo venoso mesmo sob anticoagulação. Instabilidade do RNI com varfarina. Em pacientes com trombofilia, o risco é significativamente amplificado.","conduta":"⚠️ Estrogênios devem ser evitados em pacientes com histórico de TEV ou trombofilia. Se uso for necessário (ex: osteoporose grave), preferir via transdérmica (menor efeito pró-trombótico que via oral). Monitorar RNI mais frequentemente ao iniciar ou ajustar estrogênio."},
{"med1":["acetazolamida","diamox"],"med2":["carbonato de lítio","lítio","litio"],"nivel":"moderado","titulo":"Acetazolamida + Lítio (Aumento da Excreção Renal — Redução do Nível)","mecanismo":"A acetazolamida alcaliniza a urina por inibição da anidrase carbônica renal, aumentando a excreção urinária de bicarbonato e sódio. Em condições de alcalose tubular, a reabsorção de lítio é reduzida — sua excreção aumenta e os níveis plasmáticos caem.","efeito":"Redução dos níveis séricos de lítio com possível perda de controle do humor. Risco de episódio maníaco ou depressivo em transtorno bipolar. O efeito é variável e depende da dose e da hidratação.","conduta":"⚠️ Monitorar nível sérico de lítio antes e 5–7 dias após iniciar acetazolamida. Ajustar dose se necessário. Manter hidratação adequada para estabilizar a farmacocinética do lítio."},
{"med1":["acetazolamida","diamox"],"med2":["ácido acetilsalicílico","aspirina","aas","salicilato"],"nivel":"moderado","titulo":"Acetazolamida + AAS / Salicilatos em Altas Doses (Acidose Metabólica + Toxicidade)","mecanismo":"A acetazolamida causa acidose metabólica hiperclorêmica. Salicilatos em altas doses (>2 g/dia) também causam acidose. A acidemia sistêmica aumenta a fração não-ionizada dos salicilatos, facilitando sua entrada no SNC. Adicionalmente, a acetazolamida pode reduzir a excreção renal de salicilatos em doses altas.","efeito":"Toxicidade por salicilatos potencializada: zumbido, hiperpneia, confusão, coma. Em doses analgésicas/antipirético habituais, a interação tem relevância clínica mínima — o risco é principalmente com AAS antiagregante + doses anti-inflamatórias ou analgésicas plenas.","conduta":"⚠️ Monitorar sintomas de toxicidade por salicilatos (zumbido, alteração neurológica). Em uso de AAS 100 mg/dia profilático: risco baixo. Evitar AAS em doses anti-inflamatórias durante uso de acetazolamida."},
{"med1":["acetazolamida","diamox"],"med2":["topiramato","topamax","zonisamida","zonegran"],"nivel":"moderado","titulo":"Acetazolamida + Topiramato/Zonisamida (Inibição Tripla de Anidrase — Nefrolitíase)","mecanismo":"Todos os três inibem a anidrase carbônica renal. A combinação resulta em alcalinização urinária acentuada com redução do citrato urinário e elevação do pH — criando condições ideais para precipitação de cálcio fosfato e formação de cálculos renais.","efeito":"Risco muito elevado de nefrolitíase. Oligoidrose com hipertermia (especialmente em crianças). Acidose metabólica hiperclorêmica grave.","conduta":"⚠️ Evitar a combinação de dois ou mais inibidores de anidrase carbônica sempre que possível. Se necessário: hidratação ≥2 L/dia, citrato de potássio profilático, monitorar pH urinário, eletrólitos e imagem renal anualmente."},
{"med1":["acetazolamida","diamox"],"med2":["fenitoína","hidantal","epelin"],"nivel":"moderado","titulo":"Acetazolamida + Fenitoína (Osteomalácia e Risco de Toxicidade)","mecanismo":"A acetazolamida pode aumentar os níveis de fenitoína em alguns pacientes (inibição do metabolismo) e, combinada com ela, amplifica a interferência no metabolismo da vitamina D e do cálcio — ambos perturbam o metabolismo ósseo por mecanismos distintos.","efeito":"Risco aumentado de osteomalácia e osteoporose com uso crônico. Casos isolados de toxicidade por fenitoína foram relatados.","conduta":"⚠️ Em uso crônico: suplementar vitamina D e cálcio. Monitorar densitometria óssea anualmente. Verificar nível sérico de fenitoína ao iniciar ou ajustar acetazolamida."},
{"med1":["dulaglutida","trulicity","exenatida","byetta","bydureon","liraglutida","victoza","saxenda","semaglutida","ozempic","rybelsus","wegovy","tirzepatida","mounjaro","zepbound"],"med2":["levotiroxina","tiroxina","synthroid","puran","euthyrox"],"nivel":"leve","titulo":"Agonistas GLP-1 + Levotiroxina (Retardo de Absorção)","mecanismo":"Os agonistas de GLP-1 retardam o esvaziamento gástrico de forma dose-dependente. A levotiroxina tem janela terapêutica estreita e absorção variável — qualquer alteração no trânsito gástrico pode modificar sua biodisponibilidade.","efeito":"Absorção reduzida ou imprevisível da levotiroxina, podendo resultar em hipotireoidismo subclínico ou sintomático. Monitoramento de TSH mostrando elevação inesperada durante uso de GLP-1.","conduta":"⚠️ Administrar levotiroxina em jejum, 30–60 minutos antes da refeição e do agonista GLP-1 (quando injetável ao redor das refeições). Monitorar TSH 6–8 semanas após início do agonista GLP-1 e após mudanças de dose. Ajustar dose de levotiroxina conforme TSH."},
{"med1":["dulaglutida","trulicity","exenatida","byetta","bydureon","liraglutida","victoza","semaglutida","ozempic","tirzepatida","mounjaro","zepbound"],"med2":["warfarina","varfarina","acenocumarol"],"nivel":"leve","titulo":"Agonistas GLP-1 + Warfarina (Retardo de Absorção — Instabilidade de RNI)","mecanismo":"O esvaziamento gástrico retardado pelos agonistas GLP-1 pode alterar o tempo de pico de absorção da warfarina. Adicionalmente, as náuseas e vômitos frequentes no início do tratamento com GLP-1 afetam a ingestão alimentar e, portanto, a ingestão de vitamina K — fator crítico para a estabilidade do RNI.","efeito":"Instabilidade do RNI nos primeiros meses de uso de GLP-1, com risco de sobreanticoagulação ou subanticicoagulação.","conduta":"⚠️ Monitorar RNI com maior frequência ao iniciar, aumentar dose ou trocar o agonista GLP-1. Orientar o paciente a manter ingestão consistente de alimentos ricos em vitamina K mesmo com náuseas — modificar a dieta com consistência, não eliminar os vegetais verdes."},
{"med1":["dulaglutida","trulicity","exenatida","byetta","semaglutida","ozempic","liraglutida","tirzepatida","mounjaro","zepbound"],"med2":["insulina","insulina nph","insulina glargina","insulina detemir","insulina asparte","insulina lispro","insulina regular"],"nivel":"moderado","titulo":"Agonistas GLP-1 + Insulina (Hipoglicemia Aditiva)","mecanismo":"Os agonistas GLP-1 estimulam a secreção de insulina de forma glicose-dependente e reduzem o glucagon. Em combinação com insulina exógena, especialmente de ação rápida, o risco de hipoglicemia pós-prandial é amplificado.","efeito":"Hipoglicemia, incluindo hipoglicemia grave (< 54 mg/dL) com necessidade de assistência. O risco é maior com insulina de ação curta/rápida associada ao GLP-1.","conduta":"⚠️ Ao adicionar agonista GLP-1 a esquema com insulina, reduzir dose de insulina de ação rápida em 10–20% profilaticamente. Monitorar glicemia mais frequentemente nas primeiras semanas. Orientar paciente e familiares sobre reconhecimento e tratamento de hipoglicemia."},
{"med1":["torasemida","torsemida","demadex"],"med2":["amicacina","gentamicina","tobramicina","estreptomicina","aminoglicosídeo"],"nivel":"grave","titulo":"Torasemida + Aminoglicosídeos (Ototoxicidade e Nefrotoxicidade Sinérgicas)","mecanismo":"Diuréticos de alça inibem o co-transportador Na-K-2Cl na estria vascular da cóclea, reduzindo o potencial endocleular e tornando as células ciliadas vulneráveis à lesão. Os aminoglicosídeos lesam diretamente as células ciliadas externas por formação de radicais livres e entrada excessiva de cálcio. Os mecanismos são sinérgicos.","efeito":"Ototoxicidade grave (perda auditiva sensorineural permanente, zumbido), especialmente em altas doses de ambos ou com uso IV. Nefrotoxicidade aditiva com risco de IRA.","conduta":"⚠️ Evitar combinação sempre que possível — especialmente infusões IV simultâneas. Se necessária: audiometria basal, monitorar função renal e sinais de ototoxicidade (zumbido, hipoacusia). Preferir dose única diária de aminoglicosídeo e dose mínima eficaz de torasemida. Manter hidratação adequada."},
{"med1":["torasemida","torsemida","demadex"],"med2":["digoxina","digitoxina","digoxin"],"nivel":"moderado","titulo":"Torasemida + Digoxina (Hipocalemia → Toxicidade Digitálica)","mecanismo":"A torasemida, como todos os diuréticos de alça, causa perda renal de potássio e magnésio. A hipocalemia resultante aumenta a afinidade da digoxina pela Na-K-ATPase miocárdica e reduz o limiar de toxicidade digitálica — o mesmo nível sérico de digoxina torna-se tóxico.","efeito":"Arritmias digitálicas: extrassístoles ventriculares, bigeminismo, bloqueio AV, taquicardia ventricular. O risco é diretamente proporcional ao grau de hipocalemia.","conduta":"⚠️ Monitorar potássio sérico (manter K⁺ > 4,0 mEq/L em uso de digoxina). Suplementar potássio (oral ou IV) proativamente. Associar espironolactona como poupador de potássio quando possível. Verificar ECG e nível sérico de digoxina se hipocalemia detectada."},
{"med1":["torasemida","torsemida","demadex","furosemida","lasix"],"med2":["carbonato de lítio","lítio","litio"],"nivel":"moderado","titulo":"Diuréticos de Alça + Lítio (Deplecção de Sódio → Toxicidade por Lítio)","mecanismo":"O lítio é reabsorvido no túbulo proximal junto com o sódio, competindo pelo mesmo transportador. Diuréticos de alça causam perda de sódio, desencadeando reabsorção compensatória proximal de sódio — e consequentemente de lítio. O resultado é elevação dos níveis séricos de lítio.","efeito":"Toxicidade por lítio: tremor fino tornando-se grosseiro, ataxia, confusão, náuseas, vômitos, convulsões em casos graves. O lítio tem janela terapêutica estreita (0,6–1,2 mEq/L) — pequenas elevações podem causar toxicidade.","conduta":"⚠️ Monitorar litemia 5–7 dias após início de diurético de alça e a cada ajuste de dose. Manter hidratação e ingesta de sódio estáveis. Pode ser necessário reduzir dose de lítio. Orientar sobre sinais de toxicidade (tremor, confusão, vômitos)."},
{"med1":["aciclovir","acyclovir","zovirax"],"med2":["aminoglicosídeo","amicacina","gentamicina","tobramicina","cisplatina","anfotericina b","ciclosporina"],"nivel":"moderado","titulo":"Aciclovir + Nefrotóxicos (Toxicidade Renal Aditiva e Cristalúria)","mecanismo":"O aciclovir é eliminado por filtração glomerular e secreção tubular ativa. Em altas concentrações (especialmente IV), pode precipitar em cristais nos túbulos coletores — mecanismo independente. A coexistência com outros nefrotóxicos reduz adicionalmente o clearance do aciclovir, elevando sua concentração plasmática e tubular.","efeito":"IRA, cristalúria com obstrução tubular, elevação de creatinina. Em doses orais padrão, o risco é menor, mas presente em pacientes com função renal comprometida.","conduta":"⚠️ Garantir hidratação adequada (débito urinário ≥1 mL/kg/h durante infusão IV de aciclovir). Monitorar função renal diariamente com terapia IV. Ajustar dose pela TFG. Espaçar ao máximo a administração de nefrotóxicos."},
{"med1":["aciclovir","acyclovir","zovirax"],"med2":["probenecida"],"nivel":"leve","titulo":"Aciclovir + Probenecida (Inibição Tubular — Aumento do Nível)","mecanismo":"A probenecida inibe a secreção tubular de aciclovir via transportador OAT (organic anion transporter), reduzindo seu clearance renal em ~32% e prolongando sua meia-vida.","efeito":"Elevação dos níveis plasmáticos de aciclovir. Em doses orais padrão e função renal normal, o impacto clínico é geralmente limitado. Em doses altas (herpes encefalite) ou IR prévia: risco aumentado de neurotoxicidade (tremor, confusão) e nefrotoxicidade.","conduta":"✅ Em doses antivirais habituais com função renal normal: geralmente sem necessidade de ajuste. Monitorar em pacientes com IR ou em doses altas de aciclovir IV. Considerar redução de dose de aciclovir se toxicidade surgir."},
{"med1":["maprotilina","ludiomil"],"med2":["inibidor mao","imao","fenelzina","tranilcipromina","selegilina","moclobemida","isocarboxazida"],"nivel":"grave","titulo":"Maprotilina + IMAOs (Síndrome Serotoninérgica / Crise Hipertensiva — Contraindicado)","mecanismo":"A maprotilina é um antidepressivo tetracíclico que inibe seletivamente a recaptação de norepinefrina. Os IMAOs inibem a degradação de monoaminas. A combinação resulta em acúmulo de norepinefrina e serotonina com risco de crise adrenérgica e síndrome serotoninérgica.","efeito":"Crise hipertensiva, hipertermia, rigidez muscular, convulsões, colapso cardiovascular. Potencialmente fatal.","conduta":"🚫 Contraindicado. Washout mínimo de 14 dias entre IMAO e maprotilina (em ambas as direções). Monitorar pressão arterial ao iniciar tratamento."},
{"med1":["maprotilina","ludiomil"],"med2":["atropina","biperideno","triexifenidil","escopolamina","anti-histamínico","clorfeniramina","difenidramina","dimenidrinato","clorpromazina","olanzapina","quetiapina"],"nivel":"moderado","titulo":"Maprotilina + Anticolinérgicos (Toxicidade Anticolinérgica Aditiva)","mecanismo":"A maprotilina possui propriedades anticolinérgicas intrínsecas (bloqueio de receptores muscarínicos M1). A adição de outros fármacos anticolinérgicos (anticolinérgicos clássicos, anti-histamínicos, alguns antipsicóticos) resulta em efeito aditivo.","efeito":"Síndrome anticolinérgica: boca seca intensa, retenção urinária, constipação grave, íleo paralítico, taquicardia, confusão mental e delirium (especialmente em idosos).","conduta":"⚠️ Avaliar o perfil anticolinérgico total do paciente (escala de carga anticolinérgica). Minimizar o número de fármacos anticolinérgicos. Em idosos: evitar a combinação — risco elevado de quedas e delirium."},
{"med1":["maprotilina","ludiomil"],"med2":["carbamazepina","fenitoína","fenobarbital","rifampicina"],"nivel":"moderado","titulo":"Maprotilina + Indutores Enzimáticos (Redução de Nível — Falha Terapêutica)","mecanismo":"A maprotilina é metabolizada por CYP2D6 e CYP3A4. Indutores de CYP3A4 (carbamazepina, fenitoína, fenobarbital, rifampicina) aceleram seu metabolismo, reduzindo os níveis plasmáticos em 50–60%.","efeito":"Perda de eficácia antidepressiva. Risco de recaída depressiva em pacientes epilépticos tratados com antiepilépticos indutores.","conduta":"⚠️ Monitorar resposta clínica. Pode ser necessário aumentar a dose de maprotilina. Considerar antidepressivo com menor dependência de CYP3A4 em pacientes com antiepilépticos indutores (ex: mirtazapina, escitalopram)."},
{"med1":["cariprazina","cloridrato de cariprazina","vraylar","reagila"],"med2":["cetoconazol","ketoconazol","itraconazol","voriconazol","claritromicina","ritonavir"],"nivel":"grave","titulo":"Cariprazina + Inibidores Fortes CYP3A4 (Contraindicado)","mecanismo":"A cariprazina e seu metabólito ativo (DCAR) são metabolizados pela CYP3A4. Inibidores potentes desta isoenzima elevam substancialmente a exposição total à cariprazina, podendo dobrar ou triplicar seus níveis plasmáticos.","efeito":"Toxicidade antipsicótica: parkinsonismo, acatisia grave, sedação excessiva, hipotensão, prolongamento de QTc com risco de torsades de pointes.","conduta":"🚫 Contraindicado conforme bula. Reduzir dose de cariprazina pela metade se o uso de inibidor CYP3A4 for inevitável e de curta duração. Monitorar ECG e sinais extrapiramidais. Substituir o inibidor por alternativa com menor inibição de CYP3A4 quando possível."},
{"med1":["cariprazina","cloridrato de cariprazina","vraylar","reagila"],"med2":["rifampicina","rifampin","carbamazepina","fenitoína","fenobarbital"],"nivel":"moderado","titulo":"Cariprazina + Indutores CYP3A4 (Redução de Eficácia — Contraindicado)","mecanismo":"Indutores de CYP3A4 aceleram o metabolismo da cariprazina e do DCAR (metabólito ativo), reduzindo seus níveis plasmáticos de forma clinicamente relevante e potencialmente comprometendo a eficácia antipsicótica.","efeito":"Falha terapêutica — recaída psicótica ou de episódio maníaco bipolar. Instabilidade clínica sem causa aparente.","conduta":"🚫 Contraindicado conforme bula. Substituir antiepiléptico indutor por não-indutor (levetiracetam, lamotrigina, valproato) quando clinicamente possível. Se não for possível, avaliar antipsicótico alternativo com perfil metabólico diferente."},
{"med1":["cariprazina","cloridrato de cariprazina","vraylar","reagila"],"med2":["amiodarona","sotalol","dronedarona","haloperidol","clorpromazina","tioridazina","ziprasidona","metadona","ciprofloxacino","levofloxacino","moxifloxacino","azitromicina"],"nivel":"moderado","titulo":"Cariprazina + Fármacos que Prolongam QTc (Risco de Arritmia)","mecanismo":"A cariprazina tem potencial intrínseco de prolongamento de QTc. A combinação com outros fármacos que prolongam o intervalo QT resulta em efeito aditivo sobre a repolarização ventricular.","efeito":"Prolongamento excessivo do QTc (>500 ms) com risco de torsades de pointes e morte súbita cardíaca.","conduta":"⚠️ Realizar ECG basal antes de iniciar cariprazina em pacientes em uso de outros fármacos que prolongam QT. Monitorar QTc periodicamente. Corrigir hipocalemia, hipomagnesemia e hipocalcemia. Suspender a cariprazina se QTc >500 ms."},
{"med1":["brivaracetam","briviact"],"med2":["rifampicina","rifampin"],"nivel":"moderado","titulo":"Brivaracetam + Rifampicina (Indução CYP2C19 — Redução de Nível)","mecanismo":"A rifampicina é indutora potente de CYP2C19, principal via de metabolização do brivaracetam. A indução reduz a AUC do brivaracetam em cerca de 45%, comprometendo sua exposição terapêutica.","efeito":"Redução da eficácia antiepiléptica — risco de recorrência de crises epilépticas em pacientes previamente controlados.","conduta":"⚠️ Dobrar a dose de brivaracetam ao introduzir rifampicina. Monitorar resposta clínica e ajustar conforme necessário. Ao suspender rifampicina, reduzir dose de brivaracetam para evitar toxicidade."},
{"med1":["brivaracetam","briviact"],"med2":["carbamazepina","tegretol"],"nivel":"moderado","titulo":"Brivaracetam + Carbamazepina (Interação Bidirecional — Toxicidade de CBZ)","mecanismo":"O brivaracetam pode aumentar os níveis do metabólito ativo da carbamazepina (carbamazepina-10,11-epóxido) ao inibir a epóxido hidrolase. Simultaneamente, a carbamazepina (indutor de CYP3A4/CYP2C19) pode reduzir os níveis de brivaracetam.","efeito":"Toxicidade por carbamazepina-epóxido (tontura, diplopia, ataxia, náuseas) mesmo com nível sérico de carbamazepina dentro da faixa terapêutica. Possível redução da eficácia do brivaracetam.","conduta":"⚠️ Monitorar sintomas de toxicidade por carbamazepina ao iniciar brivaracetam. Medir nível de carbamazepina e, se possível, do epóxido. Reduzir dose de carbamazepina se sintomas de toxicidade surgiremi. Ajustar dose de brivaracetam se perda de controle epiléptico ocorrer."},
{"med1":["brivaracetam","briviact"],"med2":["fenitoína","hidantal","epelin"],"nivel":"moderado","titulo":"Brivaracetam + Fenitoína (Interação Bidirecional)","mecanismo":"A fenitoína é indutora de CYP2C19, acelerando o metabolismo do brivaracetam. Reciprocamente, o brivaracetam pode inibir a CYP2C19, elevando os níveis de fenitoína. A intensidade de cada efeito varia entre indivíduos.","efeito":"Potencial redução dos níveis de brivaracetam (risco de crises) e/ou toxicidade por fenitoína (nistagmo, ataxia, sedação) dependendo do balanço das interações.","conduta":"⚠️ Monitorar nível sérico de fenitoína ao iniciar brivaracetam. Ajustar doses de ambos os fármacos conforme resposta clínica e toxicidade. Titular brivaracetam lentamente."},
{"med1":["nitrofurantoína","macrobid","macrodantin","furadantina"],"med2":["antiácido","hidróxido de magnésio","hidróxido de alumínio","carbonato de cálcio","bicarbonato de sódio","antiácido com mg"],"nivel":"moderado","titulo":"Nitrofurantoína + Antiácidos com Magnésio (Redução de Absorção — Falha Terapêutica)","mecanismo":"Os íons Mg²⁺ (e Al³⁺) dos antiácidos quelam a nitrofurantoína no trato gastrointestinal, formando complexos insolúveis e reduzindo sua absorção em até 50%. A alcalinização urinária pelos antiácidos também reduz a atividade antibacteriana da nitrofurantoína nas vias urinárias.","efeito":"Redução da concentração urinária de nitrofurantoína abaixo dos níveis bactericidas — falha no tratamento de infecção urinária, com risco de progressão para pielonefrite.","conduta":"⚠️ Espaçar nitrofurantoína e antiácidos por pelo menos 2 horas. Preferir administrar nitrofurantoína junto às refeições (melhora a absorção e reduz náuseas) e evitar antiácido na mesma ocasião. Considerar IBP ou bloqueador H2 como alternativa se antiácido for necessário cronicamente."},
{"med1":["nitrofurantoína","macrobid","macrodantin","furadantina"],"med2":["ciprofloxacino","norfloxacino","levofloxacino","moxifloxacino","fluoroquinolona"],"nivel":"moderado","titulo":"Nitrofurantoína + Fluoroquinolonas (Antagonismo Farmacológico)","mecanismo":"A nitrofurantoína é ativada por nitroreductases bacterianas para formar metabólitos altamente reativos que lesam múltiplos alvos celulares (DNA, ribossomos, parede celular). As fluoroquinolonas inibem as topoisomerases II e IV. A nitrofurantoína parece antagonizar o mecanismo das quinolonas ao competir pela enzima nitroreductase e alterar o estado redox bacteriano.","efeito":"Redução da atividade antibacteriana de ambos os agentes quando usados simultaneamente. Falha terapêutica — especialmente preocupante em ITU complicada.","conduta":"🚫 Evitar combinação. Escolher apenas um agente com base no antibiograma e no perfil do paciente. Em ITU não complicada: nitrofurantoína (5–7 dias) ou fluoroquinolona (3 dias) são igualmente eficazes como monoterapia."},
{"med1":["nitrofurantoína","macrobid","macrodantin","furadantina"],"med2":["probenecida","sulfinpirazona"],"nivel":"moderado","titulo":"Nitrofurantoína + Probenecida (Inibição Tubular — Falha Terapêutica)","mecanismo":"A probenecida inibe a secreção tubular renal da nitrofurantoína, reduzindo sua excreção urinária. Como a nitrofurantoína atua localmente nas vias urinárias por concentração renal, a redução da excreção compromete diretamente sua eficácia antibacteriana.","efeito":"Concentrações urinárias subterapêuticas de nitrofurantoína com risco de falha no tratamento de ITU. Paradoxalmente, os níveis séricos elevam-se levemente — sem benefício terapêutico adicional e com maior risco de toxicidade sistêmica (neuropatia, toxicidade pulmonar).","conduta":"⚠️ Evitar combinação. Se probenecida for necessária (p. ex., para gota), optar por outro antibiótico para a ITU (fosfomicina, cefalexina, amoxicilina-clavulanato conforme antibiograma)."},
{"med1":["etambutol","myambutol"],"med2":["isoniazida","hidrazida","inh"],"nivel":"moderado","titulo":"Etambutol + Isoniazida (Neuropatia Óptica Aditiva)","mecanismo":"O etambutol inibe a arabinosiltransferase micobacteriana e também quelam zinco intracelular — afetando mitocôndrias do nervo óptico. A isoniazida depleta vitamina B6 (piridoxina) por inibição da piridoxal fosfato, causando neuropatia periférica e potencialmente neurite óptica. Os mecanismos se somam.","efeito":"Risco aumentado de neurite óptica (visão turva, alteração de cor, perda de campo visual central) e neuropatia periférica. Ambos os efeitos são parcialmente reversíveis se detectados precocemente; a continuação pode causar déficit visual permanente.","conduta":"⚠️ Suplementar piridoxina (vitamina B6) 25–50 mg/dia em todos os pacientes em esquema com isoniazida. Avaliação oftalmológica basal (acuidade visual, visão de cores, campo visual) antes de iniciar e mensalmente durante tratamento com etambutol. Suspender etambutol imediatamente se alteração visual documentada."},
{"med1":["etambutol","myambutol"],"med2":["hidróxido de alumínio","antiácido com alumínio","sais de alumínio"],"nivel":"moderado","titulo":"Etambutol + Antiácidos com Alumínio (Redução de Absorção)","mecanismo":"Os sais de alumínio quelam o etambutol no trato gastrointestinal, formando complexos insolúveis e reduzindo sua absorção em até 30%. Os antiácidos também elevam o pH gástrico, podendo alterar adicionalmente a solubilidade do fármaco.","efeito":"Redução da biodisponibilidade do etambutol, comprometendo as concentrações plasmáticas e potencialmente a eficácia antituberculosa.","conduta":"⚠️ Espaçar etambutol e antiácidos à base de alumínio por pelo menos 4 horas. Preferir IBP ou bloqueadores H2 como alternativas antiácidas durante tratamento antituberculoso. Administrar etambutol em jejum para maximizar absorção."}
,
{"med1":["zafirlucaste","accolate"],"med2":["warfarina","varfarina","acenocumarol","sintrom"],"nivel":"moderado","titulo":"Zafirlucaste + Warfarina (Inibição CYP2C9 — Aumento do RNI)","mecanismo":"O zafirlucaste inibe CYP2C9 e CYP3A4 de forma dose-dependente. A S-warfarina (isômero farmacologicamente mais ativo) é substrato de CYP2C9 — sua inibição reduz o clearance da warfarina, elevando os níveis plasmáticos e o efeito anticoagulante.","efeito":"Elevação do RNI com risco de sangramento. Em estudos, a coadministração de zafirlucaste 160 mg/dia aumentou a AUC da S-warfarina em ~63% e o tempo de protrombina significativamente.","conduta":"⚠️ Monitorar RNI com maior frequência ao iniciar, ajustar dose ou suspender zafirlucaste. Pode ser necessário reduzir a dose de warfarina. Considerar montelucaste como alternativa antileucotrieno, que não tem interação significativa com CYP2C9."},
{"med1":["zafirlucaste","accolate"],"med2":["eritromicina","claritromicina","azitromicina"],"nivel":"moderado","titulo":"Zafirlucaste + Macrolídeos (Redução dos Níveis de Zafirlucaste)","mecanismo":"A eritromicina reduz a biodisponibilidade do zafirlucaste em ~40%, possivelmente por inibição de transportadores intestinais (P-gp) ou alteração do metabolismo de first-pass. O mecanismo exato não é completamente elucidado.","efeito":"Redução dos níveis plasmáticos de zafirlucaste com potencial perda de controle da asma. Risco de exacerbação asmática durante curso de eritromicina.","conduta":"⚠️ Monitorar controle da asma durante uso de eritromicina. Considerar azitromicina ou amoxicilina como alternativa se possível. Ajustar dose de zafirlucaste se necessário."},
{"med1":["zafirlucaste","accolate"],"med2":["teofilina","aminofilina"],"nivel":"leve","titulo":"Zafirlucaste + Teofilina (Redução de Nível)","mecanismo":"A teofilina reduz os níveis plasmáticos de zafirlucaste em ~30% por mecanismo não completamente esclarecido (possivelmente alteração da absorção ou indução metabólica leve). A direção inversa — efeito do zafirlucaste sobre a teofilina — é clínica e farmacocineticamente pouco relevante.","efeito":"Redução modesta da exposição ao zafirlucaste. Em geral, sem impacto clínico significativo no controle da asma, mas pode ser relevante em asma grave.","conduta":"✅ Monitorar controle da asma em uso combinado. Considerar ajuste de dose de zafirlucaste se controle for insuficiente. Em asma não controlada com teofilina, considerar troca para montelucaste (sem esta interação)."},
{"med1":["tansulosina","cloridrato de tansulosina","flomax","omnic"],"med2":["sildenafila","viagra","tadalafila","cialis","vardenafila","levitra","avanafila"],"nivel":"moderado","titulo":"Tansulosina + Inibidores de PDE5 (Hipotensão Sintomática)","mecanismo":"A tansulosina bloqueia receptores alfa-1A adrenérgicos na próstata e bexiga, causando vasodilatação periférica. Os inibidores de PDE5 promovem vasodilatação por via do GMPc. A combinação resulta em queda pressórica aditiva, especialmente postural.","efeito":"Hipotensão ortostática sintomática — tontura, pré-síncope e síncope, especialmente nas primeiras horas após uso do inibidor de PDE5. Risco maior com tadalafila (meia-vida longa) e nas primeiras semanas de uso.","conduta":"⚠️ A associação é possível com precaução. Iniciar inibidor de PDE5 na menor dose disponível. Orientar o paciente a não usar logo após levantar e a sentar-se caso sinta tontura. Monitorar pressão arterial. Com vardenafila: a combinação com tansulosina é explicitamente contraindicada em bula."},
{"med1":["tansulosina","cloridrato de tansulosina","flomax","omnic"],"med2":["cetoconazol","ketoconazol","itraconazol","voriconazol","claritromicina","ritonavir"],"nivel":"moderado","titulo":"Tansulosina + Inibidores Fortes CYP3A4 (Aumento de Exposição)","mecanismo":"A tansulosina é metabolizada por CYP3A4 e CYP2D6. Inibidores potentes de CYP3A4 reduzem seu clearance, podendo elevar a AUC em 2–3 vezes com cetoconazol.","efeito":"Hipotensão aumentada, tontura, palpitações e risco de síncope por vasodilatação excessiva.","conduta":"⚠️ Evitar coadministração com inibidores fortes de CYP3A4. Se necessário, monitorar pressão arterial e sintomas posturais. Preferir alternativa antifúngica com menor inibição de CYP3A4 (fluconazol tópico, nistatina)."},
{"med1":["tansulosina","cloridrato de tansulosina","flomax","omnic"],"med2":["fluoxetina","paroxetina","cimetidina"],"nivel":"leve","titulo":"Tansulosina + Inibidores CYP2D6/Cimetidina (Aumento de Nível)","mecanismo":"Fluoxetina e paroxetina inibem CYP2D6 (via metabólica secundária da tansulosina). A cimetidina inibe CYP2D6 e a secreção tubular renal. Em combinação, os níveis de tansulosina podem aumentar modestamente.","efeito":"Leve aumento da exposição à tansulosina — hipotensão postural discreta, tontura. Clinicamente relevante principalmente em pacientes com hipotensão basal.","conduta":"✅ Geralmente sem necessidade de ajuste. Monitorar sintomas posturais ao iniciar a associação. Preferir ranitidina, famotidina ou IBP como alternativa à cimetidina."},
{"med1":["hidralazina","hydralazine","apresolina"],"med2":["diazóxido","minoxidil","nitratos","nitroglicerina","nitroprussiato"],"nivel":"moderado","titulo":"Hidralazina + Outros Vasodilatadores (Hipotensão Aditiva)","mecanismo":"Todos os vasodilatadores diretos compartilham o mecanismo de relaxamento da musculatura lisa vascular. A combinação de hidralazina com outros agentes vasodilatadores produz queda pressórica aditiva e taquicardia reflexa.","efeito":"Hipotensão grave, taquicardia reflexa excessiva, tontura e síncope. Risco aumentado em pacientes com volume circulante reduzido.","conduta":"⚠️ Monitorar pressão arterial e frequência cardíaca. Em ICC refratária, a combinação hidralazina + nitrato é estratégia validada (estudo A-HeFT) — neste contexto o benefício supera o risco com titulação cuidadosa. Titular a partir das menores doses."},
{"med1":["hidralazina","hydralazine","apresolina"],"med2":["ibuprofeno","diclofenaco","naproxeno","cetoprofeno","meloxicam","celecoxibe","aine","anti-inflamatório"],"nivel":"moderado","titulo":"Hidralazina + AINEs (Redução do Efeito Anti-hipertensivo)","mecanismo":"Os AINEs inibem a síntese de prostaglandinas vasodilatadoras renais (PGE2, PGI2), causando retenção de sódio e água e vasoconstricção. Este efeito antagoniza diretamente a vasodilatação mediada pela hidralazina.","efeito":"Perda parcial ou total do controle da pressão arterial. Risco de IRA aguda por redução do fluxo renal em pacientes com doença renal crônica ou insuficiência cardíaca.","conduta":"⚠️ Evitar uso regular de AINEs em hipertensos. Se analgesia necessária, preferir paracetamol. Monitorar a pressão arterial ao introduzir AINE. Avaliar função renal periodicamente."},
{"med1":["hidralazina","hydralazine","apresolina"],"med2":["inibidor mao","imao","fenelzina","tranilcipromina","moclobemida"],"nivel":"moderado","titulo":"Hidralazina + IMAOs (Hipotensão Grave)","mecanismo":"Os IMAOs inibem a degradação de catecolaminas e potencializam a vasodilatação periférica. Combinados com hidralazina, causam hipotensão sinérgica por mecanismos complementares.","efeito":"Hipotensão grave, colapso hemodinâmico, tontura intensa e síncope.","conduta":"⚠️ Evitar combinação. Se necessária, iniciar hidralazina com dose mínima e monitorar pressão arterial em posição supina e ortostática. Ter disponibilidade de fluidos IV para correção de hipotensão grave."},
{"med1":["sulpirida","sulpiride","dogmatil","equilid"],"med2":["amiodarona","sotalol","dronedarona","haloperidol","clorpromazina","tioridazina","ziprasidona","metadona","ciprofloxacino","levofloxacino","moxifloxacino","azitromicina","domperidona"],"nivel":"moderado","titulo":"Sulpirida + Fármacos que Prolongam QTc (Risco de Torsades de Pointes)","mecanismo":"A sulpirida bloqueia receptores D2 dopaminérgicos e tem efeito intrínseco sobre canais de potássio cardíacos (bloqueio de IKr), prolongando o intervalo QTc. A combinação com outros fármacos que prolongam o QT é aditiva.","efeito":"Prolongamento excessivo do QTc (>500 ms) com risco de torsades de pointes e morte súbita. O risco é maior em mulheres, hipocalemia e bradicardia.","conduta":"⚠️ Realizar ECG basal e periódico. Corrigir hipocalemia e hipomagnesemia. Evitar combinação com outros antipsicóticos ou agentes que prolongam QT. Suspender se QTc >500 ms."},
{"med1":["sulpirida","sulpiride","dogmatil","equilid"],"med2":["levodopa","carbidopa","pramipexol","ropinirol","bromocriptina","cabergolina"],"nivel":"moderado","titulo":"Sulpirida + Agonistas Dopaminérgicos (Antagonismo Terapêutico)","mecanismo":"A sulpirida bloqueia receptores D2 dopaminérgicos de forma seletiva. Os agonistas dopaminérgicos usados no Parkinson e hiperprolactinemia estimulam justamente estes receptores. Há antagonismo farmacológico direto.","efeito":"Redução da eficácia dos agonistas dopaminérgicos — piora do Parkinson (rigidez, tremor, bradicinesia) e elevação da prolactina com retorno de galactorreia ou amenorreia.","conduta":"🚫 Contraindicado em pacientes com Parkinson. Em hiperprolactinemia tratada com cabergolina/bromocriptina, evitar sulpirida. Considerar antipsicótico alternativo com menor bloqueio D2 (quetiapina, clozapina) se antipsicótico for imprescindível no Parkinson."},
{"med1":["sulpirida","sulpiride","dogmatil","equilid"],"med2":["antiácido","hidróxido de magnésio","hidróxido de alumínio","sucralfato"],"nivel":"leve","titulo":"Sulpirida + Antiácidos (Redução de Absorção)","mecanismo":"Os antiácidos à base de hidróxido de alumínio ou magnésio e o sucralfato reduzem a absorção oral da sulpirida por adsorção e aumento do pH gástrico, diminuindo sua biodisponibilidade em até 40%.","efeito":"Redução dos níveis plasmáticos de sulpirida, com possível perda parcial de eficácia antipsicótica ou antiemética.","conduta":"✅ Espaçar a sulpirida e antiácidos por pelo menos 2 horas. Preferir IBP ou bloqueador H2 como alternativa antiácida de longo prazo se necessário."},
{"med1":["droperidol","inapsine"],"med2":["amiodarona","sotalol","haloperidol","clorpromazina","tioridazina","ziprasidona","quetiapina","metadona","ciprofloxacino","moxifloxacino","azitromicina","ondansetrona","domperidona","cisaprida"],"nivel":"grave","titulo":"Droperidol + Fármacos que Prolongam QTc (Torsades de Pointes — Contraindicado)","mecanismo":"O droperidol é um butirofenona com potente bloqueio de canais de potássio cardíacos (IKr/hERG), causando prolongamento significativo do QTc. A combinação com outros agentes que prolongam o QT amplifica o risco de forma aditiva e potencialmente sinérgica.","efeito":"Torsades de pointes, fibrilação ventricular e morte súbita. Casos fatais levaram ao acréscimo de black box warning pela FDA. O risco é dose-dependente e maior em mulheres, hipocalemia e insuficiência cardíaca.","conduta":"🚫 Contraindicado com outros prolongadores de QT. Realizar ECG antes da administração (QTc basal >440 ms em homens ou >450 ms em mulheres contraindica o droperidol). Monitorar ECG por 2–3 horas após administração. Corrigir eletrólitos antes do uso."},
{"med1":["droperidol","inapsine"],"med2":["depressor snc","álcool","opioide","fentanila","morfina","tramadol","benzodiazepínico","midazolam","diazepam","clonazepam","propofol","cetamina"],"nivel":"moderado","titulo":"Droperidol + Depressores do SNC (Sedação e Depressão Respiratória Aditivas)","mecanismo":"O droperidol tem efeito depressor do SNC via bloqueio dopaminérgico e antagonismo alfa-adrenérgico. A combinação com opioides, benzodiazepínicos e outros anestésicos amplifica a depressão neurológica e respiratória de forma aditiva.","efeito":"Sedação profunda, depressão respiratória, apneia e hipotensão. Em contexto perioperatório, é combinação intencionalmente usada — o risco é de subdosagem ou superdosagem por interação imprevista.","conduta":"⚠️ Em contexto de sedação/anestesia: reduzir doses de ambos os agentes. Monitorar ventilação e oximetria continuamente. Ter antagonistas disponíveis (naloxona para opioides, flumazenil para benzodiazepínicos). Em uso off-label como antiemético em pronto-socorro: evitar associação não monitorizada."},
{"med1":["hidroxizina","cloridrato de hidroxizina","atarax","ucerax"],"med2":["álcool","benzodiazepínico","opioide","barbitúrico","antidepressivo tricíclico","mirtazapina","quetiapina","clonazepam","diazepam","alprazolam","morfina","codeína"],"nivel":"moderado","titulo":"Hidroxizina + Depressores do SNC (Sedação Aditiva)","mecanismo":"A hidroxizina é antagonista H1 de primeira geração com penetração no SNC. Depressores do SNC (benzodiazepínicos, opioides, álcool, antidepressivos sedativos) amplificam seu efeito sedativo por ação aditiva sobre diferentes receptores.","efeito":"Sedação excessiva, déficit cognitivo, comprometimento psicomotor, depressão respiratória em doses elevadas. Risco aumentado de quedas em idosos.","conduta":"⚠️ Iniciar com doses baixas. Orientar sobre prejuízo na condução de veículos e operação de máquinas. Evitar álcool. Em idosos: preferir alternativas com menor penetração no SNC (cetirizina, loratadina para alergias). Monitorar sedação e função respiratória."},
{"med1":["hidroxizina","cloridrato de hidroxizina","atarax","ucerax"],"med2":["amiodarona","sotalol","haloperidol","tioridazina","clorpromazina","metadona","ciprofloxacino","moxifloxacino","azitromicina","eritromicina"],"nivel":"moderado","titulo":"Hidroxizina + Fármacos que Prolongam QTc","mecanismo":"A hidroxizina bloqueia canais de potássio cardíacos (IKr/hERG) de forma concentração-dependente, prolongando o QTc. A combinação com outros prolongadores de QT produz efeito aditivo sobre a repolarização ventricular.","efeito":"Prolongamento do QTc com risco de torsades de pointes. O risco é especialmente relevante em doses elevadas de hidroxizina (>50 mg), hipocalemia, insuficiência cardíaca e em idosos.","conduta":"⚠️ ECG basal em pacientes com fatores de risco cardiovascular antes de iniciar hidroxizina em doses ≥50 mg. Evitar combinação com outros QT-prolongadores. Corrigir hipocalemia e hipomagnesemia. Usar a menor dose eficaz pelo menor tempo necessário."},
{"med1":["hidroxizina","cloridrato de hidroxizina","atarax","ucerax"],"med2":["inibidor mao","imao","fenelzina","tranilcipromina","selegilina","moclobemida"],"nivel":"moderado","titulo":"Hidroxizina + IMAOs (Potencialização Anticolinérgica e Sedação)","mecanismo":"Os IMAOs potencializam os efeitos anticolinérgicos e sedativos dos anti-histamínicos H1 ao inibir a degradação de acetilcolina e neurotransmissores monoaminérgicos. A hidroxizina, com sua carga anticolinérgica intrínseca, tem seus efeitos amplificados.","efeito":"Sedação excessiva, confusão mental, retenção urinária, constipação, visão turva e potencial crise hipertensiva paradoxal por efeito adrenérgico residual.","conduta":"⚠️ Evitar combinação. Se uso for imprescindível, iniciar com dose mínima e monitorar pressão arterial, estado mental e sinais anticolinérgicos. Washout de 14 dias após suspensão do IMAO é prudente."},
{"med1":["clordiazepóxido","clordiazepoxido","librium"],"med2":["álcool","opioide","barbitúrico","morfina","codeína","fentanila","fenobarbital","quetiapina","mirtazapina"],"nivel":"grave","titulo":"Clordiazepóxido + Depressores do SNC / Álcool (Depressão Respiratória)","mecanismo":"O clordiazepóxido potencializa o GABA no SNC (agonista de receptor GABA-A). Depressores do SNC e álcool atuam por mecanismos complementares — opioides via receptores µ, barbitúricos via GABA-A (sítio diferente), álcool via múltiplos canais. A combinação é sinérgica.","efeito":"Depressão respiratória grave, coma, morte. Risco especialmente elevado com opioides — combinação responsável pela maioria das mortes por overdose intencional e não-intencional de benzodiazepínicos.","conduta":"🚫 Evitar combinação com opioides e álcool. Se uso concomitante for imprescindível: monitorização contínua da oximetria, ter naloxona disponível para o componente opioide, e flumazenil para o benzodiazepínico. Orientar enfaticamente sobre o risco de consumo de álcool."},
{"med1":["clordiazepóxido","clordiazepoxido","librium"],"med2":["fluconazol","itraconazol","cetoconazol","ketoconazol","eritromicina","cimetidina"],"nivel":"moderado","titulo":"Clordiazepóxido + Inibidores CYP3A4 (Aumento de Exposição — Sedação Prolongada)","mecanismo":"O clordiazepóxido é metabolizado por CYP3A4 a metabólitos ativos (desmetilclordiazepóxido, demoxepam) que têm meia-vida longa. Inibidores de CYP3A4 reduzem o clearance do fármaco pai e de seus metabólitos, acumulando efeito sedativo.","efeito":"Sedação prolongada e excessiva, ataxia, confusão mental, comprometimento da memória. Em idosos: risco de quedas e delirium.","conduta":"⚠️ Monitorar sedação ao introduzir inibidor de CYP3A4. Considerar redução de dose de clordiazepóxido ou substituição por oxazepam/lorazepam (conjugação direta, sem dependência de CYP3A4). Preferir ranitidina ou IBP no lugar da cimetidina."},
{"med1":["tibolona","livial"],"med2":["warfarina","varfarina","acenocumarol","sintrom"],"nivel":"moderado","titulo":"Tibolona + Anticoagulantes Cumarínicos (Redução do RNI)","mecanismo":"A tibolona e seus metabólitos têm atividade androgênica e estrogênica mista. O componente estrogênico aumenta a síntese de fatores de coagulação hepáticos, tendendo a reduzir o efeito da warfarina. Adicionalmente, a tibolona pode alterar o metabolismo hepático da warfarina via CYP.","efeito":"Queda do RNI com risco de inadequação da anticoagulação — risco trombótico. A direção oposta (elevação do RNI) também foi descrita em casos isolados, tornando o efeito imprevisível.","conduta":"⚠️ Monitorar RNI com maior frequência ao iniciar ou suspender tibolona. Ajustar dose de anticoagulante conforme necessário. Informar o paciente sobre sinais de trombose e sangramento."},
{"med1":["tibolona","livial"],"med2":["rifampicina","rifampin","carbamazepina","fenitoína","fenobarbital"],"nivel":"moderado","titulo":"Tibolona + Indutores Enzimáticos CYP3A4 (Redução de Eficácia)","mecanismo":"A tibolona é extensamente metabolizada por CYP3A4. Indutores potentes desta isoenzima aumentam seu clearance, reduzindo significativamente os níveis plasmáticos dos metabólitos ativos.","efeito":"Perda de eficácia do tratamento de sintomas do climatério (fogachos, ressecamento vaginal) e da ação preventiva sobre a densidade óssea.","conduta":"⚠️ Evitar combinação com rifampicina. Com antiepilépticos indutores (carbamazepina, fenitoína): considerar alternativa hormonal não dependente de CYP3A4 ou troca para antiepiléptico não-indutor (levetiracetam, lamotrigina)."},
{"med1":["tibolona","livial"],"med2":["tamoxifeno","letrozol","anastrozol","exemestano"],"nivel":"grave","titulo":"Tibolona + Terapia Hormonal para Câncer de Mama (Antagonismo — Contraindicado)","mecanismo":"A tibolona possui atividade estrogênica intrínseca via seus metabólitos. Em mulheres com câncer de mama hormônio receptor-positivo em tratamento com tamoxifeno (SERM anti-estrogênico) ou inibidores de aromatase, a atividade estrogênica da tibolona antagoniza diretamente a terapia oncológica.","efeito":"Estimulação estrogênica de células tumorais residuais — potencial aumento do risco de recorrência do câncer de mama. O estudo LIBERATE demonstrou maior recorrência de câncer de mama em pacientes usando tibolona com histórico de câncer.","conduta":"🚫 Contraindicado em mulheres com histórico de câncer de mama ou em uso de tamoxifeno/inibidores de aromatase. Para sintomas do climatério neste contexto, considerar alternativas não-hormonais (venlafaxina para fogachos, lubrificantes vaginais)."},
{"med1":["testosterona","testosterona cipionato","testosterona enantato","testosterona undecanoato","androgel","nebido"],"med2":["warfarina","varfarina","acenocumarol","sintrom"],"nivel":"moderado","titulo":"Testosterona + Anticoagulantes Cumarínicos (Potencialização do Efeito)","mecanismo":"Os androgênios reduzem a síntese hepática dos fatores de coagulação dependentes de vitamina K (II, VII, IX, X) e podem alterar o metabolismo hepático da warfarina via CYP2C9. O efeito líquido é uma potencialização do anticoagulante.","efeito":"Elevação do RNI com risco de sangramento. A interação é clinicamente relevante e descrita em bula — o início de testosterona em pacientes anticoagulados pode levar a elevação marcada e rápida do RNI.","conduta":"⚠️ Monitorar RNI semanalmente nas primeiras 4–6 semanas após início da testosterona. Reduzir dose de warfarina proativamente em ~25–30% ao iniciar testosterona. Ajustar conforme resposta clínica. O mesmo cuidado se aplica à suspensão da testosterona (RNI pode cair)."},
{"med1":["testosterona","testosterona cipionato","testosterona enantato","androgel","nebido"],"med2":["insulina","insulina nph","insulina glargina","insulina asparte","glibenclamida","glicazida","glimepirida","metformina"],"nivel":"moderado","titulo":"Testosterona + Antidiabéticos (Potencialização Hipoglicêmica)","mecanismo":"A testosterona aumenta a sensibilidade à insulina e promove captação de glicose pelo músculo esquelético. Em diabéticos em uso de insulina ou secretagogos, esta melhora da sensibilidade pode resultar em hipoglicemia se as doses não forem reajustadas.","efeito":"Hipoglicemia, especialmente nas primeiras semanas de reposição de testosterona. O efeito é benéfico para o controle glicêmico a longo prazo, mas exige monitoramento no período de adaptação.","conduta":"⚠️ Monitorar glicemia com maior frequência ao iniciar testosterona em diabéticos. Pode ser necessário reduzir doses de insulina ou secretagogos. O benefício metabólico da normalização da testosterona em hipogonadismo é real — não contraindicar, mas ajustar o esquema hipoglicemiante."},
{"med1":["testosterona","testosterona cipionato","testosterona enantato","androgel","nebido"],"med2":["corticosteroide","prednisona","prednisolona","dexametasona","hidrocortisona","betametasona"],"nivel":"leve","titulo":"Testosterona + Corticosteroides (Edema e Retenção Hídrica Aditivos)","mecanismo":"Tanto a testosterona quanto os corticosteroides causam retenção de sódio e água por mecanismos distintos (androgênio via receptores androgênicos renais; corticosteroide via receptor mineralocorticoide). A combinação amplifica a retenção hídrica.","efeito":"Edema periférico, elevação da pressão arterial, exacerbação de insuficiência cardíaca. Em homens com ICC, a associação requer monitoramento rigoroso.","conduta":"⚠️ Monitorar peso, pressão arterial e sinais de edema. Em pacientes com ICC ou hipertensão mal controlada, reavaliar a necessidade da combinação. Reduzir a dose de corticosteroide ao mínimo necessário."},
{"med1":["teriparatida","pth 1-34","forteo"],"med2":["digoxina","digitoxina"],"nivel":"moderado","titulo":"Teriparatida + Digoxina (Hipercalcemia → Toxicidade Digitálica)","mecanismo":"A teriparatida eleva transitoriamente o cálcio sérico (hipercalcemia aguda nas horas após injeção). A hipercalcemia potencia a toxicidade da digoxina ao aumentar a afinidade do glicosídeo pela Na-K-ATPase miocárdica, reduzindo o limiar de arritmias.","efeito":"Arritmias digitálicas (extrassístoles, bigeminismo, bloqueio AV) associadas aos picos de calcemia pós-injeção de teriparatida.","conduta":"⚠️ Monitorar calcemia e ECG periodicamente. Preferir administrar teriparatida quando o paciente não estiver em uso de digoxina, ou discutir com o cardiologista a necessidade de reduzir a dose de digoxina. Monitorar sinais de toxicidade digitálica (náusea, visão amarelada, bradiarritmias)."},
{"med1":["teriparatida","pth 1-34","forteo"],"med2":["calcitriol","alfacalcidol","vitamina d ativa","rocaltrol"],"nivel":"moderado","titulo":"Teriparatida + Calcitriol / Vitamina D Ativa (Hipercalcemia Aditiva)","mecanismo":"A teriparatida estimula a produção renal de calcitriol (1,25-OH vitamina D) e aumenta a absorção intestinal de cálcio. O calcitriol exógeno soma este efeito, podendo causar hipercalcemia clinicamente relevante.","efeito":"Hipercalcemia: náuseas, poliúria, nefrolitíase, calcificação de tecidos moles, arritmias em casos graves. Confusão mental em idosos.","conduta":"⚠️ Monitorar calcemia e calciúria de 24h ao iniciar teriparatida em pacientes já usando calcitriol. Pode ser necessário reduzir ou suspender o calcitriol. Manter ingestão hídrica adequada. Suplementação de cálcio elementar (500–1.000 mg/dia) é suficiente na maioria dos pacientes em teriparatida sem necessidade de calcitriol."},
{"med1":["raloxifeno","cloridrato de raloxifeno","evista"],"med2":["warfarina","varfarina","acenocumarol","sintrom"],"nivel":"moderado","titulo":"Raloxifeno + Anticoagulantes Cumarínicos (Redução do RNI)","mecanismo":"O raloxifeno compete com a warfarina pela ligação a proteínas plasmáticas e pode reduzir modestamente o RNI por mecanismo ainda não completamente esclarecido — possivelmente relacionado à sua atividade parcialmente estrogênica sobre a síntese de fatores de coagulação hepáticos.","efeito":"Redução do RNI em 10% com o estudo de warfarina; o efeito é modesto mas pode ser clinicamente relevante em pacientes com anticoagulação difícil de controlar. Risco de subcoagulação.","conduta":"⚠️ Monitorar RNI ao iniciar ou suspender raloxifeno. Ajustar dose de warfarina se necessário. Informar o paciente sobre a interação e os sinais de tromboembolismo (dor em panturrilha, dispneia)."},
{"med1":["raloxifeno","cloridrato de raloxifeno","evista"],"med2":["colestiramina","questran"],"nivel":"moderado","titulo":"Raloxifeno + Colestiramina (Redução de Absorção em 60%)","mecanismo":"A colestiramina, resina sequestrador de ácidos biliares, liga-se ao raloxifeno no trato gastrointestinal, impedindo sua absorção e circulação entero-hepática. A biodisponibilidade do raloxifeno é reduzida em aproximadamente 60%.","efeito":"Redução marcante da eficácia do raloxifeno na prevenção e tratamento da osteoporose e na redução do risco de câncer de mama.","conduta":"⚠️ Não coadministrar. Espaçar os dois fármacos por pelo menos 4–6 horas. Idealmente, evitar o uso combinado crônico — considerar estatina ou ezetimiba no lugar da colestiramina para controle lipídico em pacientes usando raloxifeno."},
{"med1":["raloxifeno","cloridrato de raloxifeno","evista"],"med2":["estrogênio","estradiol","estriol","conjugated estrogens","premarin","tibolona"],"nivel":"grave","titulo":"Raloxifeno + Estrogênios (Antagonismo Farmacológico — Contraindicado)","mecanismo":"O raloxifeno é um modulador seletivo do receptor de estrogênio (SERM) com atividade antagonista no tecido mamário e uterino. A administração simultânea de estrogênios exógenos compete pelos mesmos receptores e antagoniza os efeitos preventivos do raloxifeno sobre câncer de mama.","efeito":"Perda da eficácia protetora do raloxifeno contra câncer de mama. Adicionalmente, a combinação promove estimulação endometrial não antagonizada, aumentando o risco de hiperplasia e carcinoma endometrial.","conduta":"🚫 Contraindicado. Raloxifeno não deve ser usado concomitantemente com nenhuma forma de estrogênio sistêmico. Se a paciente precisar de alívio de sintomas vasomotores intensos, discutir estratégias alternativas com o ginecologista."},
{"med1":["mesalazina","mesalamine","pentasa","asacol","mezavant"],"med2":["azatioprina","imuran","mercaptopurina","purinethol"],"nivel":"moderado","titulo":"Mesalazina + Azatioprina / 6-Mercaptopurina (Inibição de TPMT — Mielossupressão)","mecanismo":"A mesalazina (5-ASA) e seus metabólitos inibem a tiopurina metiltransferase (TPMT), a enzima responsável pela inativação da 6-tioguanina (metabólito citotóxico da azatioprina). A inibição resulta em acúmulo de 6-TGN — elevando o risco de toxicidade hematológica.","efeito":"Leucopenia, trombocitopenia e anemia — às vezes grave. O efeito é análogo ao que ocorre com a sulfassalazina e é mais pronunciado em indivíduos com atividade basal reduzida de TPMT (metabolizadores intermediários ou lentos).","conduta":"⚠️ Monitorar hemograma mensalmente. Considerar genotipagem ou fenotipagem de TPMT antes de combinar. Reduzir dose de azatioprina em 25–50% ao associar mesalazina. Esta combinação é usada na doença de Crohn — o benefício pode superar o risco com monitoramento adequado."},
{"med1":["mesalazina","mesalamine","pentasa","asacol"],"med2":["lactulose","laxante osmótico"],"nivel":"leve","titulo":"Mesalazina + Lactulose (Redução da Liberação Colônica)","mecanismo":"Formulações de mesalazina com liberação pH-dependente requerem pH colônico básico para liberar o fármaco. A lactulose produz ácidos orgânicos (ácido láctico, ácido acético) pela fermentação bacteriana, acidificando o lúmen colônico e reduzindo a dissolução das formulações de mesalazina com cobertura entérica.","efeito":"Redução da biodisponibilidade colônica da mesalazina — potencial perda de eficácia no tratamento de colite ulcerativa.","conduta":"✅ Preferir formulações de mesalazina com liberação por tempo ou pressão (ex: Pentasa® multimatrix) ao invés das pH-dependentes quando lactulose for necessária. Se não for possível trocar a formulação, monitorar resposta clínica e endoscópica."},
{"med1":["toxina botulínica","toxina botulinica","botox","dysport","xeomin","botulinum toxin"],"med2":["amicacina","gentamicina","tobramicina","estreptomicina","neomicina","aminoglicosídeo"],"nivel":"moderado","titulo":"Toxina Botulínica + Aminoglicosídeos (Potencialização do Bloqueio Neuromuscular)","mecanismo":"Os aminoglicosídeos inibem a liberação de acetilcolina na junção neuromuscular (interferência com a entrada de Ca²⁺ pré-sináptico). A toxina botulínica bloqueia a exocitose de vesículas de acetilcolina. Os mecanismos são complementares — produzindo bloqueio neuromuscular aditivo.","efeito":"Fraqueza muscular generalizada mais intensa do que o esperado, disfagia, dispneia e, em casos graves, insuficiência respiratória por paralisia dos músculos respiratórios.","conduta":"⚠️ Evitar aminoglicosídeos sistêmicos nas semanas antes e após aplicação de toxina botulínica. Monitorar força muscular, deglutição e função respiratória. Em pacientes que requerem aminoglicosídeo por infecção grave, postergar a aplicação da toxina ou reduzir a dose."},
{"med1":["toxina botulínica","toxina botulinica","botox","dysport","xeomin"],"med2":["bloqueador neuromuscular","vecurônio","rocurônio","atracúrio","pancurônio","succinilcolina"],"nivel":"grave","titulo":"Toxina Botulínica + Bloqueadores Neuromusculares (Paralisia Potencializada)","mecanismo":"Os bloqueadores neuromusculares competitivos (vecurônio, rocurônio) e despolarizantes (succinilcolina) atuam na placa motora — o mesmo local onde a toxina botulínica bloqueia a liberação de acetilcolina. A combinação resulta em bloqueio neuromuscular profundo e prolongado.","efeito":"Paralisia neuromuscular muito prolongada com necessidade de ventilação mecânica por período estendido. Recuperação da função neuromuscular significativamente atrasada após o procedimento anestésico.","conduta":"⚠️ Informar o anestesiologista sobre o uso recente de toxina botulínica antes de qualquer cirurgia. Reduzir a dose de bloqueador neuromuscular e monitorar com neuroestimulador (train-of-four). Ter disponibilidade de sugamadex para reversão de rocurônio/vecurônio."},
{"med1":["colesevelam","welchol"],"med2":["levotiroxina","tiroxina","synthroid","puran","euthyrox"],"nivel":"moderado","titulo":"Colesevelam + Levotiroxina (Redução de Absorção — Hipotireoidismo)","mecanismo":"O colesevelam, como resina sequestrador de ácidos biliares, liga-se à levotiroxina no trato gastrointestinal impedindo sua absorção. Em estudos, o colesevelam reduz a absorção de levotiroxina de forma clinicamente relevante.","efeito":"Redução dos níveis séricos de T4 livre e T3 com piora do hipotireoidismo — fadiga, ganho de peso, constipação, intolerância ao frio. TSH pode elevar-se mesmo sem mudança de dose de levotiroxina.","conduta":"⚠️ Administrar levotiroxina ≥4 horas antes do colesevelam. Monitorar TSH 6–8 semanas após início do colesevelam. Pode ser necessário aumentar a dose de levotiroxina. O ajuste inverso é necessário ao suspender o colesevelam."},
{"med1":["colesevelam","welchol"],"med2":["fenitoína","hidantal","carbamazepina","tegretol","ciclosporina","sandimmun","etinilestradiol","anticoncepcional oral"],"nivel":"moderado","titulo":"Colesevelam + Múltiplos Fármacos (Adsorção Intestinal — Redução de Absorção)","mecanismo":"O colesevelam adsorve fármacos lipofílicos e de circulação entero-hepática no lúmen intestinal, reduzindo sua absorção. Fenitoína, carbamazepina, ciclosporina e contraceptivos orais (etinilestradiol) têm biodisponibilidade reduzida de forma clínica e farmacocineticamente significativa.","efeito":"Redução dos níveis plasmáticos com risco de falha terapêutica — crises epilépticas com antiepilépticos, rejeição de transplante com ciclosporina, gestação não planejada com contraceptivos orais.","conduta":"⚠️ Administrar todos os fármacos orais ≥4 horas antes do colesevelam, preferencialmente com monitoramento de níveis séricos quando disponível. Para anticoncepção: considerar método de barreira adicional. Com ciclosporina: monitorar nível sérico com maior frequência."},
{"med1":["colesevelam","welchol"],"med2":["warfarina","varfarina","acenocumarol"],"nivel":"leve","titulo":"Colesevelam + Warfarina (Redução de Absorção de Vitamina K — Variação Imprevisível)","mecanismo":"O colesevelam reduz a absorção de vitamina K lipossolúvel ao sequestrá-la junto com os ácidos biliares, potencialmente aumentando o RNI. Paradoxalmente, pode também reduzir a absorção da própria warfarina se administrados próximos. O efeito líquido é variável entre pacientes.","efeito":"Instabilidade do RNI — elevação ou queda dependendo do balanço entre menor absorção de warfarina e menor absorção de vitamina K.","conduta":"⚠️ Monitorar RNI com maior frequência ao iniciar colesevelam. Administrar warfarina ≥4 horas antes do colesevelam para minimizar a interação. Manter ingestão de vitamina K estável."},
{"med1":["fexofenadina","allegra","fexofenadine"],"med2":["eritromicina","claritromicina","cetoconazol","ketoconazol","itraconazol"],"nivel":"moderado","titulo":"Fexofenadina + Eritromicina / Cetoconazol (Inibição P-gp e OATP — Aumento de Nível)","mecanismo":"A fexofenadina é substrato de P-glicoproteína (P-gp) intestinal e dos transportadores OATP1A2/OATP2B1. A eritromicina inibe P-gp e aumenta a absorção intestinal da fexofenadina em ~82%. O cetoconazol inibe adicionalmente CYP3A4 e transportadores orgânicos. Nenhuma das interações envolve sedação significativa, mas aumenta exposição.","efeito":"Elevação de 2–3 vezes nos níveis plasmáticos de fexofenadina. Em doses habituais, a fexofenadina tem perfil seguro mesmo com níveis elevados — mas o risco de prolongamento de QTc aumenta em doses muito altas em combinação com eritromicina.","conduta":"⚠️ Evitar doses supraterapêuticas de fexofenadina em uso combinado. Monitorar ECG se fexofenadina + eritromicina em doses elevadas ou em pacientes com cardiopatia. A interação tem relevância clínica limitada em doses habituais (120–180 mg/dia)."},
{"med1":["fexofenadina","allegra","fexofenadine"],"med2":["suco de maçã","suco de toranja","suco de laranja","grapefruit"],"nivel":"moderado","titulo":"Fexofenadina + Sucos de Frutas (Redução de Absorção via OATP)","mecanismo":"Sucos de maçã, toranja (grapefruit) e laranja inibem potentemente os transportadores OATP1A2 e OATP2B1 intestinais, responsáveis pela absorção ativa da fexofenadina. O suco de toranja reduz a AUC da fexofenadina em até 36–47%.","efeito":"Redução significativa dos níveis plasmáticos de fexofenadina — potencial perda de controle de sintomas alérgicos (rinorreia, espirros, urticária).","conduta":"⚠️ Orientar o paciente a tomar fexofenadina com água, não com sucos de frutas. Espaçar o consumo de sucos por pelo menos 4 horas da tomada do comprimido. Esta é uma das raras interações fármaco-alimento que reduz (não aumenta) a absorção."},
{"med1":["trimetazidina","vastarel","preductal"],"med2":["levodopa","carbidopa","pramipexol","ropinirol","bromocriptina","amantadina"],"nivel":"moderado","titulo":"Trimetazidina + Agentes Antiparkinsonianos (Antagonismo Dopaminérgico)","mecanismo":"A trimetazidina é uma piperazina que pode causar parkinsonismo e síndrome das pernas inquietas ao interferir com a transmissão dopaminérgica central (mecanismo não completamente esclarecido, possivelmente inibição de DOPA descarboxilase). Combinada com antiparkinsonianos, pode antagonizar seu efeito ou mascarar a progressão da doença.","efeito":"Piora dos sintomas parkinsonianos — aumento de tremor, rigidez e bradicinesia. Síndrome das pernas inquietas de difícil controle. Em alguns pacientes, a trimetazidina por si só pode induzir parkinsonismo reversível.","conduta":"⚠️ Evitar trimetazidina em pacientes com Parkinson ou síndrome das pernas inquietas. Monitorar sintomas motores em todos os pacientes em uso crônico. Suspender trimetazidina ao primeiro sinal de parkinsonismo ou síndrome das pernas inquietas — os sintomas são reversíveis após descontinuação (geralmente em 4 meses)."},
{"med1":["trimetazidina","vastarel","preductal"],"med2":["metformina","glucoformin","glifage"],"nivel":"leve","titulo":"Trimetazidina + Metformina (Possível Piora da Função Renal)","mecanismo":"A trimetazidina é eliminada por via renal. Em pacientes com função renal limítrofe, a associação com metformina (que também requer função renal normal para segurança) pode aumentar o risco de acúmulo de ambos os fármacos.","efeito":"Em insuficiência renal, acúmulo de trimetazidina pode potencializar parkinsonismo. Acúmulo de metformina aumenta risco de acidose láctica. O risco é pequeno em função renal normal.","conduta":"✅ Monitorar função renal periodicamente. Ajustar ou suspender ambos os fármacos se TFG < 45 mL/min (trimetazidina contraindicada em TFG <30, metformina em TFG <30–45 conforme protocolo)."},
{"med1":["vildagliptina","galvus","alogliptina","nesina","saxagliptina","onglyza","sitagliptina","januvia","linagliptina","tradjenta"],"med2":["insulina","insulina nph","insulina glargina","insulina asparte","glibenclamida","glicazida","glimepirida"],"nivel":"moderado","titulo":"Inibidores DPP-4 + Insulina / Sulfonilureias (Hipoglicemia Aditiva)","mecanismo":"Os inibidores de DPP-4 potencializam a secreção de insulina induzida pela glicose ao prolongar a ação de GLP-1 e GIP endógenos. Em combinação com insulina exógena ou sulfonilureias (que estimulam a secreção de insulina de forma glicose-independente), o risco de hipoglicemia é aditivo.","efeito":"Hipoglicemia sintomática, especialmente no período pós-prandial. Com sulfonilureias: risco de hipoglicemia em jejum também. O risco é menor do que com combinações de dois secretagogos, mas real.","conduta":"⚠️ Reduzir dose da sulfonilureia ou insulina em 20–25% ao iniciar inibidor DPP-4. Monitorar glicemia de jejum e pós-prandial mais frequentemente nas primeiras 4–6 semanas. Orientar paciente sobre reconhecimento e tratamento de hipoglicemia."},
{"med1":["vildagliptina","galvus","alogliptina","nesina"],"med2":["enalapril","lisinopril","ramipril","captopril","ieca","inibidor da eca"],"nivel":"leve","titulo":"Inibidores DPP-4 + IECAs (Risco Aumentado de Angioedema)","mecanismo":"Os IECAs reduzem a degradação de bradicinina, elevando seus níveis plasmáticos — já que a ECA é responsável pela inativação da bradicinina. Os inibidores de DPP-4 também inibem a degradação de alguns peptídeos vasoativos incluindo substratos relacionados à bradicinina, amplificando levemente o efeito do IECA.","efeito":"Aumento do risco de angioedema — edema de face, língua, laringe e/ou intestinal. O risco é mais relevante com vildagliptina e saxagliptina do que com sitagliptina e linagliptina. A combinação amplifica o angioedema induzido pelo IECA, que por si só afeta 0,1–0,5% dos pacientes.","conduta":"⚠️ Monitorar para angioedema, especialmente nas primeiras semanas. Orientar o paciente a procurar emergência imediatamente em caso de edema de face ou dificuldade para engolir/respirar. Em pacientes com histórico de angioedema por IECA: evitar inibidores DPP-4, especialmente vildagliptina. Considerar BRA no lugar do IECA."},
{"med1":["calcitriol","rocaltrol","calcijex","1,25-dihidroxivitamina d","alfacalcidol","uno alfa"],"med2":["hidroclorotiazida","clortalidona","indapamida","bendroflumetiazida","tiazídico"],"nivel":"moderado","titulo":"Calcitriol + Diuréticos Tiazídicos (Hipercalcemia)","mecanismo":"Os diuréticos tiazídicos aumentam a reabsorção tubular renal de cálcio (via inibição do co-transportador Na-Cl no túbulo distal, com reabsorção compensatória de cálcio). O calcitriol aumenta a absorção intestinal e a mobilização óssea de cálcio. Os efeitos somam-se.","efeito":"Hipercalcemia com sintomas que variam de fraqueza e constipação (leve) a calcificação renal, nefrolitíase, arritmias e alteração do nível de consciência (grave). Síndrome leite-álcali em pacientes que também tomam suplemento de cálcio.","conduta":"⚠️ Monitorar calcemia periodicamente (a cada 3 meses em uso crônico). Orientar hidratação adequada. Ajustar a dose de calcitriol se hipercalcemia detectada. Considerar furosemida como alternativa diurética se hipercalcemia persistir — furosemida aumenta excreção de cálcio."},
{"med1":["calcitriol","rocaltrol","alfacalcidol"],"med2":["colestiramina","questran","colestipol","colesevelam"],"nivel":"moderado","titulo":"Calcitriol + Sequestradores de Ácidos Biliares (Redução de Absorção)","mecanismo":"Os sequestradores de ácidos biliares (colestiramina, colestipol, colesevelam) ligam-se a vitaminas lipossolúveis (A, D, E, K) e hormônios derivados delas no intestino, reduzindo sua absorção. A absorção do calcitriol e de outros metabólitos da vitamina D pode ser reduzida em até 40–50%.","efeito":"Redução dos níveis séricos de calcitriol com piora da absorção intestinal de cálcio — hiocalcemia, hiperparatireoidismo secundário e piora da doença óssea (osteomalácia, raquitismo, doença renal óssea).","conduta":"⚠️ Administrar calcitriol pelo menos 2 horas antes ou 6 horas após o sequestrador de ácidos biliares. Monitorar calcemia e PTH periodicamente. Ajustar dose de calcitriol conforme necessário."},
{"med1":["misoprostol","cytotec"],"med2":["ocitocina","oxitocina","syntocinon","pitocin"],"nivel":"grave","titulo":"Misoprostol + Ocitocina (Hipertonia Uterina — Contraindicado em Simultâneo)","mecanismo":"O misoprostol (análogo da prostaglandina E1) e a ocitocina são uterotônicos de mecanismos distintos mas com efeito final complementar sobre a contratilidade uterina. A combinação simultânea produz tônus uterino excessivo.","efeito":"Hipertonia uterina, taquissistolia, sofrimento fetal agudo por redução do fluxo uteroplacentário, rotura uterina (especialmente em úteros com cicatriz) e óbito fetal.","conduta":"🚫 Contraindicado uso simultâneo. Em protocolos de indução: usar misoprostol e ocitocina sequencialmente com intervalo mínimo de 4 horas. Monitorar cardiotocografia continuamente durante indução. Em caso de hipertonia: descontinuar uterotônico imediatamente e considerar tocolítico (terbutalina, nifedipina)."},
{"med1":["misoprostol","cytotec"],"med2":["antiácido","hidróxido de magnésio","carbonato de cálcio","bicarbonato de sódio"],"nivel":"leve","titulo":"Misoprostol + Antiácidos com Magnésio (Piora da Diarreia)","mecanismo":"O misoprostol causa diarreia dose-dependente por estimulação da secreção de cloreto e inibição da absorção de sódio e água na mucosa intestinal. Os antiácidos à base de Mg²⁺ têm efeito laxativo intrínseco por osmose e estimulação da motilidade. Os efeitos somam-se.","efeito":"Diarreia amplificada e mais prolongada — pode levar a desidratação, especialmente em idosos. A diarreia é já o principal efeito adverso limitante do misoprostol.","conduta":"⚠️ Evitar antiácidos à base de magnésio durante uso de misoprostol. Substituir por carbonato de cálcio ou IBP. Se diarreia grave: suspender temporariamente o misoprostol, garantir hidratação oral e eletrólitos."},
{"med1":["misoprostol","cytotec"],"med2":["ibuprofeno","indometacina","diclofenaco","naproxeno","aine"],"nivel":"moderado","titulo":"Misoprostol + AINEs (Antagonismo do Efeito Gastroprotetor)","mecanismo":"O misoprostol é prescrito para proteção gástrica em pacientes usando AINEs (os AINEs inibem PGE2 da mucosa gástrica). Paradoxalmente, os AINEs inibem a COX e reduzem a produção endógena de prostaglandinas que potencializam a ação do misoprostol. O efeito gastroprotetor do misoprostol pode ser parcialmente antagonizado pelos próprios AINEs.","efeito":"Redução da eficácia gastroprotetora do misoprostol. Maior risco de úlcera péptica e sangramento gastrointestinal do que o esperado. O efeito é mais relevante com doses baixas de misoprostol (200 mcg/dia) e AINEs em doses anti-inflamatórias plenas.","conduta":"⚠️ Preferir IBP (omeprazol, pantoprazol) à misoprostol para gastroproteção em usuários crônicos de AINEs — maior eficácia e melhor tolerabilidade. Se misoprostol for usado, garantir dose adequada (200 mcg 4×/dia) e avaliar endoscopicamente se sintomas persistirem."},
{"med1":["famotidina","pepcid","ranitidina","zantac"],"med2":["cetoconazol","ketoconazol","itraconazol","posaconazol"],"nivel":"moderado","titulo":"Bloqueadores H2 (Famotidina/Ranitidina) + Antifúngicos Azólicos (Redução de Absorção)","mecanismo":"Cetoconazol e itraconazol (forma cápsula) requerem meio ácido gástrico para se dissolverem e serem absorvidos. Os bloqueadores H2 elevam o pH gástrico, reduzindo drasticamente a solubilização e a absorção desses antifúngicos.","efeito":"Redução da biodisponibilidade do cetoconazol em até 95% e do itraconazol cápsulas em 66% com omeprazol (bloqueadores H2 têm efeito menor mas ainda relevante). Falha terapêutica antifúngica — risco de progressão de micose sistêmica.","conduta":"⚠️ Evitar combinação com cetoconazol oral. Com itraconazol: usar formulação solução oral (absorção ácido-independente) em vez de cápsulas. Voriconazol e fluconazol têm absorção independente do pH. Substituir bloqueador H2 por IBP apenas se pH-dependência for problemática — ou espaçar ≥2 horas (eficácia parcial)."},
{"med1":["famotidina","pepcid","ranitidina","zantac"],"med2":["atazanavir","reyataz"],"nivel":"moderado","titulo":"Bloqueadores H2 + Atazanavir (Redução de Absorção do Antirretroviral)","mecanismo":"O atazanavir requer pH gástrico ácido para sua dissolução e absorção. Bloqueadores H2 elevam o pH gástrico, podendo reduzir a Cmax do atazanavir em 18–40% dependendo da dose e do tempo de administração.","efeito":"Redução dos níveis plasmáticos de atazanavir com risco de falha virológica e seleção de resistência ao antirretroviral.","conduta":"⚠️ Administrar atazanavir (com ritonavir como booster) simultaneamente com a refeição e ≥2 horas antes ou 10 horas após o bloqueador H2. Com famotidina: dose máxima de 40 mg/dia. IBPs são contraindicados com atazanavir/ritonavir sem booster adicional. Preferir outros ARVs em pacientes que requerem supressão ácida intensa."},
{"med1":["aceclofenaco","preservex","airtal"],"med2":["warfarina","varfarina","acenocumarol","sintrom","heparina","apixabana","rivaroxabana","dabigatrana"],"nivel":"moderado","titulo":"Aceclofenaco + Anticoagulantes (Risco de Sangramento Aumentado)","mecanismo":"O aceclofenaco inibe COX-1 (reduzindo tromboxano plaquetário e agregação) e lesa a mucosa gastrointestinal. Em combinação com anticoagulantes, o risco de sangramento — especialmente GI — é aditivo. Com warfarina, o aceclofenaco também pode inibir CYP2C9 (modestamente), elevando o RNI.","efeito":"Sangramento gastrointestinal alto (úlcera, gastrite erosiva) e baixo (enterocolopatia por AINEs). Risco de hematúria, epistaxe e equimoses graves em anticoagulados.","conduta":"⚠️ Evitar AINEs em pacientes anticoagulados. Se imprescindível: usar por período mínimo, proteger com IBP em dose plena (omeprazol 40 mg ou pantoprazol 40 mg), monitorar RNI com warfarina. Preferir paracetamol como analgésico de primeira linha."},
{"med1":["aceclofenaco","preservex","airtal"],"med2":["carbonato de lítio","lítio","litio"],"nivel":"moderado","titulo":"Aceclofenaco + Lítio (Elevação do Nível Sérico de Lítio)","mecanismo":"Os AINEs inibem a síntese de prostaglandinas vasodilatadoras renais, reduzindo o fluxo sanguíneo renal e a filtração glomerular. Como o lítio é eliminado exclusivamente por via renal, sua depuração diminui e seus níveis séricos elevam.","efeito":"Toxicidade por lítio: tremor fino evoluindo para grosseiro, ataxia, confusão mental, poliúria paradoxal, convulsões em casos graves. O lítio tem janela terapêutica estreita (0,6–1,2 mEq/L) — elevações de 30–50% podem ser tóxicas.","conduta":"⚠️ Monitorar litemia 5–7 dias após início do AINE. Preferir paracetamol como analgésico em pacientes em uso de lítio. Se AINE for necessário, sulindac é o que menos afeta a excreção renal de lítio — mas ainda requer monitoramento."},
{"med1":["aceclofenaco","preservex","airtal"],"med2":["metotrexato","methotrexate"],"nivel":"grave","titulo":"Aceclofenaco + Metotrexato (Toxicidade por Metotrexato — Potencialmente Fatal)","mecanismo":"Os AINEs reduzem o fluxo sanguíneo renal e inibem os transportadores tubulares OAT1/OAT3, comprometendo a eliminação renal do metotrexato. Em doses anti-inflamatórias baixas (<25 mg/semana para artrite), o risco é menor — em doses oncológicas (>100 mg/m²), pode ser fatal.","efeito":"Acúmulo de metotrexato com toxicidade multissistêmica: mucosites graves, mielossupressão, hepatotoxicidade, nefrotoxicidade e síndrome de Stevens-Johnson. Em doses oncológicas: óbito.","conduta":"🚫 Contraindicado com metotrexato em doses oncológicas. Em doses antirreumatológicas baixas: evitar AINEs nas 24–48h ao redor da tomada semanal de metotrexato; se necessário, monitorar toxicidade (hemograma, creatinina, transaminases). Sempre informar ao paciente para não tomar AINE junto com metotrexato sem orientação médica."},
{"med1":["aceclofenaco","preservex","airtal"],"med2":["enalapril","lisinopril","ramipril","captopril","losartana","valsartana","irbesartana","ieca","bra","sartana"],"nivel":"moderado","titulo":"Aceclofenaco + IECAs/BRAs + Diuréticos (Tríplice Combinação Nefrotóxica)","mecanismo":"IECAs/BRAs dilatam a arteríola eferente renal; os AINEs inibem a dilatação da arteríola aferente (via PGE2/PGI2). Em conjunto, o fluxo glomerular é reduzido de ambos os lados simultaneamente. Diuréticos agravam a depleção de volume. Esta tríplice combinação compromete criticamente a autorregulação renal.","efeito":"IRA aguda — \"tríplice whammy\" — com risco de insuficiência renal que pode requerer diálise. O risco existe mesmo em pacientes com função renal previamente normal, especialmente em idosos, desidratados ou com ICC.","conduta":"🚫 Evitar a tríplice combinação AINE + IECA/BRA + diurético. Se AINE for imprescindível em paciente com IECA/BRA: monitorar creatinina em 48–72h. Hidratação adequada. Suspender diurético temporariamente se possível. Preferir paracetamol como alternativa analgésica."}
,
{"med1":["fesoterodina","fumarato de fesoterodina","toviaz"],"med2":["cetoconazol","ketoconazol","itraconazol","voriconazol","claritromicina","ritonavir"],"nivel":"grave","titulo":"Fesoterodina + Inibidores Fortes CYP3A4 (Contraindicado em IR/IH)","mecanismo":"A fesoterodina é hidrolisada a 5-HMT (metabólito ativo), que é metabolizado por CYP3A4 e CYP2D6. Inibidores potentes de CYP3A4 (cetoconazol, itraconazol, claritromicina, ritonavir) elevam a AUC da fesoterodina em ~2×, aumentando a exposição ao metabólito ativo.","efeito":"Toxicidade anticolinérgica excessiva: retenção urinária, constipação grave, íleo paralítico, taquicardia, visão turva e confusão mental. Em pacientes com IR ou IH moderada/grave, o risco de toxicidade é ainda maior.","conduta":"🚫 Contraindicado em pacientes com IR moderada-grave ou IH moderada-grave em uso de inibidores fortes de CYP3A4. Em pacientes sem comprometimento orgânico: limitar a dose a 4 mg/dia. Monitorar sintomas anticolinérgicos. Preferir solifenacina ou oxibutinina se inibidor CYP3A4 for necessário a longo prazo."},
{"med1":["fesoterodina","fumarato de fesoterodina","toviaz"],"med2":["fluoxetina","paroxetina","bupropiona"],"nivel":"moderado","titulo":"Fesoterodina + Inibidores CYP2D6 (Aumento de Exposição)","mecanismo":"O metabólito ativo da fesoterodina (5-HMT) é também substrato de CYP2D6. Inibidores desta isoenzima (fluoxetina, paroxetina, bupropiona) reduzem seu clearance, elevando a exposição ao metabólito anticolinérgico.","efeito":"Amplificação dos efeitos anticolinérgicos — retenção urinária, constipação, taquicardia, boca seca intensa. Em pacientes metabolizadores lentos de CYP2D6, o efeito é ainda mais pronunciado.","conduta":"⚠️ Limitar fesoterodina a 4 mg/dia em pacientes usando inibidores de CYP2D6. Monitorar sintomas anticolinérgicos, especialmente em idosos. Considerar escitalopram ou sertralina como alternativas ao ISRS (menor inibição de CYP2D6)."},
{"med1":["fesoterodina","fumarato de fesoterodina","toviaz"],"med2":["atropina","biperideno","triexifenidil","escopolamina","dimenidrinato","clorfeniramina","difenidramina","clorpromazina","olanzapina","quetiapina","maprotilina","amitriptilina","imipramina"],"nivel":"moderado","titulo":"Fesoterodina + Outros Anticolinérgicos (Toxicidade Anticolinérgica Aditiva)","mecanismo":"A fesoterodina é antagonista muscarínico com efeitos anticolinérgicos sistêmicos. A adição de outros fármacos com atividade anticolinérgica resulta em carga anticolinérgica cumulativa.","efeito":"Síndrome anticolinérgica: boca seca grave, constipação intestinal, retenção urinária aguda, taquicardia, confusão mental e delirium (especialmente em idosos >65 anos). Risco de íleo paralítico.","conduta":"⚠️ Avaliar a carga anticolinérgica total do paciente (escala ACB ou Anticholinergic Risk Scale). Minimizar o número de agentes anticolinérgicos concomitantes. Em idosos: a fesoterodina já está incluída nos critérios de Beers como fármaco potencialmente inapropriado — revisar a necessidade."},
{"med1":["brometo de glicopirrônio","glicopirrônio","seebri","brometo de umeclidínio","umeclidínio","incruse","tiotrópio","spiriva","aclidínio","bretaris"],"med2":["atropina","biperideno","escopolamina","fesoterodina","solifenacina","oxibutinina","tolterodina","darifenacina","ipratrópio","clorfeniramina","difenidramina","dimenidrinato","amitriptilina","clomipramina","imipramina","clorpromazina","olanzapina","quetiapina"],"nivel":"moderado","titulo":"LAMAs Inalatórios + Outros Anticolinérgicos Sistêmicos (Toxicidade Aditiva)","mecanismo":"Os broncodilatadores anticolinérgicos inalatórios de longa ação (LAMAs) bloqueiam receptores muscarínicos M3 brônquicos. Embora a absorção sistêmica seja baixa, em combinação com anticolinérgicos sistêmicos orais, a carga anticolinérgica total pode atingir níveis clinicamente problemáticos.","efeito":"Retenção urinária (especialmente em homens com HPB), constipação, visão turva, boca seca grave, taquicardia. Em idosos com comprometimento cognitivo: confusão e agravamento do delirium.","conduta":"⚠️ Revisar o perfil anticolinérgico total do paciente. Em homens com HPB sintomática, monitorar sintomas urinários ao iniciar LAMA. Se anticolinérgico oral sistêmico for necessário, preferir agentes com menor penetração no SNC (solifenacina, fesoterodina) e avaliar necessidade de alfabloqueador urinário."},
{"med1":["brometo de glicopirrônio","glicopirrônio","brometo de umeclidínio","umeclidínio","tiotrópio","aclidínio"],"med2":["atenolol","bisoprolol","metoprolol","carvedilol","propranolol","nadolol","timolol"],"nivel":"moderado","titulo":"LAMAs + Betabloqueadores Não-Seletivos (Antagonismo Broncodilatador)","mecanismo":"Os LAMAs causam broncodilatação via bloqueio muscarínico M3. Os betabloqueadores não-seletivos (propranolol, carvedilol, nadolol) bloqueiam receptores β2 brônquicos, causando broncoconstricção que antagoniza parcialmente o efeito broncodilatador.","efeito":"Redução da eficácia broncodilatadora do LAMA. Em pacientes com DPOC grave, pode precipitar broncoespasmo clinicamente relevante. O risco é maior com betabloqueadores não-seletivos do que com cardiosseletivos (bisoprolol, metoprolol).","conduta":"⚠️ Preferir betabloqueadores cardiosseletivos (bisoprolol, metoprolol) em pacientes com DPOC. Em cardiopatas com DPOC grave que necessitam de betabloqueador não-seletivo: titular cuidadosamente e monitorar função pulmonar (VEF1). O benefício cardiovascular dos betabloqueadores em ICC supera o risco em DPOC na maioria dos casos — não contraindicar absolutamente."},
{"med1":["indacaterol","maleato de indacaterol","onbrez","arcapta"],"med2":["atenolol","bisoprolol","metoprolol","carvedilol","propranolol","nadolol"],"nivel":"moderado","titulo":"Indacaterol + Betabloqueadores (Antagonismo Broncodilatador)","mecanismo":"O indacaterol é agonista β2-adrenérgico de longa ação. Os betabloqueadores, especialmente os não-seletivos, bloqueiam receptores β2 brônquicos — antagonizando diretamente o efeito broncodilatador do indacaterol e podendo causar broncoespasmo paradoxal.","efeito":"Redução da eficácia broncodilatadora e risco de broncoespasmo, com queda do VEF1. O risco é maior com betabloqueadores não-seletivos. Em DPOC grave, pode precipitar insuficiência respiratória.","conduta":"⚠️ Usar betabloqueadores cardiosseletivos (bisoprolol, metoprolol) quando necessários em pacientes com DPOC em uso de LABA. Monitorar função pulmonar ao iniciar ou ajustar betabloqueador. Em emergência de broncoespasmo: salbutamol inalatório tem efeito parcial mesmo sob bloqueio β."},
{"med1":["indacaterol","maleato de indacaterol","onbrez","formoterol","salmeterol","vilanterol","laba"],"med2":["corticosteroide sistêmico","prednisona","dexametasona","hidroclorotiazida","furosemida","teofilina","aminofilina"],"nivel":"leve","titulo":"LABAs + Corticosteroides/Diuréticos/Xantinas (Hipocalemia Aditiva)","mecanismo":"Os β2-agonistas de longa ação causam hipocalemia por estimulação da Na-K-ATPase muscular (entrada de K⁺ na célula). Corticosteroides sistêmicos, diuréticos de alça e tiazídicos aumentam a perda renal de potássio. Xantinas (teofilina) têm efeito hipocalemiante independente. Os efeitos somam-se.","efeito":"Hipocalemia clinicamente relevante com risco de arritmias ventriculares, fraqueza muscular e paralisia hipocalêmica em casos graves. O risco é maior em exacerbações de DPOC tratadas com nebulizações frequentes de β2-agonistas.","conduta":"⚠️ Monitorar potássio sérico em pacientes usando combinação de LABA + diurético ou corticoide sistêmico, especialmente durante exacerbações de DPOC/asma. Repor potássio proativamente. Manter K⁺ sérico > 3,5 mEq/L."},
{"med1":["bromoprida","bromoprida","digesan"],"med2":["levodopa","carbidopa","levodopa + carbidopa","sinemet","pramipexol","ropinirol","cabergolina","bromocriptina"],"nivel":"moderado","titulo":"Bromoprida + Agonistas Dopaminérgicos (Antagonismo Terapêutico)","mecanismo":"A bromoprida é antagonista dopaminérgico D2 (mecanismo pró-cinético). Os agonistas dopaminérgicos usados no Parkinson e distúrbios hipotalâmicos estimulam justamente os receptores D2 periféricos e centrais. Há antagonismo direto do efeito terapêutico.","efeito":"Piora dos sintomas parkinsonianos (rigidez, tremor, bradicinesia) e perda de controle de discinesias. Elevação de prolactina com retorno de galactorreia ou disfunção erétil.","conduta":"🚫 Contraindicado em pacientes com Parkinson. Para náuseas/vômitos em parkinsonianos: usar domperidona com cautela (menor penetração no SNC) ou ondansetrom (sem antagonismo dopaminérgico central). A bromoprida está incluída na lista de fármacos que devem ser evitados no Parkinson."},
{"med1":["bromoprida","digesan"],"med2":["inibidor mao","imao","fenelzina","tranilcipromina","selegilina","moclobemida"],"nivel":"grave","titulo":"Bromoprida + IMAOs (Crise Hipertensiva e Síndrome Serotoninérgica)","mecanismo":"A bromoprida tem propriedades serotoninérgicas além do antagonismo dopaminérgico. Os IMAOs amplificam efeitos serotoninérgicos e adrenérgicos. A combinação pode precipitar crise hipertensiva e síndrome serotoninérgica.","efeito":"Crise hipertensiva, hipertermia, agitação, mioclonias, taquicardia. Potencialmente fatal.","conduta":"🚫 Contraindicado. Washout mínimo de 14 dias após suspensão do IMAO antes de iniciar bromoprida. Usar ondansetrom ou metoclopramida (apenas com monitoramento rigoroso) como alternativa antiemética."},
{"med1":["bromoprida","digesan"],"med2":["haloperidol","clorpromazina","tioridazina","ziprasidona","amiodarona","sotalol","domperidona","ciprofloxacino","moxifloxacino","azitromicina","eritromicina"],"nivel":"moderado","titulo":"Bromoprida + Fármacos que Prolongam QTc (Risco Aditivo)","mecanismo":"A bromoprida bloqueia canais de potássio cardíacos (IKr/hERG), prolongando o intervalo QTc. A combinação com outros fármacos que prolongam o QT — antipsicóticos, antiarrítmicos, macrólidos, fluoroquinolonas — é aditiva.","efeito":"Prolongamento excessivo do QTc com risco de torsades de pointes. O risco é maior em mulheres, hipocalemia e cardiopatia estrutural.","conduta":"⚠️ Evitar combinação com outros prolongadores de QT. Realizar ECG basal em pacientes com fatores de risco. Corrigir hipocalemia antes de iniciar. Preferir ondansetrom (menor risco de QTc) como antiemético alternativo."},
{"med1":["betaistina","betahistine","serc","betaserc"],"med2":["cetirizina","loratadina","desloratadina","fexofenadina","levocetirizina","bilastina","rupatadina","anti-histamínico"],"nivel":"moderado","titulo":"Betaistina + Anti-histamínicos H1 (Antagonismo Farmacológico)","mecanismo":"A betaistina age como agonista parcial dos receptores H1 e H3 histaminérgicos no sistema vestibular — melhorando a microcirculação coclear e reduzindo a pressão endolinfática. Os anti-histamínicos H1 bloqueiam competitivamente os receptores H1, antagonizando diretamente o mecanismo de ação da betaistina.","efeito":"Redução ou anulação da eficácia da betaistina no tratamento de vertigem (doença de Ménière, vertigem posicional). Perda de controle dos episódios vertiginosos.","conduta":"⚠️ Evitar combinação. Se anti-histamínico for necessário para rinite ou alergia em paciente com Ménière, considerar alternativas com menor antagonismo H1 central (montelucaste) ou avaliar necessidade da betaistina. A combinação não é absolutamente contraindicada em todos os guias, mas é farmacologicamente irracional."},
{"med1":["betaistina","betahistine","serc"],"med2":["inibidor mao","imao","fenelzina","tranilcipromina","selegilina","moclobemida"],"nivel":"moderado","titulo":"Betaistina + IMAOs (Aumento dos Níveis de Histamina)","mecanismo":"A histamina é parcialmente degradada pela MAO-B. Os IMAOs inibem a MAO, reduzindo o catabolismo da histamina e potencializando seus efeitos. Como a betaistina atua no sistema histaminérgico, os IMAOs podem amplificar imprevisavelmente seu efeito farmacológico.","efeito":"Potencialização dos efeitos da betaistina com possível hipotensão e aumento de efeitos adversos (cefaleia, náusea, flushing).","conduta":"⚠️ Evitar combinação. Washouout de 14 dias após IMAOs irreversíveis antes de iniciar betaistina. Com moclobemida (IMAO reversível): intervalo de 24h é geralmente suficiente."},
{"med1":["ácido tranexâmico","acido tranexamico","transamine","hemoblock","cyklokapron"],"med2":["anticoncepcional oral","etinilestradiol","progestogênio","acetato de medroxiprogesterona","contraceptivo oral combinado"],"nivel":"moderado","titulo":"Ácido Tranexâmico + Contraceptivos Orais Combinados (Risco Trombótico Aditivo)","mecanismo":"O ácido tranexâmico inibe a fibrinólise ao bloquear a ligação do plasminogênio à fibrina, deslocando o equilíbrio hemostático para o estado pró-trombótico. Os estrogênios dos contraceptivos orais aumentam fatores de coagulação pró-trombóticos. Os mecanismos somam-se.","efeito":"Risco aumentado de trombose venosa profunda, embolia pulmonar e trombose em outros territórios (retiniana, cerebral). O risco é especialmente elevado no período peri-menstrual quando o ácido tranexâmico é prescrito para menorragia.","conduta":"⚠️ Usar ácido tranexâmico com cautela em usuárias de COC. Para menorragia em mulheres usando COC: avaliar ajuste do anticoncepcional (dose hormonal, mudança de progestágeno) antes de acrescentar ácido tranexâmico. Se uso for inevitável: menor dose e menor duração possíveis, monitorar sinais de trombose."},
{"med1":["ácido tranexâmico","acido tranexamico","transamine","cyklokapron"],"med2":["fator vii","fator ix","complexo protrombínico","novacseven","feiba","concentrado de complexo protrombínico"],"nivel":"grave","titulo":"Ácido Tranexâmico + Concentrados de Fatores de Coagulação (Trombose Grave)","mecanismo":"Os concentrados de fatores de coagulação (especialmente os ativados — Fator VIIa, FEIBA) já carregam risco trombótico intrínseco. O ácido tranexâmico, ao inibir a fibrinólise, amplifica drasticamente o estado pró-trombótico criado pelos fatores administrados.","efeito":"Trombose arterial ou venosa grave — infarto do miocárdio, AVC isquêmico, trombose intravascular disseminada e coagulação intravascular disseminada paradoxal. Casos fatais descritos com FEIBA + ácido tranexâmico.","conduta":"🚫 Contraindicado com FEIBA (complexo protrombínico ativado). Com Fator VIIa recombinante: evitar salvo em situações de emergência com monitoramento intensivo. Em hemofilia com inibidor: discutir com hematologista antes de usar a combinação."},
{"med1":["mebendazol","vermox","pantelmin"],"med2":["cimetidina","tagamet"],"nivel":"leve","titulo":"Mebendazol + Cimetidina (Aumento dos Níveis Plasmáticos)","mecanismo":"A cimetidina inibe CYP1A2 e CYP3A4, as principais enzimas de metabolização do mebendazol, além de inibir a secreção tubular renal. Em tratamento de infecções sistêmicas (equinococose, larva migrans), onde níveis plasmáticos importam, a interação tem relevância clínica.","efeito":"Elevação dos níveis plasmáticos de mebendazol em 2–3 vezes. Na helmintíase intestinal (onde a ação é local), o efeito é irrelevante. Em tratamentos sistêmicos: pode ser benéfico (maiores níveis teciduais) ou aumentar toxicidade hepática.","conduta":"✅ Em helmintíase intestinal: interação sem importância clínica. Em equinococose/cisticercose com uso sistêmico: a cimetidina foi intencionalmente usada para elevar níveis teciduais em alguns protocolos. Monitorar transaminases em tratamentos prolongados."},
{"med1":["mebendazol","vermox","pantelmin"],"med2":["carbamazepina","tegretol","fenitoína","hidantal","fenobarbital"],"nivel":"moderado","titulo":"Mebendazol + Indutores Enzimáticos (Redução de Eficácia Sistêmica)","mecanismo":"Carbamazepina, fenitoína e fenobarbital são indutores de CYP3A4 e CYP1A2, acelerando o metabolismo do mebendazol e reduzindo drasticamente seus níveis plasmáticos.","efeito":"Na helmintíase intestinal (dose única de 100 mg): impacto mínimo pois a ação é local e não depende da absorção sistêmica. Em equinococose hepática ou pulmonar (onde altas doses e níveis sistêmicos são necessários): risco de falha terapêutica.","conduta":"⚠️ Em tratamento sistêmico de equinococose: monitorar níveis plasmáticos de mebendazol (ou sulfóxido de albendazol, se este for usado alternativamente). Considerar aumento de dose ou substituição por albendazol em pacientes com carbamazepina ou fenitoína. Em helmintíase intestinal: sem necessidade de ajuste."},
{"med1":["albendazol","zentel","eskazole"],"med2":["cimetidina","praziquantel"],"nivel":"leve","titulo":"Albendazol + Cimetidina / Praziquantel (Aumento do Sulfóxido de Albendazol)","mecanismo":"A cimetidina inibe o metabolismo hepático do albendazol, elevando os níveis do sulfóxido de albendazol (metabólito ativo). O praziquantel aumenta a Cmax do sulfóxido de albendazol em ~50% por mecanismo ainda não completamente esclarecido (possível inibição do metabolismo de first-pass ou da P-gp).","efeito":"Aumento dos níveis do metabólito ativo. Em neurocisticercose e equinococose, este efeito pode ser benéfico (maior concentração tecidual). Em doses convencionais de albendazol, a toxicidade raramente é aumentada.","conduta":"✅ A combinação albendazol + praziquantel é usada intencionalmente em neurocisticercose em alguns protocolos — o aumento do sulfóxido de albendazol é considerado vantajoso. Monitorar transaminases em tratamentos prolongados. Em helmintíase intestinal de curto prazo: sem relevância clínica."},
{"med1":["albendazol","zentel","eskazole"],"med2":["dexametasona","carbamazepina","fenitoína","fenobarbital","rifampicina"],"nivel":"moderado","titulo":"Albendazol + Indutores CYP / Dexametasona (Alteração dos Níveis)","mecanismo":"A dexametasona inibe a sulfoxidação do albendazol, reduzindo a formação do metabólito ativo (sulfóxido) e elevando o metabólito inativo (sulfona). Indutores enzimáticos (rifampicina, carbamazepina) aceleram o metabolismo geral do albendazol, reduzindo ambos os metabólitos.","efeito":"Alteração imprevisível da eficácia em neurocisticercose. Com dexametasona (frequentemente usada para edema cerebral na cisticercose): paradoxalmente pode elevar os níveis plasmáticos totais do albendazol em alguns estudos, com efeito clínico variável.","conduta":"⚠️ A combinação albendazol + dexametasona é frequentemente usada em neurocisticercose (esteroide para edema pericístico). Monitorar resposta clínica e de imagem. Evitar antiepilépticos indutores quando possível — preferir levetiracetam ou lamotrigina para controle de crises em cisticercose."},
{"med1":["nitazoxanida","annita","alinia"],"med2":["warfarina","varfarina","acenocumarol"],"nivel":"moderado","titulo":"Nitazoxanida + Warfarina (Deslocamento Proteico — Elevação do RNI)","mecanismo":"A nitazoxanida e seu metabólito ativo (tizoxanida) são altamente ligados a proteínas plasmáticas (>99%). Podem deslocar a warfarina de seus sítios de ligação à albumina, aumentando transitoriamente a fração livre (ativa) da warfarina. Adicionalmente, há relato de inibição leve de CYP2C9.","efeito":"Elevação do RNI com risco de sangramento. O efeito pode ser transitório mas clinicamente relevante, especialmente nas primeiras doses de nitazoxanida.","conduta":"⚠️ Monitorar RNI nos primeiros dias após início da nitazoxanida em anticoagulados. Ajustar dose de warfarina se necessário. Como o tratamento com nitazoxanida é geralmente de curta duração (3 dias), monitorar RNI ao final do curso e após a suspensão."},
{"med1":["tenoxicam","tilatil","mobiflex"],"med2":["warfarina","varfarina","acenocumarol","heparina","apixabana","rivaroxabana","dabigatrana"],"nivel":"moderado","titulo":"Tenoxicam + Anticoagulantes (Risco de Sangramento)","mecanismo":"O tenoxicam inibe COX-1 (reduzindo tromboxano A2 e agregação plaquetária) e lesa a mucosa gastrointestinal por inibição de prostaglandinas protetoras. Em combinação com anticoagulantes, o risco de sangramento gastrointestinal é aditivo.","efeito":"Sangramento GI (úlcera, gastrite hemorrágica), hematúria e equimoses. O tenoxicam tem meia-vida muito longa (~60–75 horas) — o efeito anticoagulante pode persistir por dias após a suspensão.","conduta":"⚠️ Evitar em anticoagulados. Se AINE for necessário: preferir agentes de meia-vida curta (ibuprofeno, diclofenaco) para facilitar o manejo. Sempre associar proteção gástrica com IBP (omeprazol, pantoprazol). Monitorar RNI com warfarina. Paracetamol é a alternativa de primeira linha."},
{"med1":["tenoxicam","tilatil","mobiflex"],"med2":["carbonato de lítio","lítio","litio"],"nivel":"moderado","titulo":"Tenoxicam + Lítio (Redução do Clearance Renal — Toxicidade)","mecanismo":"O tenoxicam inibe prostaglandinas renais vasodilatadoras (PGE2, PGI2), reduzindo o fluxo sanguíneo renal e a taxa de filtração glomerular. Como o lítio é eliminado exclusivamente por via renal, seu clearance diminui e seus níveis séricos elevam. A meia-vida longa do tenoxicam (~60–75h) prolonga a interação.","efeito":"Toxicidade por lítio: tremor, ataxia, confusão, poliúria paradoxal, convulsões em casos graves. A interação pode se manifestar mesmo com uso breve de tenoxicam.","conduta":"⚠️ Monitorar litemia 5–7 dias após início do tenoxicam. Preferir paracetamol como analgésico em usuários de lítio. Se AINE for necessário, optar por sulindac (menor efeito sobre a excreção renal de lítio) com monitoramento rigoroso."},
{"med1":["tenoxicam","tilatil","mobiflex"],"med2":["metotrexato","methotrexate"],"nivel":"grave","titulo":"Tenoxicam + Metotrexato (Toxicidade Grave por MTX)","mecanismo":"O tenoxicam reduz o fluxo sanguíneo renal e inibe transportadores tubulares OAT1/OAT3, comprometendo a eliminação renal do metotrexato. A meia-vida prolongada do tenoxicam (~3 dias) significa que a interação persiste por mais tempo do que com AINEs de ação curta.","efeito":"Acúmulo de metotrexato com mucosites graves, mielossupressão, hepatotoxicidade e nefrotoxicidade. Em doses oncológicas: risco fatal.","conduta":"🚫 Contraindicado com metotrexato em doses oncológicas. Em doses antirreumatológicas: evitar tenoxicam na semana da tomada de metotrexato — a meia-vida longa o torna especialmente problemático. Usar paracetamol como alternativa analgésica. Monitorar hemograma e função renal."},
{"med1":["rifaximina","xifaxan","normix"],"med2":["ciclosporina","sandimmun"],"nivel":"moderado","titulo":"Rifaximina + Ciclosporina (Inibição P-gp — Aumento de Rifaximina)","mecanismo":"A rifaximina é substrato da P-glicoproteína intestinal, que normalmente limita sua absorção sistêmica (<1%). A ciclosporina é inibidora potente da P-gp. Em combinação, a absorção sistêmica da rifaximina pode aumentar significativamente — embora ainda permaneça baixa em termos absolutos.","efeito":"Elevação dos níveis plasmáticos de rifaximina com possível aumento de efeitos adversos sistêmicos (náusea, elevação de transaminases). Em transplantados hepáticos (principal indicação de ciclosporina + rifaximina para encefalopatia hepática), o risco merece monitoramento.","conduta":"⚠️ Monitorar função hepática e efeitos adversos ao combinar rifaximina com ciclosporina. Ajustar dose de rifaximina se necessário. A combinação é clinicamente relevante em pacientes transplantados com encefalopatia hepática recorrente."},
{"med1":["rifaximina","xifaxan","normix"],"med2":["warfarina","varfarina","acenocumarol"],"nivel":"leve","titulo":"Rifaximina + Warfarina (Alteração da Microbiota — Variação de RNI)","mecanismo":"A rifaximina, ao alterar a microbiota intestinal, pode reduzir a síntese bacteriana de vitamina K2 (menaquinona) no cólon. Em pacientes com ingestão marginal de vitamina K1, esta redução pode elevar o RNI. O efeito é geralmente modesto por ser a vitamina K bacteriana de absorção limitada.","efeito":"Variação modesta do RNI durante o curso de rifaximina. Clinicamente relevante principalmente em pacientes com dieta pobre em vegetais (baixa reserva de vitamina K1).","conduta":"✅ Monitorar RNI ao iniciar rifaximina em anticoagulados, especialmente se curso prolongado (uso profilático de encefalopatia hepática). Em cursos curtos (3 dias), o impacto é geralmente mínimo."},
{"med1":["secnidazol","secnidal","flagentyl"],"med2":["álcool","bebida alcoólica","etanol"],"nivel":"moderado","titulo":"Secnidazol + Álcool (Reação Antabuse / Efeito Dissulfiram)","mecanismo":"O secnidazol, como todos os nitroimidazóis (metronidazol, tinidazol, ornidazol), inibe a aldeído desidrogenase mitocondrial. O álcool é metabolizado a acetaldeído (por álcool desidrogenase), que normalmente é convertido a acetato pela aldeído desidrogenase. A inibição causa acúmulo de acetaldeído tóxico.","efeito":"Reação antabuse: flushing (rubor facial intenso), cefaleia pulsátil, náuseas, vômitos, taquicardia, hipotensão e sensação de morte iminente. Geralmente auto-limitada mas muito desconfortável. Raramente grave (colapso cardiovascular).","conduta":"⚠️ Orientar firmemente a evitar álcool durante o tratamento. A meia-vida longa do secnidazol (~17–29h) significa que o risco persiste por 2–3 dias após a última dose. Incluir alertas sobre álcool em medicamentos, bebidas fermentadas e enxaguatórios bucais com álcool."},
{"med1":["secnidazol","secnidal"],"med2":["warfarina","varfarina","acenocumarol"],"nivel":"moderado","titulo":"Secnidazol + Warfarina (Potencialização do Efeito Anticoagulante)","mecanismo":"Como o metronidazol, o secnidazol inibe CYP2C9 — a principal enzima responsável pelo metabolismo da S-warfarina (isômero ativo). A inibição reduz o clearance da warfarina e eleva seus níveis plasmáticos.","efeito":"Elevação do RNI com risco aumentado de sangramento. Embora o secnidazol seja geralmente usado em dose única ou curso de 1–2 dias, a elevação do RNI pode persistir por alguns dias.","conduta":"⚠️ Monitorar RNI no início e ao final do curso de secnidazol. Pode ser necessária redução temporária da dose de warfarina. Para tricomoníase e giardíase em anticoagulados: comunicar ao paciente sobre o risco de sangramento e sinais de alerta."},
{"med1":["furoato de mometasona","mometasona","nasonex","asmanex","elocon"],"med2":["cetoconazol","ketoconazol","itraconazol","ritonavir","cobicistate","claritromicina"],"nivel":"moderado","titulo":"Furoato de Mometasona + Inibidores Fortes CYP3A4 (Aumento da Absorção Sistêmica)","mecanismo":"A mometasona inalatória ou nasal tem baixíssima biodisponibilidade sistêmica normalmente (<1%). No entanto, CYP3A4 é responsável por seu metabolismo de first-pass. Inibidores potentes desta enzima podem elevar a absorção sistêmica para níveis clinicamente relevantes em uso prolongado.","efeito":"Efeitos sistêmicos de corticosteroides em uso prolongado: supressão do eixo HPA (insuficiência adrenal ao suspender abruptamente), síndrome de Cushing iatrogênica (ganho de peso, hiperglicemia, osteoporose), cataratas.","conduta":"⚠️ Monitorar sinais de hipercortisolismo em uso prolongado de mometasona com inibidores fortes de CYP3A4 (especialmente ritonavir/cobicistate em TARV). Considerar dose menor de mometasona ou alternativa com menor dependência de CYP3A4 (beclometasona, budesonida). Não suspender abruptamente a mometasona após uso prolongado."},
{"med1":["acetilcisteína","acetilcisteina","n-acetilcisteína","nac","fluimucil","mucolytic"],"med2":["nitroglicerina","nitrato","mononitrato de isossorbida","dinitrato de isossorbida","nitratos"],"nivel":"moderado","titulo":"N-Acetilcisteína (NAC) + Nitratos (Potencialização da Vasodilatação)","mecanismo":"A NAC doa grupos tiol (-SH) que potencializam a bioativação do óxido nítrico (NO) derivado dos nitratos. Adicionalmente, a NAC pode restaurar a responsividade dos nitratos em pacientes com tolerância adquirida. O resultado é uma potencialização do efeito vasodilatador.","efeito":"Hipotensão acentuada e cefaleia intensa (cefaleia por nitrato amplificada). Em pacientes com angina usando nitratos e NAC para mucolítico ou proteção hepática, o efeito pode ser surpreendentemente pronunciado.","conduta":"⚠️ Monitorar pressão arterial ao iniciar NAC em pacientes usando nitratos. Orientar sobre possível aumento de cefaleia. Em uso IV de NAC (intoxicação por paracetamol): monitorar hemodinâmica e reduzir taxa de infusão se hipotensão. A combinação foi estudada em angina refratária a nitratos — neste contexto o efeito pode ser terapeuticamente aproveitado."},
{"med1":["acetilcisteína","acetilcisteina","n-acetilcisteína","nac"],"med2":["carvão ativado","carvao ativado"],"nivel":"moderado","titulo":"N-Acetilcisteína (NAC) + Carvão Ativado (Adsorção — Redução de Eficácia)","mecanismo":"O carvão ativado adsorve a NAC no trato gastrointestinal, reduzindo significativamente sua absorção quando administrados simultaneamente por via oral. Esta interação é relevante especialmente no contexto de overdose de paracetamol, onde ambos podem ser usados.","efeito":"Redução da absorção e eficácia da NAC oral no tratamento de intoxicação por paracetamol — comprometendo a proteção hepática.","conduta":"⚠️ Na intoxicação por paracetamol com necessidade de carvão ativado: preferir NAC IV (sem interação). Se apenas NAC oral estiver disponível: espaçar ≥1–2 horas do carvão ativado. Em contexto de intoxicação múltipla, o benefício do carvão para outros tóxicos deve ser sopesado contra o risco de comprometer a NAC."},
{"med1":["trometamol de fosfomicina","fosfomicina","monurol"],"med2":["metoclopramida","domperidona","bromoprida"],"nivel":"moderado","titulo":"Fosfomicina + Procinéticos (Redução de Absorção)","mecanismo":"Os procinéticos (metoclopramida, domperidona) aceleram o esvaziamento gástrico e o trânsito intestinal. A fosfomicina trometamol é absorvida no intestino delgado de forma tempo-dependente — o trânsito acelerado reduz o tempo de contato com a mucosa absortiva, diminuindo sua biodisponibilidade.","efeito":"Redução da Cmax e AUC da fosfomicina em 25–40%, comprometendo as concentrações urinárias necessárias para a eficácia antibacteriana na ITU.","conduta":"⚠️ Evitar procinéticos nas 2–4 horas ao redor da tomada de fosfomicina. Como fosfomicina trometamol é geralmente dose única, planejar a administração afastada do horário do procinético maximiza a absorção."},
{"med1":["fentolamina","mesilato de fentolamina","regitine"],"med2":["epinefrina","adrenalina","epinephrine"],"nivel":"grave","titulo":"Fentolamina + Epinefrina (Inversão do Efeito Adrenérgico — Hipotensão Paradoxal)","mecanismo":"A epinefrina tem efeitos α-adrenérgicos (vasoconstrição) e β-adrenérgicos (vasodilatação, inotropia). A fentolamina bloqueia os receptores α. Com o bloqueio α, apenas os efeitos β (vasodilatação periférica via β2) permanecem — resultando em queda pressórica paradoxal. Este é o clássico fenômeno de \"reversão da epinefrina\".","efeito":"Hipotensão grave paradoxal em pacientes que recebem epinefrina para tratar hipotensão durante bloqueio adrenérgico alfa. O efeito esperado da epinefrina (vasoconstrição) é revertido para vasodilatação.","conduta":"🚫 Em pacientes sob bloqueio alfa (incluindo intoxicação por alfa-bloqueadores ou feocromocitoma tratado): usar norepinefrina (noradrenalina) ou vasopressina — não epinefrina — para correção de hipotensão. Informar equipe de emergência sobre o risco de reversão da epinefrina."},
{"med1":["fentolamina","mesilato de fentolamina","regitine"],"med2":["sildenafila","tadalafila","vardenafila","avanafila","inibidor pde5"],"nivel":"moderado","titulo":"Fentolamina + Inibidores de PDE5 (Hipotensão Aditiva)","mecanismo":"A fentolamina bloqueia receptores α1 e α2 adrenérgicos, causando vasodilatação periférica. Os inibidores de PDE5 promovem vasodilatação via GMPc. Os dois mecanismos se somam de forma aditiva sobre o tônus vascular.","efeito":"Hipotensão sintomática grave — tontura, pré-síncope, síncope. O risco é maior em pacientes com volume circulante reduzido ou cardiopatia.","conduta":"⚠️ Evitar combinação. Monitorar pressão arterial se uso for necessário. A fentolamina é usada principalmente em contexto hospitalar (crise hipertensiva por feocromocitoma, reversão de vasoconstrição local) — avaliar cuidadosamente antes de administrar em pacientes em uso de inibidores de PDE5."}
];

